// Tantra 7 — verses 1704-2121 — scraped from tamilnation.org
export const VERSES_T7: Verse[] = [
  {
    id: 1705, tantraId: 7, verseNumber: 1704,
    tamil: `நாலும் இருமூன்றும் ஈரைந்தும் ஈராறும்
கோவிமேல் நின்ற குறிகள் பதினாறும்
மூலம் கண்டு ஆங்கே முடிந்து முதல் இரண்டும்
காலங்கண் டான்அடி காணலும் ஆமே`,
    transliteration: `nālum irumūṉṟum īraintum īrāṟum
kōvimēl niṉṟa kuṟikaḷ patiṉāṟum
mūlam kaṇṭu āṅkē muṭintu mutal iraṇṭum
kālaṅkaṇ ṭāṉaṭi kāṇalum āmē`,
    english: `1704: The Six Adharas and their petals
Piercing the Chakras that are petalled
Four, Six, Ten and Twelve
And the Six and Ten still above;
Lo! Behold then the Twin petalled Center finale;
You have indeed beheld the Holy Feet of the Timeless One.`,
    elaborationEnglish: `There are six chakras situated at different points along the spinal column of the human body. They are known as: muladhara of four petals, svadhistana of six petals,

manipuraka of ten petals, anahatha of twelve petals, visuddhi.

of sixteen petals and ajna of two petals. Coursing the prana breath through these chakras in ascending order, the yogi beholds the Twin Feet of the Eternal in the twin-petalled ajna chakra.

four petals Svadhistana—Of six petals Manipuraka—Of ten petals Anahatha—Of twelve petals Visuddhi—Of sixteen petals Ajna—Of two petals.

The Adharas are as Lotus Petals, of varying numbers. The final climax is reached in the “‘twin-petalled Centre finale’ (in the cranium between the eye-brows).`,
    elaborationTamil: `நான்கு இதழ்கள் கொண்ட மூலாதாரமும், ஆறு இதழ்கள் கொண்ட சுவாதிட்டானமும், பத்து இதழ்கள் கொண்ட மணிப்பூரகமும், பன்னிரண்டு இதழ்கள் கொண்ட அநாகதமும், சுழுமுனை நாடியின் மேல் நிற்கின்ற இந்த சக்கரங்களாகிய குறிகளோடு பதினாறு இதழ்கள் கொண்ட விசுக்தியும் தாண்டி, இறைவனின் திருவடிகளை காண்பதற்கு மூலமாக இருக்கின்ற நீல நிற ஜோதியை கண்டு, நெற்றிக்கு நடுவில் புருவ மத்தியில் வினைகள் முடிவதற்கு முதலாக இருக்கின்ற ஆக்ஞா சக்கரத்தில் பிறவிக்கு காரணமாகிய நல் வினை தீ வினை ஆகிய இரண்டும் நீங்கி விட, காலத்தை படைத்தவனும் இறந்த காலம், நிகழ் காலம், எதிர் காலம் ஆகிய மூன்று காலங்களையும் கண்டு அறிந்தவனும் ஆகிய இறைவனின் திருவடிகளை தரிசிக்கவும் முடியும்.`,
  },
  {
    id: 1706, tantraId: 7, verseNumber: 1705,
    tamil: `ஈராறு நாதத்தில் ஈரெட்டாம் அந்தத்தின்
மேதாதி நாதாந்த மீதாம் பாராசக்தி
போதா லயத்துஅ விகாரந்தனிற்போத
மேதாதி ஆதார மீதான உண்மையே`,
    transliteration: `īrāṟu nātattil īreṭṭām antattiṉ
mētāti nātānta mītām pārācakti
pōtā layattua vikārantaṉiṟpōta
mētāti ātāra mītāṉa uṇmaiyē`,
    english: `1705: The Spheres of the upper Adharas
In the Nada sphere is the Twelve petalled Center
In the Nadanta sphere is the Ten and Six petalled Center
Beyond the Nadanta is the Two-petalled Medha Center
Where Parasakti enshrined is;
Enter there in Consciousness Undifferentiated Bodha;
There, above the Medha Center, is the Truth Finale.`,
    elaborationEnglish: `The anahatha chakra is in the Nada sphere; visuddhi chakra, in the Nadanta sphere: ajna chakra,"in the Medha sphere. Parasakti is enshrined here. Above this centre is the final Truth.`,
    elaborationTamil: `பன்னிரண்டு சூரிய கலைகளாகிய ஓசை மயத்திலும், பதினாறு சந்திர கலைகளாகிய அனைத்தும் ஓடுங்குகின்ற மயத்திலும், தலை உச்சியில் அனைத்திற்கும் முதலாகவும், ஓசையின் எல்லையாகவும் இருக்கின்ற சகஸ்ரதளத்தின் மீது வீற்றிருப்பது அசையும் சக்தியாகிய பரம்பொருள் ஆகும். அங்கே அறிவு வடிவாக இருக்கின்ற இறை சக்தி வீற்றிருக்கும் ஆலயமாகிய உடலுக்கு உள்ளே இறை சக்தியோடு வேறுபட்டு இருக்கின்ற உயிர்களின் ஆன்மாவிற்குள் ஞானமாகவும், அக்னியாகவும் முழுவதும் நிறைந்து இந்த உடலுக்குள் இருக்கின்ற ஆறு ஆதாரங்களாகவும் இருப்பது அந்த இறை சக்தியே என்று யாம் உரைப்பது உண்மையே ஆகும்.`,
  },
  {
    id: 1707, tantraId: 7, verseNumber: 1706,
    tamil: `மேல்என்றும் கீழ்என்று இரண்டற் காணுங்கால்
தான்என்றும் நான்என்றும் தன்மைகள் ஓராறும்
பார்எங்கும் ஆகிப் பரந்த பராபரம்
கார்ஒன்று கற்பகம் ஆகிநின்றானே`,
    transliteration: `mēleṉṟum kīḻeṉṟu iraṇṭaṟ kāṇuṅkāl
tāṉeṉṟum nāṉeṉṟum taṉmaikaḷ ōrāṟum
pāreṅkum ākip paranta parāparam
kāroṉṟu kaṟpakam ākiniṉṟāṉē`,
    english: `1706: Parapara pervades all the Six Adharas
When thus through Adharas
You course Prana breath
Neither Up nor Down do you know
Neither He nor I do you cognise
The mighty Parapara that pervades all
Envelops you,
Bounteous as the celestial Kalpaka tree.`,
    elaborationEnglish: `When prana breath -is-coursed up through these six adharas, step by step, the yogi is oblivious of his station as up or down, and his being as self or God. Parapara envelopes him, cool as the fruit-laden kalpaka tree.`,
    elaborationTamil: `மேன்மையானது என்றும் கீழ்மையானது என்றும் இரண்டு விதமாக பிரித்து பார்ப்பது இல்லாமல் அனைத்தும் ஒன்றே என்று பார்க்கும் பொழுது, தான் என்று நினைக்கின்ற ஆத்மாவும், நான் என்று நினைக்கின்ற உடம்பும், தன்மைகளாக தமக்குள் இருக்கின்ற ஆறு ஆதார சக்கரங்களும், உலகங்கள் அனைத்தும் ஆகி அண்டசராசரங்கள் எங்கும் பரந்து விரிந்து இருக்கின்ற அசையா சக்தியாகிய பரம்பொருளே என்பதை உணர்ந்தால், வேரால் பருகிய நீரை தங்களின் தலை உச்சியில் இருக்கும் பழங்களில் சேமித்து வைத்து இருக்கும் தென்னை பனை ஆகிய மரங்களைப் போலவே உயிர்களின் தலை உச்சிக்குள்ளும் ஜோதியாக நிற்கின்றவன் அந்த இறை சக்தியே என்பதை உணரலாம்.`,
  },
  {
    id: 1708, tantraId: 7, verseNumber: 1707,
    tamil: `ஆதார சோதனை யால்நாடி சுத்திகள்
மேதாதி ஈரெண் காலந்தத்து விண்ணொளி
போதா லயத்துப் புலன்கர ணம் புத்தி
சாதா ரணங்கெட்டான் தான்சக மார்க்கமே`,
    transliteration: `ātāra cōtaṉai yālnāṭi cuttikaḷ
mētāti īreṇ kālantattu viṇṇoḷi
pōtā layattup pulaṉkara ṇam putti
cātā raṇaṅkeṭṭāṉ tāṉcaka mārkkamē`,
    english: `1707: Experience is Adhara Yoga
Ascend Adharas step by step,
Your Nadis purified thus,
You shall have ascended
Into the heavenly effulgence of Medha
Whose twin petals into
Kalanta sphere rise;
And then you reach the state of Bodha,
Of Awareness Unitive,
senses petrified;
That verily is
Yoga--the Saha Marga.`,
    elaborationEnglish: `With nadis purified, the yogi ascends into Nada, Nadanta, Kalanta and Bodhanta spheres within as he courses the prana upwards.

1) The spheres of experience in yoga are:

2) The spheres of experience in yoga are:

Nadanta (sound sphere), Kalanta (light sphere), and Bodhanta (consciousness sphere).`,
    elaborationTamil: `ஆறு ஆதாரங்களையும் தியானத்தின் வழியாக பயிற்சி செய்வதன் மூலம் உடலில் உள்ள அனைத்து நாடிகளையும் சுத்தம் செய்த பிறகு வேதங்களுக்கு மூலமாகிய இறைவன் பதினாறு கலைகளாக தமக்குள் கலந்து வானத்தில் இருந்து உலகத்தின் இருளை நீக்கும் பேரொளியைப் போலவே தமக்குள் உண்மை ஞானத்தை விளக்கி அருளுகின்ற ஆலயமாகவே வீற்றிருப்பான். அதன் பிறகு ஐந்து புலன்களும், நான்கு அந்தக் கரணங்களும், அறிவும், உலக பற்றுக்கள் சார்ந்த தங்களின் இயல்பான நிலையை மாற்றி ஒன்றாக சேர்ந்து இறைவனை நோக்கி செயல்படுவதே தோழமை வழி முறையாகும்.`,
  },
  {
    id: 1709, tantraId: 7, verseNumber: 1708,
    tamil: `மேதாதி யாலே விடாதுஓம் எனத்தூண்டி
ஆதார சோதனை அத்துவ சோதனை
தாதுஆர மாசுவே தானெழச் சாதித்தால்
ஆதாரஞ் செய்போக மாவது காயமே`,
    transliteration: `mētāti yālē viṭātuōm eṉattūṇṭi
ātāra cōtaṉai attuva cōtaṉai
tātuāra mācuvē tāṉeḻac cātittāl
ātārañ ceypōka māvatu kāyamē`,
    english: `1708: Ascending further above Six Adharas
There you stop not--at Medha's Center--
But evoke Aum,
And beyond Adharas now proceed
And ascend the Adhvas with Prana for support
When thus you practise, to perfection's end,
Your body becomes a doughty receptacle
Of Joy Eternal.`,
    elaborationEnglish: `The yogi must not stop at medha’s (ajna) centre, but should evoke, “Aum,” and, with prana as support, he should proceed beyond the adharas to ascend further the six steps (adhvas), viz., kala, bhuvana, varna, mantra, pada and tattva. When this is practised perfectly, the yogi’s body becomes a receptacle of endless bliss.

Adhvas are pathways, or steps. These are six in number — kala, bhuvana, vama, mantra, pada, and tattva.`,
    elaborationTamil: `உடலுக்குள் இருக்கின்ற மூலாக்கினி வேள்வியை ஆதியாக இருக்கின்ற இறைவனை இடைவிடாது எண்ணிக் கொண்டு ஓங்கார மந்திரத்தின் மூலம் தூண்டி எழுப்பி, உடலுக்குள் இருக்கின்ற ஆறு ஆதார சக்கரங்களையும் தியானத்தின் வழியாக பயிற்சி செய்தும், இறைவனை அடைவதற்கான ஆறு விதமான வழி முறைகளையும் தியானத்தின் வழியாக பயிற்சி செய்தும், உடலுக்குள் இருக்கின்ற சுக்கிலத்தை மூலாதாரத்திலிருந்து சகஸ்ரதளம் வரை ஏற்றி இறக்கி மாலை போலவே தானாகவே எழுச்சி பெறும் படி சாதகம் செய்து சாதித்தால், அதுவே இறைவனை அடைவதற்கு ஆதாரமாக செயல்பட்டு இறைவனது பேரின்பத்தை அனுபவிக்க வைக்கும் அழியாத பாத்திரமாக தமது உடலை மாற்றி விடும். இறைவனை அடைவதற்கான ஆறு வழிகள் (அத்துவாக்கள்): மந்திரம் = மந்திரங்களை உச்சரிப்பதன் மூலம் இறைவனை அடைவது. பதம் = இறைவனது திருவடிகளை முழுவதுமாக சரணடைவதன் மூலம் இறைவனை அடைவது. வர்ணம் = தனக்கு விதிக்கப்பட்ட கர்மங்களை தர்மப் படி செய்து அதன் மூலமே இறைவனை அடைவது. புவனம் = உலகத்தில் இருக்கின்ற ஆலயங்கள், தீர்த்தங்கள் போன்றவற்றை யாத்திரை செய்வதன் மூலம் இறைவனை அடைவது. தத்துவம் = இறை தத்துவங்களை ஆராய்ந்து அறிந்து கொண்டு ஞானத்தினால் இறைவனை அடைவது. கலை = பாடல் #713 இல் உள்ளபடி பதினாறு கலைகளில் மேன்மை பெற்று அவற்றின் மூலமே இறைவனை அடைவது.`,
  },
  {
    id: 1710, tantraId: 7, verseNumber: 1709,
    tamil: `ஆறந்த மும்கூடி யாகும் உடம்பினில்
கூறிய ஆதார மற்றும் குறிக்கொண்மின்
ஆறிய அக்கரம் ஐம்பதின் மேலே
ஊறிய ஆதாரத்து ஓரெழுத்து ஆமே`,
    transliteration: `āṟanta mumkūṭi yārum uṭampiṉil
kūṟiya ātāra maṟṟum kuṟikkoṇmiṉ
āṟiya akkaram aimpatiṉ mēlē
ūṟiya ātārattu ōreḻuttu āmē`,
    english: `1709: The One Letter "Aum" is beyond the Fifty Letters
distributed over the Adharas
In the body where the Centers Six are,
Do seek the Adharas and above,
Over the letters five times ten
Rises the one Letter (Aum) that is basic to all.`,
    elaborationEnglish: `Over the Fifty Letters distributed over the petals of the six
adharas is the basic letter,“Aum’.`,
    elaborationTamil: `ஆறு ஆதார சக்கரங்களின் எல்லைகளும் ஒன்றாக கூடி ஆகுகின்ற உயிர்களின் உடம்பினுள் சொல்லிய ஆதாரங்களாகிய ஆறு சக்கரங்களையும் குறிக்கோளாக கொண்டு சாதகம் செய்யுங்கள். அப்போது அந்த ஆறு சக்கரங்களிலும் வீற்றிருக்கின்ற எழுத்துக்களும் சக்தியூட்டம் பெற்று, ஆறு அத்துவாக்களுக்கு ஆதாரமாக இருக்கின்ற ஐம்பது எழுத்துக்களுக்கு மேலே வீற்றிருந்து, அந்த ஐம்பது எழுத்துக்களுக்குள் ஊறி இருந்து நடுவில் ஆதாரமாக வீற்றிருக்கின்ற ஒரு எழுத்தாகிய ஓங்காரமாகவே மாறி இருக்கும்.`,
  },
  {
    id: 1711, tantraId: 7, verseNumber: 1710,
    tamil: `ஆகும் உடம்பும் அழிகின்ற அவ்வுடல்
போகும் உடம்பும் பொருந்திய வாறுதான்
ஆகிய அக்கரம் ஐம்பது தத்துவம்
ஆகும் உடம்புக்கும் ஆறந்த மாமே`,
    transliteration: `ākum uṭampum aḻikiṉṟa avvuṭal
pōkum uṭampum poruntiya vāṟutāṉ
ākiya akkaram aimpatu tattuvam
ākum uṭampukkum āṟanta māmē`,
    english: `1710: The Letters Fifty the subtle in Adharas, and Adharas
subtle are in Body
As the Gross body that decays
And the Subtle body that escapes
Are in union unseen,
So are the subtle letters fifty to tattvas that are gross,
So are the Centers Six to the body corporeal.`,
    elaborationEnglish: `As the subtle body is to the gross body, the Fifty Letters
are to the gross tattvas; and the six centres to the body
corporeal,`,
    elaborationTamil: `ஆறு ஆதார சக்கரங்களே உயிர்களின் உடம்பை ஆக்குவதும் அழிக்கின்றதும் ஆகும். உயிர்களின் உடல் முடிகின்ற காலத்தில் ஐம்பூதங்களில் இருந்து வந்த உடம்பை அதிலேயே திரும்பி போகும் படி செய்வதும், உயிர்களின் உடம்புக்குள் பொருந்தி மறைந்து இருக்கின்றதும், அந்த ஆறு சக்கரங்களே ஆகும். அந்த ஆறு சக்கரங்களாக ஆகி இருப்பது ஆறு எழுத்துக்களாகும். அந்த எழுத்துக்களுக்குள் அடங்கி இருப்பது ஐம்பது தத்துவங்களாகும். இந்த ஐம்பது தத்துவங்களால் ஆகிய உடம்புக்கும் அந்த ஆறு சக்கரங்களின் எழுத்துக்களுக்கும் எல்லையாக இருப்பது ஓங்காரமே ஆகும்.`,
  },
  {
    id: 1712, tantraId: 7, verseNumber: 1711,
    tamil: `ஆயு மலரின் அணிமலர் மேலது
ஆய இதழும் பதினாறும் அங்குள
தூய அறிவு சிவானந்த மாகிப்போய்
மேய அறிவாய் விளைந்தது தானே`,
    transliteration: `āyu malariṉ aṇimalar mēlatu
āya itaḻum patiṉāṟum aṅkuḷa
tūya aṟivu civāṉanta mākippōy
mēya aṟivāy viḷaintatu tāṉē`,
    english: `1711: The Sixteen-Petalled Lotus in Visuddhi Adhara Leads to
Knowledge-Bliss
Above the discriminating heart's lotus
Is that jewelled flower
Of ten and six petals;
There, Awareness Pure, turns into Bliss of Siva
And to Jnana (Light of Knowledge) that is Reality Supreme.`,
    elaborationEnglish: `Awareness Pure (gr yaj=tuya arivu) is to be found in the 16-petalled lotus which is above the heart’s lotus. Visuddha is ‘the nerve plexus above the anahata in the neck region. It looks like a 16-petalled lotus. Its presiding deity (in, Tantrism) is the goddess Sakini’’ (“History of Tantric Religion’, p.482, N.N. Bhattacharyya). ‘‘Visuddhi Marga’’ or The Path of Purity, is the title of a famous work by Buddhaghosha’”’ (‘A popular dictionary of Buddhism’’ p.213, by Christmas Humphreys).`,
    elaborationTamil: `உயிர்களின் உலக வாழ்க்கைக்கு ஆயுள் காலத்தை வரையறுப்பது ஆறு ஆதார சக்கரங்களாகிய மலர்களாகும். அவற்றை அணிகலனாக அணிந்து இயக்குகின்ற ஆறு எழுத்துக்கள் அந்த மலர்களின் மேல் இருக்கின்றது. இவ்வாறு எழுத்துக்களால் இயக்கப் படுகின்ற ஆதார சக்கரங்களின் இதழ்களும் பதினாறு கலைகளும் அங்கேயே உள்ளது. இவற்றை சாதகத்தின் மூலம் இயக்குவதால் தூய்மை பெற்ற அறிவானது இறைவனது பேரின்பத்தை தாங்குகின்ற பாத்திரமாக ஆகி விடுகின்றது. அதன் பிறகு உலக அறிவானது மாறி இறைவனது பேரறிவு ஆக விளைய வைப்பதற்கு இந்த ஆறு ஆதார சக்கரங்களே காரணமாக இருக்கின்றன.`,
  },
  {
    id: 1713, tantraId: 7, verseNumber: 1712,
    tamil: `இலிங்கம தாவது யாரும் அறியார்
இலிங்கம தாவது எண்டிசை எல்லாம்
இலிங்கம் தாவது எண்ணெண் கலையும்
இலிங்கம தாக எடுத்தது உலகே`,
    transliteration: `iliṅkama tāvatu yārum aṟiyār
iliṅkama tāvatu eṇṭicai ellām
iliṅkam tāvatu eṇṇeṇ kalaiyum
iliṅkama tāka eṭuttatu ulakē`,
    english: `1712: Linga or Sadasiva is World manifest
They know not what Linga is
Linga is directions eight
Linga is Kalas, eight times eight
It is as Linga the world emerged.`,
    elaborationEnglish: `The eight directions and the sixteen kalas constitute the cosmic Linga. The world emerged as such.`,
    elaborationTamil: `இலிங்கம் என்பது எதுவாக இருக்கின்றது என்பதை யாரும் அறியாமல் இருக்கின்றார்கள். எட்டு திசைகளில் உள்ள அனைத்துமே இலிங்கம் ஆகும், அறுபத்து நான்கு கலைகளும் இலிங்கம் ஆகும். இறைவன் தமது அடையாளமாகிய இலிங்கமாகவே அனைத்து உலகங்களையும் உருவாக்கினான்.`,
  },
  {
    id: 1714, tantraId: 7, verseNumber: 1713,
    tamil: `உலகில் எடுத்தது சத்தி முதலா
உலகில் எடுத்தது சத்தி வடிவாய்
உலகில் எடுத்தது சத்தி குணமாய்
உலகில் எடுத்த சதாசிவன் தானே`,
    transliteration: `ulakil eṭuttatu catti mutalā
ulakil eṭuttatu catti vaṭivāy
ulakil eṭuttatu catti kuṇamāy
ulakil eṭutta catācivaṉ tāṉē`,
    english: `1713: Sakti in Sadasiva manifested as World
In the World His Sakti He manifested first,
In the World as His Sakti's Form He pervaded
In the World His Sakti's Powers He filled
But He who this World's creation conceived
Was Sadasiva (the Linga).`,
    elaborationEnglish: `Sadasiva, who as Linga originally conceived the world’s
creation, manifested in the world as His Sakti, pervaded there
as His Sakti’s form, and filled it with His Sakti’s powers.`,
    elaborationTamil: `உலகத்தில் இறைவனால் உருவாக்கப் பட்ட அனைத்தின் செயலுக்கும் மூல காரணமாக இருப்பது இலிங்கமாகும். உலகத்தில் இறைவனால் உருவாக்கப் பட்ட அனைத்தின் செயலுக்கும் வடிவமாக இருப்பது இலிங்கமாகும். உலகத்தில் இறைவனால் உருவாக்கப் பட்ட அனைத்தின் செயலுக்கும் தன்மையாக இருப்பது இலிங்கமாகும். உலகத்தில் இறைவனால் உருவாக்கப் பட்ட அனைத்துமே அசையா சக்தியாகிய சிவப் பரம்பொருளின் அடையாளமாகிய இலிங்கமே ஆகும்.`,
  },
  {
    id: 1715, tantraId: 7, verseNumber: 1714,
    tamil: `போகமும் முத்தியும் புத்தியும் சித்தியும்
ஆகமும் ஆறாறு தத்துவத்து அப்பாலாம்
ஏகமும் நல்கி இருக்கும் சதாசிவம்
ஆகம அத்துவா ஆறும் சிவமே`,
    transliteration: `pōkamum muttiyum puttiyum cittiyum
ākamum āṟāṟu tattuvattu appālām
ēkamum nalki irukkum catācivam
ākama attuvā āṟum civamē`,
    english: `1714: Sadasiva is the Adhvas too
Worldly joys and heavenly pleasures
Wisdom and miraculous powers
The body and the state beyond
The Tattvas six and thirty
All these Sadasiva granted;
The Adhvas six, too, of Agamas sacred
Are all but He--Sadasiva.`,
    elaborationEnglish: `Sadasiva created the worldly joys and heavenly pleasures,
wisdom and miraculous powers, this body of thirty-six.tattvas
and the One Beyond; and the six adhvas of Agamic conception.`,
    elaborationTamil: `வினைகளை அனுபவிப்பதற்கான சூழலையும், அந்த வினைகளை அனுபவித்து முடித்த பிறகு முக்தியையும், இறைவனை அறிவதற்கான ஞானத்தையும், அந்த ஞானத்தினால் கிடைக்கின்ற சித்திகளையும், உடலையும் மனதையும் இயக்குகின்ற முப்பத்தாறு தத்துவங்களையும் (பாடல் #467 இல் உள்ளபடி) கடந்து இருக்கின்ற அனைத்தும் தாம் ஒன்றே என்கின்ற நிலையையும், உயிர்களுக்கு கொடுத்து அருளுகின்ற பரம் பொருளே சதா சிவமாகும். அந்த பரம் பொருளை உணர்ந்து கொள்வதற்கு வழியாக ஆகமங்கள் அருளுகின்ற தத்துவங்களாக இருக்கின்ற இலிங்கமே சிவம் ஆகும்.`,
  },
  {
    id: 1716, tantraId: 7, verseNumber: 1715,
    tamil: `ஏத்தினர் எண்ணிலி தேவர்எம் ஈசனை
வாழ்த்தினர் வாசப் பசுந்தென்றல் வள்ளலென்று
ஆர்த்தினர் அண்டங் கடந்து அப் புறநின்று
காத்தனன் என்னும் கருத்தறி யாரே`,
    transliteration: `ēttiṉar eṇṇili tēvarem īcaṉai
vāḻttiṉar vācap pacunteṉṟal vaḷḷaleṉṟu
ārttiṉar aṇṭaṅ kaṭantu ap puṟaniṉṟu
kāttaṉaṉ eṉṉum karuttaṟi yārē`,
    english: `1715: Lord (Sadasiva) protects the Celestials from afar
The countless Devas gloried My Lord
"O! Southern Breeze, fragrant cool" they praised,
"O! Bounteous One," they adored,
But they know not this:
From beyond the Spaces Vast
He His protection granted.`,
    elaborationEnglish: `Though the countless celestials praise and adore Him, tlicy
know not that it is He, from beyond the vast space, who
grants them protection.`,
    elaborationTamil: `எண்ணிக்கை இல்லாத தேவர்கள் எம்பெருமானாகிய இறைவனை நறுமணமாக இருப்பவன் என்றும், பசுமையாக இருப்பவன் என்றும், மாசு மருவில்லாத பேரழகோடு இருப்பவன் என்றும், பெருங் கருணை கொண்ட வள்ளல் என்றும் போற்றி வணங்கி வாழ்த்தி கூவி அழைத்து வழிபடுகின்றார்கள். ஆயினும் அண்ட சராசரங்களாகவும் அவற்றை எல்லாம் கடந்து அதற்கு அப்பாலும் நின்று அனைத்தையும் காத்து அருளுகின்றவனாகிய அந்த இறைவனின் உண்மையான தன்மையை அவர்கள் அறிவது இல்லை.`,
  },
  {
    id: 1717, tantraId: 7, verseNumber: 1716,
    tamil: `ஒண்சுட ரோன் அயன் மால்பிர சாபதி
ஒண்சுட ரான இரவியோடு இந்திரன்
கண்சுட ராகிக் கலந்தெங்கும் தேவர்கள்
தண்சுட ராய்எங்கும் தற்பரம் ஆமே`,
    transliteration: `oṇcuṭa rōṉ ayaṉ mālpira cāpati
oṇcuṭa rāṉa iraviyōṭu intiraṉ
kaṇcuṭa rākik kalanteṅkum tēvarkaḷ
taṇcuṭa rāyeṅkum taṟparam āmē`,
    english: `1716: Lord (Sadasiva) is the Light of Life of Gods
The resplendent Brahma,
Vishnu, Prajapati
The luminous Sun and
Indra
The bright-eyed Devas swarming celestial Spheres
He, indeed, is their
Light of Life'
He the Being Uncreated.`,
    elaborationEnglish: `He is the Unborn Being who is the light of life to the three Gods, to the sun and all the celestials throughout the spheres, and to their king, Indra too.`,
    elaborationTamil: `அனைத்திலும் பொருந்தி ஒன்றாகவே இருக்கின்ற ஜோதியான இறைவனே பிரம்மனாகவும், திருமாலாகவும், உயிர்களின் தலைவனாகிய உருத்திரனாகவும், ஒன்று பட்டு இருக்கின்ற ஒளியாகிய சூரியனாகவும், தேவர்களின் தலைவனாகிய இந்திரனாகவும், அனைத்து உயிர்களின் கண்களில் இருந்து காண்கின்ற ஒளியாகவே கலந்து நிற்கின்றவனாகவும், அனைத்திலும் இருக்கின்ற தேவர்களாகவும், குளிர்ந்த ஒளியைத் தருகின்ற சந்திரனாகவும், எங்கும் பரந்து இருக்கின்றான். அவனே இலிங்க வடிவம் ஆகும்.`,
  },
  {
    id: 1718, tantraId: 7, verseNumber: 1717,
    tamil: `தாபரத் துள்நின்று அருளவல் லான்சிவன்
மாபரத் துண்மை வழிபடு வாரில்லை
மாபரத் துண்மை வழிபடு வாளர்க்கும்
பூவகத்து உள்நின்ற பொற்கொடி யாகுமே`,
    transliteration: `tāparat tuḷniṉṟu aruḷaval lāṉcivaṉ
māparat tuṇmai vaḻipaṭu vārillai
māparat tuṇmai vaḻipaṭu vāḷarkkum
pūvakattu uḷniṉṟa poṟkoṭi yākumē`,
    english: `1717: Lord is the Golden support of Heart
Pervading all Nature, Siva blesses all;
But they know not the Truth and adore Him not;
To them that adore Him that is immanent
He is the golden stalk of the heart's lotus within.`,
    elaborationEnglish: `Siva pervades -all nature and blesses all. They who do not
know this, do not adore Him. Whosoever adore Him, He is
in them. He is the golden stalk of the lotus of their heart.`,
    elaborationTamil: `பரம்பொருளாகிய இலிங்க வடிவத்திற்கு உள்ளே நின்றும் உயிர்களுக்கு அருளும் வல்லமை பெற்றவன் அருள் வடிவான இறைவன். அனைத்திற்கும் மேலான பரம்பொருளாகிய இறைவனின் உண்மையான தன்மையை உணர்ந்து அவனை அடைவதற்கான வழியில் செல்லுவதற்கு பெரும்பாலான உயிர்கள் முயற்சி செய்வது இல்லை. அவ்வாறு முயற்சி செய்கின்ற உயிர்களுக்கு அவர்களின் தலை உச்சியில் இருக்கின்ற சகஸ்ரதளத்தில் இருக்கின்ற ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரின் நடுவுக்கு உள்ளே நிற்கின்ற பொன்னாலான கொடி போன்ற சுழுமுனை நாடியின் மூலம் தன்னை அடைவதற்கான வழியில் அவர்களை கொண்டு செல்லுகின்ற சக்தியாக இறைவன் இருப்பான்.`,
  },
  {
    id: 1719, tantraId: 7, verseNumber: 1718,
    tamil: `தூவிய விமானமும் தூலமது ஆகுமால்
ஆய சதாசிவம் ஆகுநற் சூக்குமம்
ஆய பலிபீடம் பத்திர லிங்கமாம்
ஆய அரன்நிலை ஆய்ந்து கொள்வார்கட்கே`,
    transliteration: `tūviya vimāṉamum tūlamatu ākumāl
āya catācivam ākunaṟ cūkkumam
āya palipīṭam pattira liṅkamām
āya araṉnilai āyntu koḷvārkaṭkē`,
    english: `1718: Sadasiva (Linga)'s Form, manifest and subtle
The Vimana pure is the Sthula Linga
The Sadasiva enshrined is Sukshma Linga
The Bali-peeta is Bhadra Linga
Thus it is for those who Siva's Form seek.`,
    elaborationEnglish: `Those who seek Siva's form will realise that the upper part forming an arc (known as vimana) is the manifest Linga; the enshrined Sadasiva is the subtle Linga, and that the altar (bali-pita) is Siva's throne.`,
    elaborationTamil: `விமானம் என்று அழைக்கப் படுகின்ற இலிங்கத்தின் மேல் பகுதியானது {பாணம்} தீயவற்றை அழித்து உலகிற்கு நன்மையை தருகின்ற தூல வடிவமே பிரபஞ்சமாகி பிரபஞ்சத்தோடு தொடர்பு கொண்டு இருக்கின்றது. ஆதலால் இலிங்கத்தின் அடிப் பகுதியாக இருக்கின்ற {ஆவுடையார்} பரம் பொருளாகிய சிவபெருமானின் பிரபஞ்ச சக்தியாக உலகத்திற்கு நன்மையை கொடுக்கின்ற நுண்ணிய வடிவமாக இருக்கின்றது. இலிங்கத்தின் நடுப் பகுதியாக இருக்கின்ற பலி பீடமானது தம்மிடம் வேண்டி வருபவர்களை பாதுகாக்கின்ற இலிங்க வடிவமாக இருக்கின்றது. இவ்வாறு இருக்கின்ற இறைவனின் நிலையை ஆராய்ந்து அறிந்து கொள்ளுகின்ற உயிர்களால் மட்டுமே இலிங்கத்தின் உண்மையை உணர முடியும்.`,
  },
  {
    id: 1720, tantraId: 7, verseNumber: 1719,
    tamil: `முத்துடன் மாணிக்கம் மொய்த்த பவளமும்
கொத்தும்அக்கொம்பு சிலைநீறு கோமளம்
அத்தன்தன் ஆகமம் அன்னம் அரிசியாம்
உய்த்த்தின் சாதனம் பூமண லிங்கமே`,
    transliteration: `muttuṭaṉ māṇikkam moytta pavaḷamum
kottumakkompu cilainīṟu kōmaḷam
attaṉtaṉ ākamam aṉṉam ariciyām
uytttiṉ cātaṉam pūmaṇa liṅkamē`,
    english: `1719: How to fix Linga
Pearls, gems, corals and emerald
Wood of sandal, granite hard, and ashes holy
Siva's Agama, and rice in grain and cooked
When you pour in these and fix the Linga
Haunting indeed is His flavoury fragrance.`,
    elaborationEnglish: `Installation of the linga requires certain prescribed Agamic rites. When thus installed, a haunting fragrance will pervade all around.

gaps guiw That the eight universe pervades; searpu Qaeby sacs sepeod Of my heart, too, a temple made. amnw OeHad aaear ‘ Oararmn Asehiflar 1720 rt aoe ae

Of whatever material the linga is made, the temple of the How Linga is shaped Omnipresent is actually in the seeker’s heart. His form is cosmic, encompassing the earth, heaven, seas and stars; but

Curd, ghee, milk and wax pure He is the heart’s refuge.

Copper, mercury, fire and conch Bricks hard, Bilva shapely And Konrai bloom of golden hue

From these do you shape USL Lita aienrecit`,
    elaborationTamil: `முத்துக் கல்லும், மாணிக்கம் கல்லும், அவற்றுக்கு ஈடான பவளக் கல்லும், கொத்துகின்ற உளியும் அதை தட்ட உதவுகின்ற சுத்தியும் போன்ற ஆயுதங்களால் செதுக்கப் பட்ட சிலையில், திரு நீறும், கோமேதகக் கல்லும் அணிவித்து, அனைத்திற்கும் தந்தையான இறைவன் தனது உயிர்களுக்கு அருளிய சிவ ஆகமத்தில் உள்ளபடி சமைக்கப் பட்ட உணவும், சமைக்கப் படாத அரிசியும் படையலாக வைத்து, மனதை ஒருமுகப் படுத்துகின்ற கருவியாக அணிவித்த பூமாலையில் இருந்து வருகின்ற நறுமணமும் சேர்ந்து அமைக்கப் பட்டதே பரிபூரணமான சிவ இலிங்கம் ஆகும்.`,
  },
  {
    id: 1721, tantraId: 7, verseNumber: 1720,
    tamil: `துன்றும் தயிர்நெய் பால்துய்ய மெழுகுடன்
கன்றிய செம்பு கனல்இர தம்சலம்
வன்திறல் செங்கல் வடிவுடை வில்லம்பொன்
தென்தியங்கு ஒன்றை தெளிசிவ லிங்கமே`,
    transliteration: `tuṉṟum tayirney pāltuyya meḻukuṭaṉ
kaṉṟiya cempu kaṉalira tamcalam
vaṉtiṟal ceṅkal vaṭivuṭai villampoṉ
teṉtiyaṅku oṉṟai teḷiciva liṅkamē`,
    english: `1720: How Linga is shaped
Curd, ghee, milk and wax pure
Copper, mercury, fire and conch
Bricks hard, Bilva shapely
And Konrai bloom of golden hue
From these do you shape
The Linga's Form Divine.`,
    elaborationEnglish: `There are rituals to be observed in the formation of a linga, and prescribed materials for making it for worship by the different castes. For brahmins, crystal; for kings, gold, for vaisyas, emerald; and for sudras stone.`,
    elaborationTamil: `முறைப்படி பசும் பாலில் செய்த தூய்மையான தயிரும், நெய்யும், பாலும், கலப்படமில்லாத அரக்கும், இவற்றுடன் முறைப்படி புடம் போட்ட செம்பும், நெருப்பும் (விளக்கு, யாகம், போன்றவை), பழச்சாறும், தூய்மையான அபிஷேக நீரும், வலிமையாக சுடப்பட்டு இறுகிய செம்மையான கல்லும், அழகிய வடிவத்தை உடைய வில்வ இலையும், தங்கமும், மென்மையுடன் தேன் நிறைந்த அழகிய கொன்றை மலர்களும் வைத்து வழிபடுவது மனதை தெளிவு படுத்தி இறைவனை அடைவதற்கு உதவும் சிவபெருமானின் பரிபூரண இலிங்கம் ஆகும்.`,
  },
  {
    id: 1722, tantraId: 7, verseNumber: 1721,
    tamil: `மறையவர் அர்ச்சனை வண்படி கந்தான்
இறையவர் அர்ச்சனை யேயபொன் னாகும்
குறைவிலா வசியர்க்குக் கோமள மாகும்
துறையடைச் சூத்திரர் தொல்வாண லிங்கமே`,
    transliteration: `maṟaiyavar arccaṉai vaṇpaṭi kantāṉ
iṟaiyavar arccaṉai yēyapoṉ ṉākum
kuṟaivilā vaciyarkkuk kōmaḷa mākum
tuṟaiyaṭaic cūttirar tolvāṇa liṅkamē`,
    english: `1721: Lingas for the Four Varnas
Of crystal made is Linga, Brahmins worship
Of gold, the Kings worship
Of emerald, the Vaisyas worship
Of stone is Linga, Sudras worship.`,
    elaborationTamil: `வேதங்களை உச்சரித்து சாதகர்கள் பூசை செய்கின்ற போது வடிவாக அமைக்கப் பட்ட படிக இலிங்கம் தான் பெற்ற மந்திரங்களை பிரதிபலித்து நன்மை செய்யக் கூடியது ஆகும். இறைவன் மேல் பக்தியோடு சாதகர்கள் பூசை செய்கின்ற போது அந்த இலிங்கமே அவர்களின் பக்குவத்திற்கு ஏற்ற பொன் போல ஒளி வீசி அமைதியை கொடுக்கக் கூடியது ஆகும். அப்போது ஒரு குறையும் இல்லாத சாதகரின் மனதை வசீகரிக்கக் கூடிய பேரழகு பெற்ற இலிங்கமாக ஆகும். இவை எல்லாம் இறைவனை அடைவதை மட்டுமே தொழிலாக ஏற்றுக் கொண்டு அதற்கான முறைகளை அறிந்து அதன் படியே செய்கின்றவர்களுக்கு ஆதியிலிருந்தே இருக்கின்ற ஜோதி வடிவான இறைவனின் அம்சமாகவே சாதகரையும் ஜோதியாக மாற்றக் கூடிய ஒளி வடிவான இலிங்கமாக ஆகி விடும்.`,
  },
  {
    id: 1723, tantraId: 7, verseNumber: 1722,
    tamil: `அது வுணர்ந் தோன்ஒரு தன்மையை நாடி
எதுஉண ராவகை நின்றனன் ஈசன்
புதுஉணர் வான புவனங்கள் எட்டும்
இது உணர்ந்து என்னுடல் கோயில்கொண்டானே`,
    transliteration: `atu vuṇarn tōṉoru taṉmaiyai nāṭi
etuuṇa rāvakai niṉṟaṉaṉ īcaṉ
putuuṇar vāṉa puvaṉaṅkaḷ eṭṭum
itu uṇarntu eṉṉuṭal kōyilkoṇṭāṉē`,
    english: `1722: No one way of worship
They who sought Him in one Special Way
Knew Him not in any way;
And thus it is the Lord
That the eight universes pervades;
Of my heart, too, a temple made.`,
    elaborationEnglish: `They who sought Him in one special way knew Him not in any way. Thus it is that the Lord cannot be approached by any single exclusive way.`,
    elaborationTamil: `அனைத்திலும் இருக்கின்ற பரம்பொருளை ஒரு ஜோதியின் தன்மையில் உள்ள இலிங்க வடிவத்தில் தேடுவதன் மூலம் உணர்ந்து கொண்டேன். எந்த முறையினாலும் உணர்ந்து கொள்ள முடியாத வகையில் நிற்கின்ற இறைவனை ஒளி பொருந்திய இலிங்கத்தின் மூலம் உணரும் போது, இது வரை யாம் உணராத ஒரு புதுவிதமான உணர்வாக அனைத்து உலகங்களையும் சென்று அடைகின்ற தன்மையை எமக்குள் உணர்ந்த போது, அவன் எமது உடலையே தமக்கு விருப்பமான கோயிலாக ஆட்கொண்டு வீற்றிருந்தான்.`,
  },
  {
    id: 1724, tantraId: 7, verseNumber: 1723,
    tamil: `அகலிட மாய்அறி யாமல் அடங்கும்
உகலிட மாய்நின்ற ஊனதன் உள்ளே
பகலிட மாம்முனம் பாவ வினாசன்
புகலிட மாய்நின்ற புண்ணியன் தானே`,
    transliteration: `akaliṭa māyaṟi yāmal aṭaṅkum
ukaliṭa māyniṉṟa ūṉataṉ uḷḷē
pakaliṭa māmmuṉam pāva viṉācaṉ
pukaliṭa māyniṉṟa puṇṇiyaṉ tāṉē`,
    english: `1723: God is Pervasive
In the Spaces Vast, unknown He pervades,
In the fleshly body He rapturous resides,
He dispells sin and Wisdom's Sunlight spreads
He, the Holy One, that our Refuge is.`,
    elaborationTamil: `அகன்று விரிந்து இருக்கின்ற அண்ட சராசரங்களாக யாரும் அறியாத வண்ணம் அனைத்திலும் அடங்கி இருக்கின்ற பரம்பொருள் அழியக்கூடிய இடமாக நிற்கின்ற எமது உடம்பிற்கு உள்ளே எழுந்தருளினான். அப்போது இருளே இல்லாத வெளிச்சமான இடமாக எமது உடலை மாற்றி, இது வரை எமக்கு இருந்த அனைத்து விதமான பாவங்களையும் அழித்து அருள் புரிந்து, யாம் சரணாகதியாக எப்போதும் இருக்கின்ற இடமாகவே நிற்கின்றான் புண்ணியமே உருவான இலிங்க வடிவான இறைவன்.`,
  },
  {
    id: 1725, tantraId: 7, verseNumber: 1724,
    tamil: `போது புனைகழல் பூமிய தாவது
மாது புனைமுடி வானக மாவது
நீதியுள் ஈசன் உடல்விசும் பாய்நிற்கும்
ஆதியுற நின்றது அப்பரி சாமே`,
    transliteration: `pōtu puṉaikaḻal pūmiya tāvatu
mātu puṉaimuṭi vāṉaka māvatu
nītiyuḷ īcaṉ uṭalvicum pāyniṟkum
ātiyuṟa niṉṟatu appari cāmē`,
    english: `1724: Siva's Pervasive Form
The Earth is His flower-bedecked feet
The Heavens, His Ganga-girt crown
His Body fills the Spaces Vast
In continuity unbroken;
Thus did Lord His Form assume
From Time's Eternity, Beginningless First.`,
    elaborationTamil: `மலர்கள் சூடிய இறைவனின் திருவடிகள் உலகமாக இருக்கின்றது. இறைவனின் சரிபாதியாக இருக்கின்ற இறைவியானவள் கங்கை நீராக அமர்ந்து இருக்கின்ற இறைவனின் திருமுடி ஆகாயமாக இருக்கின்றது. தர்மத்தின் வடிவமாக உள்ள இறைவனின் திருமேனியானது அண்ட சராசரங்களாக நிற்கின்றது. ஆதி மூலமாகிய இறைவனுக்கு ஏற்ற வகையில் நின்றது அவன் அருளிய பரிசாகிய இலிங்கமே ஆகும்.`,
  },
  {
    id: 1726, tantraId: 7, verseNumber: 1725,
    tamil: `தரையுற்ற சத்தி தனிலிங்கம் விண்ணாம்
திரைபொரு நீரது மஞ்சன சாலை
வரைதவழ் மஞ்சுநீர் வானுடு மாலை
கரையற்ற நந்திக் கலையும்திக்காமே`,
    transliteration: `taraiyuṟṟa catti taṉiliṅkam viṇṇām
tiraiporu nīratu mañcaṉa cālai
varaitavaḻ mañcunīr vāṉuṭu mālai
karaiyaṟṟa nantik kalaiyumtikkāmē`,
    english: `1725: Siva's Cosmic Form
The Earth is His Sakti Peeta,
The Heavens the Linga Pure,
The billowing seas His bathing ghat,
The cascading streams on mountain tops
Their cool water laves His crown heavenly,
The countless stars, His garland;
The Eight Directions His limitless raiment.`,
    elaborationTamil: `நிலத்தில் வீற்றிருக்கும் இறைவியானவள் இறைவனுக்கு சரிசமமாக இருக்கின்ற இலிங்க வடிவத்தின் அடிப் பாகத்தில் ஆகாயமாக இருக்கின்றாள். அலை மிகுந்த கடல்களில் இருக்கின்ற நீர்கள் எல்லாம் இறைவனுக்கு அபிஷேகமாக சாற்றிக் கொண்டே இருக்கின்றது. மலை உச்சியில் தவழ்கின்ற மேகங்களிலுள்ள தூய்மையான நீர் இறைவனினுக்கு நித்ய தீர்த்தமாக அபிஷேகம் செய்து கொண்டே இருக்கின்றது. வானத்தில் உள்ள நட்சத்திரங்கள் எல்லாம் இறைவனின் திருமார்பில் அணிகின்ற மாலையாக இருக்கின்றது. எல்லை இல்லாத குருநாதராகிய இறைவனின் ஆடையாக அனைத்து திசைகளும் இருக்கின்றது.`,
  },
  {
    id: 1727, tantraId: 7, verseNumber: 1726,
    tamil: `மானுடர் ஆக்கை வடிவு சிவலிங்கம்
மானுடர் ஆக்கை வடிவு சிதம்பரம்
மானுடர் ஆக்கை வடிவு சதாசிவம்
மானுடர் ஆக்கை வடிவு திருக்கூத்தே`,
    transliteration: `māṉuṭar ākkai vaṭivu civaliṅkam
māṉuṭar ākkai vaṭivu citamparam
māṉuṭar ākkai vaṭivu catācivam
māṉuṭar ākkai vaṭivu tirukkūttē`,
    english: `1726: Human form is Siva Linga
The Human Form is unto Siva Lingam
The Human Form is unto Chidambaram
The Human Form is unto Sadasivam
The Human Form is unto the Holy Dance, forsooth.`,
    elaborationEnglish: `The human form itself is verily a Siva Lingam. It is
Chidambaram, Sadasivam and the Holy Dance Hall as well.`,
    elaborationTamil: `இறைவனின் அடையாளமாகிய சிவ இலிங்கமே உயிர்களின் உடம்பின் வடிவமாகவும், சித் (சித்தமாகிய) + அம் (ஆகாயத்தில்) + பரம் (வீற்றிருக்கின்ற பரம்பொருள்) = சிதம்பரமே உயிர்களின் உடலுக்குள் இருக்கின்ற எண்ணங்களாகவும், அசையா சக்தியாகிய பரம்பொருளே உயிர்களின் உடம்பிற்குள் இருக்கின்ற ஆன்மாவாகவும், இறைவன் ஆடுகின்ற திருக்கூத்தே உயிர்களின் உடலில் இருக்கின்ற அசைவுகளாகவும் இருக்கின்றது.`,
  },
  {
    id: 1728, tantraId: 7, verseNumber: 1727,
    tamil: `உலந்திலர் பின்னும் உளரென நிற்பர்
நிலந்திரு நீர்தெளி யூனவை செய்யப்
புலந்திரு பூதங்கள் ஐந்தும் ஒன்றாக
வலந்தரு தேவரை வந்திசெய் யீரே`,
    transliteration: `ulantilar piṉṉum uḷareṉa niṟpar
nilantiru nīrteḷi yūṉavai ceyyap
pulantiru pūtaṅkaḷ aintum oṉṟāka
valantaru tēvarai vanticey yīrē`,
    english: `1727: Desire for Births persists
Tired they are not;
Still they want to live
In this fleshly body,
Of earth, water and other matter made;
They seek not to adore Lord
Whom the Elements Five
Together in prayer beseech.`,
    elaborationEnglish: `Like a mother, He affectionately took charge of the senses and became their master. The several nadis that are within the body prostrate at Nandi's feet who subdued the senses, even as all the Vedas do.`,
    elaborationTamil: `இந்த பிறவிக்கான வினைகள் தீர்ந்து இறந்து போன பிறகும் இனியும் பிறவி வேண்டும் என்று இன்னமும் தீர்க்க வேண்டிய வினைகளை அனுபவிக்க நிற்பார்கள். அவர்களுக்கு தேவையான உடலை நிலத்தை தருகின்ற நீரினால் தெளிந்து உருவாகிய உணவினால் வளர்கின்ற தசையும் அவர்களுக்கு ஏற்ற வடிவத்தை செய்து கொடுக்கும். அவர்களின் உயிர் இருக்கின்ற இடமாகிய உடம்பை தருகின்ற பஞ்ச பூதங்களாகிய நிலம், நீர், நெருப்பு, காற்று, ஆகாயம் ஆகிய ஐந்தும் ஒன்று சேர்ந்து கொடுக்கும். அந்த உடம்பிற்குள் நிகழ்கின்ற அனைத்து இயக்கங்களையும் தருகின்ற தேவர்களை வணங்கி வழிபடுவதை செய்யுங்கள். கருத்து: உயிர்களின் உடம்பாக இருப்பதே இறைவனின் சிவ இலிங்கமாகும். அதற்குள் இறைவனாகவே இருக்கின்ற அனைத்து தேவர்களும் இருக்கின்றார்கள். ஆகவே உயிர்களின் உடம்பையே கோயிலாக வணங்கி வந்தால் இனி பிறவி இல்லாத நிலையை அடையலாம். பாடல் #1823 இல் வருகின்ற “உள்ளம் பெருங்கோயில் ஊனுடம்பு ஆலயம்” என்கிற வாசகம் இந்த பொருளையே குறிக்கின்றது.`,
  },
  {
    id: 1729, tantraId: 7, verseNumber: 1728,
    tamil: `கோயில்கொண் டன்றே குடிகொண்ட ஐவரும்
வாயில்கொண் டாங்கே வழிநின் றருளுவர்
தாயில்கொண் டாற்போல் தலைவன்என் உட்புக
வாயில்கொண் டு ஈசனும் ஆளவந் தானே`,
    transliteration: `kōyilkoṇ ṭaṉṟē kuṭikoṇṭa aivarum
vāyilkoṇ ṭāṅkē vaḻiniṉ ṟaruḷuvar
tāyilkoṇ ṭāṟpōl talaivaṉeṉ uṭpuka
vāyilkoṇ ṭu īcaṉum āḷavan tāṉē`,
    english: `1728: Lord is Master of the sense gates of body
The day the Lord entered this body tabernacle
The Five Senses who their places had taken
Opened the gates;
And showed you the way of redemption;
As unto the mother's home
He in me entered;
And taking charge of the gates, Master became.`,
    elaborationEnglish: `In spite of cycles of birth, men seek not the Lord who opens the sense gates composed of the five elements. These elements within themselves seek Him, and yet men do not seek Him within.`,
    elaborationTamil: `உயிர்கள் பிறப்பு எடுக்கும் போதே அவற்றை தாம் இருக்கும் கோயிலாகவே படைக்கின்றான் இறைவன். அப்படி உயிர்கள் கோயிலாக உடலெடுத்து பிறக்கும் போதே ஐந்து தெய்வங்களும் தத்தமது தொழில்களுடன் ஐந்து பூதங்களாகவும் புலன்களாகவும் நின்று அந்த புலன்கள் நுழைகின்ற இடமாக உயிர்களின் உடலை ஏற்றுக் கொண்டு அதன் வழியாகவே நின்று அருளுகின்றனர். உயிர்கள் எப்போது புலன்களின் வழியே வாழ்வதை விட்டு விட்டு குழந்தை தாயை தேடி அழுவது போல இறைவனை தேடுகின்றார்களோ அப்போது குழந்தை இருக்கும் இடம் தேடி தாய் தானாகவே வருவது போல இறைவனும் தலைவனாகவே அந்த அடியவரின் உடலுக்கு உள்ளே இருந்து அடியவரை ஆட்கொண்டு அடியவரின் உடலையே தாம் வாழுகின்ற இடமாக கொண்டு வீற்றிருந்து அருளுவான். ஐவர்கள்: ஐந்து தெய்வங்கள் – ஐந்து தொழில்கள் – பஞ்ச பூதங்கள் – ஐந்து பொறிகள் – ஐந்து புலன்கள் பிரம்மன் – படைத்தல் – நிலம் – மூக்கு – நுகர்தல் திருமால் – காத்தல் – நீர் – நாக்கு – சுவைத்தல் உருத்திரன் – அழித்தல் – நெருப்பு – கண் – பார்த்தல் மகேஸ்வரன் – மறைத்தல் – காற்று – தோல் – உணர்தல் சதாசிவன் – அருளல் – ஆகாயம் – காது – கேட்டல்`,
  },
  {
    id: 1730, tantraId: 7, verseNumber: 1729,
    tamil: `கோயில்கொண் டான்அடி கொல்லைப் பெருமறை
வாயில்கொண் டான்அடி நாடிகள் பத்துள
பூசைகொண் டான்புலன் ஐந்தும் பிறகிட்டு
வாயில்கொண் டான் எங்கள் மாநந்தி தானே`,
    transliteration: `kōyilkoṇ ṭāṉaṭi kollaip perumaṟai
vāyilkoṇ ṭāṉaṭi nāṭikaḷ pattuḷa
pūcaikoṇ ṭāṉpulaṉ aintum piṟakiṭṭu
vāyilkoṇ ṭāṉ eṅkaḷ mānanti tāṉē`,
    english: `1729: Lord opens the sense gates
At the Feet of the Lord
Who this body as His temple chose
Lies the forest of Vedas;
At the Feet of the Lord
Who these gates made His own
Lie the Nadis ten;
He who, our adoration received
Subduing our senses five
In me entered operating the gates wide;
He, My Lord, the Nandi Great.`,
    elaborationTamil: `அழுக்குகளை மட்டுமே கொண்டு தசைகளால் மூடப்பட்டு இருக்கின்ற உயிர்களின் உடலையே தாம் வீற்றிருக்கும் கோயிலாக ஆட்கொண்ட இறைவன் தமது திருவடிகளால் அந்த உடலில் இருக்கின்ற பத்து விதமான நாடிகளின் இயக்கத்தையே தமக்கு செய்கின்ற பூசையாக ஏற்றுக் கொண்டு தமது திருவடிகளின் அருளாலேயே அந்த உடலில் இருக்கின்ற அனைத்து அழுக்குகளையும் நீக்கி, ஒழுங்கு படுத்தி, சுத்தம் செய்து, அந்த உடலைக் கொண்ட அடியவரை தம்மை நோக்கி வழி நடத்திச் செல்கின்ற மாபெரும் குருநாதனாக அவரின் உடலுக்குள் வீற்றிருக்கின்றான். பத்து நாடிகள் – வியாபித்து இருக்கும் இடங்கள் இடகலை – இடது நாசி பிங்கலை – வலது நாசி சுழிமுனை – நடு முதுகெலும்பு புருஷன் – பிறப்பு உறுப்பு காந்தாரி – இடது கண் அத்தி – வலது கண் அலம்புடை – நாக்கு சங்கினி – தலை சிங்குவை – இடது கை குரு – வலது கை`,
  },
  {
    id: 1731, tantraId: 7, verseNumber: 1730,
    tamil: `கூடிய பாதம் இரண்டும் படிமிசை
பாடிய கையிரண்டு எட்டுப் பரந்தெழும்
தேடு முகம்ஐந்து செங்கையின் மூவைந்து
நாடும் சதாசிவம் நல்லொளி முத்தே`,
    transliteration: `kūṭiya pātam iraṇṭum paṭimicai
pāṭiya kaiyiraṇṭu eṭṭup paranteḻum
tēṭu mukamaintu ceṅkaiyiṉ mūvaintu
nāṭum catācivam nalloḷi muttē`,
    english: `1730: Sadasiva form with Five Faces
His twin Feet are planted on earth below;
The ten hands, the holy in praise sing,
In directions all spread;
Five His Faces that are sought,
Five times three his eyes fiery;
Thus is Sadasiva that you seek
The Pearl that is lustrous, beyond, beyond compare.`,
    elaborationEnglish: `Sadasiva, whom we seek and whom the holy praise in songs, is a lustrous pearl beyond comparison. He has His Two Feet on the earth, ten hands spread in ten directions, and fifteen fiery eyes glowing on His five faces.`,
    elaborationTamil: `அனைத்திற்கும் மேலான சிவப் பரம்பொருளாகிய சதாசிவமூர்த்தியின் திருவுருவமானது அடியவர்களை மேல் நிலைக்கு கொண்டு செல்லும் இணைந்தே இருக்கின்ற இரண்டு திருவடிகளைக் கொண்டும், பத்து திசைகளுக்கும் பரந்து எட்டுகின்ற பத்து திருக்கரங்களைக் கொண்டும், ஐந்து திருமுகங்களைக் கொண்டும், அந்த ஐந்து திருமுகங்களிலும் முகத்திற்கு மூன்றாக மொத்தம் பதினைந்து திருக்கண்களைக் கொண்டும், ஒப்பில்லாத முத்துப் போல பிரகாசமான ஒளி வீசும் ஜோதி அம்சமாகவும் இருக்கின்றது. உருவமே இல்லாத இறைவனுக்கு இப்படி அடியவர்கள் காணக்கூடிய அருவுருவமான வடிவமாக இருப்பதே சதாசிவ இலிங்கம் ஆகும். கருத்து: சதாசிவ மூர்த்தியின் அருவுருவத் திருவடிகளானது தம்மை சரணடைகின்ற அடியவர்களின் பந்த பாசங்களை அறுக்கின்றது ஆகும். சதாசிவ மூர்த்தியின் அருவுருவத் திருக்கரங்களானது அவர் இருக்கின்ற இடத்திலிருந்தே தம்மை வேண்டுகின்ற அடியவர்கள் இருக்கின்ற இடம் வரை பத்து திசைகளிலும் பரந்து வந்து அபயமும் ஐஸ்வர்யமும் அருளுவது ஆகும்.சதாசிவ மூர்த்தியின் அருவுருவத் திருக்கண்களானது தகுதியான அடியவர்களின் பாவங்களை பார்வையாலே நீக்குகின்றது ஆகும். சதாசிவ மூர்த்தியின் அருவுருவப் பிரகாசமான ஜோதி வடிவமானது காண்கின்றவர்களை கவர்கின்ற நல்ல முத்தைப் போல் அடியவர்களை தம்மை நோக்கி ஈர்க்கின்றது ஆகும்.`,
  },
  {
    id: 1732, tantraId: 7, verseNumber: 1731,
    tamil: `வேதா நெடுமால் உருத்திரன் மேலீசன்
மீதான ஐம்முகன் விந்துவும் நாதமும்
ஆதார சத்தியும் அந்தச் சிவனொடும்
சாதா ரணமாம் சதாசிவந் தானே`,
    transliteration: `vētā neṭumāl uruttiraṉ mēlīcaṉ
mītāṉa aimmukaṉ vintuvum nātamum
ātāra cattiyum antac civaṉoṭum
cātā raṇamām catācivan tāṉē`,
    english: `1731: Sadasiva comprehends all Nine God-Forms
Brahma, Vishnu, Rudra, Mahesa,
And the Five-faced Lord above,
Bindu, Nada, Sakti Primal, and Siva
--All these are but Sadasiva in general.`,
    elaborationTamil: `வேதங்களை ஓதி படைக்கின்ற பிரம்மன், அனைத்தையும் காக்கின்ற திருமால், மாயையை அழிக்கின்ற உருத்திரன் ஆகிய மும்மூர்த்திகளும், அவர்களுக்கு மேல் இருக்கின்ற மாயையால் மறைக்கின்ற மகேஸ்வரன், அடியவருக்கு அருளுகின்ற சதாசிவன் ஆகியவரோடு சேர்த்து ஐந்து விதமான தொழில்களை செய்கின்ற தெய்வங்களும், அவர்களுக்கு மேல் வெளிச்சமாகவும் சத்தமாகவும் அவர்கள் அனைவருக்கும் ஆதார சக்தியாகிய பராசக்தியும், ஆதியாகிய பரமசிவனும் ஆகிய இந்த அனைத்து தெய்வ நிலைகளுக்கும் பொதுவானதாகவும் அனைத்திற்கும் மேலானதாகவும் அன்பே வடிவமாகவும் இலிங்க அடையாளம் கொண்டும் இருப்பதே சதாசிவப் பரம்பொருள் ஆகும்.`,
  },
  {
    id: 1733, tantraId: 7, verseNumber: 1732,
    tamil: `ஆகின்ற சத்தியின் உள்ளே கலைநிலை
ஆகின்ற சத்தியின் உள்ளே கதிரெழ
ஆகின்ற சத்தியின் உள்ளே அமர்ந்தபின்
ஆகின்ற சத்தியுள் அத்திசை பத்தே`,
    transliteration: `ākiṉṟa cattiyiṉ uḷḷē kalainilai
ākiṉṟa cattiyiṉ uḷḷē katireḻa
ākiṉṟa cattiyiṉ uḷḷē amarntapiṉ
ākiṉṟa cattiyuḷ atticai pattē`,
    english: `1732: When Sakti Evolutes
Within the Becoming Sakti the Kalas repose
Within the Becoming Sakti their rays emanate
Within the Becoming Sakti the Lord His seat takes
Within the Becoming Sakti the directions ten as Space appears.`,
    elaborationEnglish: `The kalas repose within Sakti; their rays emanate from Sakti. After the Lord activates Sakti, the ten directions appear from Her.`,
    elaborationTamil: `அசையாத சக்தியாகிய சதாசிவப் பரம்பொருளில் எண்ண அலைகள் உருவாகின்ற போது அந்த அசைவினால் வெளிப்படுகின்ற அசையும் சக்திக்கு உள்ளே உலக இயக்கத்திற்கு தேவையான ஐந்து விதமான கலைகளாகிய படைத்தல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய ஐந்தும் நிலை பெறும். அதற்குள்ளிருந்து வெளிச்சமாகிய சக்தி எழுந்து வரும் போது அதனுள் சத்தமாகிய சிவமும் அமரும். அதற்குள்ளேயே அண்ட சராசரங்களும் அதிலிருக்கும் பத்து திசைகளும் அடங்கி இருக்கும்.`,
  },
  {
    id: 1734, tantraId: 7, verseNumber: 1733,
    tamil: `அத்திசைக் குள்ளே அமர்ந்தன ஆறங்கம்
அத்திசைக் குள்ளே அமர்ந்தன நால்வேதம்
அத்திசைக் குள்ளே அமர்ந்த சரியையோடு
அத்திசைக் குள்ளே அமர்ந்த சமயமே`,
    transliteration: `atticaik kuḷḷē amarntaṉa āṟaṅkam
atticaik kuḷḷē amarntaṉa nālvētam
atticaik kuḷḷē amarnta cariyaiyōṭu
atticaik kuḷḷē amarnta camayamē`,
    english: `1733: When Sakti further Devolutes
In that Space thus opened up
The Six Vedangas took their place;
In that Space thus opened up
The Four Vedas took their place;
In that Space thus opened up
The Four Paths beginning with Chariya
Took their place;
In that Space thus opened up
The Saiva Truth the Four Paths comprehended
Took its place.`,
    elaborationEnglish: `When Sakti further evolves, opening up space; the four Vedas, the six Vedangas, the four paths of Chariya, Kriya, Yoga and Jnana comprehended by Saivism — all took their places.`,
    elaborationTamil: `அண்ட சராசரங்களில் உள்ள பத்து திசைகளுக்கு உள்ளே பாடல் #55 இல் உள்ளபடி வேதத்தின் ஆறு அங்கங்களாகிய சிட்சை, வியாகரணம், சந்தம், சோதிடம், நிருக்தம், கல்பம் ஆகியவையும், நான்கு வேதங்களாகிய ரிக்கு, சாமம், யஜூர், அதர்வணம் ஆகியவையும், இறைவனை அடையும் நான்கு வழிமுறைகளான சரியை, கிரியை, யோகம், ஞானம் ஆகியவையும், பாடல் #994 இல் உள்ளபடி இறைவனை அடையும் ஆறு சமயங்களாகிய தியானம், செபம், பூஜை, சக்கரம், ஞானம், புத்தி ஆகியவையும் அமர்ந்து இருக்கின்றன. வேதத்தின் ஆறு அங்கங்கள்: சிட்சை – வேதத்தின் எழுத்து மற்றும் ஒலி முதலியவற்றைப் பற்றிச் சொல்வது. வியாகரணம் – சொற்களின் இலக்கணத்தை ஆராய்வது. சந்தம் – செய்யுள் இலக்கணம் பற்றிச் சொல்வது. சோதிடம் – கோள் நிலைகளை வைத்து காலத்தை ஆராய்வது. நிருக்தம் – வேதச் சொற்களுக்கு பொருள் கூறுவது. கல்பம் – வேதத்தின் செயல் முறைகளை உரைப்பது. நான்கு வேதங்கள்: ரிக்கு – தெய்வங்களை போற்றி வணங்குகின்ற மந்திரங்களைக் கொண்டது. யஜூர் – தெய்வங்களை யாகம் செய்து வழிபடும் முறைகளைக் கொண்டது. சாமம் – இசை மூலம் இறைவனை போற்றும் பாடல்களைக் கொண்டது. அதர்வணம் – தெய்வ சக்திகளை உபயோகித்து பாதுகாத்துக் கொள்கின்ற மந்திரங்களைக் கொண்டது. இறைவனை அடையும் நான்கு வித வழிகள்: சரியை – கோயில்கள் செல்வது, பூஜைகள் செய்வது. (பக்தி யோகம்) கிரியை – மந்திரம் சொல்லி சக்கரங்கள் வைத்து வழிபடுவது. (கர்ம யோகம்) யோகம் – தியானம், தவம் செய்வது. (இராஜ யோகம்) ஞானம் – அனைத்திற்கும் மேலான நிலையில் சலனங்கள் இன்றி இருப்பது. (ஞான யோகம்) இறைவனை அடையும் ஆறு வித சமயங்கள்: தியானம் – மந்திரத்தை மனதிற்குள் தியானித்தல். செபம் – அக வழிபாடு மூலம் செபித்தல். பூஜை – புற வழிபாடு மூலம் செபித்தல். சக்கரம் – சக்கரங்கள் அமைத்து செபித்தல். ஞானம் – மந்திரத்தின் பொருளை தேடி ஆராய்ந்து அறிந்து கொள்ளுதல். புத்தி – மந்திரத்தின் ஒவ்வொரு எழுத்தையும் ஆராய்ந்து அறிந்து கொள்ளுதல்.`,
  },
  {
    id: 1735, tantraId: 7, verseNumber: 1734,
    tamil: `சமயத்து எழுந்த அவத்தையீர் ஐந்துள
சமயத்து எழுந்த இராசி ஈராறுள
சமயத்து எழுந்த சரீரம்ஆ றெட்டுள
சமயத்து எழுந்த சதாசிவந் தானே`,
    transliteration: `camayattu eḻunta avattaiyīr aintuḷa
camayattu eḻunta irāci īrāṟuḷa
camayattu eḻunta carīramā ṟeṭṭuḷa
camayattu eḻunta catācivan tāṉē`,
    english: `1734: Sakti Devolutes still further
In that Truth arose the Avastas (States of Awareness) twice five;
In that Truth arose the Rasis (Zodiacal houses) twice six
In that Truth arose the Tattvas (Body Constituents) twice forty-eight;
In that Truth arose the Sadasiva Supreme.`,
    elaborationEnglish: `From Sakti evolving still further in Siva Truth, arose the ten States of consciousness (avasthas), the twelve zodiacal houses (rasis), the ninety six universals (tattvas) and the Sadasiva.`,
    elaborationTamil: `இறைவனை அடைவதற்கான ஆறு விதமான வழிகளாகிய சமயங்களிருந்து எழுவது ஆன்மாக்கள் அனுபவிக்க வேண்டியதாகிய ஐந்து விதமான மேலாலவத்தைகளும், ஐந்து விதமான கீழாலவத்தைகளும், 12 இராசிகளும், இறையருளால் கிடைக்கக் கூடிய 16 விதமான பேறுகளும் உள்ளது. இந்த சமயங்கள் அனைத்தும் சதா சிவப் பரம்பொருளே ஆகும்.`,
  },
  {
    id: 1736, tantraId: 7, verseNumber: 1735,
    tamil: `நடுவு கிழக்குத் தெற்குஉத் தரமேற்கு
நடுவு படிகநற் குங்குமவன்னம்
அடைவுள அஞ்சனம் செவ்வரத் தம்பால்
அடியேற்கு அருளிய முகம்இவை அஞ்சே`,
    transliteration: `naṭuvu kiḻakkut teṟkuut taramēṟku
naṭuvu paṭikanaṟ kuṅkumavaṉṉam
aṭaivuḷa añcaṉam cevvarat tampāl
aṭiyēṟku aruḷiya mukamivai añcē`,
    english: `1735: The Five Faces of Sadasiva and their Hues
Central, East, South,
North and West
These the Five Faces of
Sadasiva;
The Central Face is of crystal hue;
The Eastward Face is crimson unto Kum-Kum
The Southward Face is dark unto thick pitch
The Northward Face is red unto Aratham flower
The Westward Face is white unto milky hue;
Thus did He reveal unto me,
His lowly vassal.`,
    elaborationEnglish: `Sadasiva revealed His Five Faces of five’ different hues to this lowly vassal (Tirumular)—the central Face, Isana, of crystal color; the eastward Face, Tatpurusha, crimson; the southward Face, Aghora pitch dark; the northwayl Face, Vama, red and the westward Face, Sadyojata, milky white.

1) Kum-Kum—a crimson paint formed of tumeric, alum, lime juice, and also saffron or yellow color. 2) Aratham—red water lily flower, also red coral.`,
    elaborationTamil: `தம்மை வணங்கும் அடியவர்களுக்காக இறைவன் அருளிய திருமுகங்கள் ஐந்தாகும். இவை முறையே நடுவில் மேல் நோக்கி இருக்கின்ற ஈசானம் முகம், கிழக்கு நோக்கி இருக்கின்ற தற்புருடம் முகம், தெற்கு நோக்கி இருக்கின்ற அகோரம் முகம், வடக்கு நோக்கி இருக்கின்ற வாமதேவம் முகம், மேற்கு நோக்கி இருக்கின்ற சத்தியோசாதம் முகம் ஆகும். ஈசானம் முகம் படிக நிறத்திலும், தற்புருடம் முகம் நல்ல குங்கும நிறத்திலும், அகோரம் முகம் கருப்பு நிறத்திலும், வாமதேவம் முகம் செம்மையான அரத்தம் பூவைப் பொன்ற சிகப்பு நிறத்திலும், சத்தியோசாதம் முகம் பாலைப் போன்ற வெண்மையான நிறத்திலும் இருக்கின்றது.`,
  },
  {
    id: 1737, tantraId: 7, verseNumber: 1736,
    tamil: `அஞ்சு முகமுள ஐம்மூன்று கண்ணுள
அஞ்சினொ டுஅஞ்சு கரதலம் தானுள
அஞ்சுடன் அஞ்சா யுதமுள நம்பியென்
நெஞ்சு புகுந்து நிறைந்துநின் றானே`,
    transliteration: `añcu mukamuḷa aimmūṉṟu kaṇṇuḷa
añciṉo ṭuañcu karatalam tāṉuḷa
añcuṭaṉ añcā yutamuḷa nampiyeṉ
neñcu pukuntu niṟaintuniṉ ṟāṉē`,
    english: `1736: Sadasiva's Form
Five His Faces; thrice five His eyes;
Twice Five His hands number,
Five and Five Weapons He holds;
Thus my dear Lord, my heart entered
And in fullness pervaded.`,
    elaborationEnglish: `Entering in me with His Five Faces, fifteen eyes and ten hands,
holding weapons in them all, Sadasiva pervaded within me
in fullness.`,
    elaborationTamil: `சதா சிவப் பரம்பொருளுக்கு ஐந்து திருமுகங்கள் உள்ளது. அந்த ஐந்து திருமுகங்களிலும் முகத்திற்கு மூன்றாக மொத்தம் பதினைந்து திருக்கண்கள் உள்ளது. அவருக்கு பத்து திருக்கரங்கள் உள்ளது. அந்த பத்து திருக்கரங்களிலும் பத்து விதமான ஆயுதங்கள் தம் அடியவரைக் காக்கின்ற கருவிகளாக உள்ளது. இவ்வாறு சதாசிவ இலிங்கமாக இருக்கின்ற இறைவன் தம்மை நம்புகின்ற அடியவர்களின் நெஞ்சத்திற்கு உள்ளே புகுந்து முழுவதுமாக நிறைந்து நிற்கின்றான்.`,
  },
  {
    id: 1738, tantraId: 7, verseNumber: 1737,
    tamil: `சத்தி தராதலம் அண்டம் சதாசிவம்
சத்தி சிவமிக்க தாபர சங்கமம்
சத்தி உருவம் அருவம் சதாசிவம்
சத்தி சிவதத்துவ முப்பத் தாறே`,
    transliteration: `catti tarātalam aṇṭam catācivam
catti civamikka tāpara caṅkamam
catti uruvam aruvam catācivam
catti civatattuva muppat tāṟē`,
    english: `1737: Sakti is the Kinetic and Siva the potential Aspects of
God-head
Sakti is this wide world
Sakti is this universe vast
Sakti-Siva conjoint is the Kinetic and Potential
Sakti is the Formed;
Siva the Formless;
Sakti-Siva Tattvas are six and thirty true.`,
    elaborationEnglish: `Sakti is this wide world and the infinite universe. She has form. Siva is formless. Conjointly Sakti and Siva are the and the potential aspects. Out of them arose the thirty-six tattvas.`,
    elaborationTamil: `சக்தி பூமியாகிய நிலத்திலும் சதாசிவப் பரம்பொருள் அண்டமாகிய ஆகாயத்தில் இருக்கின்றார்கள். சக்தியும் சதாசிவப் பரம்பொருளும் பரிபூரணமாக சதாசிவ இலிங்கத்தில் ஒன்றாக சேர்ந்து இருக்கின்றார்கள். சக்தி உருவமாகவும் சதாசிவப் பரம்பொருள் அருவமாகவும் இருக்கின்றார்கள். சக்தியும் சிவமும் முப்பத்தாறு தத்துவங்களாகவும் இருக்கின்றார்கள்.`,
  },
  {
    id: 1739, tantraId: 7, verseNumber: 1738,
    tamil: `தத்துவ மாவது அருவம் சராசரம்
தத்துவ மாவது உருவம் சுகோதயம்
தத்துவம் எல்லாம் சகலமு மாய்நிற்கும்
தத்துவம் ஆகும் சதாசிவம் தானே`,
    transliteration: `tattuva māvatu aruvam carācaram
tattuva māvatu uruvam cukōtayam
tattuvam ellām cakalamu māyniṟkum
tattuvam ākum catācivam tāṉē`,
    english: `1738: Sadasiva is Tattva (Truth) Real
Formless is the Tattva primal
Formed, it is the world, animate and inanimate;
A source of pleasure then indeed it is;
Tattva is all and pervasive,
Sadasiva is Tattva (Truth) Real.`,
    elaborationEnglish: `Tattva (basic truth) is primal, pervasive and formless. Sadasiva is real tattva. When in form, that is when the thirty-six fundamental principles of existence devoluted from maya, Sadasiva is the animate and inanimate world, and the source of all bhoga.

1) Tattva means two things: i) basic truth; ii) the 36 fundamental principles of existence.`,
    elaborationTamil: `உருவம் இல்லாமல் அசையும் பொருள் அசையாத பொருள் என்று அனைத்திலும் இருப்பதும், உலகத்திலுள்ள அனைத்து உயிர்களுக்கும் உருவம் கொடுத்து அவை இன்ப துன்பங்களை அனுபவிப்பதற்கு ஆதாரமாக இருப்பதும், அண்ட சராசரங்களில் இருக்கும் அனைத்துமாகவும் இருப்பதே முப்பத்தாறு தத்துவங்களாகும். இந்த முப்பத்தாறு தத்துவங்களாகவும் இருப்பது சதா சிவப் பரம்பொருளே ஆகும்.`,
  },
  {
    id: 1740, tantraId: 7, verseNumber: 1739,
    tamil: `கூறுமின் ஊறு சதாசிவன் எம்இறை
வேறோர் உரைசெய்து மிகைப்பொரு ளாய்நிற்கும்
ஏறுரை செய்தொழில் வானவர் தம்மொடு
மாறுசெய் வான் என் மனம்புகுந் தானே`,
    transliteration: `kūṟumiṉ ūṟu catācivaṉ emiṟai
vēṟōr uraiceytu mikaipporu ḷāyniṟkum
ēṟurai ceytoḻil vāṉavar tammoṭu
māṟucey vāṉ eṉ maṉampukun tāṉē`,
    english: `1739: Sadasiva is Our Lord
"Sadasiva is our Lord"--
Say this times hundred;
Anything else you try to say,
He will still be beyond it;
He suffers not those Gods`,
    elaborationEnglish: `Sadasiva has entered into my heart. He is there above all other gods. Repeat one hundred times that Sadasiva is our Lord. He is beyond whatever else is said.`,
    elaborationTamil: `எடுத்துக் கூறினால் உணர்வுப் பூர்வமாக அறிந்து கொள்கின்ற சதா சிவப் பரம்பொருளே எமது இறைவனாகும். அவனே வேறு வேறு விதங்களில் பல விதமாக திருவிளையாடல்கள் செய்து அனைத்திற்கும் மேலான பொருளாகவும் நிற்கின்றான். உலகத்தில் தவத்திலும் தானத்திலும் சிறந்து அதன் பயனால் மேலான நிலைக்கு சென்று உலக இயக்கத்திற்காக பல தொழில்களை புரிகின்ற வானவர்கள் அனைவரோடும் சேர்ந்து இருந்து தீயவற்றை மாற்றி நன்மையை அருளுவதை செய்கின்றான் எமது மனதில் புகுந்தான் சதாசிவ இலிங்க வடிவமாக இருக்கின்ற இறைவன்.`,
  },
  {
    id: 1741, tantraId: 7, verseNumber: 1740,
    tamil: `இருளார்ந்த கண்டமும் ஏந்து மழுவும்
சுருளார்ந்த செஞ்சடைச் சோதிப் பிறையும்
அருளார்ந்த சிந்தையெம் ஆதிப் பிரானைத்
தெருளார்ந்தென் உள்ளே தெளிந்திருந் தேனே`,
    transliteration: `iruḷārnta kaṇṭamum ēntu maḻuvum
curuḷārnta ceñcaṭaic cōtip piṟaiyum
aruḷārnta cintaiyem ātip pirāṉait
teruḷārnteṉ uḷḷē teḷintirun tēṉē`,
    english: `1740: Muse on Sadasiva's Form
The dark throat, the up-lifted axe,
The matted red locks, the radiant crescent moon,
The Primal Lord that is Grace abounding,
Him I mused, all dark doubts dispelled.`,
    elaborationEnglish: `Bereft of doubts, I meditated on the abundantly graceful
Primal Lord of dark throat, wearing the radiant crescent moon
on His matted russet locks, and holding the axe in His hand.`,
    elaborationTamil: `ஆலகால விஷத்தை அருந்தியதால் கருமை நிறைந்த திருக்கழுத்தும், திருக்கரத்தில் ஏந்தி இருக்கின்ற பாசங்களை அறுக்கின்ற மழுவும், சுருள் நிறைந்த செம்மையான சடையும், அந்த சடையின் மேல் ஜோதியாகப் பிரகாசிக்கும் பிறை நிலாவும் அருள் நிறைந்த சிந்தையும் கொண்டு விளங்குகின்ற எமது ஆதிப் பரம்பொருளாகிய இறைவனை தெளிவான அறிவினால் ஆராய்ந்து எனக்கு உள்ளே தெளிவாக உணர்ந்து இருக்கின்றேன்.`,
  },
  {
    id: 1742, tantraId: 7, verseNumber: 1741,
    tamil: `சத்திதான் நிற்கின்ற ஐம்முகம் காற்றிடில்
உத்தமம் வாமம் உரையத்து இருந்திடும்
தத்துவம் பூருவம் தற்புரு டன்சிரம்
அத்தரு கோரம் மகுடத்துஈ சானனே`,
    transliteration: `cattitāṉ niṟkiṉṟa aimmukam kāṟṟiṭil
uttamam vāmam uraiyattu iruntiṭum
tattuvam pūruvam taṟpuru ṭaṉciram
attaru kōram makuṭattuī cāṉaṉē`,
    english: `1741: Names of the Five Faces of Sadasiva
To recount the Five Faces where His Grace abounds
Thus it is:
The Northward Face is Vama
The Westward Face is Satyojata
The Eastward Face is Tatpurusha
The Southward Face is Aghora
The Upward Face is Isana.`,
    elaborationEnglish: `These Five Names, namely Vama, Sadyojata, Tatpurusha, Aghora and Isana are ‘‘regarded’’ as the representations of five different stages of Saivism which originated in immemorial A similar idea about the different Yugavataras of Lord Vishnu is recorded in the Bhagavata Purana’’. (Pp.122-123 of ‘‘Saivism through the Ages’’ R.K. Siddhanta Shastree).`,
    elaborationTamil: `ஆதியிலிருந்தே தானாக இருக்கின்ற அசையாத சக்தியாகிய இறைவனின் ஐந்து விதமான திருமுகங்களோடு அசையும் சக்தியாகிய இறைவி சேர்ந்து விட்டால் வடக்கு நோக்கி இருக்கின்ற வாமதேவ திருமுகம் அமைதியாகி இறைவியின் ஆற்றலுக்கு உட்பட்டு விடும். மேற்கு நோக்கி இருக்கின்ற சத்தியோசாத திருமுகம் குதிரையின் ஓட்டம் போல இயங்கும். கிழக்கு நோக்கி இருக்கின்ற தற்புருட திருமுகம் சிகப்பான இரத்த ஓட்டம் போல இயங்கும். தெற்கு நோக்கி இருக்கின்ற அகோர திருமுகத்தில் இறைவனும் இறைவியும் சரிபாதியாக இருப்பார்கள். நடுவில் மேல் நோக்கி இருக்கின்ற ஈசான திருமுகத்தில் இறைவனும் இறைவியும் இணைந்து மகுடம் போல உயர்ந்து இருப்பார்கள்.`,
  },
  {
    id: 1743, tantraId: 7, verseNumber: 1742,
    tamil: `நாணுநல் ஈசானன் நடுவுச்சி தானாகும்
தாணுவின் தன்முகம் தற்புருட மாகும்
காணும் அகோரம் இருதயம் குய்யமாம்
மாணுற வாமம்ஆம் சத்திநற் பாதமே`,
    transliteration: `nāṇunal īcāṉaṉ naṭuvucci tāṉākum
tāṇuviṉ taṉmukam taṟpuruṭa mākum
kāṇum akōram irutayam kuyyamām
māṇuṟa vāmamām cattinaṟ pātamē`,
    english: `1742: How Sakti dwells in the Five faces of Sadasiva
In the shining Isana face is Sakti's Crown;
In the Tatpurusha face is Her Visage
In the Aghora is Her Heart and Waist;
In the Vama face are Her Feet blessed.`,
    elaborationEnglish: `Sakti’s crown is in Isana, Her visage in Tatpurusa. Her heart and waist are in Aghora and Her blessed Feet in Vama.`,
    elaborationTamil: `இறைவனின் ஐந்து திருமுகங்களோடு பாடல் #1741 இல் உள்ளபடி இறைவி சென்று சேரும்போது அறிவு வடிவமாக இருக்கின்ற இறைவனின் ஈசான முகம் இறைவியின் தலை உச்சியாகவும், முக்தியாகிய நிலை பேற்றைக் கொடுக்கின்ற இறைவனது தற்புருட முகம் இறைவியின் திருமுகமாகவும், கண்களால் அருளைக் கொடுக்கின்ற இறைவனின் அகோர முகம் இறைவியின் இருதயமாகவும், அமிழ்தம் பெற்று மேல் நிலையைக் கொடுக்கின்ற இறைவனின் வாமதேவ முகம் இறைவியின் கீழ் பகுதியாகவும், நன்மையைக் கொடுக்கின்ற இறைவனின் சத்தியோசாத முகம் இறைவியின் திருவடிகளாகவும் விளங்கும்.`,
  },
  {
    id: 1744, tantraId: 7, verseNumber: 1743,
    tamil: `நெஞ்சு சிரம்சிகை நீள்கவ சம்கண்ணாம்
வஞ்சமில் விந்து வளர்நிறம் பச்சையாம்
செஞ்சுறு செஞ்சுடர் சேகரி மின்னாகும்
செஞ்சுடர் போலும் தெசாயுதம் தானே`,
    transliteration: `neñcu ciramcikai nīḷkava camkaṇṇām
vañcamil vintu vaḷarniṟam paccaiyām
ceñcuṟu ceñcuṭar cēkari miṉṉākum
ceñcuṭar pōlum tecāyutam tāṉē`,
    english: `1743: Form of Sakti in Sadasiva
The breast, the head, the tresses long,
The eyes, the fore-head mark, the armour
These the Sakti's are
Of growing green hue
As lightning is She, the dazzling crowning Sakti
Fiery bright, Her ten Weapons.`,
    elaborationEnglish: `Sakti’s head, tresses, eyes, forehead-mark, breast and armour
are of glowing green. Her form is dazzling as lightning, and
Her ten weapons are ‘fiery bright.`,
    elaborationTamil: `இறைவனின் ஐந்து உறுப்புகளாகிய மார்பு, தலை, தலைமுடி, நீண்ட கவசம், கண்கள் ஆகியவை ஒரு தீமையும் இல்லாத ஒளி உருவமாக எப்போதும் வளர்ந்து கொண்டே இருக்கின்றது. அவற்றின் பச்சை நிறம் பசுமையாக நன்மையை அருளுவதை குறிப்பது ஆகும். இறைவனின் செழுமை உற்று இருக்கும் சிகப்பான திருமேனியாகிய சுடர் ஒளிக்கு சரிசமமாக இருப்பது இறைவியின் ஒளி உருவம் ஆகும். சிகப்பான சுடர் போல பிரகாசமான ஒளி பொருந்தி இருக்கின்ற உறுப்புகள் தீமையை அழிக்கும் ஆயுதங்களாக இருக்கின்றது.`,
  },
  {
    id: 1745, tantraId: 7, verseNumber: 1744,
    tamil: `எண்ணில் இதயம் இறைஞான சத்தியாம்
விண்ணிற் பரைசிரம் மிக்க சிகையாதி
வண்ணங் கவசம் வனப்புடை இச்சையாம்
பண்ணுங் கிரியை பரநேந் திரத்திலே`,
    transliteration: `eṇṇil itayam iṟaiñāṉa cattiyām
viṇṇiṟ paraiciram mikka cikaiyāti
vaṇṇaṅ kavacam vaṉappuṭai iccaiyām
paṇṇuṅ kiriyai paranēn tirattilē`,
    english: `1744: The Five Saktis are seated in Sadasiva
The heart is the divine Jnana Sakti
The head the heavenly Para Sakti
The tresses the Adi Sakti
The colorful armour is Icchha Sakti`,
    elaborationEnglish: `In Sadasiva's heart is seated divine jnana sakti; on His head the heavenly Parasakti; over His locks the Adisakti; in His armour, ichchasakti and within His eyes, the kriya sakti.`,
    elaborationTamil: `இறைவனின் மூன்று விதமான சக்திகளானது எப்படி இருக்கின்றது என்று ஆராய்ந்து பார்த்தால் இதயமானது இறைவனின் ஞான சக்தியாக இருக்கின்றது. இறைவனின் தலையும் அதன் மேலுள்ள திருமுடியும் பல வண்ணங்களுள்ள கவசமும் செழுமையான உடையும் இச்சா சக்தியாக இருக்கின்றது. இறைவனின் திருவருள் கண்களே கிரியா சக்தியாக இருக்கின்றது.`,
  },
  {
    id: 1746, tantraId: 7, verseNumber: 1745,
    tamil: `சத்திநாற் கோணம் சலமுற்று நின்றிடும்
சத்திஅறு கோண சயனத்தை உற்றிடும்
சத்தி வட்டம் சலமுற்று இருந்திடும்
சத்தி உருவாம் சதாசிவன் தானே`,
    transliteration: `cattināṟ kōṇam calamuṟṟu niṉṟiṭum
cattiaṟu kōṇa cayaṉattai uṟṟiṭum
catti vaṭṭam calamuṟṟu iruntiṭum
catti uruvām catācivaṉ tāṉē`,
    english: `1745: Sakti in the First Three Adharas
In the quadrilateral Adhara (Muladhara)
Sakti in firmness stands;
In the hexagonal Adhara (Svadhishana)
Sakti is in sleep;
In the circular Adhara (Manipuraka)
Sakti is in agitation;
Of Sakti's Form is Sadasiva.`,
    elaborationEnglish: `Sakti stands firm in muladhara: She is asleep in svadhistana: She is agitated in manipuraka. Sadasiva is Sakti’s form.

All this forms part of Tantra sadhana, and Kundalini Yoga.`,
    elaborationTamil: `பாடல் #1744 இல் உள்ளபடி மூன்று சக்திகளின் வடிவானது இலிங்க வடிவத்தில் அமையும் போது நான்கு கோணங்கள் அமைந்த இலிங்க வடிவத்தில் தண்ணீர் போல தன்மைக்கு ஏற்ப நிறைந்து இருக்கும் ஞான சக்தியாக நின்றிடும். ஆறு கோணங்கள் அமைந்த இலிங்க வடிவத்தில் சயன நிலையில் படுத்து கிடக்கும் இச்சா சக்தியாக வீற்றிருக்கும். நான்கு வட்டங்கள் அமைந்த இலிங்க வடிவத்தில் மேக நீரைப் போல சுழன்று கொண்டே இருக்கின்ற கிரியா சக்தியாக இருந்திடும். இப்படி மூன்று வகையாக இருக்கின்ற சக்தியின் இலிங்க வடிவங்களாக இருப்பது சதா சிவமூர்த்தி ஆகும். கருத்து: ஞான சக்தியானது அடியவரின் மனப் பக்குவத்துக்கு ஏற்றபடி இலிங்க வடிவத்தில் வெளிபட்டு அருளுவார். இச்சா சக்தியானது மனதின் ஆசைகளுக்கு ஏற்றபடி இலிங்க வடிவத்தில் வெளிபட்டு அருளுவார். கிரியா சக்தியானது மேகத்திலிருந்து மழையாகப் பொழிகின்ற நீர் மீண்டும் ஆவியாகி மேகத்தில் சென்று அடைவது போல அடியவரின் பிறவி சுழற்சியில் வினைகளின் படி அனுபவிக்கின்ற நன்மை தீமைகளை செயல் படுத்தி அருளுவார்.`,
  },
  {
    id: 1747, tantraId: 7, verseNumber: 1746,
    tamil: `மான் நந்தி எத்தனை காலம் அழைக்கினும்
தான் நந்தி அஞ்கின் தனிச்சுடை ராய்நிற்கும்
கால் நந்தி உந்தி கடந்து கமலத்தில்
மேல் நந்தி ஒன்பதின் மேவிநின் றானே`,
    transliteration: `māṉ nanti ettaṉai kālam aḻaikkiṉum
tāṉ nanti añkiṉ taṉiccuṭai rāyniṟkum
kāl nanti unti kaṭantu kamalattil
mēl nanti oṉpatiṉ mēviniṉ ṟāṉē`,
    english: `1746: Sadasiva is seated in Sahasrara
Whatso be the time you seek the great Nandi,
He stands unique,
His Five Faces glowing unto the evening sun;
Rousing the Kundalini through Yogic breathing
When you upward course through centers nine
Upon the lotus top, He aloft stands.`,
    elaborationEnglish: `Nandi stands in grandeur with His Five Faces glowing like the evening sun. When kundalini is aroused to reach the lotus top by coursing the yogic breath through the nine centres, He is visioned.`,
    elaborationTamil: `மாபெரும் குருநாதராகிய இறைவனை எத்தனை காலங்காலமாக வேண்டி தொழுதாலும் தமக்குள்ளே இருக்கின்ற குருநாதராகிய இறைவன் ஒளிமயமாகிய வடிவத்தில் தனி சுடராகவே நின்று வெளிப்படுவார். மூச்சுக்காற்றை குருநாதர் காட்டிய வழியில் வயிற்றைக் கடந்து மூலாதாரத்திற்கு கொண்டு சென்று அங்குள்ள மூலாக்கினியை எழுப்பி, சுழுமுனை நாடி வழியே மேல் நோக்கி கொண்டு சென்று, ஏழாவது சக்கரமாகிய சகஸ்ரதளத்தில் இருக்கும் ஆயிரம் இதழ் கொண்ட தாமரை மலரில் கொண்டு சேர்த்து, அதற்கு மேல் ஜோதியாக வீற்றிருக்கும் குருநாதராகிய இறைவனுடன் சகஸ்ரதளத்தை தாண்டி எட்டாவது துவாத சாந்த வெளியும், அதையும் தாண்டிய ஒன்பதாவது பர வெளியாகிய சந்திர மண்டலம் வரை சென்று, இந்த ஒன்பது சக்கரங்களிலும் முழுவதுமாக அவர் நிறைந்து நிற்பதுவே சதாசிவ இலிங்கமாகும்.`,
  },
  {
    id: 1748, tantraId: 7, verseNumber: 1747,
    tamil: `ஒன்றிய வாறும் உடலின் உடன்கிடந்து
என்றும்எம் ஈசன் நடக்கும் இயல்பது
தென்தலைக்கு ஏறத் திருந்து சிவனடி
நின்று தொழுதேன் என் நெஞ்சத்தின் உள்ளே`,
    transliteration: `oṉṟiya vāṟum uṭaliṉ uṭaṉkiṭantu
eṉṟumem īcaṉ naṭakkum iyalpatu
teṉtalaikku ēṟat tiruntu civaṉaṭi
niṉṟu toḻutēṉ eṉ neñcattiṉ uḷḷē`,
    english: `1747: Sadasiva abides within body
In union inseparable
He ever abides in this fleshly body
That is His nature divine;
His Perfection's Feet upon my head I bore,
And in my heart's deep, I prayed.`,
    elaborationEnglish: `Inseparably He abides within this body of flesh. I bore His Feet on my head and with all my hear I pray to Him in depth.`,
    elaborationTamil: `இறையருளால் ஒன்றாக செயல்படுகின்ற ஆறு சக்கரங்களும் உடலோடு சேர்ந்து கிடந்து எப்போதும் எம்பெருமான் இறைவன் தமக்குள் அடங்கி இருக்கின்ற இயல்பான தன்மையாகிவிடும். அதன் பிறகு அழகிய தலையில் உடையவனாகிய இறைவனை தமக்குள் முழுவதும் உணர்ந்து தெளிவு பெற தீய மலங்களை திருத்தி நன்மையை அருளுகின்ற இறைவனின் திருவடியை நின்று வணங்கித் தொழுதேன் எமது நெஞ்சத்தின் உள்ளே. குறிப்பு: தென் தலையை அழகிய தலை என்று சொல்லப்படுவதன் காரணம் ஆறு சக்கரங்களும் ஒன்றாக சேர்ந்த பிறகு சகஸ்ரதளத்தில் இருக்கும் ஆயிரம் இதழ் கொண்ட தாமரை மலர் விரிவடைந்து அதிலிருந்து வெளிப்படுகின்ற ஜோதி வடிவான இறை சக்தியானது கொன்றை மலரின் வாசனையை வெளிப்படுத்துவதால் ஆகும்.`,
  },
  {
    id: 1749, tantraId: 7, verseNumber: 1748,
    tamil: `உணர்ந்தேன் உலகினில் ஒண்பொரு ளானைக்
கொணர்ந்தேன் குவலயம் கோயிலென் நெஞ்சம்
புணர்ந்தேன் புனிதனும் பொய்யல்ல மெய்யே
பணிந்தேன் பகலவன் பாட்டும் ஒலியே`,
    transliteration: `uṇarntēṉ ulakiṉil oṇporu ḷāṉaik
koṇarntēṉ kuvalayam kōyileṉ neñcam
puṇarntēṉ puṉitaṉum poyyalla meyyē
paṇintēṉ pakalavaṉ pāṭṭum oliyē`,
    english: `1748: Sadasiva is realized in the Body
The shining Truth He is
Him I realized in this world below;
Into my heart's temple here on earth
I brought Him, lo!
Him in union I embraced and prayed
Truth it is, pure and simple;
To Him, the Sun Resplendent, I sang
To music and to measure appropriate.`,
    elaborationEnglish: `He is the shining Truth: I realised Him in this world. T drew Him to my heart. | embraced Him in union. | prayed and sang to Him in appropriate measure.`,
    elaborationTamil: `உலகமெங்கும் உள்ள அனைத்து பொருளிலும் ஒன்றாக கலந்து இருக்கின்ற மாபெரும் பொருளாகிய இறைவனை பாடல் #1747 இல் உள்ளபடி எமக்குள்ளே உணர்ந்தேன். உலகமெல்லாம் பரந்து விரிந்து இருக்கின்ற இறைவன் வீற்றிருக்கும் கோயிலாக எமது நெஞ்சத்துக்குள்ளே அவனை கொண்டு வந்தேன். அவ்வாறு எமக்குள் கோயில் கொண்ட புனிதனாகிய இறைவனோடு ஒன்றாக கலந்து விட்டேன். இது பொய் இல்லை உண்மையே ஆகும். எமக்குள்ளிருந்தே அனைத்து உலகத்திற்கும் வெளிச்சம் கொடுப்பவனாகிய இறைவனை பணிந்து தொழுதேன். அப்போது எமக்குள்ளிருந்து பாடல்களாகவும் ஒலியாகவும் இருக்கின்ற தனது நாத வடிவமாகிய நடராஜ தத்துவமாக அவன் வெளிப்பட்டான்.`,
  },
  {
    id: 1750, tantraId: 7, verseNumber: 1749,
    tamil: `ஆங்கவை மூன்றினும் ஆரழல் வீசிடத்
தாங்கிடும் ஈரேழு தான்நடு வானதில்
ஓங்கிய ஆதியும் அந்தமும் ஆமென
ஈங்கிவை தம்முடல் இந்துவும் ஆமே`,
    transliteration: `āṅkavai mūṉṟiṉum āraḻal vīciṭat
tāṅkiṭum īrēḻu tāṉnaṭu vāṉatil
ōṅkiya ātiyum antamum āmeṉa
īṅkivai tammuṭal intuvum āmē`,
    english: `1749: The Lord is the Source of Light and Energy for Sun,
Moon and Fire
To Sun, Moon and Fire
He lends His fiery rays;
The seven worlds twice he supports;
And in the Center of Spaces Vast
He stands,
He is the Beginning, He is the End,
His own Form, cool as moon.`,
    elaborationEnglish: `He lends the fiery rays to the sun, moon and fire. He supports the fourteen worlds. He stands at the centre of vast spaces. He is the ‘beginning as-well as the end. He is cool as the Tays of the moon.`,
    elaborationTamil: `பாடல் #1748 இல் உள்ளபடி தமக்குள்ளிருந்து நாத வடிவாக வெளிப்படுகின்ற நடராஜ வடிவ தத்துவமானது, அண்ட சராசரங்கள் அதற்கும் மேல் அதற்கும் கீழ் என்று மூன்று இடங்களிலும் முழுவதுமாக நிறைந்து நிற்கின்ற மாபெரும் தீயாகவும், ஈரேழு பதினான்கு உலகங்களையும் தாங்கிக் கொண்டும், அனைத்திற்கும் நடுவாகிய ஆகாய தத்துவமாகவும், அனைத்தையும் தாண்டி ஓங்கி விளங்குவதாகவும், அனைத்திற்கும் ஆதியாகவும், அனைத்திற்கும் முடிவாகவும், இப்படி இங்கு உள்ள அனைத்தையும் தம் உடலுக்குள்ளே கொண்டு சந்திரனைப் போல குளிர்ச்சியாகவும் இருக்கின்றது.`,
  },
  {
    id: 1751, tantraId: 7, verseNumber: 1750,
    tamil: `தன்மேனி தற்சிவ லிங்கமாய் நின்றிடும்
தன்மேனி தானும் சதாசிவ மாய்நிற்கும்
தன்மேனி தற்சிவன் தற்சிவா னந்தமாய்
தன்மேனி தானாகும் தற்பரம் தானே`,
    transliteration: `taṉmēṉi taṟciva liṅkamāy niṉṟiṭum
taṉmēṉi tāṉum catāciva māyniṟkum
taṉmēṉi taṟcivaṉ taṟcivā ṉantamāy
taṉmēṉi tāṉākum taṟparam tāṉē`,
    english: `1750: The Lord is uncreated
He standes
His Form as Uncreated Siva Linga
His Form as Sadasiva Divine
His Form as Sivananda, bliss unalloyed
His Form as Tat-Para Eternal Supreme.`,
    elaborationEnglish: `The Lord is uncreated. He stands with His body as uncreated
Siva Linga, as divine Sadasiva as uncreated Siva, as unalloyed
Sivananda and as Supreme Tat-Para.`,
    elaborationTamil: `பாடல் #1749 இல் உள்ளபடி அண்ட சராசரங்களாகவும் அனைத்துமாகவும் இருக்கின்ற நடராஜ தத்துவத்தை தமக்குள்ளே உணர்ந்து கொண்ட அடியவரின் உடலானது தானே சிவ இலிங்கமாக நிற்கும். அடியவர் தமக்குள் இருக்கின்ற இறைவனோடு சேர்ந்து தாமும் சதாசிவப் பரம் பொருளாகவே நிற்பார். அடியவர் தனது உடலே சிவனாகவும், தன்னுடைய உடலுக்குள்ளேயே சிவ பேரின்பமாகவும் ஆகி விடுவார். இவ்வாறு அடியவரின் உடல் தானே ஆகி நிற்பது தானாகவே எப்போதும் இருக்கின்ற பரம்பொருள் ஆகும்.`,
  },
  {
    id: 1752, tantraId: 7, verseNumber: 1751,
    tamil: `ஆரும் அறியார் அகாரம் அவனென்று
பாரும் உகாரம் பரந்திட்ட நாயகி
தாரம் இரண்டும் தரணி முழுதுமாய்
மாறி எழுந்திடும் ஓசையதாமே`,
    transliteration: `ārum aṟiyār akāram avaṉeṉṟu
pārum ukāram parantiṭṭa nāyaki
tāram iraṇṭum taraṇi muḻutumāy
māṟi eḻuntiṭum ōcaiyatāmē`,
    english: `1751: The Lord is the Cosmic sound "Aum"
None knows He is Ahara, the letter "A"
And the pervasive Sakti is Uhara, the letter "U"
The two sounds swelling alternate
Fill the world as Aum in unrelieved entirety.`,
    elaborationEnglish: `The two sounds swelling alternate

Fill the world as Aum in unrelieved entirety.
Siva is akara, the letter *A’; Sakti is ukara, the letter “U’,
these two sounds together swell and fill the world as ‘Aum.’
The Lord is thus the cosmic sound, ‘Aum.’`,
    elaborationTamil: `சாதகத்தின் மூலம் தமக்குள்ளிருக்கும் இறைவனை உணராத எவரும் ஓங்காரத்தில் இருக்கின்ற ‘அ’காரம் எனும் அருளாக இருப்பது எது என்று அறிந்து கொள்ள மாட்டார்கள். உலகத்திலும் ஓங்காரத்தில் இருக்கின்ற ‘உ’காரம் எனும் அருளை பிரித்து வகுத்துக் கொடுத்த இறை சக்தியை தமக்குள் தேடி உணர்ந்தால் அது பிரணவமாக உள்ளுக்குள் இறை சக்தியாகவும், வெளியிலும் இறை சக்தியாகவும், என்று இரண்டுமாக உலகம் முழுவதற்கும் நிறைந்து நிற்பதாய் தமக்குள்ளிருந்தே மாறி எழுந்திடும் நாதம் ஆகும். கருத்து: ஓங்காரத்தில் ‘அ’காரமாக உள்ளுக்குள் இருந்து இயக்குகின்ற சக்தியும் ‘உ’காரமாக வெளி உலகத்தை இயக்குகின்ற சக்தியும் நாத வடிவமாக இருக்கின்ற நடராஜ தத்துவத்தை குறிப்பதாகும். நடராஜ தத்துவத்தை தமக்குள் உணர்ந்து கொண்ட சாதகர்களே இந்த ஓங்கார தத்துவத்தை அறிந்து சதாசிவ இலிங்கத்தின் நாத வடித்தை உணர்ந்து கொள்வார்கள். ஓங்காரத்தில் இருக்கின்ற இந்த இரண்டு சக்திகளே இறைவனுக்கு இரண்டு சக்திகளாக அனைத்து தெய்வ வடிவங்களிலும் காட்டப் படுகின்றது.`,
  },
  {
    id: 1753, tantraId: 7, verseNumber: 1752,
    tamil: `இலிங்கநற் பீடம் இசையும்ஓங் காரம்
இலிங்கநற் கண்டம் நிறையும் மகாரம்
இலிங்கத்து உள் வட்டம் நிறையும் உகாரம்
இலிங்கம் அகாரம் நிறைவிந்து நாதமே`,
    transliteration: `iliṅkanaṟ pīṭam icaiyumōṅ kāram
iliṅkanaṟ kaṇṭam niṟaiyum makāram
iliṅkattu uḷ vaṭṭam niṟaiyum ukāram
iliṅkam akāram niṟaivintu nātamē`,
    english: `1752: Linga is Aum
The Linga's Holy Pedestal is the humming Omkara (Aum)
The Linga's Center part is filled with Ahara (A)
The Linga's inner round is with Uhara replete (U)
Linga is Bindu-Nada, Makaram (M) pervaded.`,
    elaborationEnglish: `Linga is ‘Aum;’ its pedestal is “Aumkdra;’ its centre is akara, ‘A;’ its inner sound is ukara, ‘U,’ Makaram, ‘M’ pervading, Linga is bindu/nada.`,
    elaborationTamil: `அரூபமாக இருக்கின்ற சதாசிவ மூர்த்தியின் இலிங்க வடிவத்தில் நன்மை தருகின்ற பீடப் பகுதியானது அனைத்தோடும் சேர்ந்து இயங்கிக் கொண்டு இருக்கின்ற ஓங்காரத்தின் தத்துவமாகும். அதில் நடுவில் இருக்கின்ற பாணமானது அனைத்திலும் பரவி நிறைந்து இருக்கின்ற ஓங்காரத்தின் ‘அ’கார எழுத்தின் தத்துவமாகும். அதில் இருக்கின்ற வட்டமானது அனைத்திற்கு உள்ளும் உறைந்து இருக்கின்ற ஓங்காரத்தின் ‘உ’கார எழுத்தின் தத்துவமாகும். இலிங்க வடிவத்தில் ‘உ’கார எழுத்தாக நிறைந்து இருப்பதுவே வெளிச்சமும் சத்தமுமாகிய பரம்பொருளின் விந்து நாத தத்துவமாகும். கருத்து: நன்மையே வடிவான இலிங்க வடிவத்தில் மேல் பாகம், நடுப் பாகம், கீழ் பாகம் என்று மூன்று பாகங்களாக பிரிந்து இருப்பது நாத வடிவாகிய நடராஜ தத்துவமாகும். அதில் மேல் பாகம் ஓங்காரத்தில் உள்ள ‘அ’காரத்தையும், நடுப் பாகம் ஓங்காரத்தில் உள்ள ‘உ’காரத்தையும், கீழ் பாகம் ஓங்காரத்தில் உள்ள ‘ம’காரத்தையும் குறிக்கின்றது. ஓங்காரத்தின் எழுத்து வடிவமே விந்து தத்துவமாகும். ஓங்காரத்தின் ஒலி வடிவமே நாத தத்துவமாகும்.`,
  },
  {
    id: 1754, tantraId: 7, verseNumber: 1753,
    tamil: `அகார முதலா அனைத்துமாய் நிற்கும்
உகார முதலா உயிர்ப்பெய்து நிற்கும்
அகார உகாரம் இரண்டும் அறியில்
அகார உகாரம் இலிங்கம் தாமே`,
    transliteration: `akāra mutalā aṉaittumāy niṟkum
ukāra mutalā uyirppeytu niṟkum
akāra ukāram iraṇṭum aṟiyil
akāra ukāram iliṅkam tāmē`,
    english: `1753: In the Beginning was Aum
Aharam (A) as beginning, all exist
Uharam (U) as beginning, all life exists
If Aharam Uharam are together known
Aharam Uharam is but Linga divine.`,
    elaborationEnglish: `All life exists with akaram (A) and Ukaram (U). Knowledge of these two brings the knowledge of divine Linga.`,
    elaborationTamil: `ஓங்கார தத்துவத்தில் ‘அ’கார எழுத்தின் முதலாகி அனைத்துமாக நிற்பதுவும், ‘உ’கார எழுத்தின் முதலாகி அனைத்து உயிர்களின் இயக்கமாக நிற்பதுவும், ‘அ’கார எழுத்தின் தத்துவம் ‘உ’கார எழுத்தின் தத்துவம் ஆகிய இரண்டுமாக இருப்பதுமாகிய பரம்பொருளை உள்ளுக்குள் உணர்ந்து அறிந்து கொண்டால், அந்த ‘அ’கார எழுத்தும் ‘உ’கார எழுத்துமாக தமக்குள் இருக்கின்ற பரம்பொருளின் இலிங்க வடிவமே ஆத்மாவாகும் என்பதை அறிந்து கொள்ளலாம்.`,
  },
  {
    id: 1755, tantraId: 7, verseNumber: 1754,
    tamil: `ஆதாரம் ஆதேயம் ஆகின்ற விந்துவும்
மேதாதி நாதமும் மீதே விரிந்தன
ஆதார விந்து ஆதிபீட நாமே
போதாஇ லிங்கப் புணர்ச்சிய தாமே`,
    transliteration: `ātāram ātēyam ākiṉṟa vintuvum
mētāti nātamum mītē virintaṉa
ātāra vintu ātipīṭa nāmē
pōtāi liṅkap puṇarcciya tāmē`,
    english: `1754: Bindu is the Support and Nada the Supported
Bindu is the Support Finite
Nada in Medha as the Supported expanded;
Bindu that is Support is the Pedestal
Nada on to it is conjoint,
That verily is Linga's union.`,
    elaborationEnglish: `Bindu is the support and nada the supported. When nada
conjoins with bindu, the pedestal, the union is Linga.

Bindu represents Siva, and Nada, Sakti.`,
    elaborationTamil: `அனைத்திற்கும் ஆதாரமாகிய மாபெரும் தெய்வமாக இருக்கின்ற விந்து (வெளிச்சம்) சக்தியும் அதற்கு மேலாக ஆதியிலிருந்தே இருக்கின்ற நாத (சத்தம்) சக்தியும் ஒன்றன் மீது ஒன்றாகவே அனைத்திலும் விரிந்து பரந்து இருக்கின்றது. இதில் ஆதாரமாகிய விந்து சக்திக்கு மேன்மை தருகின்ற பீடமே நாத சக்தியாகும். எப்போதுமே பிரிந்து போகாத இந்த இரண்டு சக்திகள் இலிங்க வடிவத்தில் கலந்து இருக்கின்ற நிலையே ஆத்ம இலிங்கமாகும்.`,
  },
  {
    id: 1756, tantraId: 7, verseNumber: 1755,
    tamil: `சத்தி சிவமாம் இலிங்கமே தாபரம்
சத்தி சிவமாம் இலிங்கமே சங்கமம்
சத்தி சிவமாம் இலிங்கம் சதாசிவம்
சத்தி சிவமாகும் தாபரம் தானே`,
    transliteration: `catti civamām iliṅkamē tāparam
catti civamām iliṅkamē caṅkamam
catti civamām iliṅkam catācivam
catti civamākum tāparam tāṉē`,
    english: `1755: Siva-Sakti (Linga) is Static, Kinetic, Sadasiva and Unborn
Being
Linga that is Sakti-Siva is Static all
Linga that is Sakti-Siva is Kinetic all
Linga that is Sakti-Siva is Sadasiva
Sakti-Siva is Tatpara, the Being Unborn.
He enters your home, and blesses you.`,
    elaborationEnglish: `Linga that is Siva/Sakti is static and kinetic: it is Sadasiva,
the Unbom Being.`,
    elaborationTamil: `பாடல் #1754 இல் உள்ளபடி எப்போதும் பிரியாமல் இருக்கின்ற இறைவனும் இறைவியும் சேர்ந்தே இருக்கின்ற ஆத்ம இலிங்கமே உடலாக இருக்கின்றது. இறைவனும் இறைவியும் சேர்ந்தே இருக்கின்ற ஆத்ம இலிங்கத்தில் உடல், இறைவனிடமிருந்து பிரிந்து வந்த ஆன்மா, இறைவன் ஆகிய மூன்றும் கலந்து இருக்கின்றது. இப்படி மூன்றும் கலந்து பிண்டத்தில் இருக்கின்ற ஆத்ம இலிங்கமே அண்ட சராசரங்களிலும் விரிந்து பரவி இருக்கின்ற பரம்பொருளாகவும் இருக்கின்றது. இப்படி அண்டத்திலும் பிண்டத்திலும் இருக்கின்ற ஆத்ம இலிங்கமானது தானாகவே அனைத்துமாகவும் இருக்கின்ற பரம்பொருளாக இருக்கின்றது.`,
  },
  {
    id: 1757, tantraId: 7, verseNumber: 1756,
    tamil: `தானேர் எழுகின்ற சோதியைக் காணலாம்
வானேர் எழுகின்ற ஐம்பது அமர்ந்திடம்
பூரேர் எழுகின்ற பொற்கொடி தன்னுடன்
தானேர் எழுகின்ற அகாரமது ஆமே`,
    transliteration: `tāṉēr eḻukiṉṟa cōtiyaik kāṇalām
vāṉēr eḻukiṉṟa aimpatu amarntiṭam
pūrēr eḻukiṉṟa poṟkoṭi taṉṉuṭaṉ
tāṉēr eḻukiṉṟa akāramatu āmē`,
    english: `1756: Lord is Light and Support
Upon the heavenly letters five times ten
Well may you behold the self-illumined Light (Aum);
That which thus arises with His Sakti (U)
Like a golden vine that blooms pretty
Is but He that is Ahara (A)--the Support Finite.`,
    elaborationEnglish: `You may behold the Fifty heavenly Letters, the self -illumined
light ‘Aum,’ which arises with His Sakti (U). He, that is akara
(the final support) is like a golden vine that beautifully blooms.`,
    elaborationTamil: `தமக்குள் இருக்கின்ற சுழுமுனை நாடியின் வழியே மூலாதாரத்திலிருந்து நேராக எழுந்து மேலே வருகின்ற ஜோதியை பாடல் #1755 இல் உள்ளபடி தாமாகவே இருக்கின்ற பரம்பொருளை உணர்ந்து கொண்டவர்கள் காணலாம். அப்போது அண்டத்தில் உள்ள அனைத்திற்கும் அதனதன் தன்மைக்கு ஏற்ப சரிசமமாக எழுந்து இருக்கின்ற இறைவனின் ஐந்து பூதங்கள் (ஆகாயம், காற்று, நெருப்பு, நீர், மற்றும் நிலம்) தமக்குள்ளும் இருக்கின்றது என்கின்ற உணர்வு வந்து விட்டால், சகஸ்ரதளத்தில் உள்ள ஆயிரம் இதழ் கொண்ட தாமரை மலரில் சுழுமுனை நாடிக்கு நேராக எழுகின்ற பொன் போல பிரகாசிக்கும் கொடியாக வீற்றிருக்கும் இறைவியுடன் தாமாகவே எப்போதும் சேர்ந்தே எழுந்தருளும் இறைவனை உணரலாம். ஓங்காரத்தில் ‘அ’கார எழுத்தாக இருக்கின்ற ஆத்ம இலிங்கத்தின் தத்துவம் இதுவே ஆகும்.`,
  },
  {
    id: 1758, tantraId: 7, verseNumber: 1757,
    tamil: `விந்துவும் நாதமும் மேவும் இலிங்கமாம்
விந்துவ தேபீட நாதம் இலிங்கமாம்
அந்த இரண்டையும் ஆதார தெய்வமாய்
வந்து கருஐந்தம் செய்யும் அவைஐந்தே`,
    transliteration: `vintuvum nātamum mēvum iliṅkamām
vintuva tēpīṭa nātam iliṅkamām
anta iraṇṭaiyum ātāra teyvamāy
vantu karuaintam ceyyum avaiaintē`,
    english: `1757: Linga Comprises both Bindu and Nada
Bindu and Nada together form Linga
Bindu is the Pedestal, Nada the Linga
With them two as support divine
The Five gods arose, their Five functions to perform.`,
    elaborationTamil: `விந்துவும் (வெளிச்சம்) நாதமும் (சத்தம்) சரிசமமாக பொருந்தி இருப்பதே ஆத்ம இலிங்கம் ஆகும். வெளிச்சமானது அந்த இலிங்கத்தின் பீடமாகவும், சத்தமானது இலிங்கத்தின் பாணமாகவும் இருக்கின்றது. அந்த வெளிச்சம் சத்தம் ஆகிய இரண்டையும் ஆதாரமாகக் கொண்டு வீற்றிருக்கின்ற தெய்வங்களாக (தொழில் காரணர்கள்) ஆத்ம இலிங்கத்தில் வந்த கருவாக (தொழில் காரணம்) பிரம்மா, திருமால், உருத்திரன், மகேஸ்வரன், சதாசிவன் ஆகிய ஐந்து தெய்வங்களும் தமக்குள்ளிருந்தே ஒவ்வொருவருக்கான தொழில்களாகிய படைத்தல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய ஐந்து விதமான தொழில்களையும் புரிகின்றனர்.`,
  },
  {
    id: 1759, tantraId: 7, verseNumber: 1758,
    tamil: `சத்திநற் பீடம் தகுநல்ல ஆன்மா
சத்திநற் கண்டம் தகுவித்தை தானாகும்
சத்திநல் லிங்கம் தகும்சிவ தத்துவம்
சத்திநல் ஆன்மாச் சதாசிவம் தானே`,
    transliteration: `cattinaṟ pīṭam takunalla āṉmā
cattinaṟ kaṇṭam takuvittai tāṉākum
cattinal liṅkam takumciva tattuvam
cattinal āṉmāc catācivam tāṉē`,
    english: `1758 All the Tattvas are in Linga
The goodly pedestal of Sakti holds the Atma Tattvas
The central part of Sakti holds the Vidya Tattvas;
The Linga of Sakti, the Siva Tattvas
Sadasiva is Sakti's Soul Divine.`,
    elaborationEnglish: `Sakti’s pedestal holds the atma ‘tattvas; Sakti’s central part, the vidya tattvas; (Sakti’s upper part linga), the Siva tattvas. Sakti’s soul is Sadasiva.`,
    elaborationTamil: `பாடல் #1757 இல் உள்ளபடி ஆத்ம இலிங்கத்திற்கு உள்ளிருந்து ஐந்து தொழில்களையும் புரிகின்ற இறை சக்தியானது நன்மையான ஆத்ம இலிங்கத்தின் பீடத்தில் சாதகரின் பக்குவத்துக்கு தகுந்த படி நன்மையைக் கொடுத்து செயல் படுகின்ற ஆத்ம தத்துவமாக இருக்கின்றது. ஆத்ம இலிங்கத்தின் பாணத்தில் சாதகரின் பக்குவத்துக்கு தகுந்த படி செயல் படுகின்ற ஞான தத்துவமாக இருக்கின்றது. ஆத்ம இலிங்கத்தில் சாதகரின் பக்குவத்துக்கு தகுந்த படி செயல் படுகின்ற சிவ தத்துவமாக இருக்கின்றது. இப்படி ஐந்து தொழில்களையும் புரிகின்ற இறை சக்தியானது நன்மையை கொடுக்கின்ற ஆத்ம இலிங்கமே அனைத்திற்கும மேலான பரம்பொருளாக தானே இருக்கின்றது.`,
  },
  {
    id: 1760, tantraId: 7, verseNumber: 1759,
    tamil: `மனம்புகுந்து என்னுயிர் மன்னிய வாழ்க்கை
மனம்புகுந்து இன்பம் பொழிகின்ற போது
நலம்புகுந்து என்னொடு நாதனை நாடும்
இனம்புகுந்து ஆதியும் மேற்கொண்டவாறே`,
    transliteration: `maṉampukuntu eṉṉuyir maṉṉiya vāḻkkai
maṉampukuntu iṉpam poḻikiṉṟa pōtu
nalampukuntu eṉṉoṭu nātaṉai nāṭum
iṉampukuntu ātiyum mēṟkoṇṭavāṟē`,
    english: `1759: Seek Lord within and be Blessed
In my heart He entered,
In my life's being He entered,
He poured His blessing to my heart's fill;
Do with me the Lord seek`,
    elaborationEnglish: `He entered in my heart, in my life's being and blessed me in profusion to my heart's fill. You too seek Him along with me. He shall surely enter in you and bless you too.`,
    elaborationTamil: `அனைத்திற்கும் மேலான பரம்பொருளாக தமது ஆத்ம இலிங்கமே இருக்கின்ற தத்துவத்தை உணர்ந்து கொண்டவர்களின் மனதிற்குள் இறைவன் புகுந்து, அவர்களின் உயிரோடு பொருந்தி, வாழ்க்கையில் எப்போதும் உடன் இருந்து, அனைத்து விதமான இன்பங்களையும் வாரி வழங்கும் போது, நலங்களெல்லாம் அவர்களுக்குள் புகுந்து, அனைத்திற்கும் தலைவனாகிய இறைவனோடு ஒன்றாக கலந்திருந்து, உலகத்தில் புகுந்து வீற்றிருக்கும் ஆதி பரம்பொருள் அவர்களின் ஆன்மாவை மேன்மை படுத்தி ஆட்கொண்டு அருளி நன்மையின் வழியில் நடத்துகின்றான்.`,
  },
  {
    id: 1761, tantraId: 7, verseNumber: 1760,
    tamil: `பராபரன் எந்தை பனிமதி சூடி
தராபரன் தன்னடி யார்மனக் கோயில்
சிராபரன் தேவர்கள் சென்னியின் மன்னும்
அராபரன் மன்னி மனத்துஉறைந் தானே`,
    transliteration: `parāparaṉ entai paṉimati cūṭi
tarāparaṉ taṉṉaṭi yārmaṉak kōyil
cirāparaṉ tēvarkaḷ ceṉṉiyiṉ maṉṉum
arāparaṉ maṉṉi maṉattuuṟain tāṉē`,
    english: `1760: Lord is Sovereign Supreme
The Supreme Parapara is He;
My Father Divine;
He sports the crescent moon;
He rules the universe;
Into the heart's temple of His devotees too he reigns
He the Hara to whom the Immortals in worship bow
He in my heart resides firm.`,
    elaborationEnglish: `He who sports the crescent moon and rules the universe is
the Supreme Parapara, my Divine Father. He reigns in the
temple of His devotee’s heart. He, whom the celestials worship
as Hara, resides firm in my heart.`,
    elaborationTamil: `அனைத்திற்கும் மேலான பரம்பொருளானவனும், எமது தந்தையானவனும், தன் தலையில் குளிர்ச்சியான நிலவை சூடிக் கொண்டு இருப்பவனும், உலகங்களுக்கு எல்லாம் தலைவனாவனும், தமது அடியார்களின் மனதையே தமக்கு விருப்பமான கோயிலாக ஏற்றுக் கொண்டு வீற்றிருப்பவனும், தேவர்களுக்கும் மேலான தேவனும், விண்ணுலக தேவர்களின் தலையில் நிலை பெற்று வீற்றிருப்பவனும், உருவமில்லாமல் இருக்கின்ற பரம்பொருளுமாகிய இறைவன் எமக்குள் நிலை பெற்று எமது மனதிற்குள் எப்போதும் வீற்றிருந்தான்.`,
  },
  {
    id: 1762, tantraId: 7, verseNumber: 1761,
    tamil: `பிரான்அல்ல நாம்எனில் பேதை உலகம்
குரால்என்னும் என்மனம் கோயில்கொள் ஈசன்
அராநின்ற செஞ்சடை அங்கியும் நீரும்
பொராநின் றவர்செய்அப் புண்ணியன் தானே`,
    transliteration: `pirāṉalla nāmeṉil pētai ulakam
kurāleṉṉum eṉmaṉam kōyilkoḷ īcaṉ
arāniṉṟa ceñcaṭai aṅkiyum nīrum
porāniṉ ṟavarceyap puṇṇiyaṉ tāṉē`,
    english: `1761: Lord is tender as Mother-Cow
"He is not the Lord, I am the one"
If you this conceit have,
The world will call you a fool;
Tender as the yearning mother cow,
He in me is enshrined,
With serpent, fire and water in His matted lock
He, in amity, stands,
He the Holy One.`,
    elaborationEnglish: `The world will call him a fool who conceitedly claims himself as the Lord, and defiantly denies the Supreme. He is the Holy One. He sports the snake, fire and water in His mattedlocks. In amity He stands enshrined in me.`,
    elaborationTamil: `தனக்குள் தலைவனாக இருந்து செயல் பட வைக்கின்றவன் இறைவன் இல்லை என்று உலகத்தவர்கள் யாராவது சொன்னால் அவர்கள் அறிவில்லாதவர்களே. ஏன் என்றால் அனைவருக்கும் உள்ளுக்குள் இருந்து ஓதுபவனாகிய இறைவன் அடியவரது மனதையே கோயிலாக கொண்டு தலையில் பாம்பை அணிந்த சடையுடன் கையில் நெருப்பும் நீரும் ஏந்திக் கொண்டு நிற்கின்றான். அவன் அடியவரை நன்மைகள் செய்ய வைத்து அதன் புண்ணியங்களை தானே ஏற்றுக் கொள்கின்றான்.`,
  },
  {
    id: 1763, tantraId: 7, verseNumber: 1762,
    tamil: `அன்று நின் றான்கிடந் தான்அவன் என்று
சென்றுநின்று எண்டிசை ஏத்துவர் தேவர்கள்
என்றுநின்று ஏத்துவன் எம்பெரு மான்தன்னை
ஒன்றியென் உள்ளத்தின் உள்ளிருந் தானே`,
    transliteration: `aṉṟu niṉ ṟāṉkiṭan tāṉavaṉ eṉṟu
ceṉṟuniṉṟu eṇṭicai ēttuvar tēvarkaḷ
eṉṟuniṉṟu ēttuvaṉ emperu māṉtaṉṉai
oṉṟiyeṉ uḷḷattiṉ uḷḷirun tāṉē`,
    english: `1762: Hold Lord in Heart of Heart
"There He stood," "There He lay"
--Thus the Immortals in directions eight
Adore Him;
But how shall I praise my Lord
Who in my heart's heart ever resides.`,
    elaborationTamil: `ஆத்ம இலிங்க வடிவத்தில் அடி முடி காண முடியாத அண்ணாமலையாக அன்று நின்றான் இறைவன். ஐந்து பூதங்களுடன் சேர்ந்தே கிடந்தான் இறைவன். அவனே எல்லா காலத்திலும் உலகமெங்கும் சென்று அனைத்தையும் இயங்குவதையும் செய்து எட்டு திசைகளிலும் கலந்து நிற்கின்றான், அவனை போற்றி வணங்குகின்ற தேவர்களும் அனைத்திலும் நின்று கிடந்து இயக்குகின்றான் இறைவன் என்று எமது தலைவனாகிய இறைவனை தாங்களும் நின்று போற்றி வணங்குவார்கள். அவன் எம்மோடு கலந்து நின்று எமது உள்ளத்திற்கு உள்ளே வீற்றிருந்தான்.`,
  },
  {
    id: 1764, tantraId: 7, verseNumber: 1763,
    tamil: `உருவும் அருவும் உருவோடு அருவும்
மருவு பரசிவன் மன்பல் உயிர்க்கும்
குருவு மெனநிற்கும் கொள்கையன் ஆகும்
தருவென நல்கும் சதாசிவன் தானே`,
    transliteration: `uruvum aruvum uruvōṭu aruvum
maruvu paracivaṉ maṉpal uyirkkum
kuruvu meṉaniṟkum koḷkaiyaṉ ākum
taruveṉa nalkum catācivaṉ tāṉē`,
    english: `1763: Lord is Bounteous
As Form, the Formless and Form-Formless
Thus is Parasiva in all life immanent;
As Guru, too, He stands;
Unto the Kalpaka tree His bounties bestows
He, the Sadasiva.`,
    elaborationTamil: `அருவமாக இருக்கின்ற பரம்பொருளாகிய சிவமே உருவமாகவும், உருவமில்லாத அருவமாகவும், அருவத்தோடு நிற்கின்ற உருவமாகவும் [அருவுருவம் / இலிங்க வடிவம்], உலகத்தில் உள்ள பல விதமான உயிர்களில் தம்மை அடைவதையே கொள்கையாக கொண்ட அடியவர்களுக்கு உள்ளுக்குள் குருவுமாகவும் நின்று கற்பகத் தரு போல அவர்கள் வேண்டிய அனைத்தையும் கொடுத்து அருளுகின்றான். அவனே சதா சிவப் பரம்பொருள் ஆகும்.`,
  },
  {
    id: 1765, tantraId: 7, verseNumber: 1764,
    tamil: `நாலான கீழது உருவம் நடுநிற்க
மேலான நான்கும் அருவம் மிகுநாப்பண்
நாலான ஒன்றும் அருவுரு நண்ணலால்
பாலாம் இவையாம் பரசிவன் தானே`,
    transliteration: `nālāṉa kīḻatu uruvam naṭuniṟka
mēlāṉa nāṉkum aruvam mikunāppaṇ
nālāṉa oṉṟum aruvuru naṇṇalāl
pālām ivaiyām paracivaṉ tāṉē`,
    english: `1764: Sadasiva is Form-Formless
In the Center He is, Sadasiva,
The Four below are the Formed,
(Brahma, Vishnu, Rudra, Mahesa)
The Four above are the Formless
(Bindu, Nada, Sakti, Siva)
Thus are His parts
He, the Parasiva.`,
    elaborationEnglish: `Parasiva has nine aspects - Sadasiva standing at the centre, with faces in five directions, is the Lord of the immortals. They who adore Him will attain immortality. May you too seek His Holy Feet.`,
    elaborationTamil: `உருவமாக கீழே இருக்கின்ற பிரம்மா, திருமால், உருத்திரன், மகேஸ்வரன் ஆகிய நான்கு தெய்வங்களாகவும், அருவுருவமாக நடுவில் இருக்கின்ற சதாசிவமூர்த்தியாகவும், அருவமாக மேலே இருக்கின்ற சத்தம் [நாதம்], வெளிச்சம் [விந்து], சக்தி, சிவம் ஆகிய நான்கு சக்திகளாகவும், இவை அனைத்தும் மிகுந்து இருக்கின்ற நான்கு விதமான மந்திரங்களால் பாடப் பெற்ற ரிக்கு, யஜூர், சாமம், அதர்வணம் ஆகிய நான்கு நூல்களாகிய வேதங்களின் மூலப் பொருளாகவும் இருந்து அருவங்களாகவும், உருவங்களாகவும், அருவுருவங்களாகவும், இவற்றை சார்ந்து இருக்கின்ற அனைத்துமாகவும் அருளுவது பரம்பொருளாகிய சிவம் ஒன்றே ஆகும்.`,
  },
  {
    id: 1766, tantraId: 7, verseNumber: 1765,
    tamil: `தேவர் பிரானைத் திசைமுக நாதனை
நால்வர் பிரானை நடுவுற்ற நந்தியை
ஏவர் பிரான்என்று இறைஞ்சுவர் அவ்வழி
யாவர் பிரானடி அண்ணலும் ஆமே`,
    transliteration: `tēvar pirāṉait ticaimuka nātaṉai
nālvar pirāṉai naṭuvuṟṟa nantiyai
ēvar pirāṉeṉṟu iṟaiñcuvar avvaḻi
yāvar pirāṉaṭi aṇṇalum āmē`,
    english: `1765: Seek Sadasiva
He is the Lord of the Immortals,
He is the Lord with Faces in directions all,
He is the Lord of Four (Brahma, Vishnu, Rudra and Mahesa)
He is Nandi that central stands;
They who adore Him as their Lord
Themselves His ways attain;
Do you, so, seek the Lord's Holy Feet.`,
    elaborationEnglish: `Do you, so, seek the Lord’s Holy Feet.

Sadasiva standing at the centre, with faces in five directions,
is the Lord of the immortals. They who adore Him will attain
immortality. May you too seek His Holy Feet.`,
    elaborationTamil: `தேவர்களுக்கெல்லாம் தலைவன், பத்து திசைகளையும் தனது திருமுகங்களாக கொண்ட தலைவன், பிரம்மா, திருமால், உருத்திரன், மகேஸ்வரன் ஆகிய நான்கு தெய்வங்களுக்கும் தலைவன், அருவமாகிய மேலுக்கும் உருவமாகிய கீழுக்கும் நடுவில் வீற்றிருக்கின்ற குருநாதனாகிய இறைவன், எவருக்கும் தலைவன் என்றெல்லாம் போற்றி வழிபடுகின்ற அடியவர்களின் நெறி முறையை பின்பற்றி தாமும் அப்படியே வழிபடுகின்ற அடியவர்களது தலைவனாகவும், தமது திருவடியை அருளி அடியவர்க்கும் அடியவனாகவும், அவர்களை காத்து அருளுபவனாக ஞான இலிங்க வடிவான இறைவன் இருக்கின்றான்.`,
  },
  {
    id: 1767, tantraId: 7, verseNumber: 1766,
    tamil: `வேண்டிநின் றேதொழு தேன்வினை போயற
ஆண்டொரு திங்களும் நாளும் அளக்கின்ற
காண்டகை யானொடும் கன்னி உணரினும்
மூண்டகை மாறினும் ஒன்றது வாமே`,
    transliteration: `vēṇṭiniṉ ṟētoḻu tēṉviṉai pōyaṟa
āṇṭoru tiṅkaḷum nāḷum aḷakkiṉṟa
kāṇṭakai yāṉoṭum kaṉṉi uṇariṉum
mūṇṭakai māṟiṉum oṉṟatu vāmē`,
    english: `1766: Sadasiva Dispels Karmas
Him I prayed,
My Karma to dispel and destroy;
He measures out Time's Eternity
As year, month and day;
Worthy is He of your visioning;
And with His virgin Sakti seek Him;
Even when your folded hands unfold
The One is He to you.`,
    elaborationEnglish: `The yogi prays to Him to dispel and destroy his, karmas accumulated through time, for Sadasiva measures out time’s eternity as days, months and years.`,
    elaborationTamil: `எனது வினைகள் அனைத்தும் நீங்கி அழிந்து விடும் படி இறைவனை வேண்டி நின்று வணங்கினேன். ஆண்டுகள் ஒவ்வொன்றையும் மாதங்கள், நாட்கள் என்று இருக்கின்ற உயிர்களின் வாழ் நாளை அளந்து அருளுபவனை கண்டு தரிசிக்கும் இயல்போடு இருக்கின்ற நாயகனாகிய இறைவனோடு எப்போதும் சேர்ந்தே இருக்கின்ற என்றும் இளமையான இறைவியையும் உணர்ந்து தொழுதாலும், தமது உடலின் இயல்பை கடினமான சாதகங்களால் மாற்றி யோகத்தின் மூலம் உணர்ந்தாலும், இரண்டுமே ஒன்றான ஞான இலிங்கத்தின் வழியாகவே இருக்கின்றது.`,
  },
  {
    id: 1768, tantraId: 7, verseNumber: 1767,
    tamil: `ஆதி பரந்தெய்வம் அண்டத்து நல்தெய்வம்
சோதி அடியார் தொடரும் பெருந்தெய்வம்
நீதியுள் மாதெய்வம் நின்மலர் எம்இறை
பாதியுள் மன்னும் பராசத்தி யாமே`,
    transliteration: `āti paranteyvam aṇṭattu nalteyvam
cōti aṭiyār toṭarum perunteyvam
nītiyuḷ māteyvam niṉmalar emiṟai
pātiyuḷ maṉṉum parācatti yāmē`,
    english: `1767: Sadasiva dispenses Divine Justice
The Primal Lord is He,
The God of the Universe is He;
God is He whom the illumined devotees praise;
Great God is He of Justice Divine;
The Pure is He my Lord;
As half-and-half in Para Sakti He is.`,
    elaborationTamil: `ஆதியிலிருந்தே இருக்கின்ற பரம்பொருளாகிய இறைவன், அண்டங்களுக்கு எல்லாம் நன்மை செய்கின்ற இறைவன், தமக்குள் சோதி வடிவாக இருக்கின்ற இறைவனை உணர்ந்து கொண்ட அடியவர்களை எப்போதும் பிரியாமல் சேர்ந்தே இருக்கின்ற மாபெரும் இறைவன், தர்மங்கள் அனைத்திற்கும் மூலப் பொருளாக இருக்கின்ற மாபெரும் இறைவன், இப்படி எந்தவிதமான குற்றங்களும் குறைகளும் இல்லாத தூய்மையான எமது இறைவன் தனது திருமேனியில் சரிபாதியாக உள்ளே எப்போதும் நிலைபெற்று சேர்ந்தே இருக்கின்ற அசையும் சக்தியாகிய இறைவியோடு ஞான இலிங்கமாக இருக்கின்றான்.`,
  },
  {
    id: 1769, tantraId: 7, verseNumber: 1768,
    tamil: `சத்திக்கு மேலே பராசத்தி தன்னுள்ளே
சுத்த சிவபதம் தோயாத தூவொளி
அத்தன் திருவடிக்கு அப்பாலைக்கு அப்பாலாம்
ஒத்தவும் ஆம்ஈசன் தானான உண்மையே`,
    transliteration: `cattikku mēlē parācatti taṉṉuḷḷē
cutta civapatam tōyāta tūvoḷi
attaṉ tiruvaṭikku appālaikku appālām
ottavum āmīcaṉ tāṉāṉa uṇmaiyē`,
    english: `1768: Truth of Supreme Siva
Beyond Sakti, inside Para Sakti
Is the Pure Siva State, as Light undimmed
Still beyond and beyond are the Lord's Feet;
This the Truth of the Lord Supreme.`,
    elaborationEnglish: `His Feet are beyond the Beyond. Seeing that Effulgent Flame is seeing all the universe. He who rises and sees His world shall remain there forever. He sees the vast expanses of the Lord entwined with Sakti. He resides in that seer's thought.`,
    elaborationTamil: `உலகத்தை இயக்கிக் கொண்டு இருக்கின்ற இறை சக்திக்கும் மேலே அண்ட சராசரங்களை இயக்கிக் கொண்டு இருக்கின்ற அசையும் சக்தியாகிய இறைவிக்கு உள்ளே சரிபாதியாக நிற்கின்ற ஒரு குற்றமும் குறையும் இல்லாத தூய்மையான சிவப் பரம்பொருளின் திருவடியானது, எதிலும் குறைவில்லாததும் எதனாலும் பாதிக்கப் படாததுமாகிய தூய்மையான பரவெளியில் வீற்றிருக்கின்றது. அப்படி இருக்கின்ற அனைத்திற்கும் தந்தையாகிய இறைவனின் திரு அடிகளானது அண்ட சராசரங்களையும் தாண்டி பரவெளியையும் தாண்டி இருக்கின்ற எல்லையில்லா இடத்தில் தனித்தும் இருக்கின்றான் எப்பொருளுக்கும் தலைவனாகிய இறைவன். அவன் தானே அனைத்துமாக இருப்பது உண்மையே ஆகும்.`,
  },
  {
    id: 1770, tantraId: 7, verseNumber: 1769,
    tamil: `கொழுந்தினைக் காணில் குவலயம் தோன்றும்
எழுந்திடம் காணில் இருக்கலும் ஆகும்
பரந்திடம் காணில் பார்ப்பதி மேலே
திரண்டெழக் கண்டவன் சிந்தையு ளானே`,
    transliteration: `koḻuntiṉaik kāṇil kuvalayam tōṉṟum
eḻuntiṭam kāṇil irukkalum ākum
parantiṭam kāṇil pārppati mēlē
tiraṇṭeḻak kaṇṭavaṉ cintaiyu ḷāṉē`,
    english: `1769: See Siva and Sakti and see All
See that Tender Flame
You will have seen all universe;
Rise and see His World
There you shall forever remain;
See the Expanses Vast
You shall have seen the Lord with Sakti entwined;
The Lord that in your thought resides.`,
    elaborationTamil: `தமக்குள்ளிருந்து ஞானமாக வெளிப்படுகின்ற இறைவனின் ஆரம்ப நிலையை தரிசிக்கும் சாதகர்களுக்கு உலகங்கள் அனைத்திலும் சூட்சுமமாக அவன் கலந்து இருப்பது தெரியும். அவன் தமக்குள்ளிருந்து எழுந்து வந்த சுவடை கண்டு உணர்ந்தால் அதன் மூலம் அவனை அடைந்து எப்போதும் அவனோடு சேர்ந்தே இருப்பதும் முடியும். தமக்குள்ளிருந்து தோன்றிய இறைவனே அனைத்து உலகங்களுக்கும் பரவி இருக்கின்ற சுவடை கண்டு உணர்ந்தால் பராசக்தியின் தலைவனாக அனைத்திற்கும் மேலே அவன் வீற்றிருப்பதை உணரலாம். அப்படி அனைத்திலும் கலந்து நிற்கின்ற இறைவன் ஒன்றாக திரண்டு எழுந்து நிற்பதை கண்டு உணர்ந்த சாதகர்களின் அறிவுக்கு உள்ளே அவன் எப்போதும் ஞான இலிங்கமாக வீற்றிருப்பான்.`,
  },
  {
    id: 1771, tantraId: 7, verseNumber: 1770,
    tamil: `எந்தை பரமனும் என்னம்மை கூட்டமும்
முந்த உரைத்து முறைசொல்லின் ஞானமாம்
சந்தித்து இருந்த இடம்பெருங் கண்ணியை
உந்தியின் மேல்வைத்து உகந்து இருந்தானே`,
    transliteration: `entai paramaṉum eṉṉammai kūṭṭamum
munta uraittu muṟaicolliṉ ñāṉamām
cantittu irunta iṭamperuṅ kaṇṇiyai
untiyiṉ mēlvaittu ukantu iruntāṉē`,
    english: `1770: Worship Siva-Sakti and Realize Jnana
The Lord, my Father
His Sakti-Cluster, my Mother
Chant their name in order according
That verily is Jnana Divine;
Above the navel, in my heart,
There with Her He resides
In rapture unceasing.`,
    elaborationEnglish: `Divine jnana is to chant the glory of the Lord and His Sakti, the heavenly Father and Mother. They induct the jiva into suddha and asuddha maya groups. Disentangling him, they place him in turiya state. Siva then takes His abode in him. This is the play of Siva/Sakti.`,
    elaborationTamil: `எமது தந்தையாகிய பரம்பொருளும், எமது தாயாகிய அனைத்து விதமான சக்திகளும் முழுவதுமாக தாம் உணர்ந்ததை எடுத்துச் சொல்லி தகுதியானவர்களுக்கு உணர்ந்து கொள்ளும் படி சொல்ல முடிந்தால் அதுவே உண்மை ஞானம் ஆகும். அப்படி உண்மை ஞானம் பெற்ற ஞானிகளுக்கு அழகிய பெரும் கண்களை உடைய இறைவி இறைவனோடு சந்தித்து இருக்கின்ற இடமாக பாடல் #1764 இல் உள்ளபடி நடுவாகிய நிலைக்கு மேல் வைத்து இருக்கும் போது அங்கே இறைவனும் விருப்பத்தோடு ஞான இலிங்கமாக இருப்பான்.`,
  },
  {
    id: 1772, tantraId: 7, verseNumber: 1771,
    tamil: `சத்தி சிவன்விளை யாட்டாம் உயிராகி
ஒத்த இருமாயா கூட்டத்து இடையூட்டிச்
சுத்தம தாகும் துரியம் பிறிவித்துச்
சித்தம் புகுந்து சிவம்அகம் ஆக்குமே`,
    transliteration: `catti civaṉviḷai yāṭṭām uyirāki
otta irumāyā kūṭṭattu iṭaiyūṭṭic
cuttama tākum turiyam piṟivittuc
cittam pukuntu civamakam ākkumē`,
    english: `1771: The Play of Sakti--Sakti activates Jiva
Into the Maya Group--Suddha and Asuddha
They induct the Jiva;
From Pure Turiya State disentangling him,
They his thoughts enter;
And inside him, Siva His habitation takes;
--This the play of Sakti-Siva.`,
    elaborationTamil: `இறைவியும் இறைவனும் தாங்கள் ஆடுகின்ற திருவிளையாட்டின் மூலம் உயிர்களின் வினைகளுக்கு ஏற்ப ஐந்து பூதங்களால் உடலை உண்டாக்கி அதனோடு உயிரை சேர்த்து, ஒன்றாக இருக்கின்ற சுத்தம், அசுத்தம் ஆகிய இரண்டு விதமான மாயைகளின் கூட்டத்திற்கு நடுவில் பந்த பாசங்களால் அந்த உயிர்களை பூட்டி அவர்களின் வினைகளை அனுபவிக்க வைக்கின்றார்கள். அந்த உயிர்களில் தம்மை அடைய விரும்பி முயற்சி செய்கின்ற உயிர்களின் வினைகளை சிறிது சிறிதாக நீக்கி சுத்தம் செய்து, அது அனுபவிக்க வேண்டிய அனைத்து அவத்தைகளையும் அதனிடமிருந்து மாற்றி நீக்கி விட்டு, அந்த உயிரின் சித்தத்தை பேரின்பத்தில் மகிழ்ந்து இருக்கும் படி செய்து, சிவமாகவே அந்த உயிரின் உள்ளத்தை ஞான இலிங்கமாக்கி விடுவார்கள்.`,
  },
  {
    id: 1773, tantraId: 7, verseNumber: 1772,
    tamil: `சத்தி சிவன்தன் விளையாட்டுத் தாரணி
சத்தி சிவமுமாம் சிவன்சத் தியுமாகும்
சத்தி சிவமன்றித் தாபரம் வேறில்லை
சத்திதான் என்றும் சமைந்துரு வாகுமே`,
    transliteration: `catti civaṉtaṉ viḷaiyāṭṭut tāraṇi
catti civamumām civaṉcat tiyumākum
catti civamaṉṟit tāparam vēṟillai
cattitāṉ eṉṟum camainturu vākumē`,
    english: `1772: All Creation is Sakti-Siva Play
All the Universe is the play of Sakti-Siva
Sakti is Siva, and Siva is Sakti
Without Sakti and Siva is no manifest creation
It is Sakti and Siva that forever Form assume.`,
    elaborationEnglish: `Without Sakti and Siva is no manifest creation
It is Sakti and Siva that forever Form assume.

Sakti is Siva. Siva is Sakti. All the universe is the play of
Sakti/Siva. There will be no visible creation without Siva and
Sakti. Sakti assumes form continuously.

7. Flas SN nisd`,
    elaborationTamil: `இறைவியும் இறைவனும் தங்கள் திருவிளையாட்டால் அண்ட சராசரங்கள் அனைத்தும் உருவாக்குகின்றார்கள். இறைவியானவள் இறைவனுமாகவும் இருக்கின்றாள், இறைவனாவன் இறைவியாகவும் இருக்கின்றான். இறைவியும் இறைவனும் இல்லாமல் இந்த உலகத்தில் ஆதாரமாக பற்றிக் கொள்ள வேண்டி பொருள் வேறு எதுவும் இல்லை. இறைவி தானே இறைவனோடு சேர்ந்து கலந்து அனைத்து விதமான வடிவங்களாகவும் ஆகுகின்றாள். இதை பரிபூரணமாக உணர்ந்து கொள்வதே ஞான இலிங்கத்தின் தத்துவமாகும்.`,
  },
  {
    id: 1774, tantraId: 7, verseNumber: 1773,
    tamil: `குரைக்கின்ற வாரிக் குவலய நீரும்
பரக்கின்ற காற்றுப் பயில்கின்ற தீயும்
நிரைக்கின்ற வாறிவை நீண்டகன் றானை
வரைத்து வலம்செயு மாறுஅறி யேனே`,
    transliteration: `kuraikkiṉṟa vārik kuvalaya nīrum
parakkiṉṟa kāṟṟup payilkiṉṟa tīyum
niraikkiṉṟa vāṟivai nīṇṭakaṉ ṟāṉai
varaittu valamceyu māṟuaṟi yēṉē`,
    english: `1773: Siva is Immanent and Transcendent
He pervades the roaring waters of the seas
He permeates the spreading winds and flaming fire
Thus is He immanent in all Nature
Yet I know Him not, adore Him not.`,
    elaborationTamil: `சத்தம் இருக்கின்ற ஆகாயத்தின் வழியில் உலகமும் [நிலம்], உலகத்தில் இருக்கின்ற நீரும், அலைந்து திரிகின்ற காற்றும், பொருளின் தன்மைக்கு ஏற்ப பழகுகின்ற நெருப்பும், இப்படி ஐந்து பூதங்களின் கூட்டமாக இருக்கின்ற வழியில் அனைத்திலும் நீண்டு விரிந்தும், இவை அனைத்தையும் தாண்டியும் இருக்கின்ற பரம் பொருளாகிய இறைவனை ஒரு எல்லைக்குள் வரையறுத்து அவனை வணங்குவதற்கான வழியை யாம் அறியாமல் இருக்கின்றோம்.`,
  },
  {
    id: 1775, tantraId: 7, verseNumber: 1774,
    tamil: `வரைத்து வலஞ்செய்யு மாறுஇங்குஒன்று உண்டு
நிரைத்து வருகங்கை நீர்மலர் ஏந்தி
உரைத்து அவன் நாமம் உணரவல் லார்க்குப்
புரைத்துஎங்கும் போகான் புரிசடை யோனே`,
    transliteration: `varaittu valañceyyu māṟuiṅkuoṉṟu uṇṭu
niraittu varukaṅkai nīrmalar ēnti
uraittu avaṉ nāmam uṇaraval lārkkup
puraittueṅkum pōkāṉ puricaṭai yōṉē`,
    english: `1774: Only Way of Knowing Siva is Worship
There is but one way here
Of knowing Him and adoring Him
They who with water and flower chant His name
They shall know Him;
And from them He of the matted lock
Separates not.`,
    elaborationTamil: `பாடல் #1773 இல் உள்ளபடி பஞ்ச பூதங்களால் ஆகிய அனைத்துமாகவும் அவை அனைத்தையும் தாண்டியும் அளவில்லாமல் இருக்கின்ற இறைவனை ஒரு எல்லைக்குள் வரையறுத்து தாம் இருக்கின்ற இடத்திலேயே வழிபாடு செய்கின்ற முறை ஒன்று இருக்கின்றது. எப்போதும் அசைந்து ஓடி வருகின்ற கங்கையாக பாவித்த தூய்மையான நீரையும், வாசனை மிக்க தூய்மையான மலரையும் கைகளில் ஏந்திக் கொண்டு, மனதிற்குள் ஜெபிக்கின்ற இறைவனின் திருநாமத்தின் மூலம் இறைவனை தமக்குள்ளேயே உணர முடிந்தவர்களுக்கு, எங்கும் பொய்த்து போகாமல் மாறாத சத்தியமாக எப்போதும் உடன் இருப்பான் கயிறு போல் திரிந்த சடை முடியை தலையில் அணிந்து கொண்டு இருக்கின்ற அருள் வடிவான இறைவன்.`,
  },
  {
    id: 1776, tantraId: 7, verseNumber: 1775,
    tamil: `ஒன்றெனக் கண்டோ ம் ஈசன் ஒருவனை
நன்றென்று அடியிணை நான்அவனைத்தொழ
வென்றுஐம் புலமும் மிகக்கிடந்து இன்புற
அன்றுஎன்று அருள்செய்யும் ஆதிப் பிரானே`,
    transliteration: `oṉṟeṉak kaṇṭō m īcaṉ oruvaṉai
naṉṟeṉṟu aṭiyiṇai nāṉavaṉaittoḻa
veṉṟuaim pulamum mikakkiṭantu iṉpuṟa
aṉṟueṉṟu aruḷceyyum ātip pirāṉē`,
    english: `1775: Worship Him as the One Being
As the One and Only Being
I saw the Lord,
And full well I adored His Holy Feet,
Subduing my senses five;
And He His blessings granted,
The gracious One, the Lord Primal.`,
    elaborationTamil: `ஐந்து விதமான பூதங்களால் உருவாகிய அசையும் பொருள் அசையா பொருள் ஆகிய அனைத்தும் ஒன்றே என்று கண்டு தரிசித்து எம் பரம்பொருளாகிய இறைவன் ஒருவனே அவை அனைத்துமாக இருப்பதை உணர்ந்து கொண்டோம். ஆகவே அவை அனைத்தும் நன்மையானது என்றும் இறைவனின் திருவடிகளுக்கு சரிசமமானது என்றும் யாம் அறிந்து கொண்டு, அவனை ஐந்து பூதங்களால் ஆகிய அனைத்திலும் கண்டு வணங்கினோம். அதன் பயனால் உலக ஆசைகளிலிருந்து வெற்றி பெற்ற எமது ஐந்து புலன்களும் இறைவனுடனே மிகவும் சேர்ந்து கிடந்து பேரின்பத்தில் திளைத்திருக்கும் படி அப்பொழுதில் இருந்து என்றும் அருள் செய்கின்றான் ஆதி மூல தலைவனாகிய இறைவன்.`,
  },
  {
    id: 1777, tantraId: 7, verseNumber: 1776,
    tamil: `மலர்ந்த அயன்மால் உருத்திரன் மகேசன்
பலந்தரும் ஐம்முகன் பரவிந்து நாதம்
நலந்தரும் சத்தி சிவன்வடி வாகிப்
பலந்தரு லிங்கம் பராநந்தி யாமே`,
    transliteration: `malarnta ayaṉmāl uruttiraṉ makēcaṉ
palantarum aimmukaṉ paravintu nātam
nalantarum catti civaṉvaṭi vākip
palantaru liṅkam parānanti yāmē`,
    english: `1776: Linga's Nine Aspects
Brahma, Vishnu, Rudra, Mahesa
The five-faced Sadasiva, Bindu and Nada
Sakti and Siva--
All these as Linga His blessings grants,
He is but Nandi that is Para Supreme.`,
    elaborationEnglish: `Brahma, Vishnu, Rudra, Mahesvara, Sadasiva of the five
faces, bindu, nada, Sakti and Siva — all the nine aspects
of Siva shower their blessings as Nandi himself.`,
    elaborationTamil: `அனைத்திற்கும் மேலான அசையா சக்தியாகிய சதாசிவமூர்த்தி எனும் பரம்பொருளே சிவ இலிங்க வடிவமாக இருந்து தனது பேரருளால் வெளிச்சத்தின் வடிவமாகிய இறைவி, சத்தத்தின் வடிவமாகிய இறைவன், அவர்களுக்கு கீழே ஐந்து விதமான தொழில்களை புரிகின்ற பிரம்மன், திருமால், உருத்திரன், மகேஸ்வரன், சதாசிவன் ஆகிய ஐந்து தெய்வங்களாகவும் இருந்து அனைவருக்கும் சக்தி கொடுத்து வழி நடத்துகின்ற குருநாதனாகவும் இருக்கின்றான்.`,
  },
  {
    id: 1778, tantraId: 7, verseNumber: 1777,
    tamil: `மேவி எழுகின்ற செஞ்சுடர் ஊடுசென்று
ஆவி எழும்அள வன்றே உடலுற
மேவப் படுவதும் விட்டு நிகழ்வதும்
பாவித்து அடக்கிற் பரகதி தானே`,
    transliteration: `mēvi eḻukiṉṟa ceñcuṭar ūṭuceṉṟu
āvi eḻumaḷa vaṉṟē uṭaluṟa
mēvap paṭuvatum viṭṭu nikaḻvatum
pāvittu aṭakkiṟ parakati tāṉē`,
    english: `1777: Rouse Kundalini and reach Supreme State
And upward your Prana course;
Halting within the body
The acts of inhalation and exhalation
This, if you, through practice accomplish
You indeed have reached
The Supreme State
Divine.`,
    elaborationTamil: `அசையா சக்திக்குள் கலந்து இருக்கின்ற ஆசைகளாகிய அசையும் சக்தியும் சேர்ந்து எழுகின்ற சிகப்பான சுடராகிய பேரொளியை ஊடுருவிச் சென்று, ஆசைகளை அனுபவிப்பதற்கு ஏற்ற வலிமை பெற்ற ஆன்மாவாக பலவாறாக பிரிந்து எழுந்து, அதனதன் ஆசைகளின் அளவுக்கு ஏற்ப அப்போதே அவற்றுக்கு ஏற்ற உடலை தமது அருளால் உருவாக்கி கொடுத்து, அதற்குள் பொருந்தி இருந்து செயல் படுவதும், அந்த ஆன்மாக்களை விட்டு அனைத்திற்கும் மேலாக இருந்து தமது பேரருளால் அனைத்தையும் இயக்குவதையும் செய்கின்ற பரம்பொருளாகிய இறைவனின் தன்மைகளை தமக்குள்ளே உணர்ந்து தாமும் அவராகவே பாவனை செய்து, தமது ஐந்து புலன்களை அடக்கி எண்ணங்கள் அற்ற நிலையை அடைந்தால், அனைத்திற்கும் மேலான இறை நிலையை தாமும் அடைய முடியும். கருத்து: இறைவனோடு எப்போதும் சேர்ந்தே இருந்த ஆன்மாவானது தமது ஆசைகளால் பிறவி எடுப்பதும், அதனதன் ஆசைகளுக்கு ஏற்ற வலிமை பெற்ற உடலும் உயிருமாக பிறப்பதும், வாழ்வில் பல வித செயல்களை புரிந்து ஆசைகளை தீர்த்துக் கொள்வதும், பின்பு இறைவனை தமக்குள் உணர்வதும், அதன் பயனால் ஆசைகளற்ற நிலைக்கு செல்வதும், எண்ணங்கள் அற்ற அந்த நிலையில் தாமே சிவமாக ஆகி விடுவதும், ஆகிய இவை அனைத்தும் சிவ இலிங்க வடிவமாக இருக்கின்ற இறைவனின் பேரருளால் ஆகும்.`,
  },
  {
    id: 1779, tantraId: 7, verseNumber: 1778,
    tamil: `உடல்பொருள் ஆவி உதகத்தாற் கொண்டு
படர்வினை பற்றறப் பார்த்துக்கை வைத்து
நொடியின் அடிவைத்து நுண்ணுணர் வாக்கி
கடியப் பிறப்பறக் காட்டினன் நந்தியே`,
    transliteration: `uṭalporuḷ āvi utakattāṟ koṇṭu
paṭarviṉai paṟṟaṟap pārttukkai vaittu
noṭiyiṉ aṭivaittu nuṇṇuṇar vākki
kaṭiyap piṟappaṟak kāṭṭiṉaṉ nantiyē`,
    english: `1778: Lord appears as Siva Guru and Baptises the Soul
My body, wealth and life,
He took from me as sacrificial offering,
Through ritual appropriate;
He directed his spiritual glance at me
And dispelled my Karma's network to destruction;
And then He laid His hands on me
And planting His Feet on my head
In a trice imparted Spiritual Awareness
And thus my birth's cycle He ended
He, the Nandi,
Through these acts of Diksha, successive.`,
    elaborationTamil: `உடல், அதற்குள் பொருளாக மறைந்து இருக்கின்ற இறைவன், ஆன்மா ஆகிய மூன்றும் சேர்ந்து தாயின் கர்ப்பப் பைக்குள் இருக்கின்ற தண்ணீரில் பிறவி எடுத்துக் கொண்டு வரும் படி செய்து, அந்த பிறவியில் தமது ஆசைகளை தீர்த்துக் கொள்ளும் போது அதனால் சேர்ந்து கொள்ளுகின்ற பல விதமான வினைகளால் உருவாகுகின்ற பற்றுக்கள் நீங்கும் படி தமது திருக்கண்ணால் பார்த்து (நயன தீட்சை), தமது திருக்கரங்களை வைத்து அபயம் கொடுத்து (ஸ்பரிச தீட்சை), ஒரு கண நேரத்தில் தமது திருவடிகளை வைத்து (திருவடி தீட்சை), அதன் மூலம் ஞானமாகிய நுண்ணியமான உணர்வுகளை (ஞான தீட்சை) ஆக்கிக் கொடுத்து, துன்பங்களால் நீண்டு கொண்டே இருக்கின்ற பிறவி சுழற்சியிலிருந்து நீங்குவதற்கான வழியை காட்டி அருளினான் உள்ளுக்குள் குருநாதனாக இருக்கின்ற இறைவன்.`,
  },
  {
    id: 1780, tantraId: 7, verseNumber: 1779,
    tamil: `உயிரும் சரீரமும் ஒண்பொரு ளான
வியவார் பரமும்பின் மேவும் பிராணன்
செயலார் சிவமும் சிற்சத்தி ஆதிக்கே
உயலார் குருபரன் உய்யக் கொண்டானே`,
    transliteration: `uyirum carīramum oṇporu ḷāṉa
viyavār paramumpiṉ mēvum pirāṇaṉ
ceyalār civamum ciṟcatti ātikkē
uyalār kuruparaṉ uyyak koṇṭāṉē`,
    english: `1779: Guru works for Disciple's Redemption
Life and body, and Prana breath that fleets after,
Siva the mighty and Chit Sakti that consorts
And Param the Truth Supreme
--All these to attain,
Gurupara my redemption worked.`,
    elaborationTamil: `உயிரோடு இருக்கின்ற உடலும், அதனோடு ஒன்றாக சேர்ந்து இருக்கின்ற பொருளாகிய ஆன்மாவும், அனைத்திலும் உயர்ந்து முழுவதுமாக இருக்கின்ற பரம்பொருளும், உடல் எடுத்த பிறகு வந்து சேர்ந்து கொள்ளுகின்ற மூச்சுக்காற்றும், ஆகிய இவை அனைத்தின் செயல்களிலும் முழுவதுமாக இருக்கின்ற இறைவனும் ஞானமாக இருக்கின்ற இறைவியுமே ஆதியிலிருந்தே செயல் பட வைக்கின்றார்கள் என்பதை முழுவதுமாக உணர்ந்த அடியவர்களிடம் முழுமையாக இருக்கின்ற குருவாகிய பரம்பொருள் அவர்களை முக்தி நிலைக்கு ஏற்றிச் செல்வதற்கு ஆட்கொண்டு அருளுவார்.`,
  },
  {
    id: 1781, tantraId: 7, verseNumber: 1780,
    tamil: `பச்சிம திக்கலே வைத்தஆ சாரியன்
நிச்சலும் என்னை நினையென்ற அப்பொருள்
உச்சிக்கும் கீழது உள்நாக்கு மேலது
வைச்ச பதமிது வாய்திற வாதே`,
    transliteration: `paccima tikkalē vaittaā cāriyaṉ
niccalum eṉṉai niṉaiyeṉṟa apporuḷ
uccikkum kīḻatu uḷnākku mēlatu
vaicca patamitu vāytiṟa vātē`,
    english: `1780: Guru imparts the Secret Divine
To His west (right), He seated me
"Daily on me meditate"--said He,
"That it is but the Truth that lies seated
Between the crown of the head and the palate of the mouth
This the Word True,
Cherish it as secret divine."`,
    elaborationEnglish: `Seating the disciple to his right, Gurupara said: ‘*Meditate
on the Truth that lies in the ajna centre bétween the crown
of the head and the palate of the mouth.”’ This is the true
word Let the seeker cherish it as a divine secret.`,
    elaborationTamil: `மேல் திசையிலே இறையருளால் வைக்கப் பட்ட குருவாக வழிகாட்டுகின்ற ஜோதியானது தினமும் தன்னை நினைத்துக் கொண்டே இரு என்று அருளிய அந்த பரம்பொருளின் வடிவமானது உச்சந் தலைக்கு கீழ் உள்ள இடத்திலும், வாய்க்கு உள்ளே இருக்கின்ற அண்ணாக்குக்கு மேலே உள்ள இடத்திலும் உள்ள சகஸ்ரதளத்தில் இறையருளால் வைக்கப் பட்ட திருவடிகளாக இருக்கின்றது. வாய் திறந்து பேசாமல் மனதை அடக்கி அந்த திருவடிகளின் மேலேயே எண்ணத்தை வைத்து இருக்க வேண்டும்.`,
  },
  {
    id: 1782, tantraId: 7, verseNumber: 1781,
    tamil: `பிட்டடித்து எங்கும் பிதற்றித் திரிவோனை
ஒட்டடித்து உள்ளமர் மாசெலாம் வாங்கித்
தட்டொக்க மாறினன் தன்னையும் என்னையும்
வட்டமது ஒத்தது வாணிபம் வாய்த்ததே`,
    transliteration: `piṭṭaṭittu eṅkum pitaṟṟit tirivōṉai
oṭṭaṭittu uḷḷamar mācelām vāṅkit
taṭṭokka māṟiṉaṉ taṉṉaiyum eṉṉaiyum
vaṭṭamatu ottatu vāṇipam vāyttatē`,
    english: `1781: Siva makes Jiva Pure as Himself
Aimless I wandered;
--Me, He made pure,
All my impurities cleansed
Me and He, to balance brought
--A barter, all to perfection indeed!`,
    elaborationEnglish: `The disciple wandered aimlessly, indulging in indiscriminate talk. Gurupara cleansed him of impurities and made him pure. Then the disciple and Guru alone remained.`,
    elaborationTamil: `அனைத்தையும் இறைவனே செய்கின்றான் என்று நினைக்காமல் நான் செய்கின்றேன் என்கிற தாழ்வான எண்ணத்தில் பல விதமான செயல்களை செய்து கொண்டு, தேவை இல்லாதவற்றை பேசிக் கொண்டு, வீணாக அலைந்து திரிந்தாலும் இறைவன் விதித்த தர்மப்படி வாழ்க்கையை கடத்துகின்ற எம்மிடமுள்ள தூசுகளை நீக்கி, எமக்குள்ளே வீற்றிருக்கின்ற அழுக்குகளை அனைத்தையும் தாமே வாங்கிக் கொண்டு அருளினான் இறைவன். பிறகு, குற்றத்தை சேர்ந்து இருக்காத தூய்மையாக எம்மை மாற்றி அருளிய இறைவனையும் எம்மையும் ஒரே வட்டமாகிய தன்மைக்குள் ஒன்றாக சேர்ந்து இருப்பதாகிய நிலைக்கு கொண்டு வந்து, தம்மை நோக்கி பிற உயிர்களும் வருவதற்கான வழிகளை எம்மை செய்ய வைத்து, அதன் பயனால் முக்தியை கொடுத்து எமக்கு அருளுகின்றான் இறைவன்.`,
  },
  {
    id: 1783, tantraId: 7, verseNumber: 1782,
    tamil: `தரிக்கின்ற பல்லுயிர்க்கு எல்லாம் தலைவன்
இருக்கின்ற தன்மையை ஏதும் உணரார்
பிரிக்கின்ற விந்து பிணக்கறுத்து எல்லாம்
கருக்கொண்ட ஈசனைக் கண்டுகொண்டேனே`,
    transliteration: `tarikkiṉṟa palluyirkku ellām talaivaṉ
irukkiṉṟa taṉmaiyai ētum uṇarār
pirikkiṉṟa vintu piṇakkaṟuttu ellām
karukkoṇṭa īcaṉaik kaṇṭukoṇṭēṉē`,
    english: `1782: Siva Extricates Jiva from Maya
He is the Lord of all life existent,
His true nature they know not,
He extricated me from Maya that separates,
Lo! then I beheld the Lord that is seed of all.`,
    elaborationTamil: `உடல் கொண்டு பிறவி எடுக்கின்ற பல விதமான உயிர்கள் அனைத்திற்கும் தலைவனாக இருக்கின்ற இறைவனின் தன்மைகள் எதையும் உணராதவர்கள் இறையருளால் உணர்த்தப் பட்ட தர்மத்தை முறையாக கடை பிடித்து வாழும் போது, இறைவனிடமிருந்து அவர்களை பிரித்து வைத்திருக்கின்ற மாயையாகிய ஆசைகள் பந்தங்களாகிய கட்டுக்களை அறுத்து, அவர்களது உடல் பொருள் ஆவி ஆகிய அனைத்தையும் தமக்குள்ளேயே சேர்த்துக் கொண்டு அருளுகின்ற இறைவனை யாம் கண்டு கொண்டோம்.`,
  },
  {
    id: 1784, tantraId: 7, verseNumber: 1783,
    tamil: `கூடும் உடல்பொருள் ஆவி குறிக்கொண்டு
நாடி அடிவைத்து அருள்ஞான சத்தியால்
பாடல் உடலினில் பற்றற நீக்கியே
கூடிய தானவ னாம்குளிக் கொண்டே`,
    transliteration: `kūṭum uṭalporuḷ āvi kuṟikkoṇṭu
nāṭi aṭivaittu aruḷñāṉa cattiyāl
pāṭal uṭaliṉil paṟṟaṟa nīkkiyē
kūṭiya tāṉava ṉāmkuḷik koṇṭē`,
    english: `1783: Siva takes Jiva into Himself
Intent on redemption of my body, wealth and life
He sought me and planted His Feet on my head
And with the Grace of Sakti divine He exorcised
My love for the body fleshly;
And He and I as one He made
Intermingling in union inseparate.`,
    elaborationTamil: `உயிர்களின் உடல், அதற்குள் மறைந்து இருக்கின்ற பொருளாகிய இறைவன், அந்த இறைவனின் சிறு பகுதியாகிய ஆன்மா, ஆகிய மூன்றும் ஒன்றாக சேர்ந்து இருப்பதை உணர்ந்து கொள்வதையே குறிக்கோளாகக் கொண்டு, உயிர்கள் தம்மை தேடி வர வேண்டும் என்கின்ற மாபெரும் கருணையினால் தமது அருளை அவர்களுக்குள் வைத்து அருளுகின்றான் அறிவு வடிவாகிய இறைவன். அந்த இறைவனின் ஞான சக்தியானது இறைவனை அடைய வேண்டும் என்கிற விருப்பத்தால் எப்போதும் இறைவன் மேல் எண்ணத்தை வைத்துக் கொண்டு தமக்கான செயல்களை செய்கின்ற உயிர்களின் உடலில் சேர்ந்து இருக்கின்ற ஆசைகள் பற்றுக்கள் ஆகிய அனைத்தையும் முழுவதுமாக நீக்கி விட்டு, அந்த உயிர்களோடு ஒன்றாக சேர்ந்து இருந்து, அவர்கள் தாமே இறைவனாக இருக்கின்ற நிலையையே குறிக்கோளாக கொண்டு இருக்க வைக்கின்றான்.`,
  },
  {
    id: 1785, tantraId: 7, verseNumber: 1784,
    tamil: `கொண்டான் அடியேன் அடிமை குறிக்கொள்ளக்
கொண்டான் உயிர்பொருள் காயக் குழாத்தினைக்
கொண்டான் பலமுற்றும் தந்தவன் கோடலால்
கொண்டான் எனஒன்றும் கூறகி லானே`,
    transliteration: `koṇṭāṉ aṭiyēṉ aṭimai kuṟikkoḷḷak
koṇṭāṉ uyirporuḷ kāyak kuḻāttiṉaik
koṇṭāṉ palamuṟṟum tantavaṉ kōṭalāl
koṇṭāṉ eṉaoṉṟum kūṟaki lāṉē`,
    english: `1784: Siva by taking all, Gives All
He marked me out his vassal to-be
My life, possessions and body He took as His own;
But as he it was that all my sustenance gave
How dare I say, He took anything from me?`,
    elaborationEnglish: `He took me into his divine order of vassalage; making my body, life and possession as his own. He gave all and took all. And I gained in the barter. What have I to complain of?`,
    elaborationTamil: `எம்மை ஆட்கொண்ட இறைவன் தமது திருவடி கருணையால் உலக வாழ்க்கையை வினைகளுக்கு ஏற்ப அனுபவிக்கின்ற எம்மை அவனது அருளால் உணர்த்தப்பட்ட தர்மத்தை கடை பிடிக்கும் வழியில் செல்ல வைத்து, தமது திருக்கையினால் அபயம் என்கிற அருள் குறியைக் காட்டி எம்மை ஆட்கொண்டு அருளினான். அதன் பிறகு எமது உயிர், எமக்குள் பொருளாக மறைந்து இருக்கின்ற அறிவு வடிவாகிய இறை சக்தி, எமது உடல், ஆகிய மூன்றும் சேர்ந்து இருக்கின்ற கூட்டத்தை தனதாக ஏற்றுக் கொண்டு, எமக்குள் இருக்கின்ற ஆணவம், கன்மம், மாயை ஆகிய மூன்று விதமான மலங்களையும் முழுவதுமாக நீக்கி வீட்டு அவற்றை தந்த அவனே மீண்டும் எடுத்துக் கொள்வதின் மூலம் எம்மை ஆட்கொண்டு எம்மோடு இருக்கின்றான் என்றாலும் எதனுடனும் கூடி இருக்காமல் அனைத்தையும் தாண்டியும் நிற்கின்றான்.`,
  },
  {
    id: 1786, tantraId: 7, verseNumber: 1785,
    tamil: `குறிக்கின்ற தேகமும் தேகியும் கூடி
நெறிக்கும் பிராணன் நிலைபெற்ற சீவன்
பறிக்கின்ற காயத்தைப் பற்றியநேர்மை
பிறக்க அறியாதார் பேயுடன் ஒப்பரே`,
    transliteration: `kuṟikkiṉṟa tēkamum tēkiyum kūṭi
neṟikkum pirāṇaṉ nilaipeṟṟa cīvaṉ
paṟikkiṉṟa kāyattaip paṟṟiyanērmai
piṟakka aṟiyātār pēyuṭaṉ opparē`,
    english: `1785: Ghosts do not know the Truth of Life
This body, the Lord within,
The Prana that is breath,
And the Soul that dwells inside
The truth of all these
That to the perishable body pertains
They who know not,
Unto ghosts of the dead they are.`,
    elaborationTamil: `ஆசைகளையும் வினைகளையும் அனுபவிப்பதற்கு ஈடாக குறிக்கப் பட்ட உடலும், உடலுக்குள் வீற்றிருக்கின்ற ஆன்மாவும், ஒன்றாக சேர்ந்து வாழ்நாளுக்கு ஏற்றபடி இறைவனால் வழிவகுத்து கொடுக்கப் பட்ட மூச்சுக்காற்றும், அந்த மூச்சுக்காற்றை நிலையாகக் கொண்டு வாழ்கின்ற உயிரும், ஆகிய இவை அனைத்தும் சேர்ந்து சிறிது சிறிதாக அழிந்து கொண்டு இருக்கின்ற உடலை சார்ந்து தாம் வாழ்ந்தாலும் இந்த அனைத்திற்குள்ளும் உண்மை நெறியாக இருக்கின்ற தர்மத்தை, உடலோடு சார்ந்த உலகப் பொருள்களிலிருந்து பிரித்து அறிந்து உணர்ந்து கொள்ள முடியாதவர்கள், ஆசைகளை அனுபவிக்க வழியில்லாமல் அலைந்து திரிகின்ற பேய்களைப் போலவே இறைவனை உணர்வதே தங்களின் வாழ்க்கையின் குறிக்கோள் என்பதை உணராமல் வீணாக அலைந்து கழிக்கின்றார்கள்.`,
  },
  {
    id: 1787, tantraId: 7, verseNumber: 1786,
    tamil: `உணர்வுடை யார்கட்கு உலகமும் தோன்றும்
உணர்வுடை யார்கட்கு உறுதுயர் இல்லை
உணர்வுடை யார்கள் உணர்ந்தஅக் காலம்
உணர்வுடை யார்கண் உணர்ந்துகண் டாரே`,
    transliteration: `uṇarvuṭai yārkaṭku ulakamum tōṉṟum
uṇarvuṭai yārkaṭku uṟutuyar illai
uṇarvuṭai yārkaḷ uṇarntaak kālam
uṇarvuṭai yārkaṇ uṇarntukaṇ ṭārē`,
    english: `1786: Know the Finite Truth
They the Awareness have, see worlds all,
They the Awareness have, know sorrows none,
When they that
Awareness have truly realized,
They indeed have the
Truth Finite seen.`,
    elaborationTamil: `பாடல் #1785 இல் உள்ளபடி உடல், ஆன்மா, உயிர் ஆகிய இந்த மூன்றுக்குள்ளும் இருக்கின்ற தர்மத்தை உணருகின்ற அனுபவத்தை பெற்றவர்களுக்கு, அனைத்து உலகங்களிலும் இருக்கின்ற தர்மங்களும் தெரிய வரும். அவர்களுக்கு இந்த உலகத்தில் அனுபவிக்க வேண்டிய துன்பங்கள் என்று எதுவும் இல்லை. அவர்கள் அந்த அனுபவத்தை உணர்ந்த அந்த நொடிப் பொழுதிலேயே தமக்குள் இருக்கின்ற தர்மத்தின் வடிவமாகிய இறைவனையும் முழுவதுமாக உணர்ந்து தரிசிப்பார்கள்.`,
  },
  {
    id: 1788, tantraId: 7, verseNumber: 1787,
    tamil: `காயப் பரப்பில் அலைந்து துரியத்துச்
சால விரிந்து குவிந்து சகலத்தில்
ஆயஅவ் ஆறாறு அடைந்து திரிந்தோர்க்குத்
தூய அருள்தந்த நந்திக்கு என் சொல்வதே`,
    transliteration: `kāyap parappil alaintu turiyattuc
cāla virintu kuvintu cakalattil
āyaav āṟāṟu aṭaintu tirintōrkkut
tūya aruḷtanta nantikku eṉ colvatē`,
    english: `1787: Woken from the Primordial Turiya State,
Wandering in the Bodily State--
Active in the Sakala State
With Tattvas six times six,
On them whose souls have thus roamed,
Nandi His Grace bestowed;
What shall I say of His greatness infinite!`,
    elaborationEnglish: `In his infinite greatness, Nandi bestows His grace on the souls of those who, having been woken from the primordial turiya state {kevala), have wandered in the bodily state (sakala) possessing the thirty-six tattvas.`,
    elaborationTamil: `உடலாக இருக்கின்ற பரம்பொருளின் அடையாளத்தில் வெளிப்புறமாக பல விதமாக அலைந்து திரிந்து அனுபவித்தலும், கனவு நிலையை சார்ந்து வாழ்ந்து மனதில் பல வித ஆசைகள் தோன்றி விரிந்து அனுபவித்தலும், மாயையே உண்மை என்ற ஒரு எண்ணத்திலேயே மனதை குவித்து வைத்து அதுவே எல்லாம் என்று நம்புதலும், ஆகிய பலவிதமான வழிகளால் தமது பிறவிக்கான ஆசைகளையும் வினைகளையும் அனுபவித்துக் கொண்டு இருந்தாலும், அந்த ஆசைகளின் வழியிலேயே இறைவனால் உணர்த்தப் பட்ட தர்மத்தை கடை பிடித்து திரிகின்ற அடியவர்களுக்கு, மாயை இல்லாத தூய்மையான அருளை தந்து அனைத்தும் மாயை தாமே உண்மை என்பதை உணர்த்திய குருநாதனாகிய இறைவனின் மாபெரும் கருணையை என்னவென்று யான் எடுத்து சொல்வது?`,
  },
  {
    id: 1789, tantraId: 7, verseNumber: 1788,
    tamil: `நானென நீயென வேறில்லை நண்ணுதல்
ஊனென ஊனுயிர் என்ன உடனின்று
வானென வானவர் நின்று மனிதர்கள்
தேனென இன்பம் திளைக்கின்ற வாறே`,
    transliteration: `nāṉeṉa nīyeṉa vēṟillai naṇṇutal
ūṉeṉa ūṉuyir eṉṉa uṭaṉiṉṟu
vāṉeṉa vāṉavar niṉṟu maṉitarkaḷ
tēṉeṉa iṉpam tiḷaikkiṉṟa vāṟē`,
    english: `1788: Siva and Jiva are inseparable
There is approach none as I and You;
Like body and life inseparate are We;
Together are We like the heavens and the heavenly beings;
Like the honey and its sweetness that I do savour.`,
    elaborationEnglish: `The best approach to Him is not in dualistic terms of ‘T’
and ‘You.’ Jiva and Siva are as inseparable as the body and
the life, the heaven and the heavenly beings, the honey and
its Sweetness.`,
    elaborationTamil: `நான் என்றும் நீ என்றும் வேறு வேறாக இல்லாமல் உலகத்தில் கிடைக்கின்ற அனைத்துமாகவும், தசைகளாகவும், உள்ளே இருக்கின்ற உயிராகவும், இந்த இரண்டும் சேர்ந்த உடலாகவும் நின்று, ஆகாயமாகவும், அதில் இருக்கின்ற தேவர்களாகவும் நின்று, மண்ணுலகில் இருக்கின்ற மனிதர்களாகவும் இறைவனே இருக்கின்றான் என்பதை அறியாமல், மாயையில் மயங்கி அந்த மயக்கமே உண்மை என்று நினைத்து சிற்றின்ப ஆசைகளை அனுபவிக்கின்ற இன்பத்திலேயே திளைத்து இருக்கின்ற வழியிலேயே வாழ்க்கையை கழிக்கின்றார்கள்.`,
  },
  {
    id: 1790, tantraId: 7, verseNumber: 1789,
    tamil: `அவனும் அவனும் அவனை அறியார்
அவனை அறியில் அறிவானும் இல்லை
அவனும் அவனும் அவனை அறியில்
அவனும் அவனும் அவனிவன் ஆமே`,
    transliteration: `avaṉum avaṉum avaṉai aṟiyār
avaṉai aṟiyil aṟivāṉum illai
avaṉum avaṉum avaṉai aṟiyil
avaṉum avaṉum avaṉivaṉ āmē`,
    english: `1789: Knower becomes the Known
He and he knows Him not;
If he knows Him, then Knower is he not;
If he knows Him
Then he the Knower and He the Known
Become but one.`,
    elaborationEnglish: `Become but one.

So long as Siva and jiva are considered as two separate
indentities, the jiva does not know Him. When jiva knows
Him, the knower (jiva) and the known (Siva) become one
and unitive.

piohg) si@“ercr Howes oamGtommytb`,
    elaborationTamil: `இறைவனும் அந்த இறைவனை தமக்குள் வைத்திருக்கின்ற உயிரும் உண்மையான பரம்பொருளை அறிந்து கொள்வதில்லை. இறைவனை மனித அறிவினால் அறிந்து கொண்டவர்களும் அவனை முழுவதுமாக அறிந்து கொள்வது இல்லை. இறைவன் உள்ளுக்குள் இருந்து உணர்த்தி அருளிய தர்மத்தை முறையாக கடைபிடிப்பதன் மூலம் உயிராக இருப்பவன் இறைவனாக தனக்குள் இருப்பவனை முழுவதுமாக அறிந்து உணர்ந்து கொண்ட பிறகு இறைவனும் உயிராக இருப்பவனும் இறைவனே தான் என்பதை உணர்ந்து தானே இறைவனாக வீற்றிருப்பான்.`,
  },
  {
    id: 1791, tantraId: 7, verseNumber: 1790,
    tamil: `நானிது தானென நின்றவன் நாடோ றும்
ஊனிது தானுயிர் போலுணர் வானுளன்
வானிரு மாமுகில் போற்பொழி வானுளன்
நானிது அம்பர நாதனும் ஆமே`,
    transliteration: `nāṉitu tāṉeṉa niṉṟavaṉ nāṭō ṟum
ūṉitu tāṉuyir pōluṇar vāṉuḷaṉ
vāṉiru māmukil pōṟpoḻi vāṉuḷaṉ
nāṉitu ampara nātaṉum āmē`,
    english: `1790: Lord's Infinite Bounty
As life and body alike feel
He in me stood in identity full;
Bounteous as He is unto the rains from heavens,
I with the heavenly Lord, one became.`,
    elaborationEnglish: `Siva stands in relation to jiva like the life and the body, and thanks to the bounteous Grace of Siva, the jiva can become one in Him in indistinguishable identity.`,
    elaborationTamil: `பாடல் #1789 இல் உள்ளபடி நான் இறைவன் என்று எண்ணுகின்ற எண்ணத்திலேயே இருக்காமல் தினந் தோறும் தனது உடலாக இருப்பதே இறைவன் தான் என்று எண்ணுகின்றான். அவன் இறைவன் அருளால் தனக்குள் உணர்த்தப் பட்ட இறை தர்மத்தை முறைப்படி கடைபிடிக்கும் போது, தனது உயிர் போல் இருக்கின்றவன் இறைவனே என்பதை உணர்ந்து கொள்கின்றான். அப்போது வானத்தில் இருக்கின்ற மாபெரும் மேகக் கூட்டம் மழையாகப் பொழிவதைப் போல தமது பேரருளை மழையாகப் பொழிபவன் தனக்குள்ளே இருக்கின்றான் என்பதை உணர்ந்து கொள்கின்றான். அதன் பிறகு தாமாக இருக்கின்ற இறைவனே ஆகாயத்தில் அனைத்திற்கும் தலைவனாகவும் இருக்கின்றான் என்கின்ற நிலையை அடைந்து விடுகின்றான்.`,
  },
  {
    id: 1792, tantraId: 7, verseNumber: 1791,
    tamil: `பெருந்தன்மை தானென யானென வேறாய்
இருந்ததும் இல்லைஅது ஈசன் அறியும்
பொருந்தும் உடல்உயிர் போல்உமை மெய்யே
திருந்தமுன் செய்கின்ற தேவர் பிரானே`,
    transliteration: `peruntaṉmai tāṉeṉa yāṉeṉa vēṟāy
iruntatum illaiatu īcaṉ aṟiyum
poruntum uṭaluyir pōlumai meyyē
tiruntamuṉ ceykiṉṟa tēvar pirāṉē`,
    english: `1791: Lord wrought Me to Perfection
Himself as Being Supreme
He stood not apart from me;
That the Lord Knows;
Unto the body and life are We;
This the truth;
He to perfection wrought me`,
    elaborationEnglish: `He is the Supreme Being. Still He never stood away and apart from jiva. He shapes the jiva to perfection and draws him into Him.`,
    elaborationTamil: `மிகப் பெரிய சாந்த நிலையில் இறைவன் என்றும் அடியவர் என்றும் வேறு வேறாக பிரிந்து இருக்கின்ற நிலை இல்லாமல் எப்போதும் ஒன்றாகவே சேர்ந்து இருக்கின்ற அந்த நிலையை இறைவனே அறிவான். அடியவரின் உடல் அழிந்து போவதற்கு முன் உடலும் உயிரும் ஒன்றாக பொருந்தி இருப்பதை போலவே பேருண்மையாகிய தர்மத்தை எப்போதும் பொருந்தி இருக்கின்ற உடலாகவே இறையருளால் உணர்த்தப் பட்ட தர்மத்தை முறைப்படி கடைபிடிக்கின்ற அடியவரின் உடலை மாற்றி அருளுகின்றான் தேவர்களுக்கெல்லாம் தலைவனாகிய இறைவன்.`,
  },
  {
    id: 1793, tantraId: 7, verseNumber: 1792,
    tamil: `இருபத மாவது இரவும் பகலும்
உருவது ஆவது உயிரும் உடலும்
அருளது ஆவது அறமும் தவமும்
பொருவது உள்நின்ற போகமது ஆமே`,
    transliteration: `irupata māvatu iravum pakalum
uruvatu āvatu uyirum uṭalum
aruḷatu āvatu aṟamum tavamum
poruvatu uḷniṉṟa pōkamatu āmē`,
    english: `1792: Truth is Indivisible
Darkness (ignorance) and Light (knowledge)
Are the states two;
Life and body are the forms two;
Dharma and penance are the graces two;
Truth is but the blessing within.`,
    elaborationTamil: `மாயையாகிய உலகத்தில் பொருளாக பிரித்து அறிந்து கொள்ள இறைவன் அருளியது இரவும் பகலுமாகிய இரண்டு நிலைகளே ஆகும். அதை வினைகளுக்கு ஏற்ப அனுபவிக்கின்ற உருவமாக இருப்பது இறைவன் அருளிய உடலும் அதற்குள் இருக்கின்ற உயிரும் ஆகும். அப்படி வினைகளை அனுபவித்துக் கொண்டு இருந்தாலும் இறையருளால் உள்ளுக்குள் உணர்த்தப்பட்ட தர்மத்தை முறைப்படி கடை பிடிக்கின்றவர்களுக்கு அந்த தர்மத்தின் பலனும் அவர்கள் மேற்கொண்ட தவத்தின் பலனுமே இறைவன் கொடுக்கின்ற திருவருளாக இருக்கின்றது. அந்த திருவருளே உண்மைப் பொருளாக அடியவருக்குள் நிற்கின்ற பேரின்பம் ஆகும்.`,
  },
  {
    id: 1794, tantraId: 7, verseNumber: 1793,
    tamil: `காண்டற்கு அரியன் கருத்திலன் நந்தியும்
தீண்டற்கும் சார்தற்கும் சேயனாத் தோன்றிடும்
வேண்டிக் கிடந்து விளக்கொளி யான்நெஞ்சம்
ஈண்டிக் கிடந்தங்கு இருளறும் ஆமே`,
    transliteration: `kāṇṭaṟku ariyaṉ karuttilaṉ nantiyum
tīṇṭaṟkum cārtaṟkum cēyaṉāt tōṉṟiṭum
vēṇṭik kiṭantu viḷakkoḷi yāṉneñcam
īṇṭik kiṭantaṅku iruḷaṟum āmē`,
    english: `1793: Pray and receive Divine Light
Elusive is He for us to see;
Beyond our Thoughts is He, the Nandi,
Distant is He to touch and feel,
Pray long in the light of your heart,
The darkness that envelops you dispelled stands.`,
    elaborationEnglish: `Nandi is beyond sight, beyond thought, beyond touch and feel. Praying to Him from the innermost recesses of your heart, the darkness of ignorance that envelopes you stands dispelled.`,
    elaborationTamil: `கண்களால் பார்த்து அறிந்து கொள்ளுவதற்கு மிகவும் கடினமானவன், எண்ணங்களால் யோசித்து பார்த்து அறிந்து கொள்ள முடியாதவன், உள்ளுக்குள் குருநாதனாக இருந்து வழிகாட்டுகின்ற இறைவன், வெளியில் தீண்டி பார்ப்பதற்கும் பற்றிக் கொண்டு இருப்பதற்கும் முடியாதபடி தொலைவில் இருக்கின்றவன், உள்ளுக்குள்ளே நாதமாக தோன்றுபவன், அவன் மட்டுமே வேண்டும் என்று வேண்டி கிடக்கின்ற அடியவர்களுக்கு உள்ளுக்குள் விளக்கில் இருக்கின்ற ஜோதியாகிய அன்பின் வடிவமாக வருகின்றவன். இப்படிப்பட்ட இறைவனின் திருவருளை பெற்றுக் கொண்டு அதிலேயே கிடக்கும் போது அடியவரின் உள்ளுக்குள் இருக்கின்ற அனைத்து விதமான மலங்களும் நீங்கிப் போய்விடும் வழியாக அதுவே இருக்கும்.`,
  },
  {
    id: 1795, tantraId: 7, verseNumber: 1794,
    tamil: `குறிப்பினின் உள்ளே குவலயம் தோன்றும்
வெறுப்பிருள் நீங்கில் விகிர்தனும் நிற்கும்
செறிப்புறு சிந்தையைக் சிக்கென நாடில்
அறிப்புறு காட்சி அமரரும் ஆமே`,
    transliteration: `kuṟippiṉiṉ uḷḷē kuvalayam tōṉṟum
veṟuppiruḷ nīṅkil vikirtaṉum niṟkum
ceṟippuṟu cintaiyaik cikkeṉa nāṭil
aṟippuṟu kāṭci amararum āmē`,
    english: `1794: God's Grace Leads to illumination
In the hint of His grace,
All universe shall be revealed to you;
When the darkness of ignorance lifts,
The Great one stands revealed;
When you seek Him,
Your swarming thoughts on Him centered,
You shall see the light of Jnana,
And thus immortal become.`,
    elaborationTamil: `உள்ளுக்குள் தோன்றும் ஜோதியாகிய இறைவனையே குறிக்கோளாக கொண்டு தியானிக்கின்ற அடியவர்களின் உள்ளே அண்ட சராசரங்களும் அதிலுள்ள அனைத்தும் உண்மைப் பொருளாக தோன்றும். அந்த திருவருள் ஜோதியால் ஆணவமாகிய மலத்தை நீக்கி விட்டால் அனைத்திலும் மாறுபட்டவனாகிய இறைவன் அடியவருக்குள் வந்து நிற்பான். அந்த இறைவனுக்கு நெருக்கமாக இருப்பதில் உறுதியாக நிற்கின்ற சிந்தனையை விடாது பற்றிக் கொண்டு இறைவனை தேடும் போது உள்ளுக்குள் உணரக்கூடிய முழுமையான திருவருள் காட்சி தோன்றும். அதை தரிசித்து தாமும் இறப்பு இல்லாத நிலையை அடையலாம்.`,
  },
  {
    id: 1796, tantraId: 7, verseNumber: 1795,
    tamil: `தேர்ந்தறி யாமையின் சென்றன காலங்கள்
பேர்ந்தறி வான் எங்கள் பிஞ்ஞகன் எம்இறை
ஆர்ந்தறி வார்அறி வேதுணை யாமெனச்
சார்ந்தறி வான்பெருந் தன்மைவல் லானே`,
    transliteration: `tērntaṟi yāmaiyiṉ ceṉṟaṉa kālaṅkaḷ
pērntaṟi vāṉ eṅkaḷ piññakaṉ emiṟai
ārntaṟi vāraṟi vētuṇai yāmeṉac
cārntaṟi vāṉperun taṉmaival lāṉē`,
    english: `1795: Lord Knows His Devotees in Time
In ignorance my time rolled on;
Yet my Lord will in time know me;
By their light of Knowledge and love intense
He will know them,
He the Bounteous One.`,
    elaborationEnglish: `Endless time passed in ignorance. When ignorance gives place to knowledge, the Lord will know jiva to: the extent of jiva’s depth of knowledge and intensity of love for the Bounteous One, will He be known to jiva.`,
    elaborationTamil: `தமக்குள்ளே இருக்கின்ற இறைவனின் திருவருளால் பிறவி இல்லாத நிலையை அடைய முடியும் என்பதை அறிந்து கொள்ளாத தன்மையினால் உயிர்களின் ஒரு பிறவியின் காலங்கள் வீணாக கழிந்து போகின்றது. இப்படி வீணாக வாழ்நாளை கழிக்காமல் இறைவனை தேடுகின்ற உயிர்கள் எது என்பதை பிரித்து அறிகின்றவன் பிறை நிலாவையும் கங்கையையும் தலையில் சடையாகச் சூடிக்கொண்டு பிறவி இல்லாத நிலையை அருளும் எமது தலைவனாகிய இறைவன் ஆவான். அவனை தமக்குள்ளே ஆராய்ந்து அறிகின்றவர்களுக்கு உண்மை அறிவாக எப்போதும் துணையாக இருப்பான். அந்த இறைவன் உள்ளுக்குள் இருந்து உணர்த்துகின்ற அறிவுத் துணையை எப்போதும் சார்ந்து இருந்து அனைத்தையும் அறிந்து கொள்ளுகின்ற அடியவர்கள் மிகப் பெரிய தன்மைகளை அடையும் வல்லமை பெற்றவர்களாக இருப்பார்கள்.`,
  },
  {
    id: 1797, tantraId: 7, verseNumber: 1796,
    tamil: `தானே அறியும் வினைகள் அழிந்தபின்
நானே அறிகிலன் நந்தி அறியுங்கொல்
ஊனே உருகி உணர்வை உணர்ந்தபின்
தேனே யனையன் நம் தேவர் பிரானே`,
    transliteration: `tāṉē aṟiyum viṉaikaḷ aḻintapiṉ
nāṉē aṟikilaṉ nanti aṟiyuṅkol
ūṉē uruki uṇarvai uṇarntapiṉ
tēṉē yaṉaiyaṉ nam tēvar pirāṉē`,
    english: `1796: Lord, of Himself, will Know You
Himself will know me,
When my Karmas perish;
I know not when; but Nandi will;
Do melt in piety
And reach divine Consciousness;
Sweet unto honey is our Lord of Immortals.`,
    elaborationEnglish: `The jiva does not know when his karmas will perish. But Nandi, the Lord of immortals, knows. Then He Himself will know the jiva. So let the aspirant melt himself in piety and Teach to divine consciousness.`,
    elaborationTamil: `இறைவன் உள்ளுக்குள் இருந்து உணர்த்துகின்ற அறிவின் துணையால் அடியவர்கள் தாமே அறிந்து கொள்ளக் கூடிய தங்களின் வினைகளையும் அவற்றை நீக்குகின்ற வழிகளையும் அறிந்து கொண்ட பிறகு, அவர்களின் அறிவுக்கு அவர்களே வகுத்துக் கொண்ட வரை முறைப்படி இருப்பதை அவர்களுக்குள் இருக்கின்ற குருநாதராகிய இறைவன் அறிவான். இப்படி வரை முறைப்படி வாழ்வதினால் தங்களின் வினைகள் அழிந்து போகும் போது அவர்களுக்குள் இருந்து பேரன்பானது வெளிப்படுகின்றது. அனைத்திற்கும் தலைவனாகிய இறைவனின் மேல் கொண்ட பேரன்பினால் தமது உடலையும் உருக்கிக் கொள்ளுகின்ற அளவிற்கு உருகின்ற மனதின் உணர்ச்சி நிலையை உண்மையாக உணர்ந்த பிறகு எவ்வளவு அருந்தினாலும் தெகிட்டாத தேனைப் போன்று அவர்களுக்கு துணையாக இருப்பவன் குருநாதனாகவும் தேவர்களுக்கெல்லாம் தலைவனாகவும் இருக்கின்ற இறைவன்.`,
  },
  {
    id: 1798, tantraId: 7, verseNumber: 1797,
    tamil: `நான் அறிந்து அன்றே இருக்கின்றது ஈசனை
வான்அறிந் தார் அறி யாது மயங்கினர்
ஊன்அறிந்து உள்ளே உயிர்க்கின்ற ஒண்சுடர்
தான்அறி யான்பின்னை யார்அறி வாரே`,
    transliteration: `nāṉ aṟintu aṉṟē irukkiṉṟatu īcaṉai
vāṉaṟin tār aṟi yātu mayaṅkiṉar
ūṉaṟintu uḷḷē uyirkkiṉṟa oṇcuṭar
tāṉaṟi yāṉpiṉṉai yāraṟi vārē`,
    english: `1797: If I do not Know Lord who else shall?
I have known the Lord from days bygone
But the Celestials knew Him not,
Doubt-tossed were they;
The Lord is the Light
In my fleshly body as Prana pulsates
If I know Him not, who else will?`,
    elaborationEnglish: `Because they were tossed in doubt, the celestials did not know the Lord; but the yogis had known Him in.the days gone by. As prana is the pulsation in the fleshy body, so is the Lord in jiva unscen.`,
    elaborationTamil: `எமக்குள்ளே யான் ஆராய்ந்து அறிந்து கொண்ட இறைவனே உயிர்கள் பிறவி எடுக்கின்ற அன்றே அதற்குள் மறைந்து நிற்கின்றான். வானுலகத்து தேவர்களும் அந்த இறைவன் இருப்பதை அறிந்து கொண்டாலும் அவனின் உண்மையான தன்மை எதுவென்று அறியாமல் நான் என்கின்ற ஆணவத்தில் மயங்கி நிற்கின்றார்கள். நான் என்கின்ற உடம்பு எது என்று அறிந்து கொண்டு அதற்கு உள்ளே உயிராக ஒன்றி இருக்கின்ற ஒளி வடிவான இறைவனை தமக்குள்ளே ஆராய்ந்து தனது வாழ்நாள் காலத்திலேயே அறிந்து கொள்ளாதவன், உயிர் போன பின்பு எப்படி அறிந்து கொள்ளப் போகின்றான்?`,
  },
  {
    id: 1799, tantraId: 7, verseNumber: 1798,
    tamil: `அருள்எங்கு மான அளவை அறியார்
அருளை நுகர்அமு தானதும் தேரார்
அருள்ஐங் கருமத்து அதிசூக்கம் உன்னார்
அருள்எங்கும் கண்ணானது ஆர்அறி வாரே`,
    transliteration: `aruḷeṅku māṉa aḷavai aṟiyār
aruḷai nukaramu tāṉatum tērār
aruḷaiṅ karumattu aticūkkam uṉṉār
aruḷeṅkum kaṇṇāṉatu āraṟi vārē`,
    english: `1798: Grace is All
They know not the measure of Grace
That is pervasive all;
They know not the ambrosial sweetness
That from Grace flows;
They think not of the Five Acts
That Grace subtle performs;
Who knows how all-pervasive is Grace, indeed!`,
    elaborationTamil: `இறையருளே அண்டசராசரங்கள் எங்கும் மற்றும் உலக வாழ்க்கையின் அனைத்து செயல்களிலும் வியாபித்து இருக்கின்ற அளவை யாரும் அறிவதில்லை. இறையருளை அனுபவிக்காதவர்கள் அதன் மூலமே கிடைக்கக் கூடிய அமிழ்தத்தை மட்டும் அருந்த விரும்புகின்றார்கள். இறையருளே படைத்தல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய ஐந்து விதமான தொழில்களின் மிக நுண்ணியமான மூல சக்தியாகவும் இயக்க சக்தியாகவும் இருப்பதை நினைத்து பார்க்காமல் இருக்கின்றார்கள். இறையருளே அனைத்தையும் பார்க்கின்ற கண்களாகவும் இருப்பதை யாரும் அறியாமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1800, tantraId: 7, verseNumber: 1799,
    tamil: `அறிவில் அணுக அறிவது நல்கிப்
பொறிவழி யாசை புகுத்திப் புணர்ந்திட்டு
அறிவது ஆக்கி அடியருள் நல்கும்
செறிவொடு நின்றார் சிவம்ஆயி னாரே`,
    transliteration: `aṟivil aṇuka aṟivatu nalkip
poṟivaḻi yācai pukuttip puṇarntiṭṭu
aṟivatu ākki aṭiyaruḷ nalkum
ceṟivoṭu niṉṟār civamāyi ṉārē`,
    english: `1799: Various Acts of Lord's Grace
To seek the Divine Light
He grants the light of knowledge;
He infuses the organs of sense
With desire
And leads you to enlightenment;
He then seats you
In the midst of the devout and holy;
They who His Grace thus received,
Verily became Siva themselves.`,
    elaborationEnglish: `He infuses jiva’s sense organs with a desire to seek enlightenment, leads him to that goal and grants him the light of knowledge. Many have thus received His Grace and have become holy; and remain devoted to Him. The Lord seats them amongst the yogis. They finally become Siva Himself,`,
    elaborationTamil: `ஞானத்தின் மூலம் இறைவனை அடைவதற்கு தேவையான அறிவை உள்ளுக்குள்ளே குருநாதராக இருக்கின்ற இறைவன் கொடுத்து, உடலில் உள்ள ஐந்து விதமான புலன்களின் வழியே பல விதமான ஆசைகளை உடலுக்குள் புகுத்தி, அந்த உடலோடு தாமும் கலந்து நின்று அந்த ஆசைகளை அனுபவிக்கச் செய்து, ஆசைகள் தீர்ந்த நிலையில் அவற்றிற்கு மேலான ஞானத்தை உயிர்கள் பெற்றுவிட்டால் அதன் பலனாக திருவருளை உள்ளுக்குள் இருக்கின்ற இறைவனே கொடுப்பான். அப்படி இறைவன் கொடுத்த அருளில் உச்ச நிலையை அடைந்து நிற்கின்ற அடியவர்கள் சிவமாகவே ஆகி விடுவார்கள்.`,
  },
  {
    id: 1801, tantraId: 7, verseNumber: 1800,
    tamil: `அருளில் பிறந்திட்டு அருளில் வளர்ந்திட்டு
அருளில் அழிந்துஇளைப் பாறி மறைந்திட்டு
அருளான ஆனந்தத்து ஆரமுது ஊட்டி
அருளால் என்நந்தி அகம்புகுந் தானே`,
    transliteration: `aruḷil piṟantiṭṭu aruḷil vaḷarntiṭṭu
aruḷil aḻintuiḷaip pāṟi maṟaintiṭṭu
aruḷāṉa āṉantattu āramutu ūṭṭi
aruḷāl eṉnanti akampukun tāṉē`,
    english: `1800: From Birth to Liberation--All Acts of Grace
In His Grace was I born,
In His Grace I grew up;
In His Grace I rested in death;
In His Grace I was in obfuscation;
In His Grace I tasted of ambrosial bliss;
In His Grace, Nandi, my heart entered.`,
    elaborationEnglish: `The jiva is born, grows up, remains in obfuscation, dies, and then tastes ambrosial bliss of His Grace. It is Nandi who confers this grace.`,
    elaborationTamil: `இறைவன் தமது திருவருளாலே உயிர்களை அவர்களின் ஆசைகளுக்கு ஏற்ற பிறவி எடுக்கும் படி செய்து, இறையருளாலே அந்த ஆசைகளை அனுபவித்து உயிர்கள் வளரும் படி செய்து, இறையருளாலே ஆசைகள் தீர்கின்ற நிலையில் ஆசைகளை குறையும் படி செய்து, ஆசைகள் நீங்கிய சோர்வு நிலையை நீக்கி, உள்ளுக்குள் மறைந்து இருக்கின்ற இறை சக்தியை வெளிப்படும் படி செய்து, இறையருளால் கிடைக்கின்ற பேரானந்தத்தை அனுபவிக்க வைத்து, தெகிட்டாத அமிழ்தத்தை ஊட்டிக் கொடுத்து, இறையருள் ஆகவே எமது குருநாதராகிய இறைவன் எமக்குள் புகுந்தார்.`,
  },
  {
    id: 1802, tantraId: 7, verseNumber: 1801,
    tamil: `அருளால் அமுதப் பெருங்கடல் ஆட்டி
அருளால் அடிபுணைந்து ஆர்வமும் தந்திட்டு
அருளானஆனந்தந்து ஆரமுது ஊட்டி
அருளால் என்நந்தி அதும்புகுந் தானே`,
    transliteration: `aruḷāl amutap peruṅkaṭal āṭṭi
aruḷāl aṭipuṇaintu ārvamum tantiṭṭu
aruḷāṉaāṉantantu āramutu ūṭṭi
aruḷāl eṉnanti atumpukun tāṉē`,
    english: `1801: More Acts of Grace
By His Grace was I bathed in the ocean of nectar;
By His Grace He rested His Feet on me
By His grace He granted the fervour of devotion
By His Grace He fed me the bliss that is ambrosial
By His Grace, Nandi my heart entered.`,
    elaborationEnglish: `The jiva, then bathed in the ocean of nectar, rests his head on the Lord’s Feet in fervour of devotion, fed with the ambrosial bliss of His Grace.`,
    elaborationTamil: `இறைவன் எம்மீது கொண்ட மாபெரும் கருணையாகிய திருவருளால் அமுதத்தால் நிறைந்த மிகப் பெரிய கடலில் எம்மை மூழ்க வைத்து நீராட்டி, அவனது திருவடிகளை எமது தலை மேல் வைத்து, அவன் கழுத்தில் அணிகின்ற மாலையையும் எம்மை அணிய வைத்து, பேரானந்தமாகிய அமிழ்தத்தை எமக்கு ஊட்டி, எமது குருநாதனாகிய இறைவனே எமக்குள் புகுந்து கொண்டான்.`,
  },
  {
    id: 1803, tantraId: 7, verseNumber: 1802,
    tamil: `பாசத்தில் இட்டது அருள்அந்தப் பாசத்தின்
நேசத்தை விட்டது அருள்அந்தநேசத்தில்
கூசற்ற முத்தி அருள்அந்தக் கூட்டத்தின்
நேசத்துத் தோன்றா நிலையரு ளாமே`,
    transliteration: `pācattil iṭṭatu aruḷantap pācattiṉ
nēcattai viṭṭatu aruḷantanēcattil
kūcaṟṟa mutti aruḷantak kūṭṭattiṉ
nēcattut tōṉṟā nilaiyaru ḷāmē`,
    english: `1802: Grace Grants Mukti and Beyond
It was His grace that led me into Pasa
It was His Grace that freed me from that Pasa
It was His grace that in divine love granted Mukti
It was His Grace that granted me the love
For the State beyond Mukti.`,
    elaborationTamil: `பாடல் #1801 இல் உள்ளபடி இறைவன் எம்மீது கொண்ட மாபெரும் கருணையாகிய திருவருளால் குடும்ப பாசத்தில் இருக்கும் படி எம்மை வைத்து, அந்த பாசத்தை அனுபவித்து முடித்த பின் ஆசையை விடும் படி செய்து, உள்ளத்தில் ஊற்றெடுத்து வரும் பேரன்பில் குறைவு இல்லாத முக்தி நிலையை கொடுத்து, அவனது திருவருளை எம்மோடு சேர்த்துக் கொடுத்தான். அந்த திருவருள் சேர்க்கையினால் பாசமும் ஆசையும் இல்லாத, எண்ணங்கள் தோன்றாத, அமைதியான நிலையே பேரருள் ஆகும்.`,
  },
  {
    id: 1804, tantraId: 7, verseNumber: 1803,
    tamil: `பிறவா நெறிதந்த பேரரு ளாளன்
மறவா அருள் தந்த மாதவன் நந்தி
அறவாழி அந்தணன் ஆதிப்பராபரன்
உறவாகி வந்துஎன் உளம்புகுந் தானே`,
    transliteration: `piṟavā neṟitanta pēraru ḷāḷaṉ
maṟavā aruḷ tanta mātavaṉ nanti
aṟavāḻi antaṇaṉ ātipparāparaṉ
uṟavāki vantueṉ uḷampukun tāṉē`,
    english: `1803: Lord is of Infinite Grace
Of infinite Grace is the Lord
Who my birth's bonds sundered;
Of the holiest of holy is Nandi
He is the Dharmic sea;
The Pure One;
The Primal Lord
In amity my heart entered.`,
    elaborationEnglish: `Nandi is the Holiest of the Holy, the dharmic sea, the Pure One, the Primal Lord who has sundered jiva's bonds of birth and entered his heart by His infinite Grace.`,
    elaborationTamil: `இனி எப்போதும் பிறக்காத வழிமுறையை எமக்கு கொடுத்தவன் பேரருளாளன். என்றும் மாறாத அருளை எமக்கு கொடுத்தவன் மாபெரும் குருநாதனாகிய இறைவன். வேதங்கள் சொல்லுகின்ற தர்மங்களை கற்றுக்கொடுத்து அதன் வழியில் வாழுகின்ற அனைவரும் சென்று அடைகின்ற அந்த வேதத்தின் எல்லையாக இருக்கின்றவன். ஆதியிலிருந்தே இருக்கின்ற அனைத்திற்கும் மேலான அசையா சக்தியாகிய அந்த பரம்பொருளே எம்மோடு உறவு கொண்டாடி எமது உள்ளத்திற்குள் புகுந்து கொண்டான்.`,
  },
  {
    id: 1805, tantraId: 7, verseNumber: 1804,
    tamil: `அகம்புகுந் தான்அடி யேற்குஅரு ளாலே
அகம்புகுந் தும்தெரி யான்அருள் இல்லோர்க்கு
அகம்புகுந்து ஆனந்த மாக்கிச் சிவமாய்
அகம்புகுந் தான்நந்தி ஆனந்தி யாமே`,
    transliteration: `akampukun tāṉaṭi yēṟkuaru ḷālē
akampukun tumteri yāṉaruḷ illōrkku
akampukuntu āṉanta mākkic civamāy
akampukun tāṉnanti āṉanti yāmē`,
    english: `1804: Nandi entered my Heart and made me Sivam
In my heart He entered, grace abounding;
Even if He is in there,
Those devoid of Grace know Him not;
Entering the heart,
He filled me with bliss;
As Sivam, he made me
As Nandi my heart entered,
And I blissful became.`,
    elaborationTamil: `பாடல் #1803 இல் உள்ளபடி எமக்குள் புகுந்த இறைவனின் திருவருளை யாம் அவனருளால் காப்பாற்றி அவன் எமக்குள் புகுந்து கொண்டதை கண்டுகொண்டோம். அவ்வாறு இறைவன் தமக்குள் புகுந்து கொண்ட திருவருளை காப்பாற்றிக் கொள்ளும் அருள் இல்லாதவர்களுக்கு அவன் தெரிவதில்லை. எமக்குள் புகுந்த அந்த இறைவன் எம்மை பேரின்பமாக மாற்றி சிவமாகவே ஆக்கி விட்டு எமக்குள் குருநாதனாக வீற்றிருந்து பேரின்பத்தின் வடிவமாக அருளுகின்றான்.`,
  },
  {
    id: 1806, tantraId: 7, verseNumber: 1805,
    tamil: `ஆயும் அறிவோடு அறியாத மாமாயை
ஆய கரணம் படைக்கும் ஐம்பூதமும்
ஆய பலஇந் திரியம் அவற்றுடன்
ஆய அருள்ஐந்து மாம் அருட் செய்கையே`,
    transliteration: `āyum aṟivōṭu aṟiyāta māmāyai
āya karaṇam paṭaikkum aimpūtamum
āya palain tiriyam avaṟṟuṭaṉ
āya aruḷaintu mām aruṭ ceykaiyē`,
    english: `1805: Bounties of Lord's Grace
He gave me the intelligence that reasons
He gave me the senses that Maya inscrutable fashions
He gave the five elements
And the diverse sense organs
And the Five Acts of Grace
--All these are but the bounties of His Grace.`,
    elaborationEnglish: `In His bounteous Grace, He gave me the instruments to reason out the inscrutable senses, to enjoy the elements and environments for my functioning, and performed the Five Acts for my liberation and attainment of Grace.`,
    elaborationTamil: `புலன்களால் ஆராய்ந்து அறியக்கூடிய உலக அறிவின் துணையால் அறிந்து கொள்ள முடியாத மாபெரும் மாயையாக இருக்கின்ற இறைவன் ஐந்து பூதங்களையும் (நிலம், நீர், காற்று, நெருப்பு, ஆகாயம்), அந்த ஐம்பூதங்களால் ஆகிய உடலையும், அந்த உடலுக்குள் அந்தக் கரணங்களாக இருக்கின்ற நான்கு விதமான (மனம், புத்தி, சித்தம், அகங்காரம்) உள் உணர்வுகளையும், அந்த உயிருக்கு பல விதமான தத்துவங்களாகவும், அந்த தத்துவமாக இருக்கின்ற ஐந்து விதமான (கண், காது, மூக்கு, வாய், மெய்) இந்திரியங்களையும் தமது படைத்தல், காத்தல், மறைத்தல், அருளல், அழித்தல் ஆகிய ஐந்து தொழில்களின் மூலமே உருவாக்கி அருளுகின்றான். இறைவனின் ஐந்து தொழில்கள்: படைத்தல் – தம்முடைய பேரான்மாவிலிருந்து ஆசையின் காரணமாக பிரிந்த ஜீவான்மாவை உலகத்தில் அந்த ஆசைகளை அனுபவிக்க ஐந்து பூதங்களை சேர்த்து தகுந்த உடலோடு படைத்தல். காத்தல் – அந்த உடலுக்குள்ளேயே இயங்குகின்ற சக்தியாக இருந்து உயிர் உள்ள காலம் வரை காத்தல். மறைத்தல் – அவ்வாறு தாம் உடலுக்குள் இருப்பதை உயிர்கள் உணராத படி மறக்கருணையினால் மறைத்தல். அருளல் – ஆன்மா தனது ஆசைகளை தீர்த்துக் கொள்ளவும், அந்த ஆசைகள் தீரத் தீர மறைந்து இருக்கின்ற இறைவனை உணர்ந்து கொள்ளவும் அருளல். அழித்தல் – ஆசைகள் முழுவதையும் அனுபவித்து முடித்த பிறகு அந்த ஜீவான்மாவின் வசித்த உடலில் இருந்து ஐந்து பூதங்களையும் பிரித்து மீண்டும் பரமாத்மாவாகிய தம்மிடமே வந்து சேரும் படி அழித்தல். அந்தக் கரணங்கள்: மனம் – மனமானது சங்கல்பம் (விருப்பம்) மற்றும் விகல்பம் (சந்தேகம்) ஆகியவைகளின் தன்மையாகும். புத்தி – மனதின் முடிவெடுக்கும் பகுதி. பொய்யிலிருந்து உண்மையைப் பகுத்தறிந்து அதன் மூலம் ஞானத்தை சாத்தியமாக்கும் பகுதி. சித்தம் – பதிவுகள், நினைவுகள் மற்றும் அனுபவங்கள் சேமிக்கப்படும் உணர்வு. அகங்காரம் – நான், என்னுடையது என்று எண்ணுவது. இந்திரியங்கள்: கண் – பார்த்தல் காது – கேட்டல் மூக்கு – நுகர்தல் வாய் – சுவைத்தல் மெய் / உடல் – தொடுதல் / உணர்தல்`,
  },
  {
    id: 1807, tantraId: 7, verseNumber: 1806,
    tamil: `அருளே சகலமும் ஆய பவுதிகம்
அருளே சராசர மாய அமலமே
இருளே வெளியே யெனும்எங்கும் ஈசன்
அருளே சகளத்தின் அன்றிஇன் றாமே`,
    transliteration: `aruḷē cakalamum āya pavutikam
aruḷē carācara māya amalamē
iruḷē veḷiyē yeṉumeṅkum īcaṉ
aruḷē cakaḷattiṉ aṉṟiiṉ ṟāmē`,
    english: `1806: All Phenomenon is manifestations of Grace
All manifestations of Nature are His Grace
All animate and inanimate are His Pure Grace
As darkness, as light, the Lord's Grace pervades,
All, all are but the Grace of His Form manifest.`,
    elaborationEnglish: `All are but His benignant Grace, be they the manifestations
of nature; be they -animate or inanimate, be they darkness
or light. .`,
    elaborationTamil: `பாடல் #1805 இல் உள்ளபடி ஐந்து விதமான தொழில்களை செய்கின்ற இறையருளே உலகமாகவும், அதிலுள்ள உள்ள இயற்கையாகவும், அதிலுள்ள அசையும் அசையாத பொருள்களாகவும், அதிலுள்ள உயிர்களை கட்டி இருக்கின்ற மூன்று விதமான (ஆணவம், கன்மம், மாயை) மலங்களாகவும், அந்த மலத்தினால் உயிர்களுக்கு இருக்கின்ற அறியாமையாகிய இருளாகவும், இறையருள் பெற்ற உயிர்களுக்கு உள்ளிருந்து இறைவன் உணர்த்துகின்ற ஞானமாகிய வெளிச்சமாகவும், அண்டங்களும் அதிலுள்ள அனைத்து பொருட்களின் வடிவமாகவும் இருக்கின்றது. இப்படி இறையருளாக இருக்கின்ற இறைவன் இல்லாமல் இவை எதுவுமே இல்லையாம்.`,
  },
  {
    id: 1808, tantraId: 7, verseNumber: 1807,
    tamil: `சிவமொடு சத்தி திகழ்நாதம் விந்து
தவமான ஐம்முகன் ஈசன் அரனும்
பவமுறும் மாலும் பதுமத்தோன் ஈறா
நவம்அவை யாகி நடிப்பவன் தானே`,
    transliteration: `civamoṭu catti tikaḻnātam vintu
tavamāṉa aimmukaṉ īcaṉ araṉum
pavamuṟum mālum patumattōṉ īṟā
navamavai yāki naṭippavaṉ tāṉē`,
    english: `1807: The Nine God Forms are of Siva
Siva, Sakti, the luminous Nada and Bindu
The five-faced Sadasiva holy,
Mahesa, Rudra, Mal and the lotus-seated Brahma
--All these forms nine
He assumes.`,
    elaborationTamil: `அண்ட சராசரங்கள் அனைத்திலும் ஆதி பராபரனாகிய சிவம், ஆதி பராபரையாகிய சக்தி, அவர்களுக்கு உள்ளிருந்து தோன்றுகின்ற ஒலியாகிய சத்தம், ஒளியாகிய வெளிச்சம், பெரும் தவங்கள் புரிந்து தகுதி பெற்று இறை நிலையை அடைந்த ஐந்து முகங்களைக் கொண்டு அருளுகின்ற சதாசிவன், அழிக்கின்ற உருத்திரன், உலகத்தை காப்பதில் மிகுதியாக நிற்கின்ற திருமால், தாமரை மலரின் மேல் தவம் புரிந்து படைக்கின்ற பிரம்மன் ஆகிய ஒன்பது விதமான இறை சக்திகளாக உருமாறி நடித்துக் கொண்டு இருக்கின்றவன் ஆதிப் பரம்பொருளாகிய இறைவன் ஒருவனே.`,
  },
  {
    id: 1809, tantraId: 7, verseNumber: 1808,
    tamil: `அருட்கண்இ லாதார்க்கு அரும்பொருள் தோன்றா
அருட்கண்உ ளோர்க்குஎதிர் தோன்றும் அரனே
இருட்கண்ணி னோர்க்குஅங்கு இரவியும் தோன்றாத்
தெருட்கண்ணி னோர்க்குஎங்கும் சீரொளி யாமே`,
    transliteration: `aruṭkaṇi lātārkku arumporuḷ tōṉṟā
aruṭkaṇu ḷōrkkuetir tōṉṟum araṉē
iruṭkaṇṇi ṉōrkkuaṅku iraviyum tōṉṟāt
teruṭkaṇṇi ṉōrkkueṅkum cīroḷi yāmē`,
    english: `1808: Grace Gives Divine Vision
They whose eyes are blind
See not the sun even;
They that have vision divine
See the light everywhere;
They who have not the vision of Grace
See not the Lord that is Truth Subtle;
They that have the vision of Grace
See Hara face to face.`,
    elaborationEnglish: `The blind do not see the sun ever. They who are blessed
with divine vision see light everywhere. They who are not
blessed with vision of Grace cannot see that subtle light; they
who are blessed with the vision of Grace see Hara face to
face. The Lord is subtle Truth.`,
    elaborationTamil: `இறைவனின் அருள் பெற்ற ஞானக் கண் இல்லாதவர்களுக்கு எளிதில் பார்க்க இயலாதபடி அனைத்திலும் மறைந்து நிற்கின்ற பரம்பொருள் தோன்றுவது இல்லை. இறைவனின் அருள் பெற்ற ஞானக் கண் உள்ளவர்களின் கண்ணுக்கு எதிரில் தோன்றுகின்றான் இறைவன். மாயையினால் இருண்ட கண்களை உடையவர்களுக்கு இந்த உலகத்தில் எங்கும் இயற்கையில் சூரியனின் வெளிச்சம் தெரிந்தாலும் அந்த வெளிச்சம் காட்டுகின்ற பொருள்களுக்குள் மறைந்து இருக்கின்ற இறைவனின் பேரருள் தோன்றுவதில்லை. மாயை நீங்கி உண்மை அறிவில் தெளிவு பெற்ற கண்களை உடையவர்களுக்கு எங்கும் செம்மையாகத் தெரிகின்ற பேரொளியாக இறைவன் இருக்கின்றான்.`,
  },
  {
    id: 1810, tantraId: 7, verseNumber: 1809,
    tamil: `தானே படைத்திடும் தானே அளித்திடும்
தானே துடைத்திடும் தானே மறைத்திடும்
தானே இவைசெய்து தான்முத்தி தந்திடும்
தானே வியாபித் தலைவனும் ஆமே`,
    transliteration: `tāṉē paṭaittiṭum tāṉē aḷittiṭum
tāṉē tuṭaittiṭum tāṉē maṟaittiṭum
tāṉē ivaiceytu tāṉmutti tantiṭum
tāṉē viyāpit talaivaṉum āmē`,
    english: `1809: Lord Alone Performs the Five Acts
Himself creates;
Himself preserves
Himself destroys;
Himself obscures
Himself, all these He does
And grants Mukti after;
Himself the all-immanent Lord.`,
    elaborationTamil: `ஆதியிலிருந்து தானாகவே இருக்கின்ற பரம்பொருளான இறை சக்தியின் அருளே அண்ட சராசரங்களில் உள்ள அனைத்தையும் உருவாக்குகின்றது, அதுவே ஆசைகளை அனுபவித்து முடிக்கும் வரை உயிர்களை காத்து அதனதன் ஆசைகளுக்கு ஏற்ப அனுபவிக்கும் படி அளிக்கின்றது, அதுவே வினை முடிந்த உயிர்களை அழித்து உலகத்தில் இருந்து நீக்குகின்றது, அதுவே தாம் அனைத்துக்கும் உள்ளே இருப்பதை மறக்கருணையினால் மறைக்கின்றது. இறையருளாகிய ஒன்றே இவை அனைத்தையும் செய்து அதை முழுவதும் அனுபவித்து முடித்த உயிர்களுக்கு அதுவே முக்தி நிலையையும் தந்து அருளுகின்றது. இவ்வாறு தாமாகவே அனைத்திலும் கலந்து பரவியிருக்கின்ற இறையருளே அனைத்திற்கும் தலைவனாகவும் இருக்கின்றது.`,
  },
  {
    id: 1811, tantraId: 7, verseNumber: 1810,
    tamil: `தலையான நான்கும் தனதுஅரு வாகும்
அலையா அருவுரு வாகும் சதாசிவம்
நிலையான கீழ்நான்கு நீடுரு வாகும்
துலையா இறைமுற்று மாய் அல்லது ஒன்றே`,
    transliteration: `talaiyāṉa nāṉkum taṉatuaru vākum
alaiyā aruvuru vākum catācivam
nilaiyāṉa kīḻnāṉku nīṭuru vākum
tulaiyā iṟaimuṟṟu māy allatu oṉṟē`,
    english: `1810: The Form, Formless and Form-Formless Aspects of Siva
The first four (Siva, Sakti, Nada, Bindu) are His Form-less ones;
The un-moving Form-Formless is the Sadasiva;
The abiding last four (Brahma, Vishnu, Rudra, Mahesa)
Are the Formed ones;
All these and the One beyond too are He.`,
    elaborationTamil: `ஆதி முதல்வனாக இருக்கின்ற அனைத்திற்கு மேலாக இருக்கின்ற அசையா சக்தியாகிய பரம்பொருளே முதன்மையான உயர் தத்துவங்களாகிய சிவம், சக்தி, நாதம், விந்து ஆகிய நான்கிற்கும் குருநாதராக வழி காட்டுகின்றது. அந்த அசையா சக்தியாகிய பரம்பொருளே அருவுருவமாகவும் நடுவில் நிற்கின்றது. அந்த பரம்பொருளே ஆதாரமாக நின்று உயிர்களுக்காக உருவாகுகின்ற உலகமாகிய கீழ் தத்துவத்தில் பிரம்மன், திருமால், உருத்திரன், மகேஸ்வரன் ஆகிய நால்வரின் தொழில்களை செய்து அண்ட சராசரங்களில் இருக்கின்ற அனைத்து உயிர்களின் உருவங்களாக நீண்டு பரவி இருக்கின்றது. அழியாத இந்த இறை சக்திகள் உயிர்களின் வினை முற்றுப் பெற்று இறைவனை அடையும் வரை உருவம் உள்ளதாகவும் உருவம் இல்லாததாகவும் இருப்பது அசையா சக்தியாகிய பரம்பொருள் ஒன்றே ஆகும்.`,
  },
  {
    id: 1812, tantraId: 7, verseNumber: 1811,
    tamil: `ஒன்றது வாலே உலப்பிலி தானாகி
நின்றது தான்போல் உயிர்க்குயி ராய்நிலை
துன்றி அவைஅல்ல வாகும் துணையென்ன
நின்றது தான்விளை யாட்டென்னுள் நேயமே`,
    transliteration: `oṉṟatu vālē ulappili tāṉāki
niṉṟatu tāṉpōl uyirkkuyi rāynilai
tuṉṟi avaialla vākum tuṇaiyeṉṉa
niṉṟatu tāṉviḷai yāṭṭeṉṉuḷ nēyamē`,
    english: `1811: God is Immanent and Transcendent
One Being is He, immanent in all life
Indestructible He is;
In them He is; but He is not they;
He indwells them as Friend Divine
This His play, He of my heart's desire.`,
    elaborationTamil: `பாடல் #1810 இல் உள்ளபடி அனைத்தும் ஒன்றாக இருக்கின்ற அழிவில்லாத பரம்பொருள் தாமே அனைத்தும் ஆகி நிற்கின்றது. அந்த இறை சக்தியே தன்னைப் போலவே படைக்கின்ற அனைத்து உயிர்களுக்கும் உள்ளிருக்கின்ற உயிர் சக்தியாய் நிலை பெற்று பொருந்தி நிற்கின்றது. அந்த உயிர்கள் இல்லாத உடல்கள் அனைத்துமாகவும் தாமே இருக்கின்றது. பிறவி எடுத்ததில் இருந்து உடலை விட்டு விட்டு இன்னொரு உடலை எடுக்கும் வரை உயிருக்கும், உயிர் நீங்கிய பின்பு மண்ணோடு மண்ணாகும் வரை உடலுக்கும் எப்போதும் விலகாத துணையாகவும் தாமே இருக்கின்றது. இதுவே பேரன்பு என்று அழைக்கப்படும் இறைவனின் மாபெரும் திரு விளையாட்டு ஆகும்.`,
  },
  {
    id: 1813, tantraId: 7, verseNumber: 1812,
    tamil: `நேயத்தே நின்றிடும் நின்மலன் சத்தியோடு
ஆயக் குடிலைகள் நாதம் அடைந்திட்டுப்
போயக் கலைபல வாகப் புணர்ந்திட்டு
வீயத் தகாவிந்து வாக விளையுமே`,
    transliteration: `nēyattē niṉṟiṭum niṉmalaṉ cattiyōṭu
āyak kuṭilaikaḷ nātam aṭaintiṭṭup
pōyak kalaipala vākap puṇarntiṭṭu
vīyat takāvintu vāka viḷaiyumē`,
    english: `1812: Nadam and Bindu are Devoluted when Siva Activates
Pure Maya Sakti
The Immaculate One who in my heart dwells
The Kudilai (Pure Maya) Sakti He activates;
And from that act is Nadam born;
That emanating Kala rays diverse
As seed the imperishable Bindu produces.`,
    elaborationEnglish: `The sukshma (subtle) maya sakti is activated in the Immaculate One. From that movement is nada bom. The imperishable bindu is then produced as the seed of the manifest world emanating the different kalas.`,
    elaborationTamil: `பாடல் #1811 இல் உள்ளபடி விளையாடுகின்ற பேரன்பாக நின்று இருக்கின்ற எந்தவிதமான அழுக்கும் இல்லாத பரம்பொருளான இறை சக்தியே ஒன்றாக கூடி இருக்கின்ற சுத்த மாயையின் உள்ளுக்குள் இருந்து இயங்குகின்ற சத்தமாகவும் வீற்றிருக்கின்றது. அந்த சுத்த மாயையை விட்டு பிரிந்து உடல் பெற்று வந்த ஆன்மாக்களோடு பலவிதமாக பொருந்தி வீற்றிருந்து என்றும் அழியாத பேரறிவாகிய வெளிச்சமாகவும் வீற்றிருந்து அண்ட சராசரங்களிலிருக்கும் உலகங்கள் அனைத்திலும் வாழுகின்ற உயிர்களாகவும் விளைந்து இருக்கின்றது.`,
  },
  {
    id: 1814, tantraId: 7, verseNumber: 1813,
    tamil: `விளையும் பரவிந்து தானே வியாபி
விளையும் தனிமாயை மிக்கமா மாயை
கிளையொன்று தேவர் கிளர்மனு வேதம்
அளவொன் றிலாஅண்ட கோடிக ளாமே`,
    transliteration: `viḷaiyum paravintu tāṉē viyāpi
viḷaiyum taṉimāyai mikkamā māyai
kiḷaiyoṉṟu tēvar kiḷarmaṉu vētam
aḷavoṉ ṟilāaṇṭa kōṭika ḷāmē`,
    english: `1813: The Devolutes of Bindu
The Bindu that thus arose pervades everywhere;
From it rises the Maya per se and the Mahamaya
And from them emanate the immortals and their clans
The Mantras and the Vedas too,
And the countless countless worlds swarming in the spread.`,
    elaborationTamil: `பாடல் #1812 இல் உள்ளபடி அண்ட சராசரங்களில் இருக்கின்ற அனைத்து உலகங்களிலும் வாழுகின்ற உயிர்களாக விளைந்து இருக்கின்ற பரம்பொருளாகிய பேரறிவு வெளிச்சமே அண்ட சராசரங்கள் அனைத்திலும் நிறைந்து நிற்கின்றது. அந்த பரம்பொருளாகிய இறை சக்தியே தனிப் பொருளாகிய மாயையிலும், அதனை விட மேன்மையான மாமாயையிலும், வானவர் இனத்தில் ஒன்றாக இருக்கின்ற தேவர்கள் உயிர்களில் உலக செயல்களுக்காக தமக்குள் இருந்து இறையருளால் கிளர்ந்து எழுகின்ற மந்திரங்களாகிய வேதத்திலும், அளவில்லாத மிகப் பெரியதாகிய அண்டங்களிலும் படர்ந்து விரிந்து இருக்கின்றது.`,
  },
  {
    id: 1815, tantraId: 7, verseNumber: 1814,
    tamil: `அருளில் தலைநின்று அறிந்துஅழுந் தாதார்
அருளில் தலைநில்லார் ஐம்பாசம் நீங்கார்
அருளின் பெருமை அறியார் செறியார்
அருளில் பிறந்திட்டு அறிந்துஅறி வாரே`,
    transliteration: `aruḷil talainiṉṟu aṟintuaḻun tātār
aruḷil talainillār aimpācam nīṅkār
aruḷiṉ perumai aṟiyār ceṟiyār
aruḷil piṟantiṭṭu aṟintuaṟi vārē`,
    english: `1814: Be Born in Grace and Receive Grace
And in conscious determination steep in it not,
Will never Grace receive;
Nor be freed of Pasas
Five;
They will not know greatness that Grace gives;
They will not resolute be;
They alone know Grace who to Grace are born.`,
    elaborationEnglish: `Those who do not take their firm stand on Grace and are not steeped in determination will never receive Grace, will

not be freed of the five pasas, viz., anava, maya, karma, tirodayi (obfuscation) and mayeyam (desires); will not taste of the holiness of Grace; and will not be resolute. Those who are bom to Grace alone know what Grace is.

“The five pasas are: the primal impurities — anava, maya and karma, and tirodayi (mala of obscuration) and mayeyam are the tangible manifestations of maya.`,
    elaborationTamil: `ஒளியாகிய பேரருளில் உறுதியாக நின்று அதை முழுவதுமாக அறிந்து கொண்டு அதிலேயே அமிழ்ந்து அதுவாகவே ஆகாதவர்கள், அந்த பேரருளை அடைவதையே வாழ்க்கையின் குறிக்கோளாக மேற்கொண்டு நிற்காதவர்கள், ஐந்து விதமான புலன்களால் வருகின்ற பந்த பாசங்களை விட்டு நீங்காதவர்கள், அந்த பேரருளில் கிடைக்கின்ற பெரும் பலனை அறிந்து கொள்ளாதவர்கள், பேரருளின் பலனை அறிந்து அதன் மூலம் தம்மை மேன்மை படுத்திக் கொள்ளாதவர்கள், பேரருளில் பிறந்து இந்த உலகத்தில் உயிர்களாக வந்திருந்தாலும் அந்த பேரருளில் இருக்கின்ற இறவாத பேரறிவை அறியாமல் இறந்து போகின்ற உலக அறிவையே அறிந்தவர்களாக இருக்கின்றார்கள்.`,
  },
  {
    id: 1816, tantraId: 7, verseNumber: 1815,
    tamil: `வாரா வழிதந்த மாநந்தி பேர்நந்தி
ஆரா அமுதளித்து ஆனந்தி பேர்நந்தி
பேரா யிரமுடைப் பெம்மான்பேர் ஒன்றினில்
ஆரா அருட்கடல் ஆடுகென் றானே`,
    transliteration: `vārā vaḻitanta mānanti pērnanti
ārā amutaḷittu āṉanti pērnanti
pērā yiramuṭaip pemmāṉpēr oṉṟiṉil
ārā aruṭkaṭal āṭukeṉ ṟāṉē`,
    english: `1815: Nandi Grants Unending Grace
Nandi the great, Nandi the famed,
Nandi that barred the way of my future birth;
He gave me the ambrosial bliss that never cloys;
He the Lord of a thousand names;
In one word He said, "Bathe eternally
In the unending sea of Grace."`,
    elaborationEnglish: `The great Nandi planted his feet on my head and I prostrated low and prayed at his feet. All worthless knowledge vanished, all impurities were dispelled. My birth cycle snapped. He gave me the ambrosial bliss, calling upon me to sport in the unending sea of Grace.`,
    elaborationTamil: `இந்த உலகத்திற்கு திரும்பவும் வந்துவிடாத பெரும் வழியை தந்து அருளிய மாபெரும் குருநாதனாகிய இறைவன் பெருமை மிக்க நந்தி ஆகும். என்றும் தெகிட்டாத அமிழ்தமாகிய பேரின்பத்தை அளித்து அருளியவன் குருநாதனாகிய இறைவன் பெருமை மிக்க நந்தி ஆகும். தனது திருப்பெயர்களாக அடியவர்கள் அழைக்கும் ஆயிரம் பெயர்களை உடைய பெருமானாக இருந்தாலும் தனக்கென்று தனிப் பெயர் ஒன்றும் இல்லாதவன். என்றும் தெகிட்டாத அமிழ்தமாகிய குருநாதனாகிய இறைவனின் பேரருள் பெருங்கடலில் மூழ்கி பேரின்பத்தில் திளைத்து இருங்கள் என்று தமது அடியவர்களுக்கு அருளினான். தத்துவ விளக்கம்: மீண்டும் மீண்டும் பிறவி எடுக்கின்ற சுழற்சியிலிருந்து விடுபட்டு மீண்டும் பிறவி எடுக்காத மாபெரும் வழியை குருநாதனாக வந்த இறைவன் அடியவருக்கு தந்து அருளி அந்த வழியை சரியாகப் பின்பற்றுகின்ற மன வலிமையையும் கொடுத்து அதை அவர் அகங்காரம் வந்துவிடாமல் சரியாகப் பின்பற்றும் போது அதற்கு பலனாக என்றும் தெகிட்டாத அமிழ்தமாகிய பேரின்பத்தை கொடுத்து அருளுகின்றான். இறைவன் கொடுக்கின்ற வழிமுறைகள் பல ஆயிரம் வகையாக இருக்கவே அடியவர்கள் அவன் புரிகின்ற ஒவ்வொரு செயலுக்கும் ஒவ்வொரு பெயரைக் கொடுத்து அவனை ஆயிரம் பெயர்களில் அழைத்தாலும் தனக்கென்று ஒரு பெயரும் இல்லாதவன் இறைவன். இப்படிப்பட்ட இறைவனே தனது பேரருளாகிய பெருங்கடலில் அடியவர்கள் மூழ்கித் திளைத்து இன்புற்றிருக்குமாறு அருளுகின்றான்.`,
  },
  {
    id: 1817, tantraId: 7, verseNumber: 1816,
    tamil: `ஆடியும் பாடியும் அழுதும் அரற்றியும்
தேடியும் கண்டேன் சிவன்பெரும் தன்மையைக்
கூடிய வாறே குறியாக் குறிதந்தென்
ஊடுநின் றான்அவன் தன்னருள் உற்றே`,
    transliteration: `āṭiyum pāṭiyum aḻutum araṟṟiyum
tēṭiyum kaṇṭēṉ civaṉperum taṉmaiyaik
kūṭiya vāṟē kuṟiyāk kuṟitanteṉ
ūṭuniṉ ṟāṉavaṉ taṉṉaruḷ uṟṟē`,
    english: `1816: Imparting Grace Siva Grants His Form to Jiva
I danced and sang and wept and lamented
Thus I sought Him, and Siva's greatness saw,
And as I with Him united
He, His indefinable Form granted
And in me pervaded, His Grace imparting.`,
    elaborationTamil: `இறைவனின் திருவிளையாடல்களை ஆடியும், அவனது பெருமைகளைப் போற்றிப் பாடியும், அவனது மாபெரும் கருணையை எண்ணி அழுதும், அவன் அருகில் செல்ல முடியவில்லையே என்று புலம்பியும், தமக்குள்ளே தேடியும், இறைவனின் மாபெரும் தன்மையை கண்டு கொண்டேன். அப்படி தேடிக் கண்டு கொண்ட இறைவனோடு சேருவதை மட்டுமே குறிக்கோளாக கொண்டு வேறு எதிலும் சிந்தனையை செலுத்தாமல் இருக்கின்ற வழியை எமக்கு கொடுத்து அருளி எம்மோடு கலந்து நின்று எம்முள்ளிருந்து ஞானமாக வெளிப்பட்டான்.`,
  },
  {
    id: 1818, tantraId: 7, verseNumber: 1817,
    tamil: `உற்ற பிறப்பும் உறுமலம் ஆனதும்
பற்றிய மாயாப் படலம் எனப் பண்ணி
அத்தனை நீயென்று அடிவைத்தேன் பேர்நந்தி
கற்றன விட்டேன் கழல்பணிந் தேனே`,
    transliteration: `uṟṟa piṟappum uṟumalam āṉatum
paṟṟiya māyāp paṭalam eṉap paṇṇi
attaṉai nīyeṉṟu aṭivaittēṉ pērnanti
kaṟṟaṉa viṭṭēṉ kaḻalpaṇin tēṉē`,
    english: `1817: Nandi Planted His Feet on me and imparted Grace
The birth I took,
The impurities (malas) I bore
He dispelled as but Maya's cloud;
"You are of these rid"--so saying
He planted His Feet on me--
He the Nandi famed;
All unworthy knowledge I gave up,
I prostrated and at His feet prayed.`,
    elaborationTamil: `எமக்கு கொடுக்கப்பட்ட பிறவியும், யாம் அனுபவிக்கின்ற ஆணவம், கன்மம், மாயை ஆகிய மூன்று விதமான மலங்களாக இருப்பதும், எம்மை பற்றிக் கொண்ட மாயையின் இருள் கூட்டம் என்று எமது ஆசைகள் தீர்ப்பதற்காக அருள் செய்து, அவனருளால் அழியக் கூடிய அனைத்தையும் எம்மை விட்டு நீக்கி விட்டு, தமது திருவடியை எம் தலைமேல் வைத்தருளினான் பெருமை மிக்க குருநாதனாகிய இறைவன். அவனது திருவடியின் அருளினால் இதுவரை யாம் அறிந்த உலக அறிவுகளை அனைத்தையும் விட்டு விட்டு அவனது திருவடியை எம் தலை மேல் அணிந்து கொண்டு அதனோடு பொருந்தி இருந்தேன்.`,
  },
  {
    id: 1819, tantraId: 7, verseNumber: 1818,
    tamil: `விளக்கினை யேற்றி வெளியை அறிமின்
விளக்கினை முன்னே வேதனை மாறும்
விளக்கை விளக்கும் விளக்குடை யார்கள்
விளக்கில் விளங்கும் விளக்கவர் தாமே`,
    transliteration: `viḷakkiṉai yēṟṟi veḷiyai aṟimiṉ
viḷakkiṉai muṉṉē vētaṉai māṟum
viḷakkai viḷakkum viḷakkuṭai yārkaḷ
viḷakkil viḷaṅkum viḷakkavar tāmē`,
    english: `1818: Light the Lamps of God by Inner Light
Light the Lamp, and see the Void
Before the Lamp all pangs cease
They that have the Light to light the Lamp
Are but the Light, in the Divine Lamp shine.`,
    elaborationTamil: `தமக்குள் உறங்கிக் கொண்டிருக்கும் குண்டலினி சக்தியின் விளக்கை சாதகத்தின் மூலம் சுழுமுனை நாடி வழியே மேலேற்றி எடுத்துச் சென்று சகஸ்ரதளத்தில் ஜோதியாக எரியச் செய்து தமக்கு வெளியில் இருக்கின்ற புற உலகின் மேல் செல்லுகின்ற புலன்களை தடுத்து நிறுத்தினால் மாபெரும் ஜோதியாக இருக்கின்ற பேரறிவு ஞானத்தின் முன்பே உலக அறிவு எல்லாம் உண்மை அறிவாக மாறும். அப்படிப்பட்ட பேரறிவாகிய இறைவனின் ஜோதியை உண்மையாக உணர்ந்து கொள்ளும் படி விளங்க வைக்கும் தெளிவு உடைய ஞானிகள் எடுத்துரைத்து விளக்கினால் முழுவதும் புரிந்து கொள்ளக் கூடிய மாபெரும் ஜோதியாக இருப்பது பரம்பொருளாகிய இறைவனே ஆகும். கருத்து: நமக்குள் இருக்கும் ஜோதியாகிய விளக்கை ஏற்றி மாயையாகிய இருளை அகற்றினால் இறைவனை அறியக் கூடிய தகுதி பெற்றவர்களாக மாறுவோம். அப்போது இறைவனை உணர்ந்த ஞானி நமக்கு வழிகாட்டி இறைவனை பரிபூரணமாக உணர வைப்பார்.`,
  },
  {
    id: 1820, tantraId: 7, verseNumber: 1819,
    tamil: `ஒளியும் இருளும் ஒருகாலும் தீரா
ஒளியு ளோர்க்குஅன்றோ ஒழியாது ஒளியும்
ஒளியுருள் கண்டகண் போலவே றாயுள
ஒளியிருள் நீங்க உயிர்சிவம் ஆமே`,
    transliteration: `oḷiyum iruḷum orukālum tīrā
oḷiyu ḷōrkkuaṉṟō oḻiyātu oḷiyum
oḷiyuruḷ kaṇṭakaṇ pōlavē ṟāyuḷa
oḷiyiruḷ nīṅka uyircivam āmē`,
    english: `1819: By Inner Light Unite One in Siva
Interminable are light and darkness
Only to those who have light, will darkness cease;
To the eyes that see light, darkness is not;
So, too, when the inner light dispells darkness
The Jive with Siva one becomes.`,
    elaborationEnglish: `Light and darkness are interminable. Darkness will cease only when light appears. The eyes which see light do not see darkness. So too, when the inner light appears, all darkness flees. The jiva becomes one with Siva.`,
    elaborationTamil: `ஜோதியாகிய ஞானமும் இருளாகிய மாயையும் எந்தவொரு காலத்திலும் இல்லாமல் போகப் போவதில்லை. உண்மையான ஞானமாகிய ஒளியை தமக்குள் ஆராய்ந்து தெளிவாக அறிந்து கொண்டவர்களுக்கு மட்டுமே அந்த ஒளியானது எப்போதும் நீங்காத ஜோதியாக வீற்றிருக்கும். தாம் பார்க்கின்ற வெளிச்சத்தையும் இருட்டையும் மட்டுமே உண்மை என்று நம்பிக் கொண்டு இருக்கின்ற புறக் கண்களைப் போல இல்லாமல் பார்க்கின்ற அனைத்தையும் மாயை என்பதை அறிந்து இறைவனின் அம்சமாகவே உள்ளுக்குள் இருக்கின்ற ஆன்மாவின் ஜோதியை உணர்ந்து கொண்ட போது இருளாகிய மாயை நீங்கி உயிரானது சிவமாகவே ஆகி விடும்.`,
  },
  {
    id: 1821, tantraId: 7, verseNumber: 1820,
    tamil: `புறமே திரிந்தேனைப் பொற்கழல் சூட்டி
நிறமே புகுந்தென்னை நின்மலன் ஆக்கி
அறமே புகுந்தெனக்கு ஆரமுது ஈந்த
திறம்ஏதென்று எண்ணித் திகைத்திருந் தேனே`,
    transliteration: `puṟamē tirintēṉaip poṟkaḻal cūṭṭi
niṟamē pukunteṉṉai niṉmalaṉ ākki
aṟamē pukunteṉakku āramutu īnta
tiṟamēteṉṟu eṇṇit tikaittirun tēṉē`,
    english: `1820: Lord is Gracious
Aimless I wandered,
On me He planted His golden Feet,
In purity He entered, and made me pure
In charity He entered, and gave me the bliss of ambrosia
What ho! this gracious act!
In wonder limitless, I stand bedazed.`,
    elaborationTamil: `இறைவனை உள்ளுக்குள் தேடாமல் வெளியில் தேடி கோயில் குளம் என்று அலைந்து திரிந்த யாம் பாடல் #1819 இல் உள்ளபடி எமக்குள் இருக்கின்ற ஆன்மாவை உணர்ந்து கொண்ட பிறகு எமது தலை மேல் தூய்மையான தங்கத்தைப் போல் பிரகாசிக்கின்ற திருவடிகளை அணிவித்து, இதுவரை உண்மை என்று நம்பிக் கொண்டிருந்த எமது உடலுக்குள் புகுந்து அந்த நிலையை மாற்றி எந்தவொரு மலங்களும் இல்லாதவனாக ஆக்கிவிட்டு, பேரருளாகிய தர்மத்தின் வழியாக வந்து எமக்கு எப்போதும் தெகிட்டாத அமிழ்தத்தை கொடுத்து அருளிய பரம்பொருளாகிய இறைவனின் மாபெரும் கருணையை நினைத்துப் பார்த்து அதனால் ஏற்பட்ட வியப்பிலேயே ஆழ்ந்து இருந்தேன்.`,
  },
  {
    id: 1822, tantraId: 7, verseNumber: 1821,
    tamil: `அருளது என்ற அகலிடம் ஒன்றும்
பொருளது என்ற புகலிடம் ஒன்றும்
மருளது நீங்க மனம்புகுந் தானைத்
தெருளுறும் பின்னைச் சிவகதி தாமே`,
    transliteration: `aruḷatu eṉṟa akaliṭam oṉṟum
poruḷatu eṉṟa pukaliṭam oṉṟum
maruḷatu nīṅka maṉampukun tāṉait
teruḷuṟum piṉṉaic civakati tāmē`,
    english: `1821: Grace is the Refuge
There is a Space Vast that is Grace
There is a Refuge Safe that is Lord
In me He entered, my darkness to dispel;
Know Him fully; then indeed, is Siva-State.`,
    elaborationTamil: `இறையருள் என்று அழைக்கப்படும் பரம்பொருள் அண்ட சராசரங்களிலும் அதை தாண்டியும் இருக்கின்ற பரவெளியில் பொருந்தி இருக்கும். உயிர்கள் என்று அழைக்கப்படும் பரம்பொருளின் அம்சமான ஆன்மாக்கள் தாம் பிறவி எடுத்து வந்து சேர்ந்த இந்த உலகத்தை பொருந்தி இருக்கும். தாம் பொருந்தி இருக்கின்ற இந்த உலகத்தில் பந்தம் பாசங்கள் ஆகிய மாயையின் மயக்கம் நீங்கும் படி செய்து அனைத்திலும் இருக்கின்ற பரம்பொருள் வந்து அடியவர்களின் உள்ளத்திற்குள் புகுந்தான். அப்படி தமது உள்ளத்திற்குள் புகுந்த இறைவனை தெளிவாக அறிந்து உணர்ந்து கொண்டு அவனையே உறுதியாக பற்றிக் கொண்டு இருந்தால் பிறகு வரும் காலத்தில் இறைவனிடம் சென்று அடையும் நிலை அதுவே ஆகும்.`,
  },
  {
    id: 1823, tantraId: 7, verseNumber: 1822,
    tamil: `கூறுமின் னீர்முன் பிறந்திங்கு இறந்தமை
வேறொரு தெய்வத்தின் மெய்ப்பொருள் நீக்கிடும்
பாறணி யும்உடல் வீழலிட்டு ஆருயிர்
தேறுஅணிவோம்இது செப்பவல் லீரே`,
    transliteration: `kūṟumiṉ ṉīrmuṉ piṟantiṅku iṟantamai
vēṟoru teyvattiṉ meypporuḷ nīkkiṭum
pāṟaṇi yumuṭal vīḻaliṭṭu āruyir
tēṟuaṇivōmitu ceppaval līrē`,
    english: `1822: Save the Soul
If other gods be born, live and die
Are they the True Ones? Speak;
Let us this body leave, to vultures a prey
And save our Soul--this you should proclaim.`,
    elaborationEnglish: `If gods are born, live and dic, can they be true gods? Proclaim
that — to save jivas, lest they should leave this body a prey
to the vultures.`,
    elaborationTamil: `உலகத்தில் கற்றதே உண்மை என்று நீங்கள் நம்புவது உண்மை என்றால் இதற்கு முன் ஜென்மத்தில் நீங்கள் எங்கு பிறந்து அங்கு எப்படி இறந்தீர்கள் என்பதை உங்களால் சொல்ல முடியுமா? அது போலவே உள்ளிருக்கும் சிவத்தை தவிர வெளியில் வேறு ஒரு தெய்வம் இருக்கின்றது என்று உலகோர் சொல்லுவது உண்மை போல் தெரியும். அப்படி உண்மை போல் தெரிகின்ற பொருளானது உங்களின் உடல் அழியும் போது உங்களை விட்டு நீங்கிப் போய் விடும். ஆகவே உலகத்தில் பிறக்கும் போது நீங்கள் அணிந்து வந்த உடல் எனும் சட்டையை இந்த உலகத்திலேயே விழுந்து கிடக்கும் படி விட்டு விட்டு அந்த உடலுக்குள் இருந்த அருமையான உயிர் எனும் தேராக செயல்புரிகின்ற சிவத்தை அணிந்து கொள்ளுங்கள். வாழ்க்கைக்கு முக்கியமான இந்த உண்மையை மற்றவர்களுக்கும் எடுத்து சொல்ல முடிந்தவர்கள் சொல்லுங்கள்.`,
  },
  {
    id: 1824, tantraId: 7, verseNumber: 1823,
    tamil: `உள்ளம் பெருங்கோயில் ஊனுடம்பு ஆலயம்
வள்ளற் பிரானார்க்கு வாய்கோ புரவாசல்
தெள்ளத் தெளிந்தார்க்குச் சீவன் சிவலிங்கம்
கள்ளப் புலன்ஐந்தும் காளா மணிவிளக்கே`,
    transliteration: `uḷḷam peruṅkōyil ūṉuṭampu ālayam
vaḷḷaṟ pirāṉārkku vāykō puravācal
teḷḷat teḷintārkkuc cīvaṉ civaliṅkam
kaḷḷap pulaṉaintum kāḷā maṇiviḷakkē`,
    english: `1823: Soul is Siva Linga
For the Bounteous Lord
This heart is the sanctum holy,
The fleshly body is temple vast
The mouth is the tower gate;
To them that discern,
Jiva is Sivalinga;
The deceptive senses but the lights that illume.`,
    elaborationEnglish: `This fleshy body is a unique temple; the mouth is its tower gate; and the heart is the holy sanctum for the Bounteous Lord. For those who can vision, jiva is the Siva lingam, and the senses the illuminating lamp.`,
    elaborationTamil: `அடியவர்களின் உள்ளமானது இறைவன் வீற்றிருக்கும் மிகப் பெரும் கோயிலாகும். அவர்களது தசையும் எலும்புகளுமான உடலானது இறைவனை பூஜிக்க வலம் வரும் ஆலயமாகும். இல்லை என்று வருபவர்களுக்கு தம்மால் இயன்றதை வழங்குகின்ற வள்ளல் தன்மை கொண்டு போற்றத் தகுந்த அடியவர்களுக்கு அவர்களின் வாயானது இறைவனை தரிசிக்க வருகின்றவர்களை வரவேற்கும் ஆலயத்தின் கோபுர நுழை வாசல் ஆகும். இறைவனை தமக்குள் ஆராய்ந்து தெளிவாக அறிந்து கொண்டவர்களின் ஆன்மாவனது இறைவனின் அடையாளமான இலிங்கமாகும். அவர்களிடம் இருக்கின்ற தமது இயல்பிலேயே மாயையால் உண்மையை மறைக்கின்ற திருட்டுத் தனம் கொண்ட புலன்களாகிய கண், காது, மூக்கு, வாய், உடல் ஆகிய ஐந்தும் தமது இயல்பு நிலை மாறி இருட்டாகிய மாயையை நீக்குகின்ற வெளிச்சத்தை தரும் விளக்குகள் ஆகும்.`,
  },
  {
    id: 1825, tantraId: 7, verseNumber: 1824,
    tamil: `வேட்டவி யுண்ணும் விரிசடை நந்திக்குக்
காட்டவும் நாம்இலம் காலையும் மாலையும்
ஊட்டவி யாவன உள்ளம் குளிர்விக்கும்
பாட்டவி காட்டுதும் பால்அவி யாமே`,
    transliteration: `vēṭṭavi yuṇṇum viricaṭai nantikkuk
kāṭṭavum nāmilam kālaiyum mālaiyum
ūṭṭavi yāvaṉa uḷḷam kuḷirvikkum
pāṭṭavi kāṭṭutum pālavi yāmē`,
    english: `1824: Prayer is True Sacrifice
To Nandi of the spreading matted locks
That the sacrificial oblations takes,
We nothing offer;
The sacrifice that we morn and even can give
Are songs of praise that melt His heart;
Let us that sacrifice offer;
Verily, that is sacrifice, milk that is sweet.`,
    elaborationTamil: `அடியவர்கள் தாம் செய்கின்ற யாகத்தில் விருப்பத்தோடு அளிக்கின்ற யாகப் பொருட்களை பிரசாதமாக ஏற்கின்ற விரிந்த சடையைக் கொண்ட குருநாதனாகிய இறைவனுக்கு நாம் வளர்த்து சமர்ப்பிக்கின்ற யாக அக்னியானது நமக்குள் இருக்கின்ற மலங்களாகிய ஆனவம், கன்மம், மாயை ஆகியவை நீங்க வேண்டி காலையில் சூரியன் தோன்றும் போதும் மாலையில் சூரியன் மறையும் போதும் நாம் செய்கின்ற யாகமாக இருக்க வேண்டும். புகையை ஊட்டுகின்ற யாகப் பொருட்களின் நெருப்பானது இறைவனின் உள்ளத்தை குளிர்விக்கும். மந்திரங்களை ஓதி யாகத்தில் பொருட்களை இட்டு அக்னியை வளர்த்து காட்டும் போது அந்த அக்னியில் ஜோதியாக வீற்றிருப்பது நம்மை ஆட்கொண்டு காத்து அருள்கின்ற இறைவன் ஆகும்.`,
  },
  {
    id: 1826, tantraId: 7, verseNumber: 1825,
    tamil: `பான்மொழி பாகன் பராபரன் தானாகும்
ஆன சதாசிவன் தன்னைஆ வாகித்து
மேன்முகம் ஈசான மாகவே கைக்கொண்டு
சீன்முகம் செய்யச் சிவனவன் ஆகுமே`,
    transliteration: `pāṉmoḻi pākaṉ parāparaṉ tāṉākum
āṉa catācivaṉ taṉṉaiā vākittu
mēṉmukam īcāṉa mākavē kaikkoṇṭu
cīṉmukam ceyyac civaṉavaṉ ākumē`,
    english: `1825: Worship Sadasiva and Become Siva
The Lord that with Lady of milky speech consorts
Is the Para Para Supreme;
In Him enshrine Sadasiva
His upward looking Face as Isana consider
And thus your worship perform
You shall Siva Himself become.`,
    elaborationTamil: `இறைவனை அடைய வேண்டும் என்ற உண்மையான தேடுதலோடு முயற்சி செய்கின்ற அடியவர்களுக்கு அவரவர்களின் கர்ம நிலைகள் நீங்கி இறைவனை அடைகின்ற பக்குவம் பெறுவதற்கு ஏற்றவாறு அருள் புரிகின்ற இறைவியை தமது சரிபாதி பாகமாகக் கொண்டு அடியவர்களுக்கு அருளும் தொழிலை புரிகின்ற சதாசிவமூர்த்தியாகிய இறைவனை முதலில் அருவுருவமாக வழிபடுவதற்கு ஆகம விதிகளின் படி முறைப்படி இலிங்க வடிவத்தை செய்து, அதில் எழுந்தருளும் படி இறைவனை உண்மையான அன்போடு வேண்டி வரவழைத்து, அதன் பிறகு தாம் செய்கின்ற இலிங்க வழிபாட்டை முறைப்படி சரியாக கடைபிடித்து, அதன் பயனால் இலிங்கத்தில் எழுந்தருளிய இறைவனை தமக்குள்ளும் எழுந்தருளும் படி செய்து, அதையே தலையாகப் பற்றிக் கொண்ட அடியவர்கள் சிவமாகவே ஆகிவிடுவார்கள்.`,
  },
  {
    id: 1827, tantraId: 7, verseNumber: 1826,
    tamil: `நினைவதும் வாய்மை மொழிவதும் அல்லால்
கனைகழல் ஈசனைக் காண அரிதாம்
கனைகழல் ஈசனைக் காண்குற வல்லார்
புனைமலர் நீர்கொண்டு போற்றவல் லாரே`,
    transliteration: `niṉaivatum vāymai moḻivatum allāl
kaṉaikaḻal īcaṉaik kāṇa aritām
kaṉaikaḻal īcaṉaik kāṇkuṟa vallār
puṉaimalar nīrkoṇṭu pōṟṟaval lārē`,
    english: `1826: Adore the Lord and Behold Him
You can think of Him, you can speak of His Truth
But rare indeed to see the Lord of the Holy Feet;
They can but see the Lord of the Holy Feet
Who adore Him with flower and water.`,
    elaborationEnglish: `Well may you think of Him, and speak of His Truth. But
rarely can you behold the Holy Feet of the Lord. They who
adore Him with flowers and water can see them.`,
    elaborationTamil: `நல்லதை மட்டுமே நினைப்பது, உண்மையை மட்டுமே பேசுவது ஆகிய ஒழுக்கங்களை சரியாக கடை பிடிக்காமல் வேறு என்ன சாதகம் செய்தாலும் இசைக்கின்ற அழகிய சிலம்புகளை அணிந்த திருவடிகளை உடைய இறைவனை தரிசிக்க முடியாது. ஆகவே நன்மையை மட்டுமே நினைப்பதையும் உண்மையை மட்டுமே பேசுவதையும் ஒழுக்கமாகக் கொண்டு அதனோடு அனைத்து உயிர்களுக்குள்ளும் இசைகின்ற அழகிய சிலம்புகளை அணிந்த திருவடிகளை உடைய இறைவனை தரிசிக்கும் வல்லமை பெற்றவர்கள் தாம் தரிசித்த இறைவனை நேரிலேயே நறுமணம் கொண்ட அழகிய மலர்களாலும் தூய்மையான நீராலும் போற்றி வணங்கி வழிபடும் வல்லமை பெறுவார்கள்.`,
  },
  {
    id: 1828, tantraId: 7, verseNumber: 1827,
    tamil: `மஞ்சன மாலை நிலாவிய வானவர்
நெஞ்சினுள் ஈசன் நிலைபெறு காரணம்
அஞ்சமு தாம்உப சாரம்எட்டு எட்டோ டும்
அஞ்சலி யோடும் கலந்துஅர்ச்சித் தார்களே`,
    transliteration: `mañcaṉa mālai nilāviya vāṉavar
neñciṉuḷ īcaṉ nilaipeṟu kāraṇam
añcamu tāmupa cārameṭṭu eṭṭō ṭum
añcali yōṭum kalantuarccit tārkaḷē`,
    english: `1827: Celestials Worship Lord with Archana
Why is it the Lord has taken His seat
In the heart of Beings Celestial
That consecrated water and garland of flowers bear?
With offerings five of dishes sweet
And with upachara rituals two times eight
They humbly prostrating, in archana, worship. evocative`,
    elaborationEnglish: `Why has the Lord taken His seat in the heart of the celestial
beings who bear the consecrated water and garland of flowers?
They humbly prostrate in worship, offering the Lord five sweet
dishes and sixteen upachara rituals.`,
    elaborationTamil: `அடியவர்களால் அபிஷேகமும் மலர்கள் சூட்டி அலங்காரமும் செய்து இறைவனின் பிரதிநிதிகளாக வழிபடப் படுகின்ற வானுலகத்து தேவர்களின் நெஞ்சத்திற்குள் இறைவன் வீற்றிருந்து அடியவர்களின் வழிபாட்டிற்கு ஏற்ப அருளை வழங்குவதற்கு காரணம் என்னவென்றால் அடியவர்கள் உண்மையான அன்போடு பஞ்சாமிர்தம் முதலாகிய 16 விதமான உபசாரங்களை செய்து அருச்சனை செய்தார்கள் என்பதனால் ஆகும். 16 வகையான உபசாரங்கள்: ஆவாகனம் – மந்திரத்தால் இறை சக்தியை ஒரு மூர்த்திக்கு மாற்றுதல் தாபனம் – மூர்த்தியை பிரதிஷ்டை செய்தல் சந்நிதானம் – மூர்த்தி இருக்கின்ற மூலஸ்தானத்தை சுத்தப் படுத்துதல் சந்நிரோதனம் – இறைவனது சாந்நியத்தை (சக்தி வெளிப்பாடு) மூர்த்தியில் நிறுத்துதல் அவகுண்டவம் – மூர்த்தியை சுற்றி மூன்று கவசங்களை மந்திரத்தால் உருவாக்குதல் தேனுமுத்திரை – மனதை ஒருநிலைப் படுத்தி முத்திரை காட்டுதல் பாத்தியம் – மூல மந்திரத்தை உச்சரித்து மூர்த்தியின் திருவடியில் தீர்த்தம் சமர்ப்பித்தல் ஆசமனீயம் – புனிதப் படுத்தும் நீரை மந்திரத்தால் உட்கொள்ளுதல் அருக்கியம் – தூய்மையான நீரினால் மூர்த்திக்கு அபிஷேகம் செய்தல் புஷ்பதானம் – மலர்கள் சாற்றுதல் தூபம் – சாம்பிராணி காட்டுதல் தீபம் – தீப ஆராதனை செய்தல் நைவேத்தியம் – இறைவனை நினைத்து சமைத்த சாத்வீகமான உணவு படைத்தல் பாணீயம் – தூய்மையான நீர் படைத்தல் செபசமர்ப்பணம் – மந்திரங்களை ஜெபித்து சமர்ப்பித்தல் ஆராத்திரிகை – போற்றி பாடி மணியடித்து ஆராதித்தல்`,
  },
  {
    id: 1829, tantraId: 7, verseNumber: 1828,
    tamil: `புண்ணியம் செய்வார்க்குப் பூவுண்டு நீருண்டு
அண்ணல் அதுகண்டு அருள்புரி யாநிற்கும்
எண்ணிலி பாவிகள் எம்இறை ஈசனை
நண்ணறி யாமல் நழுவுகின் றாரே`,
    transliteration: `puṇṇiyam ceyvārkkup pūvuṇṭu nīruṇṭu
aṇṇal atukaṇṭu aruḷpuri yāniṟkum
eṇṇili pāvikaḷ emiṟai īcaṉai
naṇṇaṟi yāmal naḻuvukiṉ ṟārē`,
    english: `1828: Pray and Receive Grace
The devout are they with flower and water pray
The Lord seeing that bestows His Grace on them
Countless are the sinners that know not how our Lord to approach
Thus they slip by in ignorance deep.`,
    elaborationEnglish: `The devout are they who pray with water and flowers. On them the Lord bestows His Grace. The undevout are they. who do not know how ta approach Him. They let go the chance by sheer ignorance.`,
    elaborationTamil: `இறைவன் விதித்த தர்மத்தை கடைபிடித்து பல புண்ணிய காரியங்களை செய்கின்றவர்களுக்கு இறைவனை வழிபடும் போது அதற்கு தேவையான பூவும் நீரும் இறையருளால் எப்போதும் கிடைக்கும். ஆனால் எண்ணிக்கையில்லாத அளவு பெரும்பாலான மனிதர்கள் அனைத்து உயிர்களிலும் இறைவனை கண்டு அறிந்து கொண்டு அந்த உயிர்களின் மேல் கருணை செய்து அதன் மூலம் இறைவனை நெருங்கிச் சென்று அவனை முழுவதும் அறிந்து கொள்ள முயற்சி செய்யாமல் அறியாமையால் இறைவனை விட்டு விலகிச் சென்ற பாவிகளாகவே வாழ்ந்து அழிகின்றார்கள்.`,
  },
  {
    id: 1830, tantraId: 7, verseNumber: 1829,
    tamil: `அத்தன் நவதீர்த்தம் ஆடும் பரிசுகேள்
ஒத்தமெய்ஞ் ஞானத்து உயர்ந்தார் பதத்தைச்
சுத்தம தாக விளக்கித் தெளிக்கவே
முத்தியாம் என்று நம்மூலன் மொழிந்ததே`,
    transliteration: `attaṉ navatīrttam āṭum paricukēḷ
ottameyñ ñāṉattu uyarntār patattaic
cuttama tāka viḷakkit teḷikkavē
muttiyām eṉṟu nammūlaṉ moḻintatē`,
    english: `1829: Anoint Feet of Holy is Unto Bathing in Holy Waters
Know the reward of bathing
In the nine waters of the Lord;
Mukti indeed for those
That anoint the feet of holy men
Who in Jnana are upraised;
Thus does Mula proclaim.`,
    elaborationEnglish: `That anoint the feet of holy men
Who in Jnana are upraised;

Thus does Mula proclaim.

They who worship with water and flowers reap the reward
of bathing in the nine Holy Waters of the Lord. Mula
(Tirumular) proclaimed that those who anoint the feet of holy
men who are upraised in jnana obtain mukti.

bpuypp Nay wered per mrgues`,
    elaborationTamil: `அனைத்து உயிர்களுக்கும் தந்தையாகிய இறைவன் நமது உடலுக்குள் இருக்கின்ற ஒன்பது விதமான தீர்த்தங்களாகிய சக்கரங்களில் திருநடனம் புரிவதனால் கிடைக்கின்ற பலனை பற்றி கூறுகின்றேன் கேளுங்கள். இறைவனுக்கு இணையாகிய உண்மையான ஞானத்தில் உயர்ந்து விளங்கும் ஞானிகளின் அருள் நிறைந்த திருவடிகளை சுத்தமான நீரினால் கழுவித் துடைத்து அந்த நீரை நமது தலையில் தீர்த்தமாக தெளித்துக் கொண்டால் அந்த அருளின் பயனால் நமக்குள் இருக்கின்ற ஒன்பது விதமான தீர்த்தங்களாகிய சக்கரங்களில் இறைவன் வந்து திருநடனம் புரிவான். அப்போது அதன் பயனால் மும்மலங்களும் நீங்கப்பெற்று கிடைக்கின்ற முக்தி நிலையாக இறைவனே இருப்பான் என்று நமக்கெல்லாம் ஆதிமூலமாகிய இறைவனே சொல்லி அருளினான். உட் கருத்து: புண்ணிய நதிகளில் நீராடுவதை விட இறைவனை உணர்ந்த ஞானிகளின் பாதங்களை கழுவிய நீரை தெளித்துக் கொள்வது எளிதில் இறையருளைப் பெறுவதற்கு வழிவகுக்கும். அது எப்படி என்றால் இறைவனை உணர்ந்த ஞானிகளின் அருள் நிறைந்த பாதங்களை தூய்மையான நீரினால் சுத்தமாக கழுவித் துடைத்தால் அந்த பாதத்தில் இருக்கின்ற அருளின் மூலம் நமக்குள் இருக்கின்ற மாயையாகிய அழுக்குகள் நீங்கி உண்மை அறிவைப் பெற்று அதன் மூலம் முக்தியை அடையலாம். உடலுக்குள் இருக்கின்ற ஒன்பது சக்கரங்கள்: மூலாதாரம் (அக்னி மண்டலம்) சுவாதிஷ்டானம் மணிப்பூரகம் அநாகதம் விசுக்தி ஆக்ஞை சகஸ்ரதளம் சூரிய மண்டலம் (துவாத சாந்த வெளி) சந்திர மண்டலம்`,
  },
  {
    id: 1831, tantraId: 7, verseNumber: 1830,
    tamil: `மறப்புற்று இவ்வழி மன்னிநின் றாலும்
சிறப்பொடு பூநீர் திருந்தமுன் ஏந்தி
மறப்பின்றி யுன்னை வழிபடும் வண்ணம்
அறப்பெற வேண்டும் அமரர் பிரானே`,
    transliteration: `maṟappuṟṟu ivvaḻi maṉṉiniṉ ṟālum
ciṟappoṭu pūnīr tiruntamuṉ ēnti
maṟappiṉṟi yuṉṉai vaḻipaṭum vaṇṇam
aṟappeṟa vēṇṭum amarar pirāṉē`,
    english: `1830: My Prayer is to Worship Lord with Archana
Even if in thoughtlessness
I world's ways pursue,
Do grant me this:
That I with water and flower
Unceasing adore You;
This my prayer;
O! Lord of immortals!`,
    elaborationEnglish: `Even if in thoughtlessness the devotee pursues mundane ways, may he ask the Lord to grant him this boon: that he should unceasingly adore the Lord with water and flowers. Let that be the devotee's unfailing prayer.`,
    elaborationTamil: `அமரர்களின் தலைவனாகிய இறைவனே ஆசையினால் உன்னை பிரிந்து இந்த உலகத்தில் பிறந்து மாயையினால் உன்னை மறந்து உலக வழிகளில் கிடைக்கின்ற இன்பத்திலேயே நின்று கிடக்கின்றோம். உன் அருளால் இந்த நிலையிலிருந்து யாம் மாறி எந்த விதமான பாவமும் இல்லாமல் உன்னை சீராக நினைத்து போற்றுவதற்கு ஏற்றபடி அருளை பெற வேண்டும் என்று உண்மையான அன்போடு நறுமணமான மலர்களையும் தூய்மையான நீரையும் எமது கைகளில் ஏந்தி வந்து உனது முன் வேண்டுகின்றோம். எம்மீது கருணை கொண்டு அருள்வாயே.`,
  },
  {
    id: 1832, tantraId: 7, verseNumber: 1831,
    tamil: `ஆரா தனையும் அமரர் குழாங்களும்
தீராக் கடலும் நிலத்துஉம தாய்நிற்கும்
பேரா யிரமும் பிரான்திரு நாமமும்
ஆரா வழியெங்கள் ஆதிப் பிரானே`,
    transliteration: `ārā taṉaiyum amarar kuḻāṅkaḷum
tīrāk kaṭalum nilattuuma tāyniṟkum
pērā yiramum pirāṉtiru nāmamum
ārā vaḻiyeṅkaḷ ātip pirāṉē`,
    english: `1831: Chant the Thousand Names of Lord
The Immortals swarm in hordes seeking Him;
The seas and lands unending,
All that yours shall be,
When you chant unceasing
The thousand names of the Primal Lord,
And the One Sacred name Special.`,
    elaborationEnglish: `The immortals swarm in clans seeking Him, ceaselessly chanting the thousand names of the Primal Lord. Hordes of celestials seek Him in an unending procession, bathing Him in pancha gavya (the five products of the cow).`,
    elaborationTamil: `அடியவர்கள் செய்கின்ற ஆராதனைகளாகவும், வானுலகத்து அமரர்களின் கூட்டமாகவும், எவ்வளவு எடுத்தாலும் தீராத அளவிற்கு நீரைக் கொண்ட கடல்களாகவும், அந்த கடல்களால் சூழப்பட்ட நிலங்களாகவும், அந்த நிலத்தில் வாழுகின்ற அடியவர்களால் அன்போடு அழைக்கப் படுகின்ற ஆயிரம் பெயர்களாகிய திருநாமங்களாகவும், அதை முறைப்படி சொல்லுகின்ற அடியவர்களை இறப்பு இல்லாத நிலைக்கு அழைத்துச் செல்லுகின்ற வழியாகவும், ஆதி மூல தலைவனாகிய இறைவனே இருக்கின்றான்.`,
  },
  {
    id: 1833, tantraId: 7, verseNumber: 1832,
    tamil: `ஆன்ஐந்தும் ஆட்டி அமரர் கணம்தொழத்
தான்அந்த மில்லாத் தலைவன் அருளது
தேன்உந்து மாமலர் உள்ளே தெளிந்ததோர்
பார்ஐங் குணமும் படைத்துநின் றானே`,
    transliteration: `āṉaintum āṭṭi amarar kaṇamtoḻat
tāṉanta millāt talaivaṉ aruḷatu
tēṉuntu māmalar uḷḷē teḷintatōr
pāraiṅ kuṇamum paṭaittuniṉ ṟāṉē`,
    english: `1833 Celestials Pray and Receive Lord's Grace
Bearing choicest flowers and water
The heavenly Beings over clouds traverse;
And with Pasa subdued, stand and pray
And unfailing, My Lord's Grace receive.`,
    elaborationTamil: `அனைத்திற்கும் நாயகர்களாக விளங்குகின்ற மூர்த்திகளாகிய பிரம்மன், திருமால், உருத்திரன், மகேஸ்வரன், சதாசிவன் ஆகிய ஐவர்களுக்கும் தீப ஆராதனை செய்து அமரர்களின் கூட்டம் தொழுது வணங்கும் போது அந்த ஐந்து நாயகர்களாக இருந்து அவர்கள் புரியும் தொழில்களை அருளுவது தனக்கென்று எந்த ஒரு முடிவும் இல்லாத தலைவனாகிய இறைவனின் திருவருளே ஆகும். தெகிட்டாத தேனாகிய பேரின்ப அமிழ்தத்தை வெளியே அலைந்து தேடாமல் உண்மை ஞானிகளால் தமக்குள்ளே தேடி அடைகின்ற மாபெரும் மலராகிய சகஸ்ரர தளத்தின் ஆயிரம் இதழ் கொண்ட தாமரை மலரின் உள்ளே தெளிந்த ஜோதியாக வீற்றிருக்கின்ற ஒரு பேரின்ப அமிழ்தமாகவும் அந்த திருவருளே இருக்கின்றது. இந்த உலகத்தில் இருக்கின்ற நிலம், நீர், காற்று, நெருப்பு, ஆகாயம் ஆகிய ஐந்து விதமான பூதங்களின் குணமாகவும் அந்த திருவருளே இருக்கின்றது. இப்படி தமது திருவருளாலே அனைத்தையும் உருவாக்கி நிற்கின்றான் இறைவன்.`,
  },
  {
    id: 1834, tantraId: 7, verseNumber: 1833,
    tamil: `உழைக்கொண்ட பூநீர் ஒருங்குடன் ஏந்தி
மழைக்கொண்ட மாமுகில் மேற்சென்று வானோர்
தழைக்கொண்ட பாசம் தயங்கிநின்று ஏத்தப்
பிழைப்பின்றி எம்பெரு மான்அரு ளாமே`,
    transliteration: `uḻaikkoṇṭa pūnīr oruṅkuṭaṉ ēnti
maḻaikkoṇṭa māmukil mēṟceṉṟu vāṉōr
taḻaikkoṇṭa pācam tayaṅkiniṉṟu ēttap
piḻaippiṉṟi emperu māṉaru ḷāmē`,
    english: `1833: Celestials Pray and Receive Lord's Grace
The heavenly Beings over clouds traverse;
And with Pasa subdued,
stand and pray
And unfailing, My
Lord's Grace receive.`,
    elaborationEnglish: `The heavenly beings traverse over clouds, bearing the choicest
flowers and water; stand with subdued pasa and pray to Him.
They all receive the Lord’s Grace without fail.`,
    elaborationTamil: `உண்மையான அன்போடு அருச்சனை செய்வதற்கு நறுமணம் மிக்க மலர்களையும் அபிஷேகம் செய்வதற்கு தூய்மையான நீரையும் ஒன்றாக கைகளில் ஏந்தி வந்து, மழை நீரைக் கொண்ட மாபெரும் மேகக் கூட்டங்களுக்கு மேலே வசிக்கின்ற விண்ணுலகத் தேவர்களுக்கு பூஜை செய்து, இந்த உலகில் பிறவி எடுக்கும் போது அதனுடன் சேர்ந்து வந்த பந்த பாசங்களினால் அனுபவிக்கின்ற பலவித துன்பங்களில் இருந்து தம்மை விடுவித்து அருளும் படி இறைவனை போற்றி வணங்கும் அடியவர்களுக்கு இறைவனின் திருவருளானது எந்தவித குற்றமும் இல்லாமல் பரிபூரணமாக கிடைக்கும்.`,
  },
  {
    id: 1835, tantraId: 7, verseNumber: 1834,
    tamil: `வெள்ளக் கடலுள் விரிசடை நந்திக்கு
உள்ளக் கடற்புக்கு வார்சுமை பூக்கொண்டு
கள்ளக் கடல்விட்டுக்கைதொழ மாட்டாதார்
அள்ளக் கடலுள் அழுந்துகின் றாரே`,
    transliteration: `veḷḷak kaṭaluḷ viricaṭai nantikku
uḷḷak kaṭaṟpukku vārcumai pūkkoṇṭu
kaḷḷak kaṭalviṭṭukkaitoḻa māṭṭātār
aḷḷak kaṭaluḷ aḻuntukiṉ ṟārē`,
    english: `1834: Enter the Sea of Heart's Faith
In the expanse of waters (Ganga),
With spreading matted locks is Nandi;
Renounce the sea of unbelief;
Enter the sea of heart's faith;
They who adore Him not thus
With hands laden with flowers
Will in the sea of sorrow fall,
And forever immersed be.`,
    elaborationTamil: `கடல் வெள்ளம் போன்ற நீரைக் கொண்ட கங்கையை தமது விரிந்த சடைக்குள் அடக்கி ஒரு சிறு நதியாக தருகின்ற குருநாதராகிய இறைவனை தமது பேரன்பினால் உள்ளமாகிய கடலுக்குள் வைக்கும் வல்லமை கொண்ட உண்மை ஞானிகளை நாடிச் சென்று பூவையும் நீரையும் அர்ப்பணித்து மாயையில் சுழலுகின்ற வாழ்க்கையாகிய கடலை விட்டு விட்டு இரு கைகளையும் கூப்பி வணங்கித் தொழுவதற்கு மறுக்கின்ற மக்கள் மேலும் மேலும் கர்மங்களை சேர்த்துக் கொண்டே இருக்கின்ற வாழ்க்கைக் கடலுக்குள் மூழ்கி பல வித துன்பங்களை அனுபவித்து தமது வாழ்க்கையை தொலைத்து விடுகின்றார்கள்.`,
  },
  {
    id: 1836, tantraId: 7, verseNumber: 1835,
    tamil: `கழிப்படுந் தண்கடற் கௌவை யுடைத்து
வழிப்படு வார்மலர் மொட்டுஅறி யார்கள்
பழிப்படு வார்பல ரும்பழி வீழ
வெளிப்படு வோர்உச்சி மேவிநின் றானே`,
    transliteration: `kaḻippaṭun taṇkaṭaṟ kauvai yuṭaittu
vaḻippaṭu vārmalar moṭṭuaṟi yārkaḷ
paḻippaṭu vārpala rumpaḻi vīḻa
veḷippaṭu vōrucci mēviniṉ ṟāṉē`,
    english: `1835: Break the Banks of the Sea of Sorrow
Breaking the marshy banks of the sea of sorrow
They adore Him with buds and blossoms;
They who know this not, into error great fall;
But those who know it, will see the Lord
In the crown of their head, seated within.`,
    elaborationEnglish: `Overcoming all doubts, they should adore Him with buds and blossoms in tru€ faith. Those who do not know this, fall into great error. Those who know it will see the Lord seated within the crown of their heads.`,
    elaborationTamil: `உப்புத் தன்மை கொண்ட குளிர்ந்த நீருள்ள கடலில் ஓசை மிக்க அலைகள் இல்லாதது போலவே ஐம்புலன்களால் வருகின்ற உணர்வுகளை அடக்கி வைத்து இறைவனை பூஜை செய்து வழிபடுகின்ற அடியவர்கள் தாம் பூஜை செய்கின்ற மலர்களின் நறுமணத்தை அறிவார்கள். அந்த நறுமணத்தின் பலனால் மனம் ஒடுங்கி இறைவன் மேல் மட்டும் எண்ணம் இலயித்து இருக்கும். அந்த நிலையில் எவர் எந்த பழி சுமத்தினாலும் அதனால் பாதிக்கப் படாமல் இறைவன் மட்டுமே கதியென்று வாழுகின்ற அடியவர்களின் மேல் சுமத்திய பழிகள் அனைத்தும் பொய்யாக விழுந்து போகும். அப்போது அந்த அடியவர்களுக்குள் இருந்து வெளிப்பட்ட சிவமானது அண்ட சராசரங்களின் எல்லை வரை பரந்து விரிந்து நிற்கும்.`,
  },
  {
    id: 1837, tantraId: 7, verseNumber: 1836,
    tamil: `பயனறிவு ஒன்றுண்டு பன்மலர் தூவிப்
பயனறி வார்க்குஅரன் தானே பயிலும்
நயனங்கள் மூன்றுடை யான்அடி சேர
வயனங்க ளால்என்றும் வந்துநின் றானே`,
    transliteration: `payaṉaṟivu oṉṟuṇṭu paṉmalar tūvip
payaṉaṟi vārkkuaraṉ tāṉē payilum
nayaṉaṅkaḷ mūṉṟuṭai yāṉaṭi cēra
vayaṉaṅka ḷāleṉṟum vantuniṉ ṟāṉē`,
    english: `1836: Adoration is the Way to Reach Lord
There is one way to reach Him
Adore Him with flowers many;
To them that do this,
The Lord by Himself stands revealed;
This the way to the Holy Feet of the three-eyed God;
Adoring Him thus, He fails never to stand before you.`,
    elaborationEnglish: `To adore Him with many flowers is the sure way to reach
the Holy Feet of the Three-Eyed God. Ta him, who does
it, the Lord stands revealed, unfailing.`,
    elaborationTamil: `பூஜை செய்து பெறுகின்ற பலன்களைப் பற்றிய அறிவு ஒன்று உண்டு. பல விதமான நறுமணம் மிக்க மலர்களை தூவி இறைவனுக்கு அருச்சனை செய்வதன் மூலம் பெறுகின்ற நற்பலன்களை அறிந்து கொள்கின்ற அடியவர்களுக்கு இறைவன் தாமாகவே படிப்படியாக பல அனுபவங்களை கொடுத்து அருள்வான். மூன்று கண்களைக் கொண்ட இறைவனின் திருவடியே கதியென்று முழுவதுமாக சரணடைந்த அடியவர்களுக்கு அவர்கள் எந்த வகையில் வழிபடுகின்றார்களோ அந்த வகையிலேயே இறைவன் வந்து நிற்பான்.`,
  },
  {
    id: 1838, tantraId: 7, verseNumber: 1837,
    tamil: `ஏத்துவர் மாமலர் தூவித் தொழுதுநின்று
ஆர்த்தெமது ஈசன் அருட்சே வடியென்றன்
மூர்த்தியை மூவா முதலுறு வாய்நின்ற
தீர்த்தனை யாரும் துதித்துஉண ராரே`,
    transliteration: `ēttuvar māmalar tūvit toḻutuniṉṟu
ārttematu īcaṉ aruṭcē vaṭiyeṉṟaṉ
mūrttiyai mūvā mutaluṟu vāyniṉṟa
tīrttaṉai yārum tutittuuṇa rārē`,
    english: `1837: Seek Him In Prayer
"My Lord, the Primal One, the Timeless Eternity,
The Holy One,"
--Thus they adore Him with flowers diverse,
And in love endearing at His Feet worship,
His Grace to receive;
How then do you in prayer seek Him not?`,
    elaborationEnglish: `When so many in endearing love pray at His Feet with choicest flowers and deep devotion and receive His Grace, why do not you, too, seek Him that way?`,
    elaborationTamil: `இறைவனின் திருவருளை வேண்டி போற்றி துதித்து, நறுமணம் மிக்க மலர்களை தூவி அருச்சனை செய்து, கை கூப்பி நின்று, திருநாமத்தை சொல்லி பெரும் கூச்சலிட்டு இறைவனின் சிவந்த திருவடிகளை வணங்குகின்றார்கள். ஆனால் எமது தலைவனும், அனைத்திற்கும் முதல்வனும், முதுமை என்பதே இல்லாதவனும், அனைத்திற்கும் முதலான ஆதியின் வடிவமாகவும் இருக்கின்ற பரிசுத்தமான புண்ணியனாகிய இறைவனை தமது ஆசைகளையும் புலன்களையும் அடக்கி ஒழுக்கத்தை கடைபிடித்து உணர்ந்து கொள்ளாமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1839, tantraId: 7, verseNumber: 1838,
    tamil: `தேவர்க ளோடுஇசை வந்துமண் ணோடுறும்
பூவொடு நீர்சுமந்து ஏத்திப் புனிதனை
மூவரிற் பன்மை முதல்வனாய் நின்றருள்
நீர்மையை யாவர் நினைக்கவல் லாரே`,
    transliteration: `tēvarka ḷōṭuicai vantumaṇ ṇōṭuṟum
pūvoṭu nīrcumantu ēttip puṉitaṉai
mūvariṟ paṉmai mutalvaṉāy niṉṟaruḷ
nīrmaiyai yāvar niṉaikkaval lārē`,
    english: `1838: Siva is the Primal One of Plural Three
Laden with flower and water
The Celestial beings seek the earth
And sing the praise of the Pure One;
Who who thinks of His bounteous Grace
Him He blesses,
He, the Primal One of the Plural Three.`,
    elaborationEnglish: `The celestials, seek the earth, laden with flowers and water,
and sing the praise of the pure Lord, the Primal One of the
plural three who blesses.`,
    elaborationTamil: `விண்ணுலகத்தில் வாழும் தேவர்களின் அம்சமாகிய அடியவர்களோடு சேர்ந்து நின்று, அவர்கள் இசைக்கின்ற பலவித மந்திரங்களாகிய பாடல்களை மனம் ஒன்றிப் பாடி, இந்த உலகத்தில் தினம் தோறும் நறுமணம் மிக்க மலர்களோடு தூய்மையான நீரையும் கைகளில் எடுத்து வந்து, தூய்மையானவனாகிய இறைவனை போற்றி துதித்து, பிரம்மன், திருமால், உருத்திரன் ஆகிய மூன்று மூர்த்திகளாக தனித்தனி தன்மைகளோடு பிரிந்து இருந்தாலும் அனைத்திற்கும் முதல்வனாகவே நின்று திருவருள் புரிகின்ற இறைவனின் பெருங் கருணை குணத்தை நினைத்து பார்க்கும் வல்லமை பெற்றவர்கள் யார்?`,
  },
  {
    id: 1840, tantraId: 7, verseNumber: 1839,
    tamil: `உழைக்கவல் லோர்நடு நீர்மலர் ஏந்திப்
பிழைப்பின்றி ஈசன் பெருந்தவம் பேணி
இழைக்கொண்ட பாதத்து இனமலர் தூவி
மழைக்கொண்டல் போலவே மன்னிநில் லீரே`,
    transliteration: `uḻaikkaval lōrnaṭu nīrmalar ēntip
piḻaippiṉṟi īcaṉ peruntavam pēṇi
iḻaikkoṇṭa pātattu iṉamalar tūvi
maḻaikkoṇṭal pōlavē maṉṉinil līrē`,
    english: `1839: Pray and Prosper
You that labour hard
Gather flowers and carry water pure;
Adore the Lord in unfailing piety
And at His shining Feet lay the flowers;
And stand and pray
And unto the rain-laden clouds
Forever prosperous you shall be.`,
    elaborationEnglish: `Gather flowers and carry pure water; bathe Him and lay the
flowers at His radiant Feet; stand and pray; and adore Him
ih unfailing piety. You will forever prosper.

Oacrg Mearsg Oengtiucail Guicsmesnit`,
    elaborationTamil: `காலையில் எழுந்த பிறகு தங்களின் தொழில் செய்வதற்கு முன்பு அவசரமின்றி நிதானமாக தூய்மையான நீரையும் நறுமணமிக்க மலர்களையும் இரு கைகளில் ஏந்திக் கொண்டு, எந்தவிதமான குற்றமும் இல்லாமல் இறைவனை சிரத்தையோடு பூசை செய்கின்ற மிகப்பெரும் தவத்தை ஒரு நாளும் தவறாமல் கடைபிடித்து, அழகிய சிலம்புகளை அணிந்து கொண்டு இருக்கின்ற இறைவனின் திருவடிகளுக்கு ஒரே வகையான நறுமலர்களை தூவி அருச்சனை செய்து, மழை பொழிகின்ற கருத்த மேகத்தை போலவே தூய்மையான நீரால் அபிஷேகம் செய்து நிலையாக நில்லுங்கள். உட் கருத்து: இறைவனுடைய திருவடிகளில் எப்போதும் இழைந்து (உராய்ந்து) கொண்டே இருக்கின்ற அழகிய சிலம்புகளைப் போலவே அடியவர்கள் தங்களின் மனதிற்குள் இறைவனின் திருவடிகளை எப்போதும் நினைத்துக் கொண்டே இருப்பது ஒரு மிகப் பெரிய தவம் ஆகும். அந்த தவத்தை சிரத்தையோடு இடைவிடாது கடை பிடித்தால் கருமையான மேகங்களுக்குள் மழை நீர் மறைந்து இருப்பது போலவே அடியவரது எண்ணத்திற்குள் இறைவனின் திருவருளானது எப்போதும் நிறைந்து நிற்கும்.`,
  },
  {
    id: 1841, tantraId: 7, verseNumber: 1840,
    tamil: `வென்று விரைந்து விரைப்பணி என்றனர்
நின்று பொருந்த இறைபணி நேர்படத்
துன்று சலமலர் தூவித் தொழுதிடில்
கொண்டிடும் நித்தலும் கூறியஅன்றே`,
    transliteration: `veṉṟu viraintu viraippaṇi eṉṟaṉar
niṉṟu porunta iṟaipaṇi nērpaṭat
tuṉṟu calamalar tūvit toḻutiṭil
koṇṭiṭum nittalum kūṟiyaaṉṟē`,
    english: `1840: Lord Receives Worship
To perform Lord's worship in manner appropriate
Senses subdue, hasten, and quick at His Feet fall;
And offering water and flower daily worship
He will accet you, thus I said, even in days of yore.`,
    elaborationEnglish: `Subdue the senses, hasten towards Him; surrender in totality and warship the Lord daily, offering water and flowers. He will surely accept your heart’s offering.`,
    elaborationTamil: `ஐந்து புலன்களின் வழியே செல்லும் ஆசைகளில் சிக்கிச் சுழலாமல் அதை மன உறுதியால் வென்று மனித வாழ்க்கையில் உடனடியாக செய்ய வேண்டியது இறைவனுக்கு தூப தீபங்கள் காட்டி வழிபடுவதே என்று சான்றோர்கள் சொல்லுவார்கள். அவர்கள் சொல்லியபடி இறைவன் மேல் கொண்ட பக்தியில் தன்னையே மறந்து இறைவனோடு தம் மனமும் பொருந்தி இருக்கும் படி நின்று தூய்மையான நீரால் அபிஷகம் செய்தும் காலைப் பனி பூத்திருக்கும் நறுமணம் மிக்க மலர்களால் அருச்சனை செய்தும் தினந்தோறும் இறைவனை தொழுது வந்தால் இறைவனது திருவருளானது அடியவர்களின் வினைகளை அழித்து நீக்கிவிடும். இதை முன் காலத்திலேயே சான்றோர்கள் சொல்லி இருக்கின்றார்கள்.`,
  },
  {
    id: 1842, tantraId: 7, verseNumber: 1841,
    tamil: `சாத்தியும் வைத்தும் சயம்புஎன்று ஏத்தியும்
ஏத்தியும் நாளும் இறையை அறிகிலார்
ஆத்தி மலக்கிட்டு அகத்துஇழுக்கு அற்றக்கான்
மாத்திக்கே செல்லும் வழியது வாமே`,
    transliteration: `cāttiyum vaittum cayampueṉṟu ēttiyum
ēttiyum nāḷum iṟaiyai aṟikilār
ātti malakkiṭṭu akattuiḻukku aṟṟakkāṉ
māttikkē cellum vaḻiyatu vāmē`,
    english: `1841: Way to Goal Supreme
Adorn Him with garland of flowers
Place them at His feet
Praise Him as the Lord Primal;
Those that have daily prayed to Him
And yet have known Him not
Let them adore Him with Athi flower, so dear to Him
And pray, their base nature be cleansed of impurities;
--That the way to Goal Supreme.`,
    elaborationEnglish: `Adore the Lord with the athi flower so dear to Him and pray that you will be cleansed of all impurities.`,
    elaborationTamil: `நறுமணமிக்க மலர்களை அணிவித்தும், அறுசுவை உணவு படைத்தும், தானாகவே தோன்றிய மூர்த்தி என்றுபோற்றி வணங்கியும், தினம் தோறும் பூஜை செய்தும் அடைவதற்கு மிகப் பெரும் செல்வமாகிய இறைவனை யாரும் அறிந்து கொள்வது இல்லை. அதற்கு காரணம் உலகப் பற்றுக்களில் சிக்கி இறைவன் மேல் முழு பக்தி இல்லாமல் போவதே ஆகும். ஆகவே, உலக பற்றுக்களில் உள்ள ஆசைகளோடு மன உறுதியுடன் போர் புரிந்து அந்த ஆசைகளை பக்தியாக மாற்றி இறைவன் மேல் போகும் படி எண்ணங்களை வைத்து வந்தால் ஓரு காலத்தில் அந்த எண்ணங்களில் எந்தவிதமான மாசும் இல்லாமல் போகும். அப்போது சென்று அடைவதற்கு மிகப்பெரிய திசையாகிய முக்திக்கு செல்லுகின்ற வழியாக அதுவே ஆகி விடும்.`,
  },
  {
    id: 1843, tantraId: 7, verseNumber: 1842,
    tamil: `ஆவிக் கமலத்தில் அப்புறத்து இன்புற
மேவித் திரியும் விரிசடை நந்தியைக்
கூவிக் கருதிக் கொடுபோய்ச் சிவத்திடைத்
தாவிக்கு மந்திரம் தாமறி யாரே`,
    transliteration: `āvik kamalattil appuṟattu iṉpuṟa
mēvit tiriyum viricaṭai nantiyaik
kūvik karutik koṭupōyc civattiṭait
tāvikku mantiram tāmaṟi yārē`,
    english: `1842: Nandi is Within
Above the lotus of the heart, beyond
In Bliss abides,
Nandi of the spreading matted locks;
Yet they know not the mantra to muse and chant
That will to Him lead and there abide.`,
    elaborationEnglish: `Nandi of the spreading matted locks abides in bliss above the lotus of the heart. Yet many do not know to chant and muse on the mantra that will unite them to Him.`,
    elaborationTamil: `உயிர்களின் உயிர்ப்பு ஆற்றலாகிய சகஸ்ரதளத்தின் உச்சியில் இருக்கும் ஆயிரம் இதழ் கொண்ட தாமரை மலரினை சென்று சேரும்படி மூச்சுக்காற்றை கொண்டு சென்று அடைந்து, அதன் பயனால் அமிழ்தம் சுரந்து பேரின்பம் உருவாகும் பலனை அனைத்து உயிர்களும் அடைய வேண்டும் என்ற கருணையினால் அந்த தாமரை மலரின் மேல் பிரகாசமாக திகழும் ஜோதியாக வீற்றிருந்து அதிலிருந்து அனைத்திற்கும் பரவுகின்ற ஒளிக் கதிர்களைப் போன்ற விரிந்த சடையைக் கொண்ட குரு நாதனாகிய இறைவன் அமர்ந்து இருக்கின்றான். அந்த இறைவனை தாம் செய்கின்ற பூஜையின் மூலம் போற்றிப் புகழ்ந்து அழைத்தும், இறைவன் மேல் எண்ணங்களை வைத்தும், அந்த எண்ணங்களை கொண்டு போய் சகஸ்ரதளத்தில் ஜோதியாக வீற்றிருக்கும் இறைவனுடன் நிலை பெற்று இருக்கும் படி சேர்க்கின்ற மனதின் திறமைக்கு திறவு கோலாக இருப்பது எதுவென்று தாங்கள் அறியாமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 1844, tantraId: 7, verseNumber: 1843,
    tamil: `காண்ஆகத் துள்ளேஅழுந்திய மாணிக்கம்
காணும் அளவும் கருத்தறி வாரில்லை
பேணிப் பெருக்கிப் பெருக்கி நினைவோர்க்கு
மாணிக்க மாலை மனம்புகுந் தானே`,
    transliteration: `kāṇākat tuḷḷēaḻuntiya māṇikkam
kāṇum aḷavum karuttaṟi vārillai
pēṇip perukkip perukki niṉaivōrkku
māṇikka mālai maṉampukun tāṉē`,
    english: `1843: Lord is a Gem-Set Jewel
He is the gem that lies embedded in the cubit of the heart
Until they see Him, they think not of Him;
Into them who cherish and muse on Him over and over
As a gem-set Jewel He shines.`,
    elaborationEnglish: `He is the, gem that lies embedded in the cubit of the heart. They do not think of Him and:do not see Him. He, the gem-studded garland, enters into them who cherish and muse on Him over and over again.`,
  },
  {
    id: 1845, tantraId: 7, verseNumber: 1844,
    tamil: `பெருந்தன்மை நந்தி பிணங்கிருள் நேமி
இருந்தன்மை யாலும் என் நெஞ்சுஇடங் கொள்ள
வருந்தன்மை யாளனை வானவர் தேவர்
தருந்தன்மை யாளனைத் தாங்கிநின் றாரே`,
    transliteration: `peruntaṉmai nanti piṇaṅkiruḷ nēmi
iruntaṉmai yālum eṉ neñcuiṭaṅ koḷḷa
varuntaṉmai yāḷaṉai vāṉavar tēvar
taruntaṉmai yāḷaṉait tāṅkiniṉ ṟārē`,
    english: `1844: Nandi Dispels Darkness
Nandi of gracious qualities
Is the Chakra (discus) that cuts the Darkness (of impurities)
He takes his abiding seat in my heart,
While the Celestial Beings to whom He bestows His gifts
Come in prayer, beseeching Him from afar.`,
    elaborationEnglish: `While the Celestial Beings to whom He bestows His gifts Come in prayer, beseeching-Him from afar. Nandi is the discus that cuts inipurities asunder, The celestials . on whom He bestows Hi. gifts come from afar beseeching Him in prayer. But He tukes His abiding seat in the yogi’s heart.`,
  },
  {
    id: 1846, tantraId: 7, verseNumber: 1845,
    tamil: `சமைய மலசுத்தி தன்செயல் அற்றிடும்
அமையும் விசேடமும் ஆனமந் திரசுத்தி
சமையநிர் வாணம் கலாசுத்தி யாகும்
அமைமன்று ஞானம் ஆனார்க்கு அபிடேகமே`,
    transliteration: `camaiya malacutti taṉceyal aṟṟiṭum
amaiyum vicēṭamum āṉaman tiracutti
camaiyanir vāṇam kalācutti yākum
amaimaṉṟu ñāṉam āṉārkku apiṭēkamē`,
    english: `1845: The Four Dikshas or Ordination Rites
By Samaya Diksha, the Primal Malas their potency lose;
By Vishesha Diksha, the Mantra purification insures;
By Nirvana Diksha, the Kalas purification is effected;
The Abhisheka Diksha is for those
Who the Jnani State has attained.`,
    elaborationEnglish: `The primal malas lose their potency by Samaya diksha. The
purification of mantra chanting is ensued by Visesha diksha,
the purification of the kalas is effected by Nirvana diksha.
‘Abhisheka diksa is for those who have attained the state
of jnana.`,
  },
  {
    id: 1847, tantraId: 7, verseNumber: 1846,
    tamil: `ஊழிதோ றூழி உணர்ந்தவர்க்கு அல்லது
ஊழில் உயிரை உணரவும் தான்ஒட்டா
ஆழி அமரும் அரிஅயன் என்றுளோர்
ஊழி கடந்தும் ஓர்உச்சியு ளானே`,
    transliteration: `ūḻitō ṟūḻi uṇarntavarkku allatu
ūḻil uyirai uṇaravum tāṉoṭṭā
āḻi amarum ariayaṉ eṉṟuḷōr
ūḻi kaṭantum ōrucciyu ḷāṉē`,
    english: `1846: Seek Him Incessantly--He is Timeless Eternity
Unless they have adored Him through aeons and aeons
They will not have become the Jiva that is Karma devoid;
Hari on the sea, and Aya besides,
Seek Him through ages after ages;
Yet is He beyond reach;
He that shines atop of Time.`,
    elaborationEnglish: `Hari and Aya have been seeking Him through age after age. Still: He is‘beyond their reach. Unless, therefore, He is sought after through aeons and aeons, He who shines beyond time cannot be reached and karma will not be effaced.`,
    elaborationTamil: `பாற்கடலில் பள்ளி கொள்பவனாகிய திருமாலும், மற்றும் பிரமனும் எத்துணையோ யுகங்கள் வாழ்பவராயினும் சிவபெருமான் அவர்கட்கு எட்டாதவனாகவே யிருக்கின்றான். அதனால், அளவற்ற பிறவிகளில் அளவற்ற யுகங்களில் சிவனைப் பொது நீக்கியுணர்ந்து வழிபடுபவர்கட்கல்லது ஏனையோர்க்கு அவரது வினை அவனை அடைய ஒட்டாது.`,
  },
  {
    id: 1848, tantraId: 7, verseNumber: 1847,
    tamil: `ஆகின்ற நந்தி அடித்தா மரைபற்றிப்
போகின்றுபதேசம் பூசிக்கும் பூசையும்
ஆகின்ற ஆதாரம் ஆறாறு அதனின்மேல்
போகின்ற பொற்பையும் போற்றுவன் யானே`,
    transliteration: `ākiṉṟa nanti aṭittā maraipaṟṟip
pōkiṉṟupatēcam pūcikkum pūcaiyum
ākiṉṟa ātāram āṟāṟu ataṉiṉmēl
pōkiṉṟa poṟpaiyum pōṟṟuvaṉ yāṉē`,
    english: `1847: Nandi Imparts Upadesa
Grasping the lotus feet of Nandi that blesses me,
I shall relate the way of Upadesa, (imparting divine knowledge)
That to redemption leads;
Of Puja that is performed;
And of the Way to transcend Adharas six
And to ascend beyond.`,
    elaborationEnglish: `Tirumular proceeds to narrate about ‘upadesa’ that leads to liberation; and about performance of Guru worship that shows the way to the six adharas, and to ascend beyond.`,
    elaborationTamil: `எனக்கு இனி வேறொரு துணையின்றாகத் தாம் ஒருவரே துணையாய் நிற்கின்ற நந்தி பெருமானது திருவடிகளைப் பற்றி நின்றே உயிர்கள் பற்றி ஒழுகுதற்குரிய இறைநூல், அவற்றின்வழி இறைவனை வழிபடும் வழிபாடு, அகக்கோயில்களாகிய ஆதாரங்கள், முப்பத்தாறு தத்துவங்கள், அத்தத்துவங்களைக் கடந்து அவையனைத் திற்கும் மேலே செல்கின்ற தூய்மை ஆகிய இவைகளை நான் கருத்தாக உணர்ந்து, உலகர்க்கும் உரைப்பேனாயினேன்.`,
  },
  {
    id: 1849, tantraId: 7, verseNumber: 1848,
    tamil: `கானுறு கோடி கடிகமழ் சந்தனம்
வானுற மாமலர் இட்டு வணங்கினும்
ஊனினை நீக்கி உணர்பவர்க்கு அல்லது
தேனமர் புங்குழல் சேரஒண் ணாதே`,
    transliteration: `kāṉuṟu kōṭi kaṭikamaḻ cantaṉam
vāṉuṟa māmalar iṭṭu vaṇaṅkiṉum
ūṉiṉai nīkki uṇarpavarkku allatu
tēṉamar puṅkuḻal cēraoṇ ṇātē`,
    english: `1848: Rid Fleshly Desires and Know Him
With the sweet scented sandal
That in the forest recesses grows,
And with flowers rare
That heavenward blossom
You may adore Him;
But unless you know Him,
Your fleshly desires rid
You cannot reach His Feet
That are with honeyed flowers bedecked.`,
    elaborationEnglish: `No use in adoring him with sweet-scented sandals and rare
flowers which blossom heavenward. Unless one seeks him,
rid of bodily desires, his feet that are bedecked with honeyed
flowers, cannot be reached.`,
    elaborationTamil: `காட்டில் பொருந்தியுள்ள கோடிக் கணக்கான சந்தன மரங்களின் கட்டைகளைத் தேய்த்தெடுக்கப்பட்ட நறுமணம் கமழ்கின்ற சந்தனத்தையும், அதுபோலவே ஆகாயம் அளாவக் குவிக்கபப்ட்ட பெருமை மிக்க மலர்கலையும் பயன்படுத்திச் சிவனை வழிபட்டாலும் உடம்பைத் தம்மின் வேறாக உணர்ந்து அதன்கண் உள்ள பற்றை விடுத்துச் சிவனையே பற்றாக உணர்பவர்க்கல்லது ஏனையோர்க்கு அவனது, தேன் நிறைந்த செந்தாமரை மலர்போலும் திருவடியைச் சேர இயலாது.`,
  },
  {
    id: 1850, tantraId: 7, verseNumber: 1849,
    tamil: `மேவிய ஞானத்தின் மிக்கிடின் மெய்ப்பரன்
ஆவயின் ஞான நெறிநிற்றல் அர்ச்சனை
ஓவற உட்பூ சனைசெய்யில் உத்தமம்
சேவடி சேரல் செயலறல் தானே`,
    transliteration: `mēviya ñāṉattiṉ mikkiṭiṉ meypparaṉ
āvayiṉ ñāṉa neṟiniṟṟal arccaṉai
ōvaṟa uṭpū caṉaiceyyil uttamam
cēvaṭi cēral ceyalaṟal tāṉē`,
    english: `1849: Path of Jnana is Supreme Archana
When you excell in the Path of Jnana
That leads unto the Para Supreme,
The Path of Jnana is all Archana;
Great indeed is constant worship within;
To reach the Lord's Feet is to still actions all.`,
    elaborationEnglish: `Excelling in the path of jnana which leads to Para Supreme
is the greatest ‘archanai’, worship. Constant worshipping
within is indeed great. Reaching the Lord's Feet is to still
all. actions.`,
    elaborationTamil: `குருவருளால் கேள்வியாகப் பெற்ற ஞானத்தைப் பின் சிந்திதத்ல, தெளிதல் என்பவற்றின்பின் நிட்டையாக முதிரப் பெறின் அவ்விடத்தில் அந்த நிட்டையில் நிற்றலே பரசிவ பூசை யாகும். (ஆகவே அந்நிலையை அடைந்தவர்க்கு ஏனையோர்க்குக் கூறப்பட்ட சிவபூசைகள் வேண்டாவாம்) அந்நிலையை அடையாது கேள்வி முதலிய மூன்றில் நிற்போர்க்கு, ''உள்ளம் பெருங்கோயில்'' என்னும் மந்திரத்துட் கூறியவாறு செய்யும் ஞான பூசையே சாதனமும், அப்பூசையின் பயனாகத் தற்போதம் கழன்றிருத்தலே பயனும் ஆகும்.`,
  },
  {
    id: 1851, tantraId: 7, verseNumber: 1850,
    tamil: `உச்சியும் காலையும் மாலையும் ஈசனை
நச்சுமின் நச்சி நமவென்று நாமத்தை
விச்சிமின் விச்சு விரிசுடர் மூன்றினும்
நச்சுமின் பேர்நந்தி நாயகன் ஆகுமே`,
    transliteration: `ucciyum kālaiyum mālaiyum īcaṉai
naccumiṉ nacci namaveṉṟu nāmattai
viccimiṉ viccu viricuṭar mūṉṟiṉum
naccumiṉ pērnanti nāyakaṉ ākumē`,
    english: `1850: Pray Thrice a Day
Morn, noon and eventide
Adore the Lord;
Adoring chant the word "Nama"--(I worship)
Chanting, invoke Him in luminaries three--the Sun, Moon, and Fire;
The famed Nandi is the Lord Supreme.`,
    elaborationEnglish: `Let the devotee adore the Lord in the morning, at noon and in the evening. While adoring, let him chant ‘IT worship” (nama) and so invoke the Lord Supreme, that is in the sun, moon and fire.`,
    elaborationTamil: `உலகீர், 'காலை, நண்பகல், மாலை' - என்னும் மூன்று போதிலும் சிவனை வழிபட விரும்புங்கள். அவ்வழிபாட்டில் 'நம' என்பதை இறுதியில் உடைய மந்திரம் சிறப்புடையனவாகும் ஆதலால் அவற்றையே மிகுதியாக உங்கட்குப் பயனை விளைக்கும் வித்துக்களாக விதையுங்கள். அவ்வாறு விதைப்பதற்குரிய நிலமாய் விளங்குவன 'கதிர், மதி, தீ' - என்னும் முச்சுடர்களுமாம். (ஆகவே, அவ்விடத்து அவற்றை விதையுங்கள்) அச்சிவன் 'நந்தி' என்னும் பெயருடைய குருமூர்த்தியாயும் விளங்குவன்.`,
  },
  {
    id: 1852, tantraId: 7, verseNumber: 1851,
    tamil: `புண்ணிய மண்டலம் பூசைநூ றாகுமாம்
பண்ணிய மேனியும் பத்துநூ றாகுமாம்
எண்ணிலிக்கு ஐயம் இடில்கோடி யாகுமால்
பண்ணிடில் ஞானிஊண் பார்க்கில் விசேடமே`,
    transliteration: `puṇṇiya maṇṭalam pūcainū ṟākumām
paṇṇiya mēṉiyum pattunū ṟākumām
eṇṇilikku aiyam iṭilkōṭi yākumāl
paṇṇiṭil ñāṉiūṇ pārkkil vicēṭamē`,
    english: `1851: To Feed Jnani is to be Supremely Blessed
A hundred times blessed
Is to perform puja in places holy;
A ten hundred times blessed
Is to worship His Presence;
A hundred, hundred times blessed
Is to feed those their thoughts have stilled;
Blessed, blessed far indeed is to see
That a Jnani is to contentment fed.`,
    elaborationEnglish: `A hundred times blessed is it to perforrn puja in holy places. Ten hundred times blessed is it to worship His Presence. A hundred hundred times blessed is it to feed those who have stilled their thoughts. To see that a jnani is fed to contentment is indeed the most blessed of all.`,
  },
  {
    id: 1853, tantraId: 7, verseNumber: 1852,
    tamil: `இந்துவும் பானுவும் இலங்கும் தலத்திடை
வந்தித்த தெல்லாம் அசுரர்க்கு வாரியாம்
இந்துவும் பானுவும் இலங்காத் தலத்திடை
வந்தித்தல் நந்திக்கு மாபூசை யாமே`,
    transliteration: `intuvum pāṉuvum ilaṅkum talattiṭai
vantitta tellām acurarkku vāriyām
intuvum pāṉuvum ilaṅkāt talattiṭai
vantittal nantikku māpūcai yāmē`,
    english: `1852: Perform Pujas, Nadis Quelled
The Pujas that you perform
When Nadis, sun and moon, active beat
Are for Asuras meet;
The Pujas that you perform
When Nadis sun and moon are quelled
Are alone for Holy Nandi appropriate.`,
    elaborationEnglish: `The pujas performed when the sun and moon nadis are active go to the asuras. The appropriate pujas for holy Nandi are to be performed after quelling the sun and moon nadis (in the yogic way).`,
    elaborationTamil: `'சந்திர கலை' எனவும், 'சூரிய கலை' எனவும் சொல்லப்படுகின்ற இடநாடி மூச்சும், வலநாடி மூச்சுக் காற்று இயங்கின் மனம் புறத்தே ஓடுதலல்லது அகத்தே அடங்கி நில்லாது. ஆகவே, அது பொழுது செய்யும் வழிபாடு குற்றம் உடைத்தாம் ஆதலின், ''அஃது அசுரர்க்கு வாரியாம்'' என்றும், மூச்சுக்காற்று இயங்காது அடங்கின் மனமும் புறத்தே ஓடாது அகத்தே அடங்கி நிற்கும். ஆகவே, அதுபொழுது செய்யும் வழிபாடு குற்றமில்லாதாம் ஆதலின், ''அது நந்திக்கு மாபூசையாம்'' என்றும் கூறினார். சிவ பூசையே பெரிய பூசையாதல் பற்றி, ''மாபூசை'' என்றார். மூச்சுக் காற்றை மேற்கூறிய இருவழிகளிலும் செல்லாது அடக்குதலே பிராணாயாமமாம். அம்முறையால் பிராணனை அடக்கியவழி கும்பகமாம். அப்பொழுது மூச்சுக் காற்று நடுநாடியிற் செல்லும். அங்ஙனம் செல்லும்பொழுது தியானங்கள் இனிது கைகூடும். ''எந்நிலையில் நிற்போரும் 'வழிபாடு' என்பதை மேற்கொள்ளும்பொழுது பிராணாயாமம் செய்து செய்க'' என்றபடி. வாரி - வருவாய் அறவே விலக்குதற் பொருட்டு ''அசுரர்க்கு வாரியாம்'' என்றாரேனும், 'பயன் அற்பமாம்' என்றலே கருத்து என்க.`,
  },
  {
    id: 1854, tantraId: 7, verseNumber: 1853,
    tamil: `இந்துவும் பானுவும் என்றெழு கின்றதோர்
விந்துவும் நாதமும் ஆகிமீ தானத்தே
சிந்தனை சாக்கிரா தீதத்தே சென்றிட்டு
நந்தியைப் பூசிக்க நற்பூசை யாமே`,
    transliteration: `intuvum pāṉuvum eṉṟeḻu kiṉṟatōr
vintuvum nātamum ākimī tāṉattē
cintaṉai cākkirā tītattē ceṉṟiṭṭu
nantiyaip pūcikka naṟpūcai yāmē`,
    english: `1853: Worship Nandi Beyond the Spheres of Sun and Moon
When beyond the Spheres of Sun and Moon you ascend
There Bindu and Nada are;
Ascending (through Adharas) thus,
Your Awareness crosses
The frontiers of Waking State;
There when you continuous worship Nandi,
That verily is worship Divine.`,
    elaborationEnglish: `Bindu and nada are there, when prana ‘ascends beyond the
spheres of the sun and moon. Thus ascending through the
adharas, consciousness crosses the frontiers of the “waking
state.’ Worshipping Nandi there is verily divine worship.
DTM mhaEHT Mpwssrot comma)`,
    elaborationTamil: `சந்திர கலையும், சூரிய கலையுமாகச் சொல்லப் படுகின்ற மூச்சுக்காற்று அடக்கப்பட்டபொழுது நடுநாடி வழியாக மேல் ஏறி விந்துத்தானமாகிய ஆஞ்ஞையையும், நாதத்தானமாகிய ஏழாந்தானத்தையும் கடந்து அதற்குமேல் பிரம ரந்திரம் வழியாகப் பன்னிரண்டங்குல அளவுள்ள நிராதாரத்தே செல்லின் அந்நிலை 'சாக்கிரத்தில் துரியம்' எனப்படும். அதனையும் கடந்திருப்பது மீதானம். அது சாக்கிரத்தில் அதீதத்தானம். அந்நிலையில் சிந்தனையைச் செலுத்திச் சிவனை வழிபடுதலே எல்லாவற்றிலும் மேலான வழிபாடாம்.`,
  },
  {
    id: 1855, tantraId: 7, verseNumber: 1854,
    tamil: `மனபவ னங்களை மூலத்தான் மாற்றி
அனித உடல்பூத மாக்கி அகற்றிப்
புனிதன் அருள்தனில் புக்கிருந்து இன்பத்
தனியுறு பூசை சதாசிவற்கு ஆமே`,
    transliteration: `maṉapava ṉaṅkaḷai mūlattāṉ māṟṟi
aṉita uṭalpūta mākki akaṟṟip
puṉitaṉ aruḷtaṉil pukkiruntu iṉpat
taṉiyuṟu pūcai catācivaṟku āmē`,
    english: `1854: Cross the Gates of Awareness and Tattvas
Course the Sakti Kundalini,
Transcend the successive gates of Awareness;
Reduce the perishable body to its elemental (tattva) constituents
And then discard them;
Then do you enter the Grace of the Holy One
And there you abide and adore
That indeed is the worship meet for Sadasiva.`,
    elaborationEnglish: `Let Kundalini sakti be coursed transcending the successive gates of consciousness. Let the body be reduced to its tattva constituents and then discarded. Then does the yogi enter the Grace of the Holy One and abide in Him. That indeed ig worship appropriate to Sadasiva.`,
    elaborationTamil: `மனத்தின் ஓட்டத்திற்குக் காரணமாயுள்ள இட ஓட்ட வல ஓட்ட மூச்சுக் காற்றுக்களை அவ்வழியே ஓட விடாது தடுத்து நடு நாடி வழியாக ஓடும்படி மாற்றி, பூத காரியமாய் நின்று அழிகின்ற உடலை அவ்வாறு அழியாது நிலைத்திருக்கின்ற உடலாகச் செய்தற் பொருட்டு அதன் காரணமாகிய பூதங்களில் ஒடுக்கி அவையாகச் செய்யுமாற்றால் போக்கி, மீண்டு அது திருவருளினின்றும் தோன்றச் செய்யுமாற்றால் திருவருள் உடம்பாக ஆக்கி அதனுள் தான் புகுந்து சிவமாகி அதனானே சிவானந்தம் மேலிட நின்ற வழிபடும் வழிபாடே ஒப்பற்ற வழிபாடாகும். அதனையே சதாசிவ மூர்த்தி ஏற்பர்.`,
  },
  {
    id: 1856, tantraId: 7, verseNumber: 1855,
    tamil: `பகலும் இரவும் பயில்கின்ற பூசை
இயல்புடை ஈசர்க்கு இணைமல ராகப்
பகலும் இரவும் பயிலாத பூசை
சகலமும் தான்கொள்வன் தாழ்சடை யோனே`,
    transliteration: `pakalum iravum payilkiṉṟa pūcai
iyalpuṭai īcarkku iṇaimala rākap
pakalum iravum payilāta pūcai
cakalamum tāṉkoḷvaṉ tāḻcaṭai yōṉē`,
    english: `1855: Practise Worship where neither Night nor Day is
The worship that you perform
By day and night
Is to the Lord an offering of flower twain;
The worship that you perform
Where neither day nor night is
Is to Him of the flowing matted locks
Acceptance full and replete indeed.`,
    elaborationEnglish: `In worship, two flowers are offered to the Lord — once at day and another at night. He of the matted locks accepts the worship in the sphere where there is neither night nor day.`,
    elaborationTamil: `பகலும், இரவும் ஆகிய கால வேறுபாடுகள் தோன்றுகின்ற பூசைகள் காலத்தைக் கடந்தவனாகிய சிவனுக்கு முற்றிலும் நேர்படும் பூசைகள் ஆகா. மற்று, அவ்வேறுபாடு தோன்றாத பூசைகளையே சிவன் முழுமையாக ஏற்பான்.`,
  },
  {
    id: 1857, tantraId: 7, verseNumber: 1856,
    tamil: `இராப்பகல் அற்ற இடத்தே இருந்து
பராக்குஅற ஆனந்தத் தேறல் பருகி
இராப்பகல் அற்ற இறையடி இன்பத்து
இராப்பகல் மாயை இரண்டுஇடத் தேனே`,
    transliteration: `irāppakal aṟṟa iṭattē iruntu
parākkuaṟa āṉantat tēṟal paruki
irāppakal aṟṟa iṟaiyaṭi iṉpattu
irāppakal māyai iraṇṭuiṭat tēṉē`,
    english: `1856: Where Neither Day Nor Night is, there No Maya is
Seated in the sphere where neither day nor night is
The supreme honeyed bliss I imbibed;
Lost in thought to events outside
At the holy Feet of Lord
Where neither day nor night is,
I dispelled the Maya twain,
That with day and night compare.`,
    elaborationEnglish: `Sitting in the sphere where there is neither day nor night,
the yogi imbibes the supreme honeyed bliss. At the Holy Feet
of the Lord that yogi is lost in thought to outside events,
dispelled of the maya that creates the distinction of night
and day`,
    elaborationTamil: `இரவும், பகலும் ஆகிய கால வேறுபாடுகள் தோன்றாத ஆழ்ந்த தியான நிலையேயிருந்து, அதனால் விளைகின்ற சிவானந்தமாகி தேனை வேறுநினைவின்றிப் பருகினமையால், இரவும், பகலும் ஆகிய கால வேறுபாடுகள் இல்லாத இறைவனது திருவடியின்பத்தில் திளைத்து, மேற்கூறிய வேறுபாடுகளையுடைய காலமாகிய மாயா காரியம் இரண்டினையும் யான் போக்கிவிட்டேன்.`,
  },
  {
    id: 1858, tantraId: 7, verseNumber: 1857,
    tamil: `படமாடக் கோயில் பகவற்குஒன்று ஈயில்
நடமாடக் கோயில் நம்பர்க்கு அங்கு ஆகா
நடமாடக் கோயில் நம்பர்க்கு ஒன்று ஈயில்
படமாடக் கோயில் பகவற்கு அது ஆமே`,
    transliteration: `paṭamāṭak kōyil pakavaṟkuoṉṟu īyil
naṭamāṭak kōyil namparkku aṅku ākā
naṭamāṭak kōyil namparkku oṉṟu īyil
paṭamāṭak kōyil pakavaṟku atu āmē`,
    english: `1857: Devotees are Walking Temples
The offering you give
To the Lord in the temple steepled high
Reaches not His devotees,
Who the walking temples noble are;
When you offer things
To the walking temples noble,
That sure reaches the Lord
In the temple steepled high.`,
    elaborationEnglish: `The offerings given to the Lord in tht high-towered temple do not reach His devotees. But the things offered to the devotees, who are the walking temples, surely reach the Lord within the high-towered temple.`,
    elaborationTamil: `கொடித் துகில் ஆடுகின்ற இயங்காக் கோயிலினுள் எழுந்தருளியிருக்கும் சிவனுக்கு ஒரு பொருளை ஏற்பித்தால் அஃது எங்கும் இயங்குகின்ற உடம்பாகிய கோயிலினுள் எழுந்தருளி யிருக்கின்ற சிவனுக்குச் சேரமாட்டாது; அங்கேயே இருந்துவிடும். ஆனால், எங்கும் இயங்கும் உடம்பாகிய கோயிலினுள் எழுந்தருளி யிருக்கும் சிவனுக்கு ஒரு பொருளை ஏற்பித்தால் அஃது அந்தச் சிவனுக்கு ஆதலுடன், கொடித்துகில் ஆடுகின்ற இயங்காக் கோயிலினுள் எழுந்தருளியிருக்கின்ற சிவனுக்கும் போய்ச் சேர்வதாகும்.`,
  },
  {
    id: 1859, tantraId: 7, verseNumber: 1858,
    tamil: `தண்டுஅறு சிந்தை தபோதனார் தாம்மகிழ்ந்து
உண்டது மூன்று புவனமும் உண்டது
கொண்டது மூன்று புவனமும் கொண்டதுஎன்று
எண்திசை நந்தி எடுத்துரைத் தானே`,
    transliteration: `taṇṭuaṟu cintai tapōtaṉār tāmmakiḻntu
uṇṭatu mūṉṟu puvaṉamum uṇṭatu
koṇṭatu mūṉṟu puvaṉamum koṇṭatueṉṟu
eṇticai nanti eṭutturait tāṉē`,
    english: `1858: Feed Tapasvins, Feed All Worlds
The food, Tapasvins of blemishless thought took
Is food, all three worlds took;
The offerings they cheerfully received
Are offerings the three worlds received;
--Thus He proclaimed, Nandi the Great.`,
    elaborationEnglish: `The great Nandi has proclaimed that the offerings received
by the tapasvins of blemishless thought are offerings received
by the Three Worlds.`,
    elaborationTamil: `'சிவனிடத்தினின்று பிறிதொன்றால் நீக்கப்படாத உள்ளத்தினையுடைய மாகேசுரர்கள் மனமகிழ்ந்து உண்ட பொருள் மூன்றுலகங்களும் உண்ட பொருளாகும்; (அவற்றிற்கு அது பயனாகும்' என்பதாம்) அதுபோலவே அவர்கள் பெற்றுக்கொண்ட பொருளும் மூன்றுலகங்களும் பெற்றுக்கொண்ட பொருளாம், என்று நந்தி பெருமான் எங்கட்குச் சிறந்தெடுத்துக் கூறினார்.`,
  },
  {
    id: 1860, tantraId: 7, verseNumber: 1859,
    tamil: `மாத்திரை ஒன்றினில் மன்னி அமர்ந்துறை
ஆத்தனுக்கு ஈந்த அரும்பொரு ளானது
மூர்த்திகள் மூவர்க்கும் மூவேழ் குரவர்க்கும்
தீர்த்தம தாம்அது தேர்ந்துகொள் வீரே`,
    transliteration: `māttirai oṉṟiṉil maṉṉi amarntuṟai
āttaṉukku īnta arumporu ḷāṉatu
mūrttikaḷ mūvarkkum mūvēḻ kuravarkkum
tīrttama tāmatu tērntukoḷ vīrē`,
    english: `1859: Offering to Tapasvins is Oblation to Gods and Ancestors
The things you gave His dear devotee,
Who in Him is seated,
Are verily oblations meet for the Gods Three;
And for ancestors too,
Through generations three times seven;
This for certain shall you know.`,
    elaborationEnglish: `Know that the offerings given.to the dear devotees of the
Lord, who are seated in Him, are oblations offered to the
three Gods and to the giver’s ancestors for twenty-one
generations.`,
    elaborationTamil: `இப்பாடலின் பொருள் பின்வரும் குறிப்புரையால் இனிது விளங்கும்.`,
  },
  {
    id: 1861, tantraId: 7, verseNumber: 1860,
    tamil: `அகரம் ஆயிரம் அந்தணர்க்கு ஈயில் என்
சிகரம் ஆயிரம் செய்து முடிக்கில்என்
பகரு ஞானி பகல்ஊண் பலத்துக்கு
நிகரில்லை என்பது நிச்சயம் தானே`,
    transliteration: `akaram āyiram antaṇarkku īyil eṉ
cikaram āyiram ceytu muṭikkileṉ
pakaru ñāṉi pakalūṇ palattukku
nikarillai eṉpatu niccayam tāṉē`,
    english: `1860: Feeding the Tapasvin is superior to feeding Brahmins
Though you a thousand temples for the gods build;
None, none is of merit compare
To a day's feed to a holy devotee given;
This be of certain.`,
    elaborationEnglish: `Neither the building of a thousand free habitations for brahmins, nor feeding sumptuously a hundred thousand brahmins, nor erecting a thousand temples to the Gods — none of these is of efficacy equal to a day's feeding of a holy devotee who wears the holy ashes.`,
    elaborationTamil: `அந்தணர் வாழும் வீதிகள் பலவற்றை அவர்கட்குத் தானம் செய்தலும், அவ்வீதிகளில் அவர்கட்கு உயர்ந்த மாட மாளிகைகள் பல கட்டித் தருதலும் ஆகிய இவற்றால் விளையும் பயன்கள் யாவும் மாகேசுரன் ஒருவனை வழிபட அவன் உண்டதனால் விளையும் பயனளவிற்கு ஒவ்வாது குறைவனவே என்பது உறுதி.`,
  },
  {
    id: 1862, tantraId: 7, verseNumber: 1861,
    tamil: `ஆறிடும் வேள்வி அருமறை நூலவர்
கூறிடும் அந்தணர் கோடிபேர் உண்பதில்
நீறிடும் தொண்டர் நினைவின் பயனிலை
பேறெனில் ஓர்பிடி பேறது வாகுமே`,
    transliteration: `āṟiṭum vēḷvi arumaṟai nūlavar
kūṟiṭum antaṇar kōṭipēr uṇpatil
nīṟiṭum toṇṭar niṉaiviṉ payaṉilai
pēṟeṉil ōrpiṭi pēṟatu vākumē`,
    english: `1861: Even the Thought of Feeding Siva Jnanis is most
Efficacious
Well may you feed a hundred hundred thousand Brahmins
That the holy thread wear and goodly sacrifices perform;
But holier far is the desire to feed in endearment great
A morsel albeit, to
The Lord's devotee true
Who the holy ashes wears.`,
    elaborationTamil: `ஆறு அங்கங்களால் தெளிய உணர்த்தப்படும் வேள்விகளைச் செய்கின்றவரும், வேதமாகிய நூலை ஓதுகின்றவரும், முப்புரிநூல் அணிபவரும் ஆகிய அந்தணர்கள் கோடிபேர் உண்டு மகிழ் வதனால் உண்டாகின்ற பயனோடு திருநீற்றை யணிகின்ற சிவ னடியார் சிலர் உண்டு மகிழும் மகிழ்ச்சியால் விளைந்து நிலைக்கின்ற பயனை வைத்து எண்ணிப் பார்க்குமிடத்து, முன்னர்க் கூறிய பயன் பின்னர்க் கூறிய உணவில் ஒரு பிடியினால் விளையும் பயனளவேயாகும்.`,
  },
  {
    id: 1863, tantraId: 7, verseNumber: 1862,
    tamil: `ஏறுடை யாய்இறை வாஎம்பி ரான்என்று
நீறிடு வார்அடி யார்நிகழ் தேவர்கள்
ஆறணி செஞ்சடை அண்ணல் இவர்என்று
வேறுஅணி வார்க்கு வினையில்லை தானே`,
    transliteration: `ēṟuṭai yāyiṟai vāempi rāṉeṉṟu
nīṟiṭu vāraṭi yārnikaḻ tēvarkaḷ
āṟaṇi ceñcaṭai aṇṇal ivareṉṟu
vēṟuaṇi vārkku viṉaiyillai tāṉē`,
    english: `1862: Siva Jnanis are Gods on Earth
"You, the Divine Bull ride,
My Lord, My God"
--Those who wear the holy ashes saying thus;
Verily are unto Devas on earth;
They that worship them as the Lord Himself,
--Who the Ganga on His russet matted locks wears,
Will have their Karmas end consummated.`,
    elaborationEnglish: `Those who wear the holy ashes and pray to Him in intense devotion are really celestials on earth. Those who worship such holy men as Lord Siva Himself, who sports the Ganga on His russet-matted locks, will reach the end of their karmas.`,
    elaborationTamil: `'இடபத்தை ஊர்தியாகவும், கொடியாகவும் உடையவனே! இறைவா! எங்கள் பெருமானே' என்று சிவனை எப் பொழுதும் துதித்து அவனது அருள் வடிவாகிய திருநீற்றை அன்புடன் அணிகின்றவர்கள் அவனுக்கு அடியராவார்கள், அவர்களை 'இவர்களே நிலவுலகில் காணப்படுகின்ற தேவர்கள்' என்றும், 'சிவபெருமான்' என்றும் கருதி அவரை மக்களின் வேறாக வைத்து வழிபடுகின்றவர்கட்கு அவரால் முன்பு செய்யப்பட்டுக் குவிந்து கிடக்கின்ற வினைகள் கெட்டொழிதல் உறுதி.`,
  },
  {
    id: 1864, tantraId: 7, verseNumber: 1863,
    tamil: `சீர்நந்தி கொண்டு திருமுக மாய்விட்ட
பேர்நந்தி என்னும் பிறங்கு சடையனை
நான்நொந்து நொந்து வருமளவுஞ் சொல்லப்
பேர்நந்தி என்னும் பிதற்குஒழி யேனே`,
    transliteration: `cīrnanti koṇṭu tirumuka māyviṭṭa
pērnanti eṉṉum piṟaṅku caṭaiyaṉai
nāṉnontu nontu varumaḷavuñ collap
pērnanti eṉṉum pitaṟkuoḻi yēṉē`,
    english: `1863: Call Nandi until He Appears
Of resplendent beauty is His Face
Of glowing sheen is His matted locks
He the Nandi famed;
In intense anguish I call His Name
And until He appears before me
I shall not cease to clamour, "My Nandi! My Nandi!"`,
    elaborationEnglish: `The famed Nandi’s face is of resplendent beauty and His matted locks of shining glow. The yogi calls His Name in intense anquish. He shall not stop to clamour for and to hail © Nandi until He appears before him.`,
  },
  {
    id: 1865, tantraId: 7, verseNumber: 1864,
    tamil: `அழிதகவு இல்லா அரன்அடி யாரைத்
தொழுகை ஞாலத்துத் தூங்கிருள் நீங்கும்
பழுது படாவண்ணம் பண்பனை நாடித்
தொழுதெழ வையகத்து ஓர்இன்பம் ஆமே`,
    transliteration: `aḻitakavu illā araṉaṭi yārait
toḻukai ñālattut tūṅkiruḷ nīṅkum
paḻutu paṭāvaṇṇam paṇpaṉai nāṭit
toḻuteḻa vaiyakattu ōriṉpam āmē`,
    english: `1864: Worship Siva's Devotee and the World will Rejoice
In this world worship
Siva's devotees, who no death know;
The hanging darkness of ignorance forever disappears.
Unfailing seek the devotee pure
And your obeisance make;
Of a certain will the world rejoice.`,
    elaborationEnglish: `Let the yogi worship Siva’s devotees who knows no death.
The vestigial ignorance in him will then disappear once and
for all. So seek the pure devotees without fail and make
obeisance to them. It will result in the rejoicing of the world.`,
    elaborationTamil: `இறைமைக் குணங்களையுடைய சிவபெரு மானை விரும்பி அவனை நாள்தோறும் தொழுது துயிலெழுதலை மட்டும் செய்தால், இவ்வுலகத்தில் உலகின்பத்தோடு சிறிது இறையின்பமும் உண்டாகும். ஆனால், தம் நிலையில் கெடுதல் இல்லாத மாகேசுரரை வழிபடுதலால், இவ்வுலகத்தில் நீங்குதற்கரிய அஞ்ஞானம் நீங்கி இறையின்பமே மிகக் கிடைக்கும்.`,
  },
  {
    id: 1866, tantraId: 7, verseNumber: 1865,
    tamil: `பகவற்குஏதா கிலும் பண்பில ராகிப்
புகுமத்த ராய்நின்று பூசனை செய்யும்
முகமத்தோடு ஒத்துநின்று ஊழிதோ றூழி
அகமத்த ராகிநின்று ஆய்ந்தொழிந் தா ரே`,
    transliteration: `pakavaṟkuētā kilum paṇpila rākip
pukumatta rāyniṉṟu pūcaṉai ceyyum
mukamattōṭu ottuniṉṟu ūḻitō ṟūḻi
akamatta rākiniṉṟu āyntoḻin tā rē`,
    english: `1865: Worship without Love for Siva Jnanis Leads Nowhere
With endearment none for holy ones
With pride brimming to full
They Pujas perform;
Thus through ages and ages they tried and perished,
Their faces turned unto agitating churns hard,
Their hearts with egoity extreme filled.`,
    elaborationEnglish: `They who perform pujas with brimming pride, with no endearment to holy ones, with hearts filled in extreme’ egoity — though such pujas are performed by them for ages and ages — in the end they only perish.`,
    elaborationTamil: `சிலர் மாகேசுரரிடத்துச் சிறிதளவும் அன்பில்லா தவராய் மாகேசுரனிடத்துச் சரண் புகுகின்ற பித்துக் கொள்ளிகளாய் அவனை மட்டும் பூசித்தலாகிய அந்த வழியிலே நெடுங்காலம் நின்று, அவனது அருள் மிகக் கிடையாத காரணம் யாதென்று ஆராய்ந்து, முடிபு காணாது இளைத்து விட்டார்கள்.`,
  },
  {
    id: 1867, tantraId: 7, verseNumber: 1866,
    tamil: `வித்தக மாகிய வேடத்தர் உண்டஊன்
அத்தன் அயன்மால் அருந்திய வண்ணமாம்
சித்தம் தெளிந்தவர் சேடம் பருகிடின்
முத்தியாம் என்றுநம் மூலன் மொழிந்ததே`,
    transliteration: `vittaka mākiya vēṭattar uṇṭaūṉ
attaṉ ayaṉmāl aruntiya vaṇṇamām
cittam teḷintavar cēṭam parukiṭiṉ
muttiyām eṉṟunam mūlaṉ moḻintatē`,
    english: `1866: Food for Holy Men is Food for Gods
The food the holy men partake
Is verily food for the gods,
Siva, Vishnu and Brahma;
To partake of the leavings
Of holy men that have realized Truth
Is the way sure to Mukti;
--Thus affirms our Mula in meaning unmistakable.`,
    elaborationEnglish: `In unmistakable words Mular has affirmed that the food partaken by the-holy men is the food for the Gods and that the sure way to attain mukti is to partake unhesitatingly, of the leavings of the holy, men who have realised the Truth.`,
  },
  {
    id: 1868, tantraId: 7, verseNumber: 1867,
    tamil: `தாழ்விலர் பின்னும் முயல்வர் அருந்தவம்
ஆழ்வினை ஆழ அவர்க்கே அறஞ்செய்யும்
ஆழ்வினை நீக்கி அருவினை தன்னொடும்
போழ்வினை தீர்க்கும் அப் பொன்னுலகு ஆமே`,
    transliteration: `tāḻvilar piṉṉum muyalvar aruntavam
āḻviṉai āḻa avarkkē aṟañceyyum
āḻviṉai nīkki aruviṉai taṉṉoṭum
pōḻviṉai tīrkkum ap poṉṉulaku āmē`,
    english: `1867: Give to the Holy Ones and Reach the Golden Land
Depressed are they not;
In holy Tapas they persevere still;
To them give
Your Karmas away to hasten;
You shall that Golden Land reach,
Where Karmas three, past, present and future, exist none.`,
    elaborationEnglish: `They who persevere in silent tapas are great. He who gives them food chases away his karmas. He will then reach the golden land where the karmas past, present and future are forever blotted out. °

1) The three’ karmas are: i) sanchita (stored up); ii) prarabdha (already bearing fruit); agami (prospective).`,
    elaborationTamil: `உலகீர், பின்னும், பின்னும் நீர் மிக அழுந்த வருகின்ற எதிர் வினைகள் தோன்றாமல் ஆழ்ந்தே போகும்படி, பாசக் கட்டாகிய இழிநிலையினின்றும் நீங்கி உயர்நிலையை எய்தினா ராயினும், மீட்டும் அந்த இழிநிலையில் பாசங்கள் வந்து வீழ்த்தாதபடி முன்பு செய்துபோந்த அந்தச் சரியை முதலிய அரிய தவங்களைப் பின்னும் மாகேசுரர் விடாது செய்வர். அத்தகையோர்க்கே நீவிர் தானத்தையும், தருமத்தையும் செய்யுங்கள். அவ்வாறு செய்தால் அச்செயல்கள் உங்களுடைய எதிர்வினை, பழவினை, பயன்வினை என்னும் மூவகை வினைகளையும் அறவே அழிக்கும். அவ்வினைகள் அழியவே, மீளப் பந்த உலகில் வரும் பிறப்பு இன்றி, வீட்டுலகமே`,
  },
  {
    id: 1869, tantraId: 7, verseNumber: 1868,
    tamil: `திகைக்குரி யானொரு தேவனை நாடும்
வகைக்குரி யானொரு வாது இருக்கில்
பகைக்குரி யாரில்லைப் பார்மழை பெய்யும்
அகக்குறை கேடில்லை அவ்வுல குக்கே`,
    transliteration: `tikaikkuri yāṉoru tēvaṉai nāṭum
vakaikkuri yāṉoru vātu irukkil
pakaikkuri yārillaip pārmaḻai peyyum
akakkuṟai kēṭillai avvula kukkē`,
    english: `1868: That Land Prospers where Holy Men are
Where there is a holy man of divine worth
Who pursues the Lord,
--That all space embraces--
There enemies none are;
Rains in abundance fall;
Full the people’s contentment
Evil none befalls that land.`,
    elaborationEnglish: `Where holy men are, there no enemies are; rains fall in abundance; contentment marks the people’s way of life. No evil befalls that land.`,
    elaborationTamil: `'இடம்' என்று சொல்லப்படுவன எவையாயினும் அவை எல்லாவற்றையும் தனது உடைமையாக உடைய ஒப்பற்ற ஒரு தனிமுதற் கடவுளை உணருமாறெல்லாம் உணர்ந்து, அவ்வுணர்வினை மயக்கத்தால் குறைத்துப் பேசுபவரது மயக்கத்தை தனது அனுபவ மொழிகளாற் போக்குகின்ற சீரடியான் ஒருவனே ஒரு நாட்டில் இருப்பினும் அந்த நாட்டின்மேல் பகைமை கொள்வார் எவரும் இலராவர். அங்குப் பருவமழை பொய்யாது பெய்யும். எந்த ஓர் இல்லத்திலும் செல்வம் குறைதலோ, அல்லது செல்வம் தீர்ந்து வறுமை உண்டாதலோ நிகழாது.`,
  },
  {
    id: 1870, tantraId: 7, verseNumber: 1869,
    tamil: `அவ்வுல கத்தே பிறந்துஅவ் உடலோணடும்
அவ்வுல கத்தே அருந்தவம் நாடுவர்
அவ்வுல கத்தே அரனடி கூடுவர்
அவ்வுல கத்தே அருள்பெறு வாரே`,
    transliteration: `avvula kattē piṟantuav uṭalōṇaṭum
avvula kattē aruntavam nāṭuvar
avvula kattē araṉaṭi kūṭuvar
avvula kattē aruḷpeṟu vārē`,
    english: `1869: The Land of the Holy
There in that Land are they born;
There in that Land in that body they Tapas perform;
There in that Land they reach the Feet of Lord
There in that Land will they His Grace receive.`,
    elaborationEnglish: `In such a holy land, men perform tapas and reach the Feet of the Lord and receive His Grace.`,
  },
  {
    id: 1871, tantraId: 7, verseNumber: 1870,
    tamil: `கொண்ட குறியும் குலவரை உச்சியும்
அண்டரும் அண்டத்து அமரரும் ஆதியும்
எண்டிசை யோரும்வந்து என்கைத் தலத்தினுள்
உண்டெனில் நாம்இனி உய்ந்தொழிந் தோமே`,
    transliteration: `koṇṭa kuṟiyum kulavarai ucciyum
aṇṭarum aṇṭattu amararum ātiyum
eṇṭicai yōrumvantu eṉkait talattiṉuḷ
uṇṭeṉil nāmiṉi uyntoḻin tōmē`,
    english: `1870: I am Redeemed when I reach the Goal of Union in Siva
The goal I sought (of union in Siva)
The peaks of mountain high in there, (Sahasrara)
The denizens of heavens,
The immortals celestial,
The hordes of humans from quarters eight
And the Primal One, too,
--If toward me they come,
And in my hands I hold them,
Redeemed am I, forever and ever.`,
    elaborationEnglish: `“The ‘yogi will be redeemed forever, when he reaches the goal of union with Siva, whom he seeks in the sahasrara. Then do the celestials, the holy men from the eight quarters of space, and the Primal One too come to him.`,
    elaborationTamil: `நிலத்தைத் தன்னகத்துக் கொண்ட கடல்களும், நிலத்தை நிலைபெறுத்துகின்ற எட்டுக் குலமலைகளின் சிகரங்களும், வானுலகமும், வானுலகத்திலுள்ள தேவர்களும், அத்தேவர்களுக்கு முதல்வனாகிய இந்திரனும் மற்றும் திசைக்காவலரும் ஆகிய அனைத்தும், அனைவரும் வந்து எனது கையிலும் அடங்கியுள்ளன, உள்ளனர் என்றால், இனி நாங்கள் எந்த இடர்ப்பாட்டிலும் அகப்படாமல் அவற்றினின்றும் தப்பிவிட்டோமன்றோ!`,
  },
  {
    id: 1872, tantraId: 7, verseNumber: 1871,
    tamil: `அண்டங்கள் ஏழும் அகண்டமும் ஆவியும்
கொண்ட சராசரம் முற்றும் குணங்களும்
பண்டை மறையும் படைப்பளிப்பு ஆதியும்
கண்டசிவனும்என் கண்ணன்றி இல்லையே`,
    transliteration: `aṇṭaṅkaḷ ēḻum akaṇṭamum āviyum
koṇṭa carācaram muṟṟum kuṇaṅkaḷum
paṇṭai maṟaiyum paṭaippaḷippu ātiyum
kaṇṭacivaṉumeṉ kaṇṇaṉṟi illaiyē`,
    english: `1871: Then I engross All Creation
The universes seven,
The cosmic space beyond,
The life--animate and inanimate--
The gunas three,
The Vedas ancient,
The Gods that create and preserve
And their Primal Lord that is Siva
--All they are but in me.`,
    elaborationEnglish: `The seven universes, the cosmic space beyond them, the
animate and inanimate lives, the three gunas, the ancient
Vedas, the Gods of creation and preservation and their Primal
Lord Siva — are all in the yogi himself.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 1873, tantraId: 7, verseNumber: 1872,
    tamil: `பெண்ணல்ல ஆணல்ல பேடல்ல மூடத்துள்
உள்நின்ற சோதி ஒருவர்க்கு அறியொணாக்
கண்ணின்றிக் காணும் செவியின்றிக் கேட்டிரும்
அண்ணல் பெருமையை ஆய்ந்தது மூப்பே`,
    transliteration: `peṇṇalla āṇalla pēṭalla mūṭattuḷ
uḷniṉṟa cōti oruvarkku aṟiyoṇāk
kaṇṇiṉṟik kāṇum ceviyiṉṟik kēṭṭirum
aṇṇal perumaiyai āyntatu mūppē`,
    english: `1872: Lord Can be seen only with Inner Light
Neither male, nor female, nor hermaphrodite,
The light that is within ignorance concealed
Never, never can cognise Him;
Without eyes He sees,
Without ears He hears,
Only those in Knowledge ripe
Have for sure, seen Him.`,
    elaborationEnglish: `The Lord is neither male, nor female, nor hermaphrodite. He sees without eyes. He hears without ears. The ignorant cannot cognize Him. Only those of ripe knowledge have surely seen Him.`,
    elaborationTamil: `இயல்பாகவே அறியாமையில் மூழ்கி அதுவாய் நிற்கின்ற உயிர்களுள் ஒவ்வொன்றின் அறிவினுள்ளும் நிற்கின்ற அறி வாயுள்ளவனும், ஒருவராலும் அறிய இயலாதவனும் கண்ணில்லாமலே காண்கின்றவனும், செவியில்லாமலே கேட்பவனும் ஆகிய சிவன் உலகில் காணப்படும் 'ஆண், பெண், அலி' என்னும் மூவகைப் பொருள்களுள் ஒருவகையினுள்ளும் படாது அவற்றின் வேறாய்த் தனித்து நிற்பவன். ஒருவராலும் அறியப்படாத அவனது அப் பெருந்தன்மையை அறிந்த அறிவே பேரறிவாகும்.`,
  },
  {
    id: 1874, tantraId: 7, verseNumber: 1873,
    tamil: `இயங்கும் உலகினில் ஈசன் அடியார்
மயங்கா வழிசெல்வர் வானுலகு ஆள்வர்
புயங்களும் எண்டிசை போதுபா தாள
மயங்காப் பகிரண்ட மாமுடி தானே`,
    transliteration: `iyaṅkum ulakiṉil īcaṉ aṭiyār
mayaṅkā vaḻicelvar vāṉulaku āḷvar
puyaṅkaḷum eṇṭicai pōtupā tāḷa
mayaṅkāp pakiraṇṭa māmuṭi tāṉē`,
    english: `1873: Lord's Devotees Rule the High Heavens
In the world existent
The Lord's devotees pursue the sure path;
They will rule in the heavens high;
They Siva become;
Whose arms stretch embracing directions eight;
In the nether world are His Feet;
In the peaks of the cosmic universe,
The Crown of His Head rises.`,
    elaborationEnglish: `The devotees of the Lord pursue the sure path in this world.
In the heavens above they will rule. They become Siva whose
eight arms embrace the eight directions, whose Feet are in
the depths of the nether world and whose crown is in the
peaks of the cosmic unjverse.`,
    elaborationTamil: `சிவனடியார்கள் பிறரைப் போலவே தாமும் மயக்க உலகத்தில் வாழ்வராயினும் அவ்வுலகம் மயக்குகின்ற மயக்கத்துட் படாது தெளிந்த உணர்வோடே வாழ்வர். உடம்பு நீங்கிய பின்னும் பிறரைப் போல மயக்க உலகங்களில் உழலாமல் சிவன் உலகத்தை அடைந்து அதன்கண் சில புவனங்கட்குத் தலைவராயும் விளங்குவர். அவையேயன்றித் தாமும் சிவனைப் போலவே எல்லா உலகங்களும் தம்முள் வியாப்பியமாய் அடங்கத் தாம் அவற்றைத் தம்முள் அடக்கி வியாபகமாயும் நிற்பர்.`,
  },
  {
    id: 1875, tantraId: 7, verseNumber: 1874,
    tamil: `அகம்படி கின்றநம் ஐயனை ஒரும்
அகம்படி கண்டவர் அல்லலில் சேரார்
அகம்படி உட்புக்கு அறிகின்ற நெஞ்சம்
அகம்படி கண்டுஆம் அழிக்கலும் எட்டே`,
    transliteration: `akampaṭi kiṉṟanam aiyaṉai orum
akampaṭi kaṇṭavar allalil cērār
akampaṭi uṭpukku aṟikiṉṟa neñcam
akampaṭi kaṇṭuām aḻikkalum eṭṭē`,
    english: `1874: Muse on the Lord and Know no Sorrow
Muse on the Lord;
He resides in your heart;
They who see Him residing within
Know sorrows none;
The heart that knows Him enter in,
Loses its ego,
Well may that be destroyed too;
Do strive that state to reach.`,
    elaborationEnglish: `The Lord resides in our heart. Those who see Him residing
within know not sorrows. The heart that knows His entrance,
loses its ego. Strive to reach that state and muse on Him.`,
    elaborationTamil: `புறநிலையிற் செல்லாது அகநிலையிற் சென்று அங்குள்ள இறைவனை அறிகின்ற அறிவு 'நான்' என்னும் முனைப்பு அடங்கி நிற்றலை அனுபவத்தில் யாம் கண்டோம். அதனால் அந்த அறிவு மாயா காரியங்கைள ஒழித்து அவற்றினின்றும் நீங்கித் தூய்மை யுறுகின்றது. ஆகவே, அகநிலையிலே நிற்கின்ற நம் பெருமானை அவ்விடத்திற் காண்கின்ற அகநிலையறிவைப் பெற்றவர்கள் துன்பத்தை அடைய மாட்டார்கள்.`,
  },
  {
    id: 1876, tantraId: 7, verseNumber: 1875,
    tamil: `கழிவும் முதலும் காதல் துணையும்
அழிவும் தாய்நின்ற ஆதிப் பிரானைப்
பழியும் புகழும் படுபொருள் முற்றும்
ஒழியும்என் ஆவி உழவுகொண் டானே`,
    transliteration: `kaḻivum mutalum kātal tuṇaiyum
aḻivum tāyniṉṟa ātip pirāṉaip
paḻiyum pukaḻum paṭuporuḷ muṟṟum
oḻiyumeṉ āvi uḻavukoṇ ṭāṉē`,
    english: `1875: Renounce: God ploughs your Life for a Rich Harvest
He is the Beginning Finite,
He is companion endearing;
He causes dissolution too,
--He, the Lord Primal;
I gave up blame and praise,
And possessions entire;
Then my life, He ploughed
For a harvest abundant.`,
    elaborationEnglish: `He is the Primal Lord, the Beginning Finite, of endearing compassion that is the cause of dissolution. The yogi gives up all thought of blame, praise and possessions. Then does the Lord plough his life for an abundant harvest.`,
    elaborationTamil: `கடந்த காலத்தில் நிகழ்ந்துபோன அந்தச் செயல் களும், இப்பொழுது கடந்து கொண்டிருக்கின்ற காலத்தில் நிகழ்கின்ற இந்தச் செயல்களும், இவற்றைச் செய்விக்கின்ற முதல்வனும், அவன் செய்விக்கின்றபடி யான் செய்யும் பொழுது அதற்குத் துணையாய் உடன் நிற்கின்ற அன்புள்ள துணைவனும் ஆகிய எல்லாமாய் உள்ள முழுமுதற் கடவுளாகிய சிவனை நான் எனக்கு வருகின்ற பழியாயும், புகழாயும் விளைகின்ற அனைத்துப் பொருள்களுமாக உணர்கின்ற உணர்ச்சியோடே எனது உயிர் போய்க்கொண்டிருக்கின்றது. அதனால், எனது உடல் வழியாக நிகழும் முயற்சிகள் அனைத்தையும் அப்பெருமான் தனது முயற்சியாகவே ஏற்றுக் கொள்கின்றான்.`,
  },
  {
    id: 1877, tantraId: 7, verseNumber: 1876,
    tamil: `என்தாயோடு என்அப்பன் ஏழ்ஏழ் பிறவியும்
அன்றே சிவனுக்கு எழுதிய ஆவணம்
ஒன்றாய் உலகம் படைத்தான் எழுதினான்
நின்றான் முகில்வண்ணன் நேர்எழுத் தாமே`,
    transliteration: `eṉtāyōṭu eṉappaṉ ēḻēḻ piṟaviyum
aṉṟē civaṉukku eḻutiya āvaṇam
oṉṟāy ulakam paṭaittāṉ eḻutiṉāṉ
niṉṟāṉ mukilvaṇṇaṉ nēreḻut tāmē`,
    english: `1876: My Life willed to Siva
He is my mother and father in one
My births seven fold seven are to Siva willed;
--This the document drawn up even in days of yore;
Brahma who this world created wrote it thus;
And Vishnu the cloud-hued witnessed it.`,
    elaborationEnglish: `For the yogi, He is mother and father in one. His unnumerable births have been willed away to Siva; and that will was drawn up in the days of yore by Brahma, the creator, Vishnu, the cloud-hued, witnessing.`,
    elaborationTamil: `எனக்குத் தாயாகியவளும், தந்தையாகியவனும் நான் பிறப்பதற்கு முன்பே தங்களைச் சிவனுக்கு அடிமை' என்று எழுதிக் கொடுத்த ஆளோலையை வைத்துத்தான் ஈரேழுலகங்களை யும் ஒக்கப் படைத்தவனாகிய பிரமதேவன் என்னைப் படைக்கும் பொழுது எனது தலையில், 'இவன் சிவனுக்கு அடிமை' என்று எழுதினான். 'அந்த எழுத்துப் பொய்யானதன்று, மெய்யானதே' என நிலை நாட்டுபவனாகவே காப்போனாகிய திருமால் அமைந்தான்.`,
  },
  {
    id: 1878, tantraId: 7, verseNumber: 1877,
    tamil: `துணிந்தார் அகம்படி துன்னி உறையும்
பணிந்தார் அகம்படி பால்பட்டு ஒழுகும்
அணிந்தார் அகம்படி ஆதிப் பிரானைக்
கணிந்தார் ஒருவர்க்கு கைவிடலாமே`,
    transliteration: `tuṇintār akampaṭi tuṉṉi uṟaiyum
paṇintār akampaṭi pālpaṭṭu oḻukum
aṇintār akampaṭi ātip pirāṉaik
kaṇintār oruvarkku kaiviṭalāmē`,
    english: `1877: Devotees treasure Lord as Heart's Jewel
In the hearts of the resolute He firm abides;
In the hearts of those who adore, He in accord comports
Those who held the Primal Lord as their heart's Jewel
And so reckoned Him
How can they part from Him, ever?`,
    elaborationEnglish: `The Lord abides firm in the hearts of the resolute. He comports in accord in the hearts of those who adore Him. Those who have held and reckoned the Primal Lord as their heart's jewel can never give Him up.`,
    elaborationTamil: `'சிவனே நமக்கு எல்லாப் பொருளும்' எனத் துணிந்தவரது உள்ளத்தில் ஒன்றி உறைபவனும், அங்ஙனம் துணிந்த படியே மனமொழி மெய்களால் தன்னை வழிபட்டு ஒழுகு வசத்தனாய் நின்று அருள்புரிகின்றவனும் ஆகிய, அழகிதாய் அருள் நிறைந்த திரு வுள்ளத்தினையுடைய முழுமுதற் கடவுளாகிய சிவபெருமானைப் பல் காலும் நினைக்கின்ற ஒருவர்க்கு அவனை விடுதல் கூடுமோ! (கூடாது)`,
  },
  {
    id: 1879, tantraId: 7, verseNumber: 1878,
    tamil: `தலைமிசை வானவர் தாழ்சடை நந்தி
மிலைமிசை வைத்தனன் மெய்ப்பணி செய்யப்
புலைமிசை நீங்கிய பொன்னுலகு ஆளும்
பலமிசை செய்யும் படர்சடை யோனே`,
    transliteration: `talaimicai vāṉavar tāḻcaṭai nanti
milaimicai vaittaṉaṉ meyppaṇi ceyyap
pulaimicai nīṅkiya poṉṉulaku āḷum
palamicai ceyyum paṭarcaṭai yōṉē`,
    english: `1878: Lord lifted me to perform His Holy Work
The Celestial Beings bore on their heads
The Nandi of the flowing matted locks;
He on earth raised me high
His holy work to perform;
Higher still will He lift me,
Unto the Golden Kingdom of Purity to rule,
--He of the spreading matted locks.`,
    elaborationEnglish: `The celestial beings bore on their heads the Nandi of the
flowing matted locks. Nandi raised the yogi high on earth
to perform his holy work. The Lord will lift him higher still,
to the very golden kingdom of purity to me.`,
    elaborationTamil: `தேவர்கள் தம் தலையால் தனது திருவடிமேல் வணங்குகின்ற, தாழ்ந்த சடையை உடைய சிவபெருமான் தனக்கு உண்மையான தொண்டினைச் சிலர் செய்ய அதற்குப் பயனாக அவரைத் தேவர்கள் தம் தலைமேல் வைத்துப் போற்றும்படி வைத்தான். அதற்குமேல் அவன் அவரை முக்குணங்களும், கன்மமும், ஆணவமும் இல்லாத ஒளிமயமான மேல் உலகத்தை ஆள்கின்ற பயனையும் கூட்டுவிப்பான்.`,
  },
  {
    id: 1880, tantraId: 7, verseNumber: 1879,
    tamil: `அறியாப் பருவத்து அரன்அடி யாரைக்
குறியால் அறிந்தின்பம் கொண்டது அடிமை
குறியார் சடைமுடி கட்டி நடப்பார்
மறியார் புனல்மூழ்க மாதவம் ஆமே`,
    transliteration: `aṟiyāp paruvattu araṉaṭi yāraik
kuṟiyāl aṟintiṉpam koṇṭatu aṭimai
kuṟiyār caṭaimuṭi kaṭṭi naṭappār
maṟiyār puṉalmūḻka mātavam āmē`,
    english: `1879: How Tapasvins Look
In the days of childhood innocence
By their insignia external
I marked out the Holy Ones;
And becoming their devotee, I rejoiced;
Their matted locks tied in signal knot,
Caring not for this world
The Holy ones wander;
They return not to here below;
Immersed are they in the waters of Contemplation Divine
--This their tapas intense.`,
    elaborationEnglish: `In the days of innocent childhood the yogi marked out the holy ones by their external insignia, became their devotee and rejoiced in the act. The holy ones wander with their matted locks tied in signal knot, without a care of this world. They do not return to worldly thoughts. They are immersed in divine, contemplation. This is their intense tapas.`,
    elaborationTamil: `ஒன்றும் அறியாத இளமைப் பருவத்திற்றானே சிவனடியார்களை அவரது வேடத்தால் அறிந்து மகிழ்ச்சியுற்றதே சிவனுக்கு உண்மை அடிமைத் தன்மையாகும். அதன் பின் அவர்கள் செல்லும் செலவைத் தவிர்ந்த அவர்களது திருவடிகளை விளக்கிய நீரினைத் தலையில் தெளித்துக் கொள்ளுதலே அங்ஙனம் செய்வார்க்குப் பெரிய தவமாகும்.`,
  },
  {
    id: 1881, tantraId: 7, verseNumber: 1880,
    tamil: `அவன்பால் அணுகியே அன்புசெய் வார்கள்
சிவன்பால் அணுகுதல் செய்யவும் வல்லன்
அவன்பால் அணுகியே நாடும் அடியார்
இவன்பால் பெருமை இலயமது ஆமே`,
    transliteration: `avaṉpāl aṇukiyē aṉpucey vārkaḷ
civaṉpāl aṇukutal ceyyavum vallaṉ
avaṉpāl aṇukiyē nāṭum aṭiyār
ivaṉpāl perumai ilayamatu āmē`,
    english: `1880: Seek Devotees; Seek Siva
They who seek the devotees holy in love endearing
Can in depth Siva seek and be near;
The devotees who the Holy One seek
Will in Siva's greatness merged be.`,
    elaborationEnglish: `They return not to here below;

Immersed are they in the waters of Contemplation

Divine
—This their tapas intense.

They who seek the holy devotees in endearing love, seek in
depth and are near to Siva. Such devotees will be merged
in Siva’s greatness.`,
    elaborationTamil: `முன்னை மந்திரத்திற் கூறியவாறு இளமையிலே அடியார் பத்தியிற் சிறந்த ஒருவனை அடைந்து அன்பு செய்பவர்கள் சிவனையே அடையவும் வல்லாராவர். இன்னும் அவரிடத்தில் சிவனையே வழிபடும் ஒருவனது பெருமை அடங்கி விடுவதாகும்.`,
  },
  {
    id: 1882, tantraId: 7, verseNumber: 1881,
    tamil: `முன்னிருந் தார்முழுது எண்கணத் தேவர்கள்
எண்ணிறந்து அன்பால் வருவர் இருநிலத்து
எண்இரு நாலு திசைஅந் தரம் ஒக்கப்
பன்னிரு காதம் பதஞ்செய்யும் பாரே`,
    transliteration: `muṉṉirun tārmuḻutu eṇkaṇat tēvarkaḷ
eṇṇiṟantu aṉpāl varuvar irunilattu
eṇiru nālu ticaian taram okkap
paṉṉiru kātam patañceyyum pārē`,
    english: `1881: Celestials Seek the Jnanis
Seeking the Holy ones
The eight clans of Celestial Beings
Swarm the earth in endearment surpassing;
The earth seems unto a crowded heaven
For twelve leagues, in directions eight.`,
    elaborationEnglish: `The eight orders of celestials beings seek the holy ones and
swarm the earth in surpassing endearment. The earth seems
like a crowded heaven for a radius of twelve leagues in eight
directions. ,

“Eight’’ clans of Celestial Beings - this is a way of speaking.
The number. is not to be taken as exact, unless the lords
of eight directions are meant..`,
    elaborationTamil: `பதினெண்கணங்களாக வகுத்துச் சொல்லப் படுகின்ற தேவ சாதியர் பலரும் முன்னே நல்வினைகள் பலவற்றைச் செய்து அந்நிலையை அடைந்தார்கள். அதன்பின்பு அந்நிலையில் இருக்க விரும்பாமல் சிவன்பால் அன்பு செலுத்தியுய்தற்கு இந் நிலவுலகத்தில் வருவார்கள். அவ்வாறு வந்து அவர் சிவனை வழி படுகின்ற இடம் எட்டுத் திசையிலும் பன்னிரு காதப் பரப்பிற்குச் சிவ லோகமாகும்படி அவர்களது ஞானம் செய்யும்.`,
  },
  {
    id: 1883, tantraId: 7, verseNumber: 1882,
    tamil: `சிவயோகி ஞானி செறிந்தஅத் தேசம்
அவயோகம் இன்றி அறிவோர் உண்டாகும்
நவயோகம் கைகூடும் நல்லியல் காணும்
பவயோகம் இன்றிப் பரலோகம் ஆமே`,
    transliteration: `civayōki ñāṉi ceṟintaat tēcam
avayōkam iṉṟi aṟivōr uṇṭākum
navayōkam kaikūṭum nalliyal kāṇum
pavayōkam iṉṟip paralōkam āmē`,
    english: `1882: Land of Siva Jnanis is Blessed
Where Siva Yoga Jnanis flourish
Misfortunes will not be;
New ways of prosperity dawn;
All things good befall;
A very heaven that land will be;
With rebirths none for its denizens.`,
    elaborationEnglish: `No misfortune befalls the land where Sivayoga jnanis flourish; in that land the learned will increase, new ways of prosperity will dawn, and all good Tec will flourish. That land will be nothing but a heaven for its denizens.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 1884, tantraId: 7, verseNumber: 1883,
    tamil: `மேலுணர் வான்மிகு ஞாலம் படைத்தவன்
மேலுணர் வான்மிகு ஞாலம் கடந்தவன்
மேலுணர் வார்மிகு ஞாலத்து அமரர்கள்
மேலுணுர் வார்சிவன் மெய்யடி யார்களே`,
    transliteration: `mēluṇar vāṉmiku ñālam paṭaittavaṉ
mēluṇar vāṉmiku ñālam kaṭantavaṉ
mēluṇar vārmiku ñālattu amararkaḷ
mēluṇur vārcivaṉ meyyaṭi yārkaḷē`,
    english: `1883: Greatness of Siva Yoga Jnanis
They who the Higher Knowledge attained,
Can even create this world;
They who the Higher Knowledge attained,
Can transcend worlds several;
They who the Divine Light perceived
Are verily immortals here below;
They indeed are Siva's devotees true.`,
    elaborationEnglish: `He who has attained the higher knowledge can even create this world and can transcend several worlds. He who has perceived the divine light is immortal here below. He indeed is the true devotee of Siva. 15. Gunser af) RULES FOR FEEDING HOLY MEN`,
    elaborationTamil: `பிரமன், விட்டுணு, பிறதேவர் ஆகியோ ரெல்லாம் தாம் தாம் செய்யும் அதிகாரத்தைத் தமது ஆற்றலால் அமைந் தனவாகவே கருதி மயங்குவாரல்லது, 'இவை பரம்பொருளாகிய சிவனது ஆணையின்வழி நமக்கு அமைந்தன, என்று உணர மாட்டார்கள் (அதனால் அவர்கள் மெய்யடியாராதல் இல்லை) அந் நிலையில், 'நமக்குக் கிடைத்த நலங்கள் யாவும் பரம்பொருளாகிய சிவனது அருளால் கிடைத்தன' எனச் சிவனுக்கு மெய்யடியா ராயினாரே உணர்வார்கள்.`,
  },
  {
    id: 1885, tantraId: 7, verseNumber: 1884,
    tamil: `எட்டுத் திசையும் இறைவன் அடியவர்க்கு
கட்ட அடிசில் அழுதென்று எதிர்கொள்வர்
ஒட்டி ஒருநிலம் ஆள்பவர் அந்நிலம்
விட்டுக் கிடக்கில் விருப்பறி யாரே`,
    transliteration: `eṭṭut ticaiyum iṟaivaṉ aṭiyavarkku
kaṭṭa aṭicil aḻuteṉṟu etirkoḷvar
oṭṭi orunilam āḷpavar annilam
viṭṭuk kiṭakkil viruppaṟi yārē`,
    english: `1884: Lord cares for Siva Jnanis
Wherever it be
The food that is to them offered,
The Lord's devotees receive as sweet ambrosia;
Even as those who own a lone plot of land
Will unhappy be,
If that land uncared for lies.`,
    elaborationEnglish: `The Lord’s devotees receive as sweet ambrosia whatever food is offered to them. As unhappy as the husbandman feels when the lone piece of land he owns actually lies uncared for, so should one feel when a devotee is left uncared for.`,
    elaborationTamil: `ஒரு வயலையே தங்களுடையதாகக் கொண்டிருப் பவர் அது தரிசாய்க் கிடந்தால் விளைவு ஒன்றையும் பெறமாட்டார். அது போலச் சிவனடியார்கள் 'அடியார்களுக்கு' என்று நினைத்துச் சமைத்த உணவையே, 'இஃது எட்டுத் திக்கினையும் நிறைவு செய்யும் அமுத மாகும்' என விரும்பி உண்பதன்றி, 'தமக்கும் தம் கேளிர் கிளைஞர் கட்குமே' என்று நினைத்துச் சமைத்த உணவை உண்ணமாட்டார்கள்.`,
  },
  {
    id: 1886, tantraId: 7, verseNumber: 1885,
    tamil: `அச்சிவன் உள்நின்ற அருளை அறிந்தவர்
உச்சியம் போதாக உள்ளமர் கோவிற்குப்
பிச்சை பிடித்துண்டு பேதம் அறநினைந்து
இச்சைவிட்டு ஏகாந்தத்து ஏறி இருப்பரே`,
    transliteration: `accivaṉ uḷniṉṟa aruḷai aṟintavar
ucciyam pōtāka uḷḷamar kōviṟkup
piccai piṭittuṇṭu pētam aṟaniṉaintu
iccaiviṭṭu ēkāntattu ēṟi irupparē`,
    english: `1885: Jnanis accept alms to sustain the Body-Temple
The holy ones who have tasted of Lord's inner grace
Will at noon-tide accept alms
To sustain the body temple where the Lord resides;
Of differences they think not;
All desires extinguished,
They in solitude are seated.`,
    elaborationEnglish: `In order to sustain their body-temple where the Lord resides,
the holy ones who have savoured the Lord’s inner Grace will
accept alms at noon-tide. They do not think of differences.
They are seated in solitude having extinguished all desires.`,
    elaborationTamil: `தம்முள் நிற்கின்ற சிவனுக்குள்ளே தாம் நின்று அவனது திருவருள் இயல்பை அநுபவமாக உணர்ந்த அடியார்கள் பசிமிகுந்த போது தம்முள்ளே அமர்ந்திருக்கின்ற தலைவனது இல்லமாகிய உடலில் உயிர் நின்றாங்கு நிற்றற் பொருட்டு, பிச்சையேற்று உண்டு சிவனைத் தம்மின் வேறாக நினையாது தாமேயாக நினைந்து உலகப் பற்று அற்று ஒன்றாகிய சிவ நிலையிலே உயர்ந்திருப்பார்கள்.`,
  },
  {
    id: 1887, tantraId: 7, verseNumber: 1886,
    tamil: `விச்சுக் கலம் உண்டு வேலிச்செய் ஒன்றுண்டு
உச்சிக்கு முன்னே உழவு சமைந்தது
அச்சம்கெட்டு அச்செயல் அறுத்துண்ண மாட்டாதார்
இச்சைக்குப் பிச்சை இரக்கின்ற வாறே`,
    transliteration: `viccuk kalam uṇṭu vēliccey oṉṟuṇṭu
uccikku muṉṉē uḻavu camaintatu
accamkeṭṭu acceyal aṟuttuṇṇa māṭṭātār
iccaikkup piccai irakkiṉṟa vāṟē`,
    english: `1886: Jnanis harvest the Body-field
In the body-field is the seed;
The field has a fence;
In the crown of the head
The crop ripened;
If without fear they harvest not,
And feed themselves not,
They are but those
Who beg for hunger's sake.`,
    elaborationEnglish: `The seed lies in the fenceless body-field (muladhara) The crop ripens in the crown of the head (sahasrara). They who do not harvest the crop are but begging not to eating to appease their hunger.`,
    elaborationTamil: `அடியவர்கட்கு உலக உழவரின் வேறான விதைக் கூடை உண்டு; வேலி நிலம் உண்டு. அதனால் அவர் பசிக்குமுன்பே அவரது உழவுத்தொழில் அவர்கட்குப் பயனைத் தந்து விடுகின்றது. ஆகவே, 'பசி வந்து வருத்துமோ' என்னும் அச்சம் இல்லாமல் அதற்கு முன்பே அவர்கள் அறுவடை செய்து பசியின்றி உண்கின்றார்கள். அது மாட்டாதவர்களே வயிறு வளர்க்கும் விருப்பத்தால் பலரிடம் சென்று இரந்து உயிர் வாழ்கின்றனர்.`,
  },
  {
    id: 1888, tantraId: 7, verseNumber: 1887,
    tamil: `பிச்சையது ஏற்றான் பிரமன் தலைதன்னில்
பிச்சையது ஏற்றான் பிரியா அறஞ்செய்யப்
பிச்சையது ஏற்றான் பிரமன் சிரங்காட்டிப்
பிச்சையது ஏற்றான் பிரமன் பரமாகவே`,
    transliteration: `piccaiyatu ēṟṟāṉ piramaṉ talaitaṉṉil
piccaiyatu ēṟṟāṉ piriyā aṟañceyyap
piccaiyatu ēṟṟāṉ piramaṉ ciraṅkāṭṭip
piccaiyatu ēṟṟāṉ piramaṉ paramākavē`,
    english: `1887: Why Lord Begged
The Lord begged in Brahma's skull,
The Lord begged for Dharma to perpetuate;
The Lord begged in Brahma's skull,
That Brahma to Brahmam become.`,
    elaborationEnglish: `The Lord begged in Brahma’s skull to perpetuate dharma;
so that Brahtha may become Brahman.`,
    elaborationTamil: `சிவபெருமான் பிரமனது தலை ஓட்டினையே கலமாகக் கொண்டு எங்கும் சென்று பிச்சையேற்றான். ஏன்? இயல்பாக அறம் செய்யாதவரும் உயர்ந்தோர்க்குக் கொடுத்தலாகிய செயல் வாய்த்து அறம் பெறுதற் பொருட்டு. இன்னும் அஃதேயன்றி, 'தானே பரம்பொருள்' என்பதை விளக்குதற்கும்.`,
  },
  {
    id: 1889, tantraId: 7, verseNumber: 1888,
    tamil: `பரந்துலகு ஏழும் படைத்த பிரானை
இரந்துணி என்பர்கள் எற்றுக்கு இரக்கும்
நிரந்தக மாக நினையும் அடியார்
இரந்துண்டு தன்கழல் எட்டச்செய் தானே`,
    transliteration: `parantulaku ēḻum paṭaitta pirāṉai
irantuṇi eṉparkaḷ eṟṟukku irakkum
nirantaka māka niṉaiyum aṭiyār
irantuṇṭu taṉkaḻal eṭṭaccey tāṉē`,
    english: `1888: Why Devotees Beg
The Lord who the seven worlds created
A beggar they call Him?
Why, though, He begs?
That the holy devotees
Who constant think of Him,
Beg and reach His Feet.`,
    elaborationEnglish: `Beg and reach His Feet. The Lord created the seven worlds. Yet they call him a beggar. Why does He beg? He does it, so that the holy devotees, who think of Him constantly, might*beg and reach His Feet.`,
    elaborationTamil: `சிவபெருமானை உலக முதல்வனாக உணரா தவர்கள் அவன் இரத்தலை மட்டுமே நோக்கி அது பற்றி இகழ்ந் தொழிவர். அவர்கள் போலன்றி அவனை உலக முதல்வனாக உணர் பவர், 'சிவன் ஏன் இரக்கவேண்டும்'என ஆழ்ந்து நோக்குவர். அங் ஙனம் நோக்குவார்க்கு, 'அவன் அடியவர் உலகியலில் ஈடுபடாது பசி நீங்குதல் மாத்திரைக்குத்தன் செயலைப் போலவே இரந்து உண்டு முடிவில் தனது திருவடியடையும் செயலைப் போலவே இரந்து உண்டு முடிவில் தனது திருவடியடையும் நோக்குத் தப்பாது நிறைவெய்துதற் பொருட்டாம்' என்பது விளங்கும்.`,
  },
  {
    id: 1890, tantraId: 7, verseNumber: 1889,
    tamil: `வரஇருந் தான்வழி நின்றிடும் ஈசன்
தரஇருந் தான்தன்னை நல்லவர்க்கு இன்பம்
பொரஇருந் தான்புக லேபுக லாக
வரஇருந் தால்அறி யான்என்ப தாமே`,
    transliteration: `varairun tāṉvaḻi niṉṟiṭum īcaṉ
tarairun tāṉtaṉṉai nallavarkku iṉpam
porairun tāṉpuka lēpuka lāka
varairun tālaṟi yāṉeṉpa tāmē`,
    english: `1889: Lord Waits for His Devotees
The Lord stands waiting
For them that come seeking Him;
For the holy ones He waits
His bliss to bestow;
He stands waiting, them to enter;
Can you say "He knows me not."`,
    elaborationEnglish: `The Lord waits for those who come seeking. Him. He waits
to bestow the bliss on the holy ones. He waits for them to
enter. How can one say that he does not know the yogi.
anant uFlub soured Dugohys`,
    elaborationTamil: `அடியவர்களே! கருடனுக்கு அஞ்சிய பாம்புகளே சிவனையே அடைக்கலமாக அடைந்து அதனால், ஏன் கருடா சுகமா? என்று கேட்கும் அளவிற்கு அச்சமின்றி யிருக்கின்றன என்றால், 'சிவன் தன்னை அடைந்தவர்களது இன்னலை எண்ணுவ தில்லை' என்றல் கூடுமோ! கூடாது. உண்மையில் அவன் நல்லவர் கட்கு இன்பத்தை அலைவீசும் கடலைப்போல மிகத்தருவதற் காகவே இருக்கின்றான். இன்னும் அவர்கட்கு அவன் தன்னையே கொடுத்துவிடுவான். ஆகையால், அவன் ஒரு காலத்தில் தலையோட்டிலே எங்கும் சென்று இரந்தானாயினும், எப்பொழுதும் தேவரும், மூவரும், யாவரும் தன்பால் வந்து வணங்கி நலம்பெற இருத்தல்போலவே நீங்களும் பலரது இல்லங்களைத் தேடிச்சென்று இரவாது இருங்கள்.`,
  },
  {
    id: 1891, tantraId: 7, verseNumber: 1890,
    tamil: `அங்கார் பசியும் அவாவும் வெகுளியும்
தங்கார் சிவனடி யார்சரீரத்திடைப்
பொங்கார் புவனத்தும் புண்ணிய லோகத்தும்
தங்கார் சிவனைத் தலைப்படு வாரே`,
    transliteration: `aṅkār paciyum avāvum vekuḷiyum
taṅkār civaṉaṭi yārcarīrattiṭaip
poṅkār puvaṉattum puṇṇiya lōkattum
taṅkār civaṉait talaippaṭu vārē`,
    english: `1890: Devotees Constant Seek Siva
Gnawing hunger, greed and anger
These bodily evils
Siva's devotees possess not;
Neither in this world below,
Nor in the blessed world above
Will they remain;
Seeking Siva and Siva alone
Will they engrossed ever be.`,
    elaborationEnglish: `Siva’s devotees do not possess such bodily evils as gnawing hunger, greed and anger. They do not remain cither in this ‘world or in the next. They are engrossed in seeking Siva and Siva alone.`,
    elaborationTamil: `சிவனடியார்கள் தாம் எடுத்த உடம்பிலே உள்ளா ராயினும் அதன்கண் இல்லாதவரேயாவர். அஃது எங்ஙனம் எனின் அவ்வுடம்பில் உளதாகின்ற பசி, அவா, சினம் என்பவை தம்மை வெல்லும் அளவிற்கு மிகார். ஆதலின், இன்னும் அவர்கள் இந்திரன், மால், பிரமன் முதலியோர் உலகத்திலும், சிவலோகத்திலுங்கூட அங்குள்ள போகங்களை நுகர்ந்து வாழார். மற்றுச் சிவனது திருவடி நிழலில் தலைக்கூடுதல் ஒன்றனையே செய்வார்கள்.`,
  },
  {
    id: 1892, tantraId: 7, verseNumber: 1891,
    tamil: `மெய்யக ஞானம் மிகத்தெளிந் தார்களும்
கையதும் நீண்டார் கடைத்தலைக் கேசெல்வர்
ஐயம் புகாமல் இருந்த தவசியார்
வையகம் எல்லாம் வரஇருந்தாரே.`,
    transliteration: `meyyaka ñāṉam mikatteḷin tārkaḷum
kaiyatum nīṇṭār kaṭaittalaik kēcelvar
aiyam pukāmal irunta tavaciyār
vaiyakam ellām varairuntārē.`,
    english: `1891: World Seeks to feed; Tapasvins do not Beg for a Living
Though they received the clear light of Jnana,
Yet they perforce seek portals of the bounteous for alms;
To these Tapasvins that beg not for a living,
All the world in reverence repairs.`,
    elaborationEnglish: `Tapasvins, though they have received jnana, go from door
to door for alms. All the world will hold these Tapasvins in
reverence, for they do not beg for a living.`,
    elaborationTamil: `இருந்த இடத்திலேயிருக்கும் யோகிகள் வறியவர் இரக்கும் இரவிற்குத் தாம் செல்லாமல், உலகத்தில் உள்ளவர்கள் எல்லாம் தம்பால் வந்து தம்மை வழிபடும்படி இருப்பார்கள். அங்ஙனமாயின், 'ஞானத்தில் மிகுந்தவர் இரத்தலைச் செய்யார்' என்பது சொல்ல வேண்டுமோ!`,
  },
  {
    id: 1893, tantraId: 7, verseNumber: 1892,
    tamil: `நாலேழு மாறவே நண்ணிய முத்திரை
பாலான மோன மொழியிற் பதிவித்து
மேலான நந்தி திருவடி மீதுய்யக்
கோலா கலங்கெட்டுக் கூடுதன் முத்தியே.`,
    transliteration: `nālēḻu māṟavē naṇṇiya muttirai
pālāṉa mōṉa moḻiyiṟ pativittu
mēlāṉa nanti tiruvaṭi mītuyyak
kōlā kalaṅkeṭṭuk kūṭutaṉ muttiyē.`,
    english: `1892 Significance of Mudra
The Mudra is to transcend avastas eleven,
Fix awareness on Silent Letter Pranava (Aum)
That the Way is;
And reach the Holy Feet of Nandi;
And all desires worldly quelled
You attain Mukti divine.`,
    elaborationEnglish: `Fix the mudra (that directs the eleven sense organs, five jnanendriyas, fivé karmendriyas, and one manas)-on the silent letter, pranava “Aum.” You will reach the Holy Feet of Nandi, and attain mukti.`,
    elaborationTamil: `நால்வகைத் தோற்றத்து எழுவகைப் பிறப்பும் நீங்குதற் பொருட்டு நல்லோர் தங்கள் உள்ளங்களை அவற்றிற்கு ஏற்பப் பொருந்திய முத்திரைகளாகிய பல வகைப்பட்ட மொழிகளிலே பொருத்தி, அவ்வாற்றால் பரம்பொருளாகிய சிவனடிமேல் செல்லும் படி செலுத்தினால், உலக ஆரவாரங்கள் அடங்கி, மேலான வீடுபேறு உண்டாகும்.`,
  },
  {
    id: 1894, tantraId: 7, verseNumber: 1893,
    tamil: `துரியங்கள் மூன்று சொருகுஇட னாகி
அரிய உரைத்தாரம் அங்கே அடக்கி
மருவிய சாம்பவி கேசரி உண்மை
பெருகிய ஞானம் பிறழ்முத் திரையே`,
    transliteration: `turiyaṅkaḷ mūṉṟu corukuiṭa ṉāki
ariya uraittāram aṅkē aṭakki
maruviya cāmpavi kēcari uṇmai
perukiya ñāṉam piṟaḻmut tiraiyē`,
    english: `1893: Mudras--Sambhavi and Kecari
In the palatal place where the three Turiya states of awareness subsume,
Insert your tongue inward, and there contain it;
Thus practise the Mudras, Sambhavi and Kecari
Divine Jnana's light to flood.`,
    elaborationEnglish: `Divine Jnana’s light to flood.

Insert the tongue inward where the three’ turiya states of
.consciousness subsume and contain it there. Thus practise the
mudras, sambhavi and kechari. This will result in the flood
of -divine jnana’s light.

sribua) 55H) sonea Ge wimTtencuwmLb`,
    elaborationTamil: `அரிய சொற்களையே உரைப்பதாயினும் அதனையும் துரிய நிலையில் நிற்குங்கால் எழாமல் அடங்கியிருக்கச் செய்து நின்ற 'சாம்பவி, கேசரி' என்னும் இரண்டு முத்தரைகளே முத்துரியங்களும் செறிந்திருக்கும் இடமாய்' உலகியலினின்றும் நீங்குதற்கும், உண்மை ஞானம் பெருகுதற்கும் ஏதுவாய முத்திரைகளாம்.`,
  },
  {
    id: 1895, tantraId: 7, verseNumber: 1894,
    tamil: `சாம்பவி நந்தி தன்னருள் பார்வையாம்
ஆம்பவம் இல்லா அருட்பாணி முத்திரை
ஓம்பயில் ஒங்கிய உண்மைய கேசரி
நாம்பயில் நாதன்மெய்ஞ் ஞானமுத் திரையே`,
    transliteration: `cāmpavi nanti taṉṉaruḷ pārvaiyām
āmpavam illā aruṭpāṇi muttirai
ōmpayil oṅkiya uṇmaiya kēcari
nāmpayil nātaṉmeyñ ñāṉamut tiraiyē`,
    english: `1894: Sambhavi Mudra brings Grace and Kecari Jnana
Sambhavi Mudra brings Nandi's glance
In Grace abounding and birth ending;
Kecari true where Aum is in silence chanted
Is the Mudra that divine Jnana brings;
That the one I abored,
as Natha (Guru) divine.`,
    elaborationEnglish: `That the one I practise, as Natha (Guru) divine. Sambhavi mudra brings grace and snaps the cycle of birth. Kechari mudra brings jnana.`,
    elaborationTamil: `சாம்பவி முத்திரையாவது தனது கண்களைச் சிவனது கண்களாகப் பாவித்துக்கொண்டு, நோக்குவன எவற்றையும் அந்தப் பாவனையோடே நோக்குதலாம். இதனால் உலகப் பொருள்கள் மாயையாகாது அருள்மயமாக, தனது ஞானேச்சாக் கிரியைகளும் சிவனது ஞானேச்சாக் கிரியைகளில் அடங்கி நிற்கும். இனித் தன்னைச் சிவனாகப் பாவித்து வணங்குவோரையும் அருளே தனுவாய் நின்று சிவமாகச் செய்யும். இனிக் கேசரி முத்திரையாவது, பிறப்பில்லாமைக்கு ஏது வாகிய சின்முத்திரைக் கையுடன் பிரணவ யோகத்தில் பயில்வதாகிய ஞானயோக நிலையாம். இவை இரண்டுமே நாம் நாள்தோறும் பயில்கின்ற சிவஞான முத்திரைகளாகும்.`,
  },
  {
    id: 1896, tantraId: 7, verseNumber: 1895,
    tamil: `தானத்தின் உள்ளே சதாசிவன் ஆயிடும்
ஞானத்தின் உள்ளே நற்சிவம் ஆதலால்
ஏனைச் சிவமாம் சொரூபம் மறைந்திட்ட
மோனத்து முத்திரை முத்தாந்த முத்தியே`,
    transliteration: `tāṉattiṉ uḷḷē catācivaṉ āyiṭum
ñāṉattiṉ uḷḷē naṟcivam ātalāl
ēṉaic civamām corūpam maṟaintiṭṭa
mōṉattu muttirai muttānta muttiyē`,
    english: `1895: Mauna Mudra Leads to Mukti Final
He who appears in Adharas is Sadasiva;
He who appears in Jnana is the goodly Siva;
In the silence of Mauna Mudra, Siva's form disappears;
That verily is the Mukti Finale, the Ultima Thule.`,
    elaborationEnglish: `Sadasiva appears in adharas; great Siva appears in jnana. Siva’s form vanishes in the silence of mauna mudra. Truly that is the finale mukti, the ‘ultima thule the last thing.’`,
    elaborationTamil: `'ஆதாரம், நிராதாரம், மீதானம்' என்பன எல்லாம் வரையறைப்பட்ட இடங்களேயாதலின் அவ்விடங்களில் எல்லாம் விளங்குபவன் தடத்த சிவனே. (ஆகவே யோகம் முழுவதிலும் விளங்குபவன் தடத்த சிவனே. அதனால் யோக முத்திரைகள் யாவும் பதமுத்தி அபரமுத்திகளையே தரும்.) ஞானத்தில் சொரூப சிவன் விளங்குதலால் தடத்த சிவனின் வேறாகிய சொரூப சிவனைக் குறிக்கின்ற சின்முத்திரையே முத்திகளிலெல்லாம் முடிந்த முத்தியாகிய பரமுத்தியைத் தரும் முத்திரையாகும்.`,
  },
  {
    id: 1897, tantraId: 7, verseNumber: 1896,
    tamil: `வாக்கு மனமும் இரண்டும் மவுனமாம்
வாக்கு மவுனத்து வந்தாலும் மூங்கையாம்
வாக்கு மனமும் மவுனமாம் சுத்தரே
ஆக்கும் அச் சுத்த்ததை யார்அறி வார்களே`,
    transliteration: `vākku maṉamum iraṇṭum mavuṉamām
vākku mavuṉattu vantālum mūṅkaiyām
vākku maṉamum mavuṉamām cuttarē
ākkum ac cutttatai yāraṟi vārkaḷē`,
    english: `1896: Mauna is Stillness of Both Thought and Speech
To attain stillness of Speech and Thought at once is mauna
Mauna sans Speech alone
Is but state of dumbness;
Only when Speech and Thought are alike in mauna
Are you in State Suddha (Perfection)
Who but knows
That Suddha state to bring about?`,
    elaborationEnglish: `Mauna is Stillness of both thought and speech. Mauna, without speech alone is but the state of dumbness. Perfect suddha State is attained only when speech and thought are in mauna.`,
    elaborationTamil: `வாக்கு, மனம் என்னும் இரண்டும் வாளா இருத்தலே 'மௌனம்' என்பதற்குப் பொருளாகும். 'அதைவிடுத்து, மனம் எவ்வாறு செயற்பட்டாலும் வாக்கு மட்டும் செயற்படாது வாளா இருத்தல்தான் மௌனம்' எனக் கூறினால் உலகில் ஊமைகளாய் உள்ளார் யாவரும் மௌன விரதிகளாகி விடுவர். வாக்கு, மனம் என்னும் இரண்டும் அடங்கிய தூய நிலையே 'சுத்த நிலை' எனப் படுகின்ற அந்த வீடுபேற்றைத் தரும். அந்த உண்மையை அறிகின்றவர் யாவர்?`,
  },
  {
    id: 1898, tantraId: 7, verseNumber: 1897,
    tamil: `யோகத்தின் முத்திரை ஓர்அட்ட சித்தியாம்
ஏகத்த ஞானத்து முத்திரை எண்ணுங்கால்
ஆகத் தகும்வேத கேசரி சாம்பவி
யோகத்துக் கேசரி யோகமுத் திரையே`,
    transliteration: `yōkattiṉ muttirai ōraṭṭa cittiyām
ēkatta ñāṉattu muttirai eṇṇuṅkāl
ākat takumvēta kēcari cāmpavi
yōkattuk kēcari yōkamut tiraiyē`,
    english: `1897: Yoga Mudra and Jnana Mudra
Sambhavi is the lion among Yoga Mudras
That leads certain to Siddhis eight;
When Jnana Mudra you seek
Appropriate indeed is Kecari
That by Vedas lauded high.`,
    elaborationEnglish: `Sambhavi is the lion among yoga mudras that leads to the eight siddhis. Kechari is the jnana mudra that is lauded high by the Vedas.`,
    elaborationTamil: `யோகம் கைவந்தமைக்கு அடையாளம் அட்டமா சித்திகள் வாய்ந்தமையாகும். அதுபோல இறைவனின் வேறாகது ஒன்றாகிய அனுபவ ஞானம் கைவந்தமைக்கு அடையாளத்தை ஆராயுமிடத்து மிக்க தகுதி வாய்ந்ததான வேதத்திற் சொல்லப்பட்ட கேசரியாகிய சாம்பவி முத்தரை யோடு கூடிய கேசரி முத்திரையே யாகும். யோக நூலினும் கேசரி முத்திரை சொல்லப்பட்டதாயினும் அஃது யோக கேசரி முத்திரையாம் .`,
  },
  {
    id: 1899, tantraId: 7, verseNumber: 1898,
    tamil: `யோகிஎண் சித்தி அருளொலி வாதனை
போகி தன் புத்தி புருடார்த்த நன்னெறி
ஆகும்நன் சத்தியும் ஆதார சோதனை
ஏகமும் கண்டொன்றில் எய்திநின் றானே`,
    transliteration: `yōkieṇ citti aruḷoli vātaṉai
pōki taṉ putti puruṭārtta naṉṉeṟi
ākumnaṉ cattiyum ātāra cōtaṉai
ēkamum kaṇṭoṉṟil eytiniṉ ṟāṉē`,
    english: `1898: Yogi attains Nada State
Yogi attains siddhis eight
He experiences the divine Nada State;
He is of Karma rid
He is of calm mind
He pursues the Four Ends of Human Goal,
He courses the Sakti Kundalini
Through centres six within the body;
That way he reaches the One
And union in Him attains.`,
    elaborationEnglish: `The yogi attains the eight siddhis by coursing the kundalini sakti through the six centres with in the body and experiences the divine nada state. Rid of karma, he abides in tranquillity and serenity. He pursues the fourth state of sayujya, that is identity in Siva. He reaches the Primal One and stands in union with Him.`,
    elaborationTamil: `யோகி பெறும் அட்டமா சித்திகள் தருவருளால் கிடைப்பனவாயினும் அதுவும் ஒருவகைப் பந்தமே இனிப் போகியாய் இருப்பவன். 'நல்ல புத்திமான்' என மதிக்கப்படுவானாயின் அவன் அறம் முதலிய மூன்று புருடார்த்தத்தைப் பெறும் நன்னெறியில் நிற் பவனேயாவான். ஆறு ஆதாரங்களையும் நன்கு தரிசித்தவன் திருவருள் நெறியைத் தலைப்பட்டவனாவன். ஆகவே ஞானி ஒருவனே ஒப்பற்ற முதற்பொருளை உணர்ந்து அதன்பால் உள்ள பேரின்பத்தவனைப் பெற்றவனாவன்.`,
  },
  {
    id: 1900, tantraId: 7, verseNumber: 1899,
    tamil: `துவாதச மார்க்கமென் கோடச மார்க்கமாம்
அவாஅறும் ஈர்ஐ வகைஅங்கம் ஆறும்
தவாஅறு வேதாந்த சித்தாந்தத் தன்மை
நவாஅக மோடுஉன்னல் நற்சுத்த சைவமே`,
    transliteration: `tuvātaca mārkkameṉ kōṭaca mārkkamām
avāaṟum īrai vakaiaṅkam āṟum
tavāaṟu vētānta cittāntat taṉmai
navāaka mōṭuuṉṉal naṟcutta caivamē`,
    english: `1899: Yoga is the Pure Way of Siddhanta-Vedanta
The Yogic way of Dvadasa
But leads to Sodasa Kala Prasada
It sunders desires;
This the pure way of Vedanta-Siddhanta;
To meditate on the Mantra that begins with "Na" (Nama Sivaya)
That verily is Suddha (pure) Saivam.`,
    elaborationEnglish: `The yogic way of marga (twelve-stage way) sunders desires. It is but the subtle way of performing pujas with sixteen rituals. It subdues: the ten organs — motoria and sensoria — that is the end of Vedanta. Yoga is the pure way of Siddhanta/ Vedanta.

It states here that the Yogic Way is (12) and the Kalas Sodasha (16).The authority for the latter number will be found in notes under verses (as moon kalas) ante, but for the former is not directly traceable, unless it implies a relationship between yoga and the zodiacal positions of the sun (cakras).`,
    elaborationTamil: `பன்னிரு கலைப் பிராசாதமே பதினாறு கலைப் பிராசாதமாய் விரியும். அதனால் அவை இரண்டும் தம்மில் வேறாவன அல்ல. விரிவில் பதினாறாகின்ற அந்தப் பிராசாத யோகமே உலகியலிற் செல்லும் அவாவை அடியோடு அறுக்கும். அதனால் அந்தப் பிராசாத யோகங்களே அவா முற்ற நீங்குதற்கு ஏதுவாகிய 'வேதாந்த யோகம்' சித்தாந்த யோகம்' என்றும் சொல்லப்படும். அவற்றை மிக விருப்பத் தோடு செய்தலே சைவத்துள்ளும் மேலான சைவ நெறியாம்.`,
  },
  {
    id: 1901, tantraId: 7, verseNumber: 1900,
    tamil: `மோனத்து முத்திரை முத்தர்க்கு முத்திரை
ஞானத்து முத்திரை நாதர்க்கு முத்திரை
தேனிக்கும் முத்திரை சித்தாந்த முத்திரை
கானிக்கும் முத்திரை கண்ட சமயமே`,
    transliteration: `mōṉattu muttirai muttarkku muttirai
ñāṉattu muttirai nātarkku muttirai
tēṉikkum muttirai cittānta muttirai
kāṉikkum muttirai kaṇṭa camayamē`,
    english: `1900: All Mudras firm up breath
The Mudra that is Mauna
Is the Mudra for those Mukti seek;
The Mudra that is Jnana (Kecari)
Is the Mudra for those who Gurus be;
Mudra that draws nectar of Grace is the Mudra
That is Siddhanta (Sambhave)
Mudras all firm up breath,
That Siva Truth, of yore revealed.`,
    elaborationEnglish: `Mauna is the mudra for those who seek mukti, jnana (kechari)
mudra draws nectar. All mudras firm up the breath.

SION sort FUG GHGoucapid`,
    elaborationTamil: `'மோன முத்திரை' எனப்படுவதாகிய ஞான கேசரி முத்திரையே உணர்வைச் சிவத்தில் நிறுத்தும் முத்திரையும், சிவா னந்தத்தைப் பெருகச் செய்யும் முத்திரையும் சித்தாந்த முத்திரையும், சிவன் சீவனைச் சதா நோக்கிக் கொண்டிருக்கும் முத்திரையும் ஆகும். அதனால் அதுவே சீவன் முத்தர்க்கும், சீவன் முத்தராய் ஆசிரியத் தன்மையை உடையவர்க்கும் ஏற்புடைய முத்திரையாம். அதுபற்றிப் பல சைவங்களும் அதனையே சிறந்த முத்திரையாகக் கண்டன.`,
  },
  {
    id: 1902, tantraId: 7, verseNumber: 1901,
    tamil: `தூநெறி கண்ட சுவடு நடுவுஎழும்
பூநெறி கண்டுஅது பொன்னக மாய்நிற்கும்
மேல்நெறி கண்டது வெண்மதி மேதினி
நீல்நெறி கண்டுள நின்மலன் ஆமே`,
    transliteration: `tūneṟi kaṇṭa cuvaṭu naṭuvueḻum
pūneṟi kaṇṭuatu poṉṉaka māyniṟkum
mēlneṟi kaṇṭatu veṇmati mētiṉi
nīlneṟi kaṇṭuḷa niṉmalaṉ āmē`,
    english: `1901: Pure Vision inside Cranium
In the Sushumna Nadi Central
The Lord's Holy Feet will appear;
The lotus center (Sahasrara),
Within a Golden Sphere is;
Beyond, the upward course (of Kundalini) lifts you
To the Moon's Sphere that is white;
And there you vision the Pure One.`,
    elaborationEnglish: `“The Lord’s Holy -Feet will appear in the central sushumna nadi. Beyond is the sahasrara in the golden mount sphere; the coursing of kundalini further upward lifts. the yogi to the white moon’s sphere. There he receives the vision of the Pure One. 18. Yes GOS BMS F079)`,
    elaborationTamil: `தூய நெறியாகிய யோக முறை கைவந்து உண்மையைக் கண்ட அடையாளம், புருவ நடுவில் தோன்றுகின்ற முடி நிலை ஆதாரமாய்க் காணப்பட்டு, மேருமலையின் உச்சியை அடைந்தது போலத் தோன்றும். எனினும் அதுவே முடிநிலையாகாது, அதற்கு மேலேயுள்ள ஏழாந்தானத்திற் சென்றவர் கண்டது சந்திர மண்டலமாம். ஒருவன் அதற்குமேலும் செல்வானாயின், சத்தி சிவ நெறிகளைக் கண்டு மலம் நீங்கிய தூய உணர்வினனாவன்.`,
  },
  {
    id: 1903, tantraId: 7, verseNumber: 1902,
    tamil: `வளர்பிறை யில்தேவர் தம்பாலின் முன்னி
உளரொளி பானுவின் உள்ளே ஒடுங்கித்
தளர்வில் பிதிர்பதம் தங்கிச் சசியுள்
உளதுறும் யோகி உடல்விட்டால் தானே`,
    transliteration: `vaḷarpiṟai yiltēvar tampāliṉ muṉṉi
uḷaroḷi pāṉuviṉ uḷḷē oṭuṅkit
taḷarvil pitirpatam taṅkic caciyuḷ
uḷatuṟum yōki uṭalviṭṭāl tāṉē`,
    english: `1902: Soul's Journey after Yoga-Samadhi Attained
When the Yogi his mortal coil shuffles,
During the phase the
Crescent moon waxes
He (the soul) shall reach the world of Devas;
There for a while abiding,
Into the Sphere of Sun he subsides;
Thence He reaches the
Sphere
Where the Souls of
Ancestors dwell;
And from there, finally in the Sphere of Moon, he abides.`,
    elaborationEnglish: `The Lord's Holy Feet will appear in the central sushumna nadi. Beyond is the sahasrara in the golden mount sphere; the coursing of kundalini further upward lifts. the yogi to the white moon’s sphere. There he receives the vision of the Pure One.

This is a very important chapter, (all 8 verses, 1902-1909) describing as it does what happens when success is achieved in Yoga-Samadhi, and also what failure, total or partial involves. :

The subject matter of this chapter, is an important one. It explains why the Jnani’s body should not be cremated but buried (1910), and what are the rituals that should accompany the disposal of the body in this manner.`,
    elaborationTamil: `இயன்ற அளவு யோக நெறியில் நின்ற யோகி அந்நிலையிலே தனது புற உடலை விட்டு நீங்கினால் நீங்கின காலம வளர்பிறைக் காலமாய் இருப்பின் முன்னர்த் தேவருலகை அடைந்து சில காலம் இருந்து, பின் சூரிய மண்டலத்தில் நுட்பமாய்ப் புகுந்து, அப்பால் பிதிரர்கள் உலகத்தில் தங்கி, இறுதியில் சந்திர மண்டலத்துள் தஹ்கி அங்குள்ள இன்பத்தை நுகர்வான்.`,
  },
  {
    id: 1904, tantraId: 7, verseNumber: 1903,
    tamil: `தான்இவை ஒக்கும் சமாதி கைகூடாது
போன வியோகி புகலிடம் போந்துபின்
ஆனவை தீர நிரந்தர மாயோகம்
ஆனவை சேர்வார் அருளின் சார் வாகியே`,
    transliteration: `tāṉivai okkum camāti kaikūṭātu
pōṉa viyōki pukaliṭam pōntupiṉ
āṉavai tīra nirantara māyōkam
āṉavai cērvār aruḷiṉ cār vākiyē`,
    english: `1903: When Samadhi is not Reached
All these of the Yogi,
This life in Samadhi ended;
When that does happen not,
He will in this world take refuge again,
And by Lord's Grace
Resume Yoga in practice continual
And thus complete the undertaking, unfinished.`,
    elaborationEnglish: `When the yogi fails to reach samadhi,. he will be reborn in this world and by the.Lord’s Grace will resume and continue - yoga practice, until he completes’his unfinished undertaking.`,
    elaborationTamil: `யோக நிலை முற்றப்பெறாது உடல்விட்ட யோகிக்கு மேற்சொல்லியன எல்லாம் பொருந்தும். அவன் அவ்வாறு மேற்சொல்லிய இடங்களிலெல்லாம் தங்கிப் பயன்களை நுகர்ந்தபின் அங்கு நின்றும் பூமியில் வந்து பிறந்து விட்ட குறையாகிய வினையைப் புசித்துத் தீர்ந்தபி திருவருளின் துணையைப் பெற்று இடைவிடாது யோகத்தின் முதிர்ந்த நிலைகளை எய்துவர்.`,
  },
  {
    id: 1905, tantraId: 7, verseNumber: 1904,
    tamil: `தான்இவ் வகையே புவியோர் நெறிதங்கி
ஆன சிவயோகத்து ஆமாறுஆம் அவ்விந்து
தானதில் அந்தச் சிவயோகி ஆகுமுன்
ஊனத்தோர் சித்திவந்து ஓர்காயம் ஆகுமே`,
    transliteration: `tāṉiv vakaiyē puviyōr neṟitaṅki
āṉa civayōkattu āmāṟuām avvintu
tāṉatil antac civayōki ākumuṉ
ūṉattōr cittivantu ōrkāyam ākumē`,
    english: `1904: Siddha-Hood
Thus in the world they will be
And in Siva Yoga again be;
And as Siva Yogin in Bindu merge,
Many miraculous powers attain,
The Siddha-hood their fleshly body reaching.`,
    elaborationEnglish: `The Siva yogi merges in bindu sakti and attains many miraculous powers, his fleshy body reaching siddha-hood.`,
    elaborationTamil: `மேற்கூறிய யோகி மேற்கூறியவாறு உலக மக்கள் நெறியிலே தானும் நின்று, அதற்கு இடையிலே யோகம் முதிரப் பெற்றுச் சிவயோகியாவான். அங்ஙனம் அவன் சிவயோகி ஆவதற்கு வழி பிராசாத மந்திரம். அந்த மந்தித்தில் நின்று சிவயோகி ஆவதற்கு முன்பு அவன் பொதுவான யோகப் பயிற்சியால் கிடைக்கும் காய சித்தியைப் பெறுதலும் உண்டு.`,
  },
  {
    id: 1906, tantraId: 7, verseNumber: 1905,
    tamil: `சிவயோகி ஞானி சிதைந்துடல் விட்டால்
தவலோகம் சேர்ந்துபின் தான்வந்து கூடிச்
சிவயோக ஞானத்தால் சேர்ந்தவர் நிற்பர்
புவலோகம் போற்றும்நற் புண்ணியத்தோரே`,
    transliteration: `civayōki ñāṉi citaintuṭal viṭṭāl
tavalōkam cērntupiṉ tāṉvantu kūṭic
civayōka ñāṉattāl cērntavar niṟpar
puvalōkam pōṟṟumnaṟ puṇṇiyattōrē`,
    english: `1905: Continuity of Yoga through lives
While in the pursuit of Yoga
If Siva Yogins, holy, die,
They reach the World of Tapas
Only to this world return
And to Yoga repair;
Blessed indeed are they,
Whom the Beings Celestial praise high.`,
    elaborationEnglish: `If Siva yogis die while in the pursuit of yoga, they reaclf
the world of tapas, only to return to this world. Blessed are
they whom the celestial beings esteem high.`,
    elaborationTamil: `பிராசாத யோகமாகிய சிவயோகத்தில் நின்றவன் ஞானம் பெற்றவனோடு ஒத்தவனேயாவன். அவன் ஞானம் பெறுதற்கு முன் உடலை விட்டு நீங்கினானாயினி நேரே சிவலோகத்தையே அடைந்து அங்கு இன்பம் துய்த்தபின் மீளப் பிறந்து அந்தச் சிவ யோகத்தின் வழியே பெற்ற ஞானத்தால் மேன்மை எய்தி அத்தன்மை யாரோடே இருப்பன். அவ்வாறன்றிச் சிவலோகம் முதலியவற்றிற் செல்வோர் பசு புண்ணியம் செய்தவரே யாகையால் சிவயோகி ஆங்கெல்லாம் புகான்.`,
  },
  {
    id: 1907, tantraId: 7, verseNumber: 1906,
    tamil: `ஊனமில் ஞானிநல் யோகி உடல்விட்டால்
தானற மோனச் சமாதியுள் தங்கியே
தானவன் ஆகும் பரகாயம் சாராதே
ஊனமில் முத்தராய் மீளார் உணர்வுற்றே`,
    transliteration: `ūṉamil ñāṉinal yōki uṭalviṭṭāl
tāṉaṟa mōṉac camātiyuḷ taṅkiyē
tāṉavaṉ ākum parakāyam cārātē
ūṉamil muttarāy mīḷār uṇarvuṟṟē`,
    english: `1906: Mauna Samadhi Leads to the Unitive State
If Sivayogi gives up life,
In mauna Samadhi he enters
To seek the state unitive;
He will not in another body be born,
Nor as Jivan Mukta return
Conscious of here below;
But with Lord get united in one.`,
    elaborationEnglish: `Mauna samadhi leads to the unitive state. If the Siva yogi enters in mauna samadhi, he will neither be rebom, -nor will Temain as jivan mukta. He remains with the Lord in union.`,
    elaborationTamil: `குறைவில்லாத ஞானத்தைப் பெற்றவன் 'குறை வற்ற யோகி' என்றும் சொல்லப்படுவான். (அதற்குக் காரணம், உடம்புள்ள வரையில் அவன் உடலை விட்டு நீங்கியபின் வேறோர் உடலை எடுத்தல் இன்றியே, உடம்பில் மோன சமாதி நிலையில் தான் வேறின்றி இருந்தவாறே உடனே தான் சிவமேயாவன் ஆகவே, அவன் பரமுத்த னாதலன்றி, உலகியல் உணர்வைப் பொருந்திப் பிறப்பில் மீளான்.`,
  },
  {
    id: 1908, tantraId: 7, verseNumber: 1907,
    tamil: `செத்தார் பெறும் பயன் ஆவது ஏதெனில்
செத்துநீர் சேர்வது சித்தினைக் கூடிடில்
செத்தார் இருந்தார் செகத்தில் திரிமலம்
செத்தார் சிவமாகி யேசித்தர் தாமே`,
    transliteration: `cettār peṟum payaṉ āvatu ēteṉil
cettunīr cērvatu cittiṉaik kūṭiṭil
cettār iruntār cekattil tirimalam
cettār civamāki yēcittar tāmē`,
    english: `1907: Siddhas even when Dead in Body are Alive in Awareness
Blessed indeed are those who die
If in death they unite one with Lord;
Then, even dead, alive are they;
They who are dead unto the Impurities Three
Are Siddhas true.
Siva they become.`,
    elaborationEnglish: `Blessed are the siddhas; for if they die they remain one with
the Lord. Though dead in body, they are alive in awareness.`,
    elaborationTamil: `'பிறந்தவர் இறத்தல் இயல்பு என்னும் அம் முறை யிலே இறந்தவர் என்ன பயனைப்பெறுவர்' என வினவில் அம்முறை யில் இறந்தவர் அடையும் பயன் அந்த இறப்பைத் தவிர வேறில்லை. (என்றதில், 'அவர் சிறப்பாக அடையும் பயன் வேறில்லை' என்றபடி) இனிப் பொதுவான யோகத்தைச் செய்து அதன் பயனாகச் சித்திகளைப் பெற்றவர் இறந்தாரானால், அவரது புகழ் உலகில் இறவாதிருக்கும். ஆகவே, மும்மலங்களும் கெடப்பெற்றோரே வாழ்விலும், வாழ் விற்குப் பின்னரும் சிவமாய் நிற்கும் சிறந்த பேற்றை உடையராவர்.`,
  },
  {
    id: 1909, tantraId: 7, verseNumber: 1908,
    tamil: `உன்னக் கருவிட்டு உரவோன் அரன்அருள்
பன்னப் பரமே அருட்குலம் பாலிப்பன்
என்னப் புதல்வர்க்கும் வேண்டி யிடுஞானி
தன்இச்சைக்கு ஈசன் உருச்செய்யும் தானே`,
    transliteration: `uṉṉak karuviṭṭu uravōṉ araṉaruḷ
paṉṉap paramē aruṭkulam pālippaṉ
eṉṉap putalvarkkum vēṇṭi yiṭuñāṉi
taṉiccaikku īcaṉ urucceyyum tāṉē`,
    english: `1908: Jnani Shapes Disciple towards God-hood
Who intense seek the Grace of Lord Exalted
Their birth to sunder,
He himself draws them
Into the fold of His devotees dear;
Unto it, the Jnani draws unto him
His disciples, in love abounding,
In his own way subtle,
Toward Godhood, He shapes them.`,
    elaborationEnglish: `God holds dear the devotees who seek the Grace of the Lord
intensely, and sunders the fetters of their births. In a similar
manner the jnani draws his disciples in abounding love and’
in his own subtle way shapes the disciples towards Godhood.`,
    elaborationTamil: `ஞானத்தைப் பெற விரும்பும் உறுதியுடையவன், 'சிவனையன்றி வேறொன்றையும் நினைத்தல் கூடாது' என்னும் எண்ணமாகிய விதையை முதலிலே தனது உள்ளமாகிய நிலத்தில் ஊன்றி, (அந்த எண்ணம் சத்திநிபாதத்தால் உண்டாகும்) அங்ஙனமே சிவனையே பலகாலும் நினைத்தும், போற்றியும் வருவானாயின், அந்தச் சிவனே அவனுக்கு ஞானியர் குழாத்தை அவனுக்கு அருள் புரியும் வண்ணம் கூட்டுவிப்பான். (சேரமான் பெருமாளுக்கு வன் றொண்டரைக் கூட்டுவித்ததுபோல.) அங்ஙனம் கூட்டுவிக்கப்பட்ட பின் அவன் தானும் அக்குழாத்து ஞானியர் போல உலகத்தார் அனைவரையும் தன் மக்கள் போலக் கருதி, 'அவர்களும் தான் பெற்ற பேற்றைப் பெற வேண்டும்' என விரும்புவான். அத்தகையோனுக்குச் சிவன் அவன் விரும்பியவாறெல்லாம் காட்சி தருவான்.`,
  },
  {
    id: 1910, tantraId: 7, verseNumber: 1909,
    tamil: `எங்கும் சிவமாய் அருளாம் இதயத்துத்
தங்கும் சிவஞானிக்கு எங்குமாம் தற்பரம்
அங்காங்கு எனநின்று சகமுண்ட வான்தோய்தல்
இங்கே இறந்துஎங்கு மாய்நிற்கும் ஈசனே`,
    transliteration: `eṅkum civamāy aruḷām itayattut
taṅkum civañāṉikku eṅkumām taṟparam
aṅkāṅku eṉaniṉṟu cakamuṇṭa vāṉtōytal
iṅkē iṟantueṅku māyniṟkum īcaṉē`,
    english: `1909: Jnani Exists in Siva's Pervasiveness
The heart of Siva Jnani overflows in Grace;
He sees Siva everywhere;
He feels His presence pervasive;
Fragmented may be the sky you see;
But all space it engulfs;
Unto it, the Jnani,
Though rid of consciousness here,
One with Siva pervasive exists.`,
    elaborationEnglish: `The Siva jnani sees the Lord’s Grace overflowing everywhere and he revells in the Lord’s omnipresence. Though the sky we see is partial and fragmented, it engulfs the whole of space. Similarly, the jnani, though circumscribed by his body, aes consciousness that is one with the all pervasive Siva’s.`,
    elaborationTamil: `ஓரோரிடத்தில் மட்டுமே உள்ளது போலக் கட்டடங் களுக்கு உள்ளதுபோலக் காணப்படுகின்ற ஆகாயம் உண்மையில் அவ்வாறின்றி எங்கும் நிறைந்திருத்தல் போல இறைவன் ஓரோ ரிடத்தில் மட்டும் இருப்பவன் போல அங்கங்குள்ள குருலிங்க சங்க மங்களிலே இருப்பினும் உண்மையில் அவன் அந்த இடங்களை யெல்லாம் கடந்து எங்கும் இருக்கின்றான். இந்த உண்மையைத் திருவருளால் உணர்ந்து அந்தத் திருவருள் வியாபகத்திலே நிற்பவனே சிவஞானியாவான். அவன் உடல் விட்டால் அவனுக்கு சிவன் தனது எங்கும நிறைந்த நிறைவு நிலையை அனுபவமாகச் செய்து எல்லை யில்லாத இன்பத்தையும் அருளுவான்.`,
  },
  {
    id: 1911, tantraId: 7, verseNumber: 1910,
    tamil: `அந்தமில் ஞானிதன் ஆகம் தீயினில்
வெந்திடின் நாடெலாம் வெப்புத் தீயினில்
நொந்து நாய்நரி நுகரின் நுண்செரு
வந்துநாய் நரிக்கு உணவாகும் வையகமே`,
    transliteration: `antamil ñāṉitaṉ ākam tīyiṉil
ventiṭiṉ nāṭelām vepput tīyiṉil
nontu nāynari nukariṉ nuṇceru
vantunāy narikku uṇavākum vaiyakamē`,
    english: `1910: Do not Consign Siva Jnani's Body to Fire; Nor Neglect it
If the body of Siva Jnani is to fire consigned,
The people entire will in burning fever suffer;
If his body a prey to dogs and jackals left,
Tumultous war the land will see,
And the people a prey to dogs and jackals be.`,
    elaborationEnglish: `If the body of the jnani is consigned to fire, the people of the land will burn in high fever. Disasters will follow and the land will be drought-affected without a drop of water. Famine will ravish the land creating numerous ravages in its train. If the jnani's body is left a prey to dogs and jackals, tumultuous war will seize the land.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 1912, tantraId: 7, verseNumber: 1911,
    tamil: `எண்ணிலா ஞானி உடல்எரி தாவிடில்
அண்ணல்தம் கோயில் அழல்இட்டது ஆங்கு ஒக்கும்
மண்ணில் மழைவிழா வையகம் பஞ்சமாம்
எண்ணரு மன்னர் இழப்பார் அரசே`,
    transliteration: `eṇṇilā ñāṉi uṭaleri tāviṭil
aṇṇaltam kōyil aḻaliṭṭatu āṅku okkum
maṇṇil maḻaiviḻā vaiyakam pañcamām
eṇṇaru maṉṉar iḻappār aracē`,
    english: `1911: Disasters Follow if Jnani's Body is Consigned To Fire
If to fire the Jnani's body is consigned
That will be unto fire the Lord's temple consigned;
No more will rains fall on the land,
Famine shall ravish the world,
Countless kings will their kingdoms lose.`,
    elaborationTamil: `இதன் பொருளும் வெளிப்படை.`,
  },
  {
    id: 1913, tantraId: 7, verseNumber: 1912,
    tamil: `புண்ணிய மாம்அவர் தம்மைப் புதைப்பது
நண்ணி அனல்கோக்கில் நாட்டில் அழிவாகும்
மண்ணில் அழியில் அலங்கார பங்கமாம்
மண்ணுலகு எல்லாம் மயங்கும் அனல்மண்டியே`,
    transliteration: `puṇṇiya māmavar tammaip putaippatu
naṇṇi aṉalkōkkil nāṭṭil aḻivākum
maṇṇil aḻiyil alaṅkāra paṅkamām
maṇṇulaku ellām mayaṅkum aṉalmaṇṭiyē`,
    english: `1912: Bury Jnani's Body in Proper Way
Proper indeed is to bury them;
If to fire they are consigned
Destruction dogs the land;
If left to perish, uncared for,
The world its prosperity loses,
A fell prey to devastating fire falls.`,
    elaborationEnglish: `The proper thing to do is to bury the jnani's body in the way the Agamic scriptures have laid down. Then many blessings will be conferred on the rulers and the people of the land.`,
    elaborationTamil: `மலங்கு ஆர - மனங்கலங்குதல் மிகும்படி, மண்ணில் அழிதல் - கேட்பாரின்றிக் கிடநத் அழிதல். ஏனையவை வெளிப்படை.`,
  },
  {
    id: 1914, tantraId: 7, verseNumber: 1913,
    tamil: `அந்தமில் ஞானி அருளை அடைந்தக்கால்
அந்த உடல்தான் குகைசெய்து இருந்திடில்
சுந்தர மன்னரும் தொல்புவி உள்ளோரும்
அந்தமில் இன்ப அருள்பெறு வாரே`,
    transliteration: `antamil ñāṉi aruḷai aṭaintakkāl
anta uṭaltāṉ kukaiceytu iruntiṭil
cuntara maṉṉarum tolpuvi uḷḷōrum
antamil iṉpa aruḷpeṟu vārē`,
    english: `1913: Bury Jnani's Body in an Underground Sepulchre
Let the body of Jnani,
When Lord's Grace receives,
Be in a cave seated,
Appropriate in earth's bowel dug;
Then stately rulers and people in land
Receive blessings,
Of Grace infinite.`,
    elaborationTamil: `இதன் பொருளும் வெளிப்படை.`,
  },
  {
    id: 1915, tantraId: 7, verseNumber: 1914,
    tamil: `நவமிகு சாணாலே நல்லாழம் செய்து
குவைமிகு சூழஐஞ் சாணாகக் கோட்டித்
தவமிகு குகைமுக் கோணமுச் சாணாக்கிப்
பவமறு நற்குகை பத்மா சனமே`,
    transliteration: `navamiku cāṇālē nallāḻam ceytu
kuvaimiku cūḻaaiñ cāṇākak kōṭṭit
tavamiku kukaimuk kōṇamuc cāṇākkip
pavamaṟu naṟkukai patmā caṉamē`,
    english: `1914: Samadhi Rituals
Well dig the sepulchre,
Heap the earth five cubits around,
Shape it into a triangle
Three cubits on sides;
And there in Padmasana,
Seat the body.`,
    elaborationTamil: `குகையை (நில அறையை) ஒன்பது சாண் ஆழமும் ஒரு பக்கத்திற்கு ஐந்து சாண் சதுரமும் ஆகச் செய்து அடியில் திருமேனி தவநிலையில் அமர்கின்ற ஆசனம் பக்கத்திற்கு மூன்றாக முக் கோணமாக அமைத்து, அதன் மேல் திருமேனியைப் பதுமாசனமாக இருத்துக.`,
  },
  {
    id: 1916, tantraId: 7, verseNumber: 1915,
    tamil: `தன்மனை சாலை குளங்கரை ஆற்றிடை
நன்மலர்ச் சோலை நகரின்நற் பூமி
உன்னரும் கானம் உயர்ந்த மலைச்சாரல்
இந்நிலம் தான்குகைக்கு எய்தும் இடங்களே`,
    transliteration: `taṉmaṉai cālai kuḷaṅkarai āṟṟiṭai
naṉmalarc cōlai nakariṉnaṟ pūmi
uṉṉarum kāṉam uyarnta malaiccāral
innilam tāṉkukaikku eytum iṭaṅkaḷē`,
    english: `1915: Samadhi Cave Locations
Locations
One's own homestead,
roadside, tank bund, riverbed,
Flowery grove, city's common
Forest dense, and mountain valley high
--These the sites appropriate,
For the abored to shape.`,
    elaborationEnglish: `One's own homestead, roadside, tank bund, riverbed, wooded grove, city's common, dense forest and high mountain valleys — these are the appropriate locations for a samadhi.`,
    elaborationTamil: `இதன் பொருளும் வெளிப்படை.`,
  },
  {
    id: 1917, tantraId: 7, verseNumber: 1916,
    tamil: `நற்குகை நால்வட்டம் பஞ்சாங்க பாதமாய்
நிற்கின்ற பாதம் நவபாதம் நேர்விழப்
பொற்பமா ஓசமும் மூன்றுக்கு மூன்றுஅணி
நிற்பவர் தாம் செய்யும் நேர்மைய தாமே`,
    transliteration: `naṟkukai nālvaṭṭam pañcāṅka pātamāy
niṟkiṉṟa pātam navapātam nērviḻap
poṟpamā ōcamum mūṉṟukku mūṉṟuaṇi
niṟpavar tām ceyyum nērmaiya tāmē`,
    english: `1916: Dimension For the Sepulchre Cave
Five feet on four sides all,
Nine feet straight deep,
Three feet each on the triangle's sides
--These the dimensions
Appropriate for the sepulchre to shape.`,
    elaborationEnglish: `The sepulchure should have the correct dimensions — five feet on all the four sides, nine feet deep, and three feet each on the inner triangle’s sides at the base.`,
    elaborationTamil: `நில அறையின் மேலே அழகிய கோயில் ஐந்து அடிக்கு ஐந்து அடிச் சதுரமாய், உயரம் ஒன்பதடியாக மும்மூன்று அடி உயரத்தில் ஒவ்வொரு நிலையாய் மூன்று நிலைகள் தோன்றும்படி அமைத்தல் முறையாகும்.`,
  },
  {
    id: 1918, tantraId: 7, verseNumber: 1917,
    tamil: `பஞ்ச லோகங்கள் நவமணி பாரித்து
விஞ்சப் படுத்துஅதன் மேல்ஆ சனம்இட்டு
முஞ்சிப் படுத்துவெண் ணீறு இட்ட தன்மேலே
பொன்செய் நற்சுண்ணம் பொதியலும் ஆமே`,
    transliteration: `pañca lōkaṅkaḷ navamaṇi pārittu
viñcap paṭuttuataṉ mēlā caṉamiṭṭu
muñcip paṭuttuveṇ ṇīṟu iṭṭa taṉmēlē
poṉcey naṟcuṇṇam potiyalum āmē`,
    english: `1917: Samadhi Rituals
In abundance spread the five metals precious
And the nine gems rare;
Upon them place the seat,
Scatter the Kusha grass,
And shower the holy ashes white;
Above that scatter
Turmeric powder that is of color gold
And incenses richly mixed.`,
    elaborationEnglish: `Spread the five precious metals and the nine rare gems within, the cave. Place the seat. Upon that, scatter kusa grass and shower with white holy ashes. Above them scatter the golden-coloured turmeric powder mixed with incenses.`,
    elaborationTamil: `நில அறையின் அடியில் ஐம்பொன்களும், ஒன்பான் மணிகளும் நிரம்ப இட்டு மூடி, அதன்மேல் மேற்கூறிய முக்கோண பீடத்தை அமைத்து, அதன்மேல் தருப்பையைப் பரப்பி, திருவெண்ணீற்றைத் திருமேனிக்கு அடியிலும், சுற்றிலும், மேலேயும் நிரம்ப இட்டு, அதன்மேல் பொன்னிறமாய் உள்ள நறுமணப் பொடியை மிகுதியாகத் தூவுதலும் சிறப்புடையதாகும்.`,
  },
  {
    id: 1919, tantraId: 7, verseNumber: 1918,
    tamil: `நள்குகை நால்வட்டம் படுத்துஅதன் மேல்சாரக்
கள்ளவிழ தாமம் களபம்கத் தூரியும்
தெள்ளிய சாந்து புழுகுபன் னீர்சேர்த்து
ஒள்ளிய தூபம் உவந்திடு வீரே`,
    transliteration: `naḷkukai nālvaṭṭam paṭuttuataṉ mēlcārak
kaḷḷaviḻa tāmam kaḷapamkat tūriyum
teḷḷiya cāntu puḻukupaṉ ṉīrcērttu
oḷḷiya tūpam uvantiṭu vīrē`,
    english: `1918: Samadhi Rituals (Cont.)
Shape the cave inside into a square,
Upon that lay garlands of honey-dew flowers;
Sandal, musk, civet, and unguents diverse;
And pouring rose's water
Light the ritual lamp, in devotion ecstatic.`,
    elaborationEnglish: `Lay garlands of honey-dew flowers, sandal, musk, civet and diverse unguents upon the cave that is square-shaped inside. Sprinkling rose water, light the ritual lamp with devotion and affection.`,
    elaborationTamil: `நடுவில் நில அறை இருக்க, நாற்புறத்திலும் மேலே வரம்பு அமைத்தபின், அதற்கு மேற்கு பக்கத்தில் நிலத்தின்மேல் ஆசனத் தின்மேல் திருமேனியை எழுந்தருளப் பண்ணி, சந்தனத்தின் கருப்பூரம் முதலியவை கலந்த குழம்பு, தனியாக இழைத்த சந்தனம், புனுகு, பனிநீர் முதலியவை களால் திருமுழுக்குச் செய்வித்து, தேன் துளிக்க மலரும் பூவால் ஆகிய மாலையைச் சார்த்தி, தூப தீபம் காட்டுக.`,
  },
  {
    id: 1920, tantraId: 7, verseNumber: 1919,
    tamil: `ஓதிடும் வெண்ணீற்றால் உத்தூளம் குப்பாயம்
மீதினில் இட்டுஆ சனத்தினின் மேல் வைத்துப்
போதறு கண்ணமும் நீறும் பொலிவித்து
மீதில் இருத்தி விரித்திடு வீரே`,
    transliteration: `ōtiṭum veṇṇīṟṟāl uttūḷam kuppāyam
mītiṉil iṭṭuā caṉattiṉiṉ mēl vaittup
pōtaṟu kaṇṇamum nīṟum polivittu
mītil irutti virittiṭu vīrē`,
    english: `1919: Samadhi Rituals (Cont.)
Smear the body entire with ashes white and holy
To form a shroud protective;
Place the body on an Asana (seat) appropriate,
Spangle bright with incenses several and ashes holy;
And thus seated, cover the cave with earth.`,
    elaborationEnglish: `The white holy ashes will form a protective shroud over the entire body. Then place the body in an appropriate asana (posture). Thus seated, cover the cave with earth.`,
    elaborationTamil: `தூப தீபம் காட்டுதல் முதலியவற்றைச் செய்தபின் திருநீற்றைத் திருமேனிமேல் குப்பாயம் போல மிகுதியாகப் பூசி, நில அறையில் அமைத்துள்ள பீடத்தின் மேல் மலர்கள், நறுமணப்பொடி, திருநீறு இவைகளை இட்டு, மேலே திருமேனியை எடுத்து இருத்திச் சுற்றிலும் ஆடையைச் சூழ வையுங்கள்.`,
  },
  {
    id: 1921, tantraId: 7, verseNumber: 1920,
    tamil: `விரித்தபின் நாற்சாரும் மேவுதல் செய்து
பொரித்த கறிபோ னகம் இள நீரும்
குருத்தலம் வைத்துஓர் குழைமுகம் பார்வை
தரித்தபின் மேல்வட்டம் சாத்திடு வீரே`,
    transliteration: `virittapiṉ nāṟcārum mēvutal ceytu
poritta kaṟipō ṉakam iḷa nīrum
kuruttalam vaittuōr kuḻaimukam pārvai
tarittapiṉ mēlvaṭṭam cāttiṭu vīrē`,
    english: `1920: Samadhi Rituals (Cont.)
Having covered thus, level the four sides;
Place his sandals and ear rings,
And an image with face and eyes
Decked in dress appropriate;
Offer parched rice, food,
and tender coconut.`,
    elaborationEnglish: `Having covered him thus, place his sandals, ear rings and an image with face and eyes decked in suitable dress. Also offer parched rice, food and a tender coconut.`,
    elaborationTamil: `குகையில் திருமேனியைச் சுற்றி ஆடையால் மூடியபின் குகையின் மேல நான்கு பக்கங்களிலும் பல வகையான படையற் பொருள்களை வாழைக் குருத்தின்மேல் மேல் இட்டு நிவேதித்த பின்பு திருமேனியைப் பரிவட்டத்தால் மூடிவிடுங்கள்.`,
  },
  {
    id: 1922, tantraId: 7, verseNumber: 1921,
    tamil: `மீது சொரிந்திடும் வெண்ணீறும் கண்ணமும்
போது பலகொண்டு தர்ப்பைப்புல் வில்வமும்
பாத உதகத்தான் மஞ்சனம் செய்துபார்
மீதுமூன் றுக்குமூன்று அணிநிலம் செய்யுமே`,
    transliteration: `mītu corintiṭum veṇṇīṟum kaṇṇamum
pōtu palakoṇṭu tarppaippul vilvamum
pāta utakattāṉ mañcaṉam ceytupār
mītumūṉ ṟukkumūṉṟu aṇinilam ceyyumē`,
    english: `1921: Samadhi Rituals (Cont.)
Then pour the ashes white and powdered incense,
Shower flowers diverse, Kusha grass and Bilva leaves,
Sprinkle water holy,
And raise a platform three feet by three.`,
    elaborationEnglish: `Finally pour some holy ashes and holy water upon the diverse
flowers, kusa grass and bilva leaves that are overspread, and
raise a platform three feet by three.`,
    elaborationTamil: `திருமேனியைப் பரிவட்டத்தால் மூடிய பின்பு திருவெண்ணீறு, மணப்பொடி, பலவகை மலர்கள், தருப்பைப்புல், வில்வ இலை முதலியவைகளை நிரம்பச் சொரியுங்கள்; பின் அருக்கியம் முதலியவைகளைக் கொடுத்துக் கோயில் எடுத்தற்குரிய தொடக்கத்தைச் செய்து விடுங்கள்.`,
  },
  {
    id: 1923, tantraId: 7, verseNumber: 1922,
    tamil: `ஆதன மீதில் அரசு சிவலிங்கம்
போதும் இரண்டினில் ஒன்றைத் தாபித்து
மேதரு சந்நிதி மேவுத் தரம்பூர்வம்
காதலில் சோடசம் காண்உப சாரமே`,
    transliteration: `ātaṉa mītil aracu civaliṅkam
pōtum iraṇṭiṉil oṉṟait tāpittu
mētaru canniti mēvut tarampūrvam
kātalil cōṭacam kāṇupa cāramē`,
    english: `1922: Samadhi Pujas
Upon the platform plant
The sapling of peepal tree, or a Lingam holy,
Arrange the Sannidhi (face) toward north or east
And perform pujas with rituals sixteen,
In devotion endearing.`,
    elaborationEnglish: `In devotion endearing.

Plant the sapling of a peepal tree or a holy lingam on the
platform, with the sannidhi (face) toward north or east. Then
perform pujas with sixteen items in endearing devotion.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 1924, tantraId: 7, verseNumber: 1923,
    tamil: `உதயத்தில் விந்துவில் ஓங்குகுண் டலியும்
உதயக் குடிலில் வயிந்தவம் ஒன்பான்
விதியில் பிரமாதி கள்மிகு சத்தி
கதியில் கரணம் கலைவை கரியே`,
    transliteration: `utayattil vintuvil ōṅkukuṇ ṭaliyum
utayak kuṭilil vayintavam oṉpāṉ
vitiyil piramāti kaḷmiku catti
katiyil karaṇam kalaivai kariyē`,
    english: `1923: Devolutes of Bindu
When Creation commenced,
From Para Bindu arose Kundalini
And from Kudilai the Vaindavam in the firmament vast
And the nine gods Brahma and the rest
And their Saktis
And in order corresponding
The Karanas, the Kalas and the sound Vaikari (Nada).`,
    elaborationEnglish: `When creation began, kundalini arose from parabindu. From kudilai arose the vaindavams — the nine gods Brahma and the rest with their Saktis, the karmas, the kalas and the sound vaikari.

1) Kundalini, kudilai, tatparai, vagesi are emanations of

parabindu.

2) Nine vaindavams are the emanations of parabindu — the

four above (i.e., kundalini etc) and the five gods: Sadasiva,

Brahma, Vishnu, Rudra, and Mahesvara.

3) Saktis-Saktis of these five Gods.

4) Karanas—the intellectual organs: manas, buddhi, chitta,

and ahamkara.

5) Kalas—five kala tattvas.

6) Vaikari—the unmanifested sound.`,
    elaborationTamil: `முழுப்படைப்புக் காலத்தில் முதற்கண் சுத்த மாயா காரியங்களே தோன்றும். அக்காரியம் வாக்குகளும், இறைவனது நவந்தரு பேதங்கட்கும் இடமாய் நிற்கும் சுத்த தத்துவங்களும் ஆகும். நவந்தரு பேதங்களை ஒடுக்க முறையில் வைத்து எண்ணினால் பிரமன் முதலியனவாக அமையும். புண்ணியம் காரணமாக இறைவனது அதிகார சத்தி பதிதலால் அப்பெயர் பெற்று நிற்கும் அணுபக்கத் தினரும் உளர். அது நிற்க. வேறு பிரமனாதியர்க்கும், மற்றும் நால்வகை வாக்கிற்கும், அனைத்துப் பொருள்கட்கும் இடமாய் நிற்பன பஞ்சகலைகள்.`,
  },
  {
    id: 1925, tantraId: 7, verseNumber: 1924,
    tamil: `செய்திடும் விந்துபே தத்திறன் ஐ ஐந்தும்
செய்திடும் நாதபேதத்திற னால் ஆறும்
செய்திடும் மற்றவை ஈர்இரண்டில்திறம்
செய்திடும் ஆறுஆறு சேர்தத் துவங்களே`,
    transliteration: `ceytiṭum vintupē tattiṟaṉ ai aintum
ceytiṭum nātapētattiṟa ṉāl āṟum
ceytiṭum maṟṟavai īriraṇṭiltiṟam
ceytiṭum āṟuāṟu cērtat tuvaṅkaḷē`,
    english: `1924: Thirty Six Tattvas Devolute
Bindu attains modification five times five (twenty-five)
Nada attains modification four and six (ten)
The rest two--Sakti and Siva--attain not modification
But activate the other two--Bindu and Nada.`,
    elaborationEnglish: `Sakti and Siva attain no modifications, but active the other two — bindu and nada — which attain twenty-five and ten modifications (as atma tattvas and higher tattvas) respectively.

1) 25 Evolutes of parabindu are: the nine vaindavams, the five saktis of the five Gods; four intellectual organs; five kala lattvas; vaikhari, the unmanifest sound; and niyati tattva evolutes of nada are: , 1. kala (time); 2. vidya (knowledge); 3. raga (desire); 4. purusha (the experience of the soul); 5. maya (illusion) and the five suddha tattvas —- suddha vidya, isvdram, sadakyam, Sakti and Siva.`,
    elaborationTamil: `நவந்தரு பேதங்களில் நாதங்களும், விந்துக்களும் முறையே சிவமும், சத்தியும் ஆதலால் சிவனது 'இலயம், போகம், அதிகாரம்' என்னும் மூற்று நிலைகளுள் அதிகார நிலையாகிய மகேசுரனது பேதங்கள் இருபத்தைந்தினையும் 'சத்தியின் காரியங்கள்' என்றும், நவந்தரு பேதங்களில் விந்து, சத்தி இவை யொழிந்த ஏழும், குணமூர்த்திகள் மூவரும் ஆகப் பதின்மரும் நாயக, நாயகி பாவத்தில் நாயகர்கள் ஆதலால் அவர்களையே, 'சிவ பேதங்கள்' என்றும் ஒருவாறு கூறலாம். இனி அந்தச் சத்தி சிவங்கள் ''சகுணம், சமலம், நின்மலம், ஆனந்தம்'' என்னும் காரணத்தால் நான்காகின்ற மாயையின் வகை மூன்றினின்றும் முப்பத்தாறு தத்துவங்களையும் வகைப்படத் தோற்றுவிக்கும்.`,
  },
  {
    id: 1926, tantraId: 7, verseNumber: 1925,
    tamil: `வந்திடு பேத மெலாம்பர விந்துமேல்
தந்திடு மாமாயை வாகேசி தற்பரை
உந்து குடிலையோடு ஏமுறு குண்டலி
விந்துவில் இந்நான்கும் மேவா விளங்குமே`,
    transliteration: `vantiṭu pēta melāmpara vintumēl
tantiṭu māmāyai vākēci taṟparai
untu kuṭilaiyōṭu ēmuṟu kuṇṭali
vintuvil innāṉkum mēvā viḷaṅkumē`,
    english: `1925: Saktis Devolute from Bindu
All these manifestations
Vagesi, Tatparai,
Kudilai and Kundalini;
These Saktis four ultimate from Bindu evolute.`,
    elaborationEnglish: `The saktis — vagesi, tatparai, kudilai and kundalini evolve
from bindu.`,
    elaborationTamil: `மாயா காரியங்களாய் உள்ள பலவற்றிற்கும் காரணமாய் நிற்பது 'பரவிந்து' என்னும் தத்துவம். அது சுத்த மாயையின் காரியமே எனினும் அதன்கண்ணே 'அபர வாகீசுவரி, பரவாகீசுவரி', அனைத்து மந்திரங்களையும் செலுத்துகின்ற பிரணவம், அதன வடிவமாகிய குண்டலி என்னும் நான்கும் பொருந்தி விளங்கும்.`,
  },
  {
    id: 1927, tantraId: 7, verseNumber: 1926,
    tamil: `விளங்கு நிவர்த்தாதி மேலக ராதி
வளங்கொள் உகாரம் மகாரத் துள்விந்து
களங்கமில் நாதாந்தம் கண்ணினுள் நண்ணி
உளங்கொள் மனாதியுள் அந்தமும் ஆமே`,
    transliteration: `viḷaṅku nivarttāti mēlaka rāti
vaḷaṅkoḷ ukāram makārat tuḷvintu
kaḷaṅkamil nātāntam kaṇṇiṉuḷ naṇṇi
uḷaṅkoḷ maṉātiyuḷ antamum āmē`,
    english: `1926: Kalas Nada and Karanas Devoluted
The Kalas Nivirti and the rest,
In which repose sounds "A", "U" and "M" composed
There in Nadanta Bindu enters
And into the Karanas that include the Mind
And the internal organs intellectual
Devolute manifesting these
The Bindu its act of creation ceases.`,
    elaborationEnglish: `The kalas (nivirthi and the rest in which the sounds, ‘A,’
“U,” and ‘M’ repose), the karanas (that include the mind and
the internal intellectual organs) and nada evolve from bindu.

1) Nivirtikala — this dispels doubts of the jivas who reach
its sphere.

Pratista kala — firms up the jiva in truth.

_Vidya kala — confers jnana.

Santi kala — confers equipoise.
Santyatita kala — confers manifestness (svarupa) beyond
equipose.`,
    elaborationTamil: `நிவர்த்தி, பிரதிட்டை, வித்தை, சாந்தி, சாந்திய தீதை என்னும் பஞ்சகலைகளில் முறையே பொருந்தி நிற்கின்ற அகாரம், உகாரம், மகாரம், விந்து, நாதம் - என்னும் சூக்கும பஞ்சாக்கரங்கள் முறையே மனம் முதலாகப் புருடன் ஈறாக உள்ள கருவிகளைச் செலுத்தி நிற்கும்.`,
  },
  {
    id: 1928, tantraId: 7, verseNumber: 1927,
    tamil: `அந்தமும் ஆதியும் ஆகிப் பராபரன்
வந்த வியாபி எனலாய அந்நெறி
கந்தம தாகிய காரண காரியம்
தந்துஐங் கருமமும் தான்செய்யும் வீயமே`,
    transliteration: `antamum ātiyum ākip parāparaṉ
vanta viyāpi eṉalāya anneṟi
kantama tākiya kāraṇa kāriyam
tantuaiṅ karumamum tāṉceyyum vīyamē`,
    english: `1927: Bindu is the Causal Seed of Five Acts
The Parapara that is the End and the Beginning
Immanent, He expands thus;
As Cause and Effect, too, well He is;
And as Bija
The Five Acts performs.`,
    elaborationEnglish: `The Parapara is the end and the beginning, and immanently abides. Bija is the causal seed of the Five Acts too. The cosmic universe arose by the power of bija. Bija is the macro and the micro causal seed.`,
    elaborationTamil: `முதல்வன் உலகத்திற்கு முதலும், முடிவுமாகி, அதனுள் எங்கும் நிறைந்து நிற்கும் முறைமையால் பல தொகுதிகளாய் நிற்கும் காரண காரியப் பொருள்களைத் தோற்றுவித்து, அவன் ஐந் தொழில் செய்ய முதற்கருவியாய் நிற்பது விந்துவாகிய சுத்த மாயையே.`,
  },
  {
    id: 1929, tantraId: 7, verseNumber: 1928,
    tamil: `வீயம தாகிய விந்துவின் சத்தியால்
ஆய அகண்டமும் அண்டமும் பாரிப்பக்
காயஐம் பூதமும் காரிய மாயையில்
ஆயிட விந்து அகம்புறம் ஆகுமே`,
    transliteration: `vīyama tākiya vintuviṉ cattiyāl
āya akaṇṭamum aṇṭamum pārippak
kāyaaim pūtamum kāriya māyaiyil
āyiṭa vintu akampuṟam ākumē`,
    english: `1928: Bija is the Macro and Micro Causal Seed
By the power of Bija that from Bindu emanated
The world and the cosmic universe arose
From out of Casual (Asuddha) Maya (Stuff of matter)
Arose the elements five--the sky and the rest;
And this Bindu, micro and macro, is.`,
    elaborationTamil: `அனைத்திற்கும் முதற் காரணமாகிய சுத்த மாயை யின் ஆற்றலால் அனைத்திற்கும் வியாபகமாகிய நிவிர்த்தி முதலிய கலைகளும், அவற்றுள் அடங்கி நிற்கும் புவனங்களும் விரிந்து நிற்க, காரிய மாயையாகிய மூலப் பிரகிருதியினின்றும் பௌதிக சரீரத்திற்குக் காரணமாகிய ஐம்பூதங்களும் தோன்ற, சுத்தமாயை அவை அனைத்திலும் உள்ளும், புறம்புமாய் நிறைந்து நிற்கும்.`,
  },
  {
    id: 1930, tantraId: 7, verseNumber: 1929,
    tamil: `புறம்அகம் எங்கும் புகுந்துஒளிர் விந்து
நிறமது வெண்மை நிகழ்நாதம் செம்மை
உறமகிழ் சத்தி சிவபாதம் ஆயுள்
திறனொடு வீடுஅளிக் கும்செயல் கொண்டே`,
    transliteration: `puṟamakam eṅkum pukuntuoḷir vintu
niṟamatu veṇmai nikaḻnātam cemmai
uṟamakiḻ catti civapātam āyuḷ
tiṟaṉoṭu vīṭuaḷik kumceyal koṇṭē`,
    english: `1929: Bindu is White and Nada Red
The Bindu that shines
Within the body and without (in all Nature)
Is white in hue;
Red is vibrant Nada;
As Sakti and Siva embedded within
Well can they Mukti grant,
If in wisdom activated.`,
    elaborationEnglish: `Bindu is white in hue, shining within and without the body,
and in all nature. Nada that is vibrant is red-hued. They are
Siva and Sakti embedded within. They can well grant mukti.
Osrest_Qau ass) ugwwCunh Gargsp`,
    elaborationTamil: `பிண்டத்தில் கரு உற்பத்திக் காரணமாய் ஆண் உடலில் வெண்ணிறம் உடைமை பற்றி, 'சுக்கிலம்' எனப்படுகின்ற தாது 'விந்து' எனப்பெயர் பெற்றதனை அண்டத்தில் புறம், அகம் என்னும் வேறுபாடின்றி எவ்விடத்தும் வியாபகமாய் நிற்கும் காரணப் பொருளாகிய 'சுத்த மாயை' என்றே கொள்ளுதல் வேண்டும். (நாதத்தின் காரியத்தை 'விந்து' என்னும் தத்துவமாகக் கொள்ள லாகாது' - என்பதாம்.) இனப் பெண்ணுடலில் செந்நிறம் உடைமை பற்றி, சோணிதம்' எனப்படுகின்ற தாது, காரியப் பொருளாகிய நாதம்' எனத் தக்கதாகும். ஆகவே அவை முறையே முதல்வனாகிய சிவனது கூறும், அவனுக்குத் துணைவியாகிய சத்தியது கூறுமேயாகும், (அவ்வாறில்லை யேல் அவை உயிர்க்கு இன்றியமையாக் கருவிகளாகிய தனு கரணங் களைத் தோற்றுவித்தல் இயலாது என்பதாம்.) அவை அங்ஙனமாய்த் தனுகரணங்களைத் தோற்றுவித்து உயிர்கட்கு மன உறுதியுடன் செய்யும் ஞானச் செய்தி வாயிலாக வீட்டைத் தருவனவாம்.`,
  },
  {
    id: 1931, tantraId: 7, verseNumber: 1930,
    tamil: `கொண்டஇவ் விந்து பரமம்போல் கோதற
நின்ற படம்கட மாய்நிலை நிற்றலின்
கண்டக லாதியின் காரண காரியத்து
அண்டம் அனைத்துமாய் மாமாயை ஆகுமே`,
    transliteration: `koṇṭaiv vintu paramampōl kōtaṟa
niṉṟa paṭamkaṭa māynilai niṟṟaliṉ
kaṇṭaka lātiyiṉ kāraṇa kāriyattu
aṇṭam aṉaittumāy māmāyai ākumē`,
    english: `1930: Bindu is Cause-Effect
All-pervasive unto the Param
The Bindu stands;
Veiling all unto a filament vast;
And filling everywhere as the space in pots all;
As Mamaya that is Cause and Effect
It all cosmos pervades.`,
    elaborationEnglish: `Bindu stands with the all-pervasive Param; bindu as mamaya is the cause and effect, and it pervades all the cosmos.`,
    elaborationTamil: `உயிர்களை மேற்கூறியவாறு அண்டத்தையே யன்றிப் பிண்டத்தையும் ஆட்கொள்கின்ற விந்து பரம்பொருளைப் போலவே மல கன்மங்களோடு விரவுதலின்றித் தூயதாய், ஆயினும் நூலும் மண்ணும், ஆடையும் குடமுமாய்க் காரியப்படுதல் போலக் காரியப்படுவதாய், காரண ரூபத்தில் என்றும் அழிவின்றி, கலை முதலிய தத்துவங்களின் காரியமாய் உள்ள அனைத்து அண்டங் களிலும் அவையேயாய்க் கலந்து பெருமாயையாய் உள்ளது.`,
  },
  {
    id: 1932, tantraId: 7, verseNumber: 1931,
    tamil: `அதுவித்தி லேநின்று அங்கு அண்ணிக்கும் நந்தி
இதுவித்தி லேஉள வாற்றை உணரார்
மதுவித்தி லேமலர் அன்னம தாகிப்
பொதுவித்திலே நின்ற புண்ணியன் தானே`,
    transliteration: `atuvitti lēniṉṟu aṅku aṇṇikkum nanti
ituvitti lēuḷa vāṟṟai uṇarār
matuvitti lēmalar aṉṉama tākip
potuvittilē niṉṟa puṇṇiyaṉ tāṉē`,
    english: `1931: Bindu is the Seed in the body and Divine Swan in
Cosmos
There in the Bindu,
Nandi stands His Grace to bestow;
That it is in their Bija within, they know not;
That Seed as scented flower in the (body) into microcosm blossoms
As a Divine Swan So-ham in the macrocosm it is;
He the Blessed One that is the Causal Seed of all.`,
    elaborationEnglish: `Nandi stands in the bindu to bestow His manifold blessings
and Grace. They do not know that bindu is the seed that
blossoms as a scented flower in the body and a divine swan
in the cosmos. Bija is the blessed one, that is.the causal
seed of all.`,
    elaborationTamil: `'அது' எனச் சேய்மையாதாகச் சுட்டிச் சொல்லப் படுகின்ற மகாமாயையாகிய அந்த விந்துவிலே நின்று, அதனை அடைந்தவர்க்கு இனிப்பவனாகிய சிவன், 'இது' என அண்மையாகச் சுட்டிச் சொல்லப்படுகின்ற சுக்கிலமாகிய இந்த விந்துவிலும் நின்று உயிர்களைப் பிறப்பித்துப் பின் வீடடையச் செய்தலை உணரும் உணர்வுடையார் உலகத்து அரியர், ஆயினும், மகாமாயையையே தனக்கு உடமாகக் கொண்டு விளங்குகின்ற அந்தப்பெருமான், நீரால் உண்டாக்கின்ற உணவுப்பொருளில் தங்கிப் பின் கருவுற்பத்திக்கு யாவரிடத்தும் பொதுவாய் உள்ள காரணமாகின்ற விந்துவிலும் இருக்கும் புண்ணியன் ஆகின்றான்.`,
  },
  {
    id: 1933, tantraId: 7, verseNumber: 1932,
    tamil: `வித்தினில் அன்றி முளையில்லை அம்முளை
வித்தினில் அன்றி வெளிப்படு மாறில்லை
வித்தும் முளையும் உடனன்றி வேறில்லை
அத்தன்மை யாரும் அரன்நெறி காணுமே`,
    transliteration: `vittiṉil aṉṟi muḷaiyillai ammuḷai
vittiṉil aṉṟi veḷippaṭu māṟillai
vittum muḷaiyum uṭaṉaṉṟi vēṟillai
attaṉmai yārum araṉneṟi kāṇumē`,
    english: `1932: Siva is Seed, Bindu is Embryo
Without seed is embryo none,
Except from seed the embryo appears not;
The seed and the embryo are but one, separate never;
Thus are the Bindu and Siva too;
This you should know.`,
    elaborationEnglish: `Seed and embryo are inseparable. Without the one the other cannot fructify or survive. Siva is the seed, and bindu is the embryo.`,
    elaborationTamil: `முளை விதையில்தான் உள்ளது. என்றாலும் அது விதை தனியேயிருக்கும்பொழுது தோன்றாது. நிலத்தில் விதைத்தால் தான் தோன்றும். 'வித்தில் முளை உள்ளது' என்றால், அது 'குடத்தில் நீர் உள்ளது' என்பது போல்வதன்று. அஃதாவது இடமும், இடத்து நிற்கும் பொருளும் ஆகின்ற அவ்வளவினது அன்று. சிலந்தியின் உடம்பும், அதினின்றும் வெளிவருகின்ற நூலும் போலக் காரண காரிய இயைபுடையனவாம். அது போன்றதே சிவன் உலகத்தைத் தோற்றுவிக்கின்ற முறையும்.`,
  },
  {
    id: 1934, tantraId: 7, verseNumber: 1933,
    tamil: `அருந்திய அன்னம் அவைமூன்று கூறாம்
பொருந்தும் உடல்மனம் போம்மலம் என்னத்
திருந்தும் உடன்மன மாம் கூறு சேர்ந்திட்டு
இருந்தன முன்னாள் இரதமது ஆகுமே`,
    transliteration: `aruntiya aṉṉam avaimūṉṟu kūṟām
poruntum uṭalmaṉam pōmmalam eṉṉat
tiruntum uṭaṉmaṉa mām kūṟu cērntiṭṭu
iruntaṉa muṉṉāḷ iratamatu ākumē`,
    english: `1933: How Food Builds Body, Blood and Mind
The food you partake in divisions three go
To the body, to the mind and to the excreta;
The parts that to the body and the mind go
Verily become the blood, first.`,
    elaborationEnglish: `The food you take goes in three directions — to the body,
to the mind, and to the excreta. ;`,
    elaborationTamil: `பலவகையாக உண்ணப்பட்ட உணவுகள் மூன்று கூறுபடும். ஒரு கூறு உடம்பாய்ப் பரிணமிக்கும். மற்றொரு கூறு மனத்தின் தன்மையாய் அமையும். இன்னொரு கூறு மலமாகிக் கழிந்தொழியும். உணவால் திருத்தம் உறுகின்ற உடம்பும், மனமும் சேர்ந்து முன்னாட்களில் காரண நிலையில் 'சாரம்' என்பதாய் இருக்கும்.`,
  },
  {
    id: 1935, tantraId: 7, verseNumber: 1934,
    tamil: `இரதம் முதலான ஏழ்தாது மூன்றில்
உரிய தினத்தில் ஒருபுல் பனிபோல்
அரிய துளிவிந்து வாகும்ஏழ் மூன்றின்
மருவிய விந்து வளரும்கா யத்திலே`,
    transliteration: `iratam mutalāṉa ēḻtātu mūṉṟil
uriya tiṉattil orupul paṉipōl
ariya tuḷivintu vākumēḻ mūṉṟiṉ
maruviya vintu vaḷarumkā yattilē`,
    english: `1934: How Bindu is Formed From Food
Out of the seven constituents food breaks into,
(Blood, lymph, bone, skin, flesh, brain and semen)
The Bindu forms in days three
Unto the tiny dew drop on a blade of grass;
And full matures in days three times seven.`,
    elaborationEnglish: `Blood, lymph, bone, skin, flesh, brain and semen are the seven
products of food. The bindu that is formed like the tiny drop
on a blade of grass matures seven times in three days.`,
    elaborationTamil: `மேல் சொல்லப்பட்ட 'சாரம்' என்பது உட்பட ஏழ் தாதுக்களில் மூன்றிலிருந்து சில நாட்களில் புல் நுனியிற் பனியளவான துளிகள் பல உருவாகும். அந்தத் துளிகளே பிண்ட உற்பத்திக்குக் காரணமான 'விந்து' எனக் குறிப்பிட்டுக் கூறப்படுகின்றன. அவை இருபத்தொரு நாள் வரையில் உடம்பினுள் அந்த நிலையிலே முதிர்ந்து வரும்.`,
  },
  {
    id: 1936, tantraId: 7, verseNumber: 1935,
    tamil: `காயத்தி லேமூன்று நாளில் கலந்திட்டுக்
காயத்துள் தன்மனம் ஆகும் கலாவிந்து
நேயத்தே நின்றோர்க்கு நீங்கா விடாமையின்
மாயத்தே செல்வோர் மனத்தோடு அழியுமே`,
    transliteration: `kāyatti lēmūṉṟu nāḷil kalantiṭṭuk
kāyattuḷ taṉmaṉam ākum kalāvintu
nēyattē niṉṟōrkku nīṅkā viṭāmaiyiṉ
māyattē celvōr maṉattōṭu aḻiyumē`,
    english: `1935: Bindu is Transformed into Mind and Kalas
When in the body for three days it remains thus,
It becomes a part of the Mind;
As Kala Bright--Intelligence illumined;
For those immersed in thoughts holy, it is there retained;
For those who in sex intercourse indulge,
It will depart, their mental powers deteriorated.`,
    elaborationEnglish: `Remaining thus in,the body for three days, it becomes a part of the mind, as shining kalas. They who are steeped in profound holy thoughts will retain it.`,
    elaborationTamil: `மேற்கூறியவாறு முன் இருபத்தொரு நாள் வரையில் முதிர்ந்து வந்த விந்துக்கள் பின் இருபத்தொரு நாட்கள் வரையில் மனத்தின் வழிப்பட்டு நிற்கும். 'சத்தி நிபாதரும், உலகரும்' எனமக்கள் இருதிறத்ததராதலின் அவருள் சத்திநிபாதர் மனம் சிவன் பஞ்சமூர்த்திகளாய் விளங்கி நிற்கின்ற நிவிர்த்தி முதலிய பஞ்ச கலா ரூபமாய் நிற்கும் சுத்த மாயையை நோக்கிச் செல்லுமாகலின் அவர் காம வசப்பட்டு விந்துவை வெளியே வீழ்ந்தொழிய விடாமையின் அவை அவரை விட்டு நீங்கா. (அவரது மனம் பஞ்ச கலைகளை நோக்கிச் செல்கின்ற செலவிற்கு அவை வலிமை தந்து நிற்கும் என்பதாம். அவரொழிந்த ஏனை உலகர் சிறிதுபோதிலே நிலையின்றி ஒழிவதாகிய காம இன்பத்திலே செல்பவர் ஆதலின் அவர் மனம் அங்ஙனம் சென்ற பொழுது அவரது விந்துக்களும் அதனுடன் சென்று வெளியே வீழ்ந்து அழிந்தொழியும்.`,
  },
  {
    id: 1937, tantraId: 7, verseNumber: 1936,
    tamil: `அழிகின்ற விந்து அளவை அறியார்
கழிகின்ற தன்னையுட் காக்கலும் தேரார்
அழிகின்ற காயத்து அழிந்துஅயர் உற்றோர்
அழிகின்ற தன்மை அறிந்தொழி யாரே`,
    transliteration: `aḻikiṉṟa vintu aḷavai aṟiyār
kaḻikiṉṟa taṉṉaiyuṭ kākkalum tērār
aḻikiṉṟa kāyattu aḻintuayar uṟṟōr
aḻikiṉṟa taṉmai aṟintoḻi yārē`,
    english: `1936: Waste Bindu, the Body Perishes
They know not the destruction that wasting of Bindu results in;
They resolve not their decay to prevent by will power determined;
They who thus perish in this perishing body
Know not the way they perish;
And give it up not.`,
    elaborationTamil: `உலகர் தாம் செல்கின்ற போக நெறியால் அழிந் தொழிகின்ற விந்துவினது ஆற்றலை, 'இவ்வளவினது' என்று அறிய மாட்டார்கள். அதனால் கீழ்நோக்கி வீழும் இயல்புடைய அந்த விந்துவை அவ்வாறு வீழாது உள்ளே நிறுத்திக் காக்கும் வழியைப்பற்றி அவர்கள் எண்ணுவதும் இல்லை. அழிவைத் தனது இயல்பாக உடைய உடம்பினுள்ளே தங்கியிருந்து, அவ்வுடம்பால் உண்டாகின்ற பல இடுக்கண்களால் துன்பமுற்று மெலிகின்றவர்கள் தாம் பெற்றுள்ள பொருள்கள் அழியுந்தன்மை உடையவாதலை அறிந்து, அவ்வழியுந் தன்மையை நீக்கிக்கொள்ள மாட்டார்கள்.`,
  },
  {
    id: 1938, tantraId: 7, verseNumber: 1937,
    tamil: `பார்க்கின்ற மாதரைப் பாராது அகன்றுபோய்
ஓர்க்கின்ற உள்ளம் உருக அழல்மூட்டிப்
பார்க்கின்ற கண்ணாசை பாழ்பட மூலத்தே
சேர்க்கின்ற யோகி சிவயோகி தானே`,
    transliteration: `pārkkiṉṟa mātaraip pārātu akaṉṟupōy
ōrkkiṉṟa uḷḷam uruka aḻalmūṭṭip
pārkkiṉṟa kaṇṇācai pāḻpaṭa mūlattē
cērkkiṉṟa yōki civayōki tāṉē`,
    english: `1937: Siva Yogi Sublimates Bindu
Do not look at women
Who intent on lust look at you;
Away from them;
Light the fire of Kundalini;
Melt your heart in divine love;
Uproot the evil desire that sight kindles;
Fix it on the source of Primal Energy
He who does it is verily the Siva Yogi.`,
    elaborationEnglish: `Do not indulge in lust. Light the kundalini fire and melt your heart in intense devotion. Eradicate the base desires that sight kindles. Concentrate on the source of primal energy. Truly, the Siva yogi sublimates bindu in this way.`,
    elaborationTamil: `தன்னைக் காதலோடு பார்க்கின்ற மகளிரைத் தான் அவர்க்கு இசைந்து பாராமல் விலகிச் சென்று யோகத்தில் நின்று புறப்பொருளைக் கண்ணால் பார்க்க எழுகின்ற ஆசையை மூலக் கனலை வளரப்பதில் சேர்த்து, மாதரைச் சிந்திக்கின்ற மனம் மாதேவனைச் சிந்தித்து உருகும்படி செய்கின்ற யோகியே சிவயோகியாதல் கூடும்.`,
  },
  {
    id: 1939, tantraId: 7, verseNumber: 1938,
    tamil: `தானே அருளால் சிவயோகம் தங்காது
தானேஅக் காமாதி தங்குவோ னும் உட்கும்
தானே அதிகாரம் தங்கில் சடங்கெடும்
ஊனே அவற்றுள் உயிர்ஒம்பா மாயுமே`,
    transliteration: `tāṉē aruḷāl civayōkam taṅkātu
tāṉēak kāmāti taṅkuvō ṉum uṭkum
tāṉē atikāram taṅkil caṭaṅkeṭum
ūṉē avaṟṟuḷ uyirompā māyumē`,
    english: `1938: Waste Not Bindu
He to lust a slave becomes,
Will in constant fear be;
His body deteriorates,
And his life ebbs away;
He will not Grace receive,
And in Siva Yoga lasts not.`,
    elaborationEnglish: `He who falls a prey to lust is forever in fear. His body deteriorates. He will not receive Grace, or reach Siva yoga.`,
    elaborationTamil: `தன்னியல்பால் திருவருள் வழியில் சென்று சிவயோகத்தில் நில்லாது காமம் முதலியவற்றிலே நிற்கின்ற கீழ் மகனும் அஞ்சும் அளவிற்கு 'யோகி' எனப்படுவன் காம நெறியில் மிக்குச் செல்வானாயின் விந்து மிக அழிந்தொழியும். உடம்பும் உயிரைக் காக்க மாட்டாது வீணே கெட்டொழியும்.`,
  },
  {
    id: 1940, tantraId: 7, verseNumber: 1939,
    tamil: `மாயாள் வசத்தே சென்றிவர் வேண்டில்
ஓயா இருபக்கத்து உள்வளர் பக்கத்துள்
ஏயாஎண் நாள்இன்ப மேல்பனி மூன்றிரண்டு
ஆயா அபரத்துள் ஆதிநாள் ஆறாமே`,
    transliteration: `māyāḷ vacattē ceṉṟivar vēṇṭil
ōyā irupakkattu uḷvaḷar pakkattuḷ
ēyāeṇ nāḷiṉpa mēlpaṉi mūṉṟiraṇṭu
āyā aparattuḷ ātināḷ āṟāmē`,
    english: `1939: Regulation Days for Sexual Union
Those who wish to sleep with women
Let them observe the periodicity thus:
Of the two phases of the moon,
The first eight days of the waxing moon
For union appropriate are not;
In the six days that remain,
And in the first six days of the waning moon
Can they in union be.`,
    elaborationEnglish: `‘The first eight days of the waxing moon are not appropriate for sexual union. The last six days of the waxing moon and the first ten days of the waning moon are the suitable days for this union.`,
    elaborationTamil: `மாமை நிறத்தால் வசீகரிக்கின்ற பெண்ணின் வசப் பட்டோராகிய இவர் அவளொடு கூட வேண்டின், என்றும் ஒழியாது மாறி மாறி வருகின்ற பூர்வ பக்க அபர பக்கங்களில் வளர் பிறையாகிய பூர்வ பக்கத்தில் முதல் எட்டு நாட்கள் போகத்திற்குப் பொருந்தா. ('விந்து சயத்தை விரும்புவோர் அந்நாட்களில் அதனைப் பெருதல் அரிது' என்பதாம்.) சோதிட நூலோரால் சிறப்பித்துச் சொல்லப்படாத அபர பக்கத்தில் முதல் ஆறு நாட்கள் வளர்பிறையின் இறுதி ஆறு நாட்களோடு ஒப்பனவாம்.`,
  },
  {
    id: 1941, tantraId: 7, verseNumber: 1940,
    tamil: `ஆறுஐந்து பன்னொன்றும் அன்றிச் சகமார்க்கம்
வேறுஅன்பு வேண்டுவோர் பூவரில் பின்னம்தோடு
ஏறும் இருபத் தொருநாள் இடைத்தோங்கும்
ஆறின் மிகுந்தோங்கும் அக்காலம் செய்யவே`,
    transliteration: `āṟuaintu paṉṉoṉṟum aṉṟic cakamārkkam
vēṟuaṉpu vēṇṭuvōr pūvaril piṉṉamtōṭu
ēṟum irupat torunāḷ iṭaittōṅkum
āṟiṉ mikuntōṅkum akkālam ceyyavē`,
    english: `1940: Regulation Days for Practising Yogis
Let those that Yoga practise
Avoid the fifth, the sixth and the eleventh days
After the woman menstruates;
The rest, who the pleasure seek,
Take the six days, in the middle
Of the three weeks that follow.`,
    elaborationEnglish: `The fifth, sixth and the eleventh days after the woman menstruates are not fit for performing the sex act. The six days in the middle of the three weeks that follow are appropriate to seek pleasure.`,
    elaborationTamil: `'பூப்பிற்குப் பின்னாட்களாகிய வளர்பிறையில் முதல் எட்டு நாட்கள் கூடதற்கு உரியன அல்ல' என மேல் விலக்கப்பட்டவற்றில் ஐந்தாம் நாளும், ஆறாம் நாளும் யோகியர்க்கு முற்றிலும் விலக்கத்தக்கன. (எனவே, 'ஏனையோர்க்கு அந்நாட்கள் ஒருகாற் பொருந்தினும் பொருந்தலாம்' என்பதாம். பதினொன்றாம் நாள் யோகியர் அல்லார்க்கு ஆம்.) சக மார்க்கம் - யோக நெறி. வேறன்பு - மகளிரை விரும்புதல். ''சகமார்க்கத்தினிடையே வேறு அன்பை ஐந்து, ஆறு பதினொன்று அல்லாத நாட்களில் வேண்டுவர் நல்லோர்'' என்க. பூப்பிற்குப் பின் ஐந்து நாட்களில் அக்குற்றம் நீங்கியொழியும். (ஆயினும், 'மேலும் 'மூன்று நாட்கள் ஆகா' என முன் மந்திரத்தில் விலக்கப்பட்டன. அந்த ஐந்து நாட்களுக்கு மேல் இருபத்தொரு நாளில் பெண்மை சிறிது சிறிதாக மிகுந்து வரும் அந்த நாட்களில் இறுதி ஆறு நாட்களில் மிகவும் மிகுந்து நிற்கும். அதனால் இல்லறத்தில் நிற்கும் ஆடவர் அந்நாட்களில் கலவி செய்க.`,
  },
  {
    id: 1942, tantraId: 7, verseNumber: 1941,
    tamil: `செய்யும் அளவில் திருநான் முகூர்த்தமே
எய்யும் கலைகாலம் இந்து பருதிகால்
நையுமிடத்து ஓடி நன்கா நூல்நெறி
செய்க வலம் இடம் தீர்ந்து விடுக்கவே`,
    transliteration: `ceyyum aḷavil tirunāṉ mukūrttamē
eyyum kalaikālam intu parutikāl
naiyumiṭattu ōṭi naṉkā nūlneṟi
ceyka valam iṭam tīrntu viṭukkavē`,
    english: `1941: Duration of Sexual Union and Rules for Release of Bindu
When on union they decide on,
Let it be for muhurtas four,
Following the injunctions of Kama Sastras,
Let them the sexual act perform;
When the Moon's Kalas (Left Nadi) shine bright,
And breath in Sun Nadi's low runs
Emit Bindu, the breath holding,
Breathing through nostril right, quelling left.`,
    elaborationEnglish: `The union they decide on should be for four muhurtas,
following the injunction of the Kama Sastras. When the
moon's kalas (left nadi) shine bright, emit bindu ‘holding your
breath.

‘Bindu’ here is Semen.`,
    elaborationTamil: `கலவி செய்தற்குப் பொருந்திய காலம் இரவில் முதல் யாமமும், கடையாமமும் ஒழிந்த இடையிரு யாமமேயாம். அதனுள்ளும் காலத்தை, 'சூரியகலைக் காலம், சந்திரகலைக் காலம்' என வரையறுத்தற்கு ஏதுவாகிய பிராண வாயுவின் இயக்கம் சந்திர கலையாகின்ற இடநாடியின் நீங்கிச் சூரிய கலையாகின்ற வலநாடிவழியே இயங்கும்பொழுது காமநூல் முறைப்படி கலவி செய்த பின்பு சூரிய கலையும், சந்திர கலையும் அல்லாத அமுத கலையாகிய நடுநாடியில் பிராணவாயு செல்லுங்கால் விந்துவை விடுக்க.`,
  },
  {
    id: 1943, tantraId: 7, verseNumber: 1942,
    tamil: `விடுங்காண் முனைந்துஇந் திரியங்க ளைப் போல்
நடுங்காது இருப்பானும் ஐஐந்தும் நண்ணப்
படுங்காதல் மாதின்பால் பற்றற விட்டுக்
கடுங்காற் கரணம் கருத்துறக் கொண்டே`,
    transliteration: `viṭuṅkāṇ muṉaintuin tiriyaṅka ḷaip pōl
naṭuṅkātu iruppāṉum aiaintum naṇṇap
paṭuṅkātal mātiṉpāl paṟṟaṟa viṭṭuk
kaṭuṅkāṟ karaṇam karuttuṟak koṇṭē`,
    english: `1942: Sublimate Sex Act
Embrace the damsel,
Your five sense organs with her five conjoining;
But, detached your passion for the woman be;
Like the senses that are Godward sublimated
Be calm; excited be not;
Control your breath, senses and mind,
Concentrated be your thought,
Thus emit your Bindu.`,
    elaborationEnglish: `Embrace the damsel and unite your five senses with hers. But remain detached. Divert your thoughts Godward, be calm and do not get excited. Direct your senses inward.`,
    elaborationTamil: `மண் முதல் புருடன்காறும் உள்ள இருபத்தைந்து கருவிகளும் தன்னை வந்து வாதிக்கும் பொழுது அவற்றால் சலனம் உறுதல் இன்றி இருக்கின்ற யோகியும் ஒரோ ஒருகால் பெண்ணின்பால் காதல் கொள்கின்றவனாவான் ஆயினும் அப்பொழுதும் அவன் அவள் மேல் பற்றுக்கொள்ளாது, போக காலத்தில் மிகுதியாய் இயங்குகின்ற பிராண வாயுவின் இயக்கத்தால் மெலிவடைகின்ற அந்தக் கரணங்களை அகமுகப் படுத்தி, முன் பஞ்சேந்திரியங்களைத் தன் வசப்படுத்தியது போலவே விந்துவையும் தன் வசப்படுத்தியே விடுவான்.`,
  },
  {
    id: 1944, tantraId: 7, verseNumber: 1943,
    tamil: `கொண்ட குணனே நலமேநற் கோமளம்
பண்டை உருவே பகர்வாய் பவளமே
மிண்டு தனமே மிடைய விடும் போதில்
கண்ட கரணம் உட் செல்லக்கண் டேவிடே`,
    transliteration: `koṇṭa kuṇaṉē nalamēnaṟ kōmaḷam
paṇṭai uruvē pakarvāy pavaḷamē
miṇṭu taṉamē miṭaiya viṭum pōtil
kaṇṭa karaṇam uṭ cellakkaṇ ṭēviṭē`,
    english: `1943: Direct your senses Inward
Goodly amour, beauty and youth
Shapely form and coral lips
And breasts that swell,
--When in union with damsel such as she--
You the Bindu emit,
Emit, your senses inward directed.`,
    elaborationTamil: `மாதர்பால் ஆடவரது மனத்தை ஈர்ப்பனவாய் உள்ளன அவருக்கு இயல்பாக அமைந்த நாணம், மடம், அச்சம், பயிப்பு' - என்னும் குணங்களும், மேனியழகும், இளமையும், வடிவமைப்பும், பேசுகின்ற வாயாகிய பவளமும், ஒன்றை ஒன்று நெருக்கும் வகையில் புடைபரந்து எழுகின்ற கொங்கைகளும் ஆகிய இவையாம். 'இவை நேற்றுக் கண்டனதாம் இன்று காணப்படுகின்றன' என்னும் வகையிலே இருப்பன அல்லது அவ்வப்பொழுது புதிது புதிதாய்த் தோன்றுவன அல்ல ஆயினும் அவை அவ்வாறிருந்தே ஆடவரை வசீகரித்தல் வியப்பு. அம்முறையில், மாணவகனே, அவை உன்னைப் பற்றி நெருங்கியிருக்கும் பொழுது நீ விந்து சயம் பெற வேண்டினால் யோகியர் போல அவைகளைப் பொறிகளாற் பற்றி, அப்பற்றுதலானே திரிபெய்துகின்ற அந்தக் கரணங்களை அகமார்க்கத்தில் செலுத்தி அதனால் விந்துவை உன் வசப்படுத்தி விடு.`,
  },
  {
    id: 1945, tantraId: 7, verseNumber: 1944,
    tamil: `விட்டபின் கர்ப்பஉற் பத்தி விதியிலே
தொட்டுறுங் காலங்கள் தோன்றக் கருதிய
கட்டிய வாழ்நாள் சாம்நாள் குணம் கீழ்மைசீர்ப்
பட்ட நெறியிதுஎன்று எண்ணியும் பார்க்கவே`,
    transliteration: `viṭṭapiṉ karppauṟ patti vitiyilē
toṭṭuṟuṅ kālaṅkaḷ tōṉṟak karutiya
kaṭṭiya vāḻnāḷ cāmnāḷ kuṇam kīḻmaicīrp
paṭṭa neṟiyitueṉṟu eṇṇiyum pārkkavē`,
    english: `1944: Determine the Results of the Act
Having emitted,
Examine the laws of conception
The time of union, of pregnancy and delivery
The baby's length of life, and death;
Its character, good and bad,
These you in detail determine.`,
    elaborationEnglish: `Having emitted, examine the laws of conception and determine
the results of the act — the time .of union of pregnancy,
delivery and the baby’s destined length of life and time of
death.`,
    elaborationTamil: `ஆடவன் பெண்டினிடத்து விந்துவை விட்டபின் கலவிக் காலத்துச் சரவோட்டம் முதலியவை பற்றி அவ்விந்து கருவாகித் தோன்றும் முறையில் அதன் தொடக்கம் முதலியவை களையும், பின்பு அதன் வாழ்நாள் சாநாள்களையும், பின்பு அதன் இழி குணம், உயர்குணம் என்பவற்றையும் 'தனித்தனி இவ்வியல்பினது' என்று ஆராய்ந்தறிதலையும் செய்வானாக.`,
  },
  {
    id: 1946, tantraId: 7, verseNumber: 1945,
    tamil: `பார்த்திட்டு வையத்துப் பரப்பற்று உருப்பெற்று
வார்ச்செற்ற கொங்கை மடந்தையை நீக்கியே
சேர்த்துற்று இருதிங்கள் சேராது அகலினும்
மூப்புற்றே பின்னாளில் ஆம்எல்லாம் உள்ளவே`,
    transliteration: `pārttiṭṭu vaiyattup parappaṟṟu uruppeṟṟu
vārcceṟṟa koṅkai maṭantaiyai nīkkiyē
cērttuṟṟu irutiṅkaḷ cērātu akaliṉum
mūppuṟṟē piṉṉāḷil āmellām uḷḷavē`,
    english: `1945: Seek not Further Union
Having examined these,
Abstain from worldly concerns,
And leave the maiden of shapely breasts;
And further union seek not;
Within months two
Will the baby its form take,
And all the rest you have reckoned follow.`,
    elaborationEnglish: `Having exarhined these, abstain from the maiden do not seek
further union.`,
    elaborationTamil: `மேற்கூறியபடி கருவைப் பற்றி எண்ணிப் பார்க்க வேண்டியவற்றையெல்லாம் எண்ணிப்பார்த்து உலகத்தில் பொதுவாக நிகழும் புலன் அடக்கம் இன்மையைத் தந்தை, தாயர் தவிர்த்து இருத்தலால் கரு மக உருப் பெற்று வளர்ந்து முதிர்ந்து பின்பு விதி அம்மகவைத் தாயின் வயிற்றிலிருந்து நீக்கி நிலத்தைச் சேரும்படி சேர்த்து, (தாய் தந்தையர் குழவிமாட்டுள்ள அன்பால் ஊக்கம் மிகுந்து செய்விக்கும் தெய்வக் காப்புக்களால்) மேல் கருவுட் பட்டனவாகக் கூறிய அவ்வினைப் பயன்கள் குழவியை வந்து பற்றதொழியினும் அதன்பின் குழவி வளர்ந்து வரும் பிற்காலத்தில் அவையெல்லாம் வந்து பற்றுவனவேயாகும். ஆகையால், மேற் கூறியவற்றையெல்லாம் ஆடவன் எண்ணிப் பார்ப்பானாக.`,
  },
  {
    id: 1947, tantraId: 7, verseNumber: 1946,
    tamil: `வித்திடு வோர்க்கு அன்றி மேலோர் விளைவில்லை
வித்திடு வோர்க்கு அன்றி மிக்கோர் அறிவில்லை
வித்தினில் வித்தை விதற உணர்வரேல்
மத்தில் இருந்ததோர் மாங்கனி யாமே`,
    transliteration: `vittiṭu vōrkku aṉṟi mēlōr viḷaivillai
vittiṭu vōrkku aṉṟi mikkōr aṟivillai
vittiṉil vittai vitaṟa uṇarvarēl
mattil iruntatōr māṅkaṉi yāmē`,
    english: `1946: Know the Seed of Seed and Preserve Body
Except for those who plant the seed,
Harvest there be none, future;
Except for those who plant the seed,
Wisdom great there be none;
If they know the Seed of seed for certain
Preserved their body be
Unto the mango fruit kept in vessel suspended.`,
    elaborationEnglish: `Only they who plant the seed will reap the harvest and receive great wisdom. So, know the seed of seed; your body will be preserved like a mango fruit kept in a hanging vessel.`,
    elaborationTamil: `உலகில் விதையை நிலத்தில் விதைப்பவர்க் கல்லது விளைவு ஏதும் கிடைக்க மாட்டாது. விதையை நன்முறையில் விதைப்பவர்க்கல்லது சிறந்த ஓர் அறிவும் இல்லையாகும். (அதுபோல விந்துவாகிய வித்தினை நன்முறையில் இடாதார்கக்ம் நன்மகப் பேறாகிய விளைவும் கிடைக்கமாட்டாது; அவர்க்குச் சிறந்த ஓர் அறிவும் இல்லையாகும்.) விந்துவாகிய வித்தினது இல்லற வித்தையை அமைந்து நோக்கி உணர்வாராயின், மரத்தில் தூங்கும் மாங்கனி போலும் பயன் கிடைப்பதாகும்.`,
  },
  {
    id: 1948, tantraId: 7, verseNumber: 1947,
    tamil: `கருத்தினில் அக்கரம் ஆயுவும் யாவும்
கருத்துளன் ஈசன் கருஉயிரோடும்
கருத்தது வித்தாய்க் காரண காரியம்
கருத்தறு மாறுஇவை கற்பனை தானே`,
    transliteration: `karuttiṉil akkaram āyuvum yāvum
karuttuḷaṉ īcaṉ karuuyirōṭum
karuttatu vittāyk kāraṇa kāriyam
karuttaṟu māṟuivai kaṟpaṉai tāṉē`,
    english: `1947: Lord Settles Fate and longevity of Embryo With Concern
The Lord has concern great
For the seed in womb;
Even in the seed with forethought
He settles its fate and span of life;
Thus, when the Seed itself is the Causal Thought,
To attribute Cause and
Effect to factors outside
Is but imagination's figment.`,
    elaborationEnglish: `The Lord is very much concerned about the seed in the womb,
and He settles its fate and span of life.`,
    elaborationTamil: `இறைவன் கருவிற்பட்ட உயிரோடு அதன் அறிவுக் கறிவாய்க் கலந்து நிற்கின்றான். அதனால் அவ்வறிவிற்குப் பொருள்களை அறியும் ஆற்றலையும், ஆயுள் முதலானவற்றையும் அப்பொழுதே அமைக்கின்றான். அவன் அவ்வாறமைத்தற்கும் தந்தை தாயரது எண்ணமே காரணமாய் நிற்க, அவ்வமைப்பு அக்காரணத்தின் காரியமாகின்றது. ஆகவே, குழவியின் அறிவு, ஆயுள் முதலியவை தந்தை தாயரது எண்ணத்தினால் அமைவனவேயாம்.`,
  },
  {
    id: 1949, tantraId: 7, verseNumber: 1948,
    tamil: `ஒழியாத விந்து வுடன்நிற்க நிற்கும்
அழியாப் பிராணன் அதிபலஞ் சத்தி
ஒழியாத புத்தி தபஞ்செப மோனம்
அழியாத சித்தியுண் டாம்விந்து வற்றிலே`,
    transliteration: `oḻiyāta vintu vuṭaṉniṟka niṟkum
aḻiyāp pirāṇaṉ atipalañ catti
oḻiyāta putti tapañcepa mōṉam
aḻiyāta cittiyuṇ ṭāmvintu vaṟṟilē`,
    english: `1948: Conserve Bindu and Attain Siddhis
If Bindu stands retained in body
Life ebbs not;
Great strength, energy, intelligence alert,
Tapas, contemplation and Maunam (silent-ness)
And siddhis enduring,
--All these are attained,
--If Bindu be conserved true.`,
    elaborationTamil: `யோக முயற்சியால் விந்து வீழ்தலின் நீங்கி உடற் குள்ளே நிற்குமாயின் பிராணனும், உடலின் மிக்க வலிமையும், அறிவின் ஆற்றலும் அழியாது நிலைபெறும். இனி விந்து மூலாக் கினியால் தன் இயல்பு வேறுபட்டு உடம்பினுள் ஒன்றாய்க் கலந்து விடுமாயின் இடைவிடாத ஞானம், தவம், செபம், மௌன நிலை, எட்டுச் சித்திகள் ஆகிய எல்லாம் உளவாகும்.`,
  },
  {
    id: 1950, tantraId: 7, verseNumber: 1949,
    tamil: `வற்ற அனலைக் கொளுவி மறித்தேற்றித்
துற்ற சுழியனல் சொருகிக் சுடருற்று
முற்று மதியத்து அமுதை முறைமுறை
செற்றுண் பவரே சிவயோகி யாரே`,
    transliteration: `vaṟṟa aṉalaik koḷuvi maṟittēṟṟit
tuṟṟa cuḻiyaṉal corukik cuṭaruṟṟu
muṟṟu matiyattu amutai muṟaimuṟai
ceṟṟuṇ pavarē civayōki yārē`,
    english: `1949: Conservation of Sex Energy Vital for Yoga Practice
Thus conserved, they light the Fire of Kundalini,
And forcing it upward through Nadi Sushumna
Reach the state of illumination;
There they partake of the ambrosia
From the Moon within flows;
Those who do this in unbroken continuity,
Are verily Siva Yogins true.`,
    elaborationEnglish: `Thus by conserving the sex energy, the yogis light the fire of kundalini, and coursing it upward through the sushumna nadi they reach the state of illumination. Siva yogins are they indeed who continuously partake of the ambrosia flowing from the moon in the sphere within.`,
    elaborationTamil: `விந்து வறளும்படி யோக முயற்சியால் மூல அனலை அதன்பால் சேர்த்து, அதனால் அது கீழ்நோக்கி வீழும் இயல்பை விட்டு மேல்நோக்கி ஏறும் இயல்பினதாகச் செய்து அவ்வாறு சுழுமுனை வழியாக மேல் ஏறி ஆஞ்ஞையை முட்டி அடையப் பண்ணி, அஃது அவ்விடத்துள்ள ஒளியோடு கலந்தபின்னர், மேலும் செல்கின்ற மூலக்கனலால் ஆஞ்ஞைக்கு மேல் உள்ள நிறைமதி மண்டலத்திலிருந்து ஊறி வழிகின்ற அமுதத்தை முறை முறையாகத் தமது பண்டை இயல்பு கெட உண்கின்றவர்களே சிவயோகியர் ஆவார்கள்.`,
  },
  {
    id: 1951, tantraId: 7, verseNumber: 1950,
    tamil: `யோகியும் ஞானியும் உத்தம சித்தனும்
யோகியும் ஞான புரந்தரன் ஆவோனும்
மோகம் உறினும் முறைஅமிர்து உண்போனும்
ஆகிய விந்து அழியாத அண்ணலே`,
    transliteration: `yōkiyum ñāṉiyum uttama cittaṉum
yōkiyum ñāṉa purantaraṉ āvōṉum
mōkam uṟiṉum muṟaiamirtu uṇpōṉum
ākiya vintu aḻiyāta aṇṇalē`,
    english: `1950: Conserve Sex Energy and Become Heroes
The Yogi, the Jnani, and the Siddha high
The Bhoga Yogi who is yet the king of Jnanis,
All these, though troubled by passions
Yet savour the ambrosia within; (in the Yogic way)
Heroes, all, they are indeed,
Who the Bindu had conserved.`,
    elaborationEnglish: `The yogi, the jnani, the siddhar high and the bhoga-yogi, who is yet the king of jnanis, are real heroes; because, though they were troubled and tempted by passions, they resolved to taste the ambrosia within in the yogic way.`,
    elaborationTamil: `மாதர்மேல் மையலை உற்றபோதிலும் அதனால் உண்டாகிய விந்து அவர்பால் சென்று வீழாத நிலைமையை எய்திய பெரியோன், யோகியும், மேலான சித்திகளைப் பெற்றவனும், அதே நிலையில் போகத்தை இழக்காதவனும், ஞான வேந்தனாய் விளங்குபவனும், யோக முறையில் உண்ணும் மதி மண்டலத்து அமுதத்தைப் பெற்று உண்பவனுமாவான்.`,
  },
  {
    id: 1952, tantraId: 7, verseNumber: 1951,
    tamil: `அண்ணல் உடலாகி அவ்வனல் விந்துவும்
மண்ணிடை மாய்க்கும் பிராணனாம் விந்துவும்
கண்ணும் கனலிடைக் கட்டிக் கலந்தெரித்து
உண்ணில் அமிர்தாகி யோகிக்கு அறிவாமே`,
    transliteration: `aṇṇal uṭalāki avvaṉal vintuvum
maṇṇiṭai māykkum pirāṇaṉām vintuvum
kaṇṇum kaṉaliṭaik kaṭṭik kalanterittu
uṇṇil amirtāki yōkikku aṟivāmē`,
    english: `1951: Burn Bindu in Fire of Kundalini
The fiery Bindu above is Lord's Body (macrocosmic)
The Bindu wasted here below is vital Prana (microcosmic)
If mixing the two, they burn it in the Fire of Kundalini
Then they consume the very ambrosia
--This, the wisdom of
Yogis true.`,
    elaborationEnglish: `The Lord's body is the fiery bindu above (macrocosmic), and
the bindu wasted below is the vital prana (microcosmic). If
these two are mixed, and burnt in the kundalini fire, the yogis
consume the very clixir of life. This is the true wisdom of yogis.`,
    elaborationTamil: `சிவோகம் பாவனையால் உயிர் சிவனாதலால், அது நின்ற உடம்பும் சிவனது உடம்பாகியபின், அவ்யோகியது விந்தும் நீர்த்தன்மை நீங்கிச் சிவனது விந்துபோல நெருப்புத் தன்மை எய்த அதனையும், உலகில் நாள்தோறும் வெளிவிடுத்துச் சிறிது சிறிதாக அழிக்கப்படுகின்ற பிராணவாயுவாகிய மூலப்பொருளையும் ஒற்றுமைப்பட ஒன்றாகக் கலந்து மூலாக்கினியால் சமைத்து உண்ணும் முறையை ஓர் யோகி வல்லனாயின், அவனுத விந்து தேவாமிர்தமாய் உடல் நலங்கள் பலவற்றைத் தருதலுடன், ஞானமும் நன்கு சிறந்து பிரகாசிக்கச் செய்யும்.`,
  },
  {
    id: 1953, tantraId: 7, verseNumber: 1952,
    tamil: `அறியாது அழிகின்ற ஆதலால் நாளும்
பொறியால் அழிந்து புலம்புகின் றார்கள்
அறிவாய் நனவில் அதீதம் புரியச்
செறிவாய் இருந்து சேரவே வாயுமே`,
    transliteration: `aṟiyātu aḻikiṉṟa ātalāl nāḷum
poṟiyāl aḻintu pulampukiṉ ṟārkaḷ
aṟivāy naṉavil atītam puriyac
ceṟivāy iruntu cēravē vāyumē`,
    english: `1952: In Yoga Bindu is Divinely Assimilated
In ignorance the folks waste it daily,
And destroyed by senses, in pain weep;
If in wisdom, they conscious perform Yoga supreme,
The Bindu disppears, divinely assimilated.`,
    elaborationEnglish: `Ignorant folks destroy bindu in vain daily. But if in wisdom they perform supreme yoga, bindu is divinely assimilated. So, refrain from lust, for it is death's messenger. Preserve bindu. Then you will enjoy the divine light for ages and ages to come, remaining free from impurities.`,
    elaborationTamil: `உலக மாந்தரது விந்துக்கள் அவரது அறியாமை யாலேதான் வீழ்ந் தொழிகின்றன ஆதலால், அவ்வீழ்ச்சிக்கண் நாள்தோறும் அவர்ஐம்பொறி வழியில் அகப்பட்டுத்துயர் உறு கின்றனர். ஆகையால், பெரியோர் அறிவுடையராய்ச் சாக்கிரத்தில் தானே அதீத நிலையை அடைந்திருக்க, பிண்டத்திற்கு முதலாயுள்ள விந்துவாகிய சுக்கிலமேயன்றி, அண்டத்திற்கு முதலாயுள்ள விந்து வாகிய சுத்த மாயையும் ஒரு சேர அவர்க்கு அடங்கித் தம்மியல்பு கெட்டு நிற்கும்.`,
  },
  {
    id: 1954, tantraId: 7, verseNumber: 1953,
    tamil: `மாதரை மாய வரும் கூற்றம் என்றுன்னக்
காதலது ஆகிய காமம் கழிந்திடும்
சாதலும் இல்லை சதகோடி ஆண்டினும்
சோதியின் உள்ளே துரிசறும் காலமே`,
    transliteration: `mātarai māya varum kūṟṟam eṉṟuṉṉak
kātalatu ākiya kāmam kaḻintiṭum
cātalum illai catakōṭi āṇṭiṉum
cōtiyiṉ uḷḷē turicaṟum kālamē`,
    english: `1953: Lust is Death's Messenger
If you hold women as Death's messengers,
Love's passion vanishes away;
Death there is none;
For ages innumerable will you in Divine Light be,
Your Impurities forever totally rid.`,
    elaborationTamil: `விந்து இழப்பிற்குக் காரணம் பால் உணர்ச்சியே யாகலின், அதனை மகளிரை அந்தப் பாலினராகக் கருதாமல், அங்ஙனம் கருதுபவர்க்கு அதனால் வரும் அழிவுபற்றி அவரைக் கொல்ல வரும் கூற்றுவனாகவே கருதின் அவர்மேல் செல்கின்ற ஆசையும், அதனால் எழும் பால் உணர்ச்சியும் நீங்கிவிடும். அவை நீங்கவே விந்து இழக்கப் படாதாகலின், அதனால் மனித ஆயுள் அளவேயன்றி, மேலும் பல்லாண்டு செல்லினும் இறப்பு வாராது. இனி அந்நாட்கள் எல்லாம் பரம்பொருளின் உள்ளே குற்றமற்றிருக்கும் நாட்களாயும் அமையும்.`,
  },
  {
    id: 1955, tantraId: 7, verseNumber: 1954,
    tamil: `காலம் கடந்தவன் காண்விந்து செற்றவன்
காலம் கடந்தழிந் தான்விந்து செற்றவன்
காலங் களின்விந்து செற்றுற்ற காரிகை
காலின்கண் வந்த கலப்பறி யாரே`,
    transliteration: `kālam kaṭantavaṉ kāṇvintu ceṟṟavaṉ
kālam kaṭantaḻin tāṉvintu ceṟṟavaṉ
kālaṅ kaḷiṉvintu ceṟṟuṟṟa kārikai
kāliṉkaṇ vanta kalappaṟi yārē`,
    english: `1954: Conquer Bindu and Conquer Time
He that has conquered Bindu has conquered Time;
He that has wasted Bindu has perished before his time;
They know not that Bindu that has been preserved
In time becomes one with Kundalini,
Their breath controlled in the Yogic way.`,
    elaborationEnglish: `In time becomes one with Kundalini,

Their breath controlled in the Yogic way.

Conquer bindu; for that helps to conquer time. The bindu
that has been preserved merges with kundalini in time, and
the breath that will be controlled in the yogic way will
checkmate death.`,
    elaborationTamil: `விந்து சயம்பெற்றவன் பல்லாண்டுகள் வாழ்தலால் காலத்தைக் கடந்து நிற்பவனாவன். விந்துவை அழித்துவிட்டவன் குறிப்பிட்ட சிலகாலம் வரையில் எவ்வகையிலோ வாழ்ந்து மறைந்தவனாவான். இவ்விருவரும் முறையே கலவிக் காலம் உட்பட எந்தக் காலத்திலும் விந்துவைத் தன் உடலில் வற்றியிருக்கச் செய்தவனும், மாதி னொடு பிராணாயாம முறையில் அமைந்த கலவியை அறியா தவனும் ஆவர்.`,
  },
  {
    id: 1956, tantraId: 7, verseNumber: 1955,
    tamil: `கலக்கு நாள் முன்னாள் தன்னிடைக் காதல்
நலத்தக வேண்டில் அந் நாரி யுதரக்
கலத்தின் மலத்தைத்தண் சீதத்தைப் பித்தை
விலக்கு வனசெய்து மேலணை வீரே`,
    transliteration: `kalakku nāḷ muṉṉāḷ taṉṉiṭaik kātal
nalattaka vēṇṭil an nāri yutarak
kalattiṉ malattaittaṇ cītattaip pittai
vilakku vaṉaceytu mēlaṇai vīrē`,
    english: `1955: Embrace Woman after Cleansing Her
If you desire woman's love, intense to excite,
The day before you in sexual union indulge,
Cleanse the woman of her bowel, phlegm and bile,
Then in union embrace her.`,
    elaborationTamil: `மாதினொடு கூடுவீர், நீவிர் அக்காதல் வாழக்கை இருவரிடத்தும் நலமாக அமைய வேண்டின் மேலெல்லாம் கூறிவந்த முறையில் குறித்த நாட்கு முன்னாளே அவளது உடம்பில் மலமும், சலமும் ஆகிய உபாதிகளும், வாதம், பித்தம், ஐ என்னும் அவற்றின் மிகை குறைகளும் இல்லாதபடி நீக்குதற்கு உரியவற்றைச் செய்து அதன்பின்னர்க் கூடுவீராக.`,
  },
  {
    id: 1957, tantraId: 7, verseNumber: 1956,
    tamil: `மேலா நிலத்தெழு விந்துவும் நாதமும்
கோலால் நடத்திக் குறிவழி யேசென்று
பாலாம் அமிர்துண்டு பற்றறப் பற்றினால்
மாலா னதுமான மாளும் அவ்விந்துவே`,
    transliteration: `mēlā nilatteḻu vintuvum nātamum
kōlāl naṭattik kuṟivaḻi yēceṉṟu
pālām amirtuṇṭu paṟṟaṟap paṟṟiṉāl
mālā ṉatumāṉa māḷum avvintuvē`,
    english: `1956: Bindu is Assimilated in Body Through Yoga
Direct Prana breath to
Bindu and Nada
That in cranium Sphere arises,
Upward through Sushumna
Nadi
By devices appropriate;
Thus you reach to the nectar divine;
Hold on to it,
That Bindu in you indissolubly dissolves,
Your illusions to disappear.`,
    elaborationEnglish: `Divert prana through the sushumna nadi to (para) bindu and nada that are in the cranium sphere. The sweet ambrosia flows; hold on to it. Thus is the semenal bindu assimilated in the body through yoga.`,
    elaborationTamil: `விந்து ஆறு ஆதாரங்களில் மேல் ஆதாரமாகிய ஆஞ்ஞையில் தோன்றும்; அதற்கு மூலமாகிய பொருள் ஏழாம் தானமாகிய மதி மண்டலத்தில் தோன்றும். ஆகையால், பிராண வாயுவையும், அதனால் எழும் மூலாக்கினியையும் சுழுமுனை வழியாகச் செலுத்தி ஒவ்வோர் ஆதாரமாகக் கடந்து மதி மண்டலத்தை அடைந்து அங்கே உண்டாகின்ற அமிர்தத்தை உண்டு கொண்டே மாதினை ஆசையின்றித் தழுவினால், மையல் உண்டாகாது. அஃது உண்டாகாதாகவே விந்துவும் வெளிப்படாது அகத்திலே நிற்கும்.`,
  },
  {
    id: 1958, tantraId: 7, verseNumber: 1957,
    tamil: `விந்து விளைவும் விளைவின் பயன்முற்றும்
அந்த அழிவும் அடக்கத்தில் ஆக்கமும்
நந்திய நாசமும் நாதத்தால் பேதமும்
தந்துணர் வோர்க்குச் சயமாகும் விந்துவே`,
    transliteration: `vintu viḷaivum viḷaiviṉ payaṉmuṟṟum
anta aḻivum aṭakkattil ākkamum
nantiya nācamum nātattāl pētamum
tantuṇar vōrkkuc cayamākum vintuvē`,
    english: `1957: Conquest of Bindu Leads to Nada
The ripening of Bindu,
The result full of that ripening,
The dire consequences of wasting it,
And the blessings of retaining it,
The Nada that ensues
And the transformation that Nada effects,
--Those who all these realize
Have verily conquered the Bindu.`,
    elaborationEnglish: `The conquest of bindu truly leads to nada which effects transformations.`,
    elaborationTamil: `விந்து உண்டாகும் முறையும், அஃது உண்டாகி முதிர்வதனால் விளைகின்ற பயனும், அதனை வீண்போகாது அடக்குதற்குரிய வழியும், அவ்வழிப்படி அதனை அடக்குதலால் வரும் ஆக்கங்களும், விந்து கெடுவதாகிய கேடும், அக்கேட்டினால் விளையும் விளைவுகளின் வகையும் ஆகிய இவற்றையெல்லாம் முறையாக மனத்திற் கொணர்ந்து, ஆய்ந்து உணர்பவர்க்கு விந்து சயம் உண்டாக வழி ஏற்படும்.`,
  },
  {
    id: 1959, tantraId: 7, verseNumber: 1958,
    tamil: `விந்துஎன் வீசத்தை மேவிய மூலத்து
நந்திய அங்கிய னாலே நயந்தெரிந்து
அந்தமில் பானுஅதிகண்ட மேலேற்றிச்
சந்திரன் சார்புறத் தண்ணமு தாமே`,
    transliteration: `vintueṉ vīcattai mēviya mūlattu
nantiya aṅkiya ṉālē nayanterintu
antamil pāṉuatikaṇṭa mēlēṟṟic
cantiraṉ cārpuṟat taṇṇamu tāmē`,
    english: `1958: Fry Bindu in Kundalini Fire
The Bindu that is Bija (Seed)
Burn it agreeably,
In the Fire that is Kundalini,
That from Muladhara flames;
Course it upward into the Solar Sphere within
And touch the Lunar Sphere beyond;
There, indeed, is the nectar divine.`,
    elaborationEnglish: `Burn the semenal bindu in kundalini fire that flames from muladhara. Course it upward into the solar sphere and touch the lunar sphere beyond, where divine ambrosia is present.`,
    elaborationTamil: `[இமந்திரத்திலும் மேல், ''அண்ணல் உடலாகி'' என்னும் மந்திரத்துட் கூறப்பட்ட பொருளே, 'அண்ணல் உடலாதல்' ஆகிய அவ்வொன்றொழியக் கூறப்பட்டது.]`,
  },
  {
    id: 1960, tantraId: 7, verseNumber: 1959,
    tamil: `அமுதச் சசிவிந்து வாம்விந்து மாள
அமுதப் புனலோடி அங்கியின் மான
அமுதச் சிவயோகம் ஆதலால் சித்தி
அமுதப் பலாவனம் ஆங்குறும் யோகிக்கே`,
    transliteration: `amutac cacivintu vāmvintu māḷa
amutap puṉalōṭi aṅkiyiṉ māṉa
amutac civayōkam ātalāl citti
amutap palāvaṉam āṅkuṟum yōkikkē`,
    english: `1959: Bindu Sublimated by Kundalini Yoga Leads to Ambrosial
Flow
When the Bindu of the body
Thus perishes (by Yoga)
It is into Divine Bindu transformed
Of the ambrosial Lunar Sphere within;
When the Bindu of the body
Perishes in the fire of Kundalini,
The ambrosial waters flow and fill the body;
Then indeed is Siva Bhoga that is ambrosial sweet;
And thus bathed in divine waters of ambrosia
The Yogi attains Siddhis rare.`,
    elaborationEnglish: `When the human bindu is destroyed thus, it is changed into divine bindu. Bindu of the body is sublimated by kundalini yoga that draws the ambrosial flow. Indeed, that is Siva bhoga. By immersion in the divine waters of ambrosia, the yogi attains tare siddhis.`,
    elaborationTamil: `சந்திர மண்டலத்தில் ஊறுகின்ற அமுதமாகிய துளிகளில், யோகியினது உடம்பில் உண்டாகின்ற விந்து முன் மந்திரத்தில் கூறிய முறையில் சென்று ஒடுங்க, மற்று உடம்பைக் காக்கின்ற அமுதமாய் நீர்க்கூறுகள் விரையச் சுழன்று மூலாக்கினியால் வற்ற, அவ்வாற்றால் அமுதம் போலும் இனிய சிவபோகம் விளையும் ஆதலால், அவ்யோகிக்கு அப்பொழுதுதான் அடைந்தபேறு அமுத மழை பொழிதல் போல அமையும்.`,
  },
  {
    id: 1961, tantraId: 7, verseNumber: 1960,
    tamil: `யோகம் அவ் விந்து ஒழியா வகையுணர்ந்து
ஆகம்இரண்டும் கலந்தாலும் ஆங்குறாப்
போகம் சிவபோகம் போகிநற் போகமா
மோகங் கெடமுயங் கார்மூடர் மாதர்க்கே`,
    transliteration: `yōkam av vintu oḻiyā vakaiyuṇarntu
ākamiraṇṭum kalantālum āṅkuṟāp
pōkam civapōkam pōkinaṟ pōkamā
mōkaṅ keṭamuyaṅ kārmūṭar mātarkkē`,
    english: `1960: In Yoga Way Bindu is not Released
Two bodies in union may unite,
Yet if he emits not
Bindu
That union is Yoga way;
That Bhoga is Siva
Bhoga;
That the true Bhoga
Where the Yogi emits not
To quell the witless woman's passion.`,
    elaborationEnglish: `The two bodies, male and female, may unite if bindu is not
emitted — that union is of the yoga way. That bhoga is Siva
bhoga.`,
    elaborationTamil: `மாதும், ஆடவனும் ஒருங்கு கூடி, இருவர் உடலும் 'ஓர் உடலே' எனும்படி இறுகப் புல்லிய விடத்தும் ஆடவனுக்கு அப்புல்லுதல் காரணமாக வெளிப்படுதற்குரிய விந்து வெளிப்படா திருக்கப் பெறுதலே உண்மை யோகமாகும். ஆயினும் அவ்விடத்து இன்ப நுகர்ச்சி இல்லா தொழியாது; உள்ளதேயாகும். அவ்வின்ப நுகர்ச்சி உடலின்ப நுகர்ச்சியாகாது சிவ இன்ப நுகர்ச்சியாகவே அமையும். அதுவே இன்ப நுகர்ச்சியை உடையவனுக்குத் தீங்கினை விளையாது, நன்மையையே விளைக்கும் இன்ப நுகர்ச்சியாம். இந்நுகர்ச்சியைப் பெறும் வகையில் மாதரைப் புணர அறியாதார் புணர்ச்சிக் காலத்தில் அவரை உடல் இன்ப மயக்கமின்றிப் புணர மாட்டார்.`,
  },
  {
    id: 1962, tantraId: 7, verseNumber: 1961,
    tamil: `மாதர் இடத்தே செலுத்தினும் அவ்விந்து
காதலி னால்விடார் யோகம் கலந்தவர்
மாதர் உயிராசை கைக்கொண்ட வாடுவர்
காதலர் போன்றங்ஙன் காதலாம் சாற்றிலே`,
    transliteration: `mātar iṭattē celuttiṉum avvintu
kātali ṉālviṭār yōkam kalantavar
mātar uyirācai kaikkoṇṭa vāṭuvar
kātalar pōṉṟaṅṅaṉ kātalām cāṟṟilē`,
    english: `1961: Bindu is not Emitted
They who stand in Yoga way
Even though with women unite,
Their Bindu, in passion, they emit not;
And the women their life's passion unquenched
Will verily pine and droop,
Yearning still for love,
As lovers new forever do.`,
    elaborationEnglish: `If bindu is not released in the yogi way of sexual union; the woman whose passions remain unquenched will pine and yearn for loye forever.`,
    elaborationTamil: `யோகத்தைப் பொருந்தியவர் மாதரிடத்தே அவர் விழைவு நோக்கி விந்துவை விடுத்தாராயினும் அவர்மேல் கொண்ட மோகத்தால் விடுத்தாரல்லர். ஏனெனின், அவர் மாதர்பால் காட்டுகின்ற மோகத்தைச் சொல்லுமிடத்து ஏனையோர் மோகம் போன்றதாயிருப்பினும் அது வேறேயாம். ('பொதுவாக யாவர்மீதும் உளதாகிய அருளேயாம்' என்பதாம்.) இனி, யோகத்தில் பொருந்தாதவர் மாதர்மேல் தம் உயிர்மேல் வைத்திருக்கும் ஆசையைப்போலும் ஆசையை வைத்து அதனால் மெலிவெய்துவர்.`,
  },
  {
    id: 1963, tantraId: 7, verseNumber: 1962,
    tamil: `சாற்றிய விந்து சயமாகும் சத்தியால்
ஏற்றிய மூலத் தழலை எழமூட்டி
நாற்றிசை ஓடா நடுநாடி நாதத்தோடு
ஆற்றி அமுதம்அருந்தவித் தாமே`,
    transliteration: `cāṟṟiya vintu cayamākum cattiyāl
ēṟṟiya mūlat taḻalai eḻamūṭṭi
nāṟṟicai ōṭā naṭunāṭi nātattōṭu
āṟṟi amutamaruntavit tāmē`,
    english: `1962: Bodily Bindu Becomes Cosmic Bindu
By Kundalini Sakti, Bindu conquer;
Kindle that Fire in Muladhara
Course it upward straight
Through central Nadi, Sushumna;
Reach Nada,
And swill ambrosia there flows;
Your Bindu the Divine Bindu becomes.`,
    elaborationEnglish: `Vanquishing bindu by kundalini sakti, kindle the fire in the
muladhara and reach nada by coursing it upward through the
central nadi, sushumna. Swill the ambrosia flowing there.
Through the body, bindu becomes cosmic bindu that is divine.`,
    elaborationTamil: `[இம்மந்திரத்திலும் மேல் ''வற்ற அனலை'' என்னும் மந்திரத்தில் சொல்லப்பட்ட முறையே ''சுழி அனல் சொருகிச் சுடருற்று'' என்பதொழியச் சொல்லப்பட்டது.]`,
  },
  {
    id: 1964, tantraId: 7, verseNumber: 1963,
    tamil: `விந்துவும் நாதமும் மேலக் கனல்மூல
வந்த அனல் மயிர்க் கால்தோறும் மன்னிடச்
சிந்தனை மாறச் சிவம்அக மாகவே
விந்துவும் மாளும்மெய்க் காயத்தில் வித்திலே`,
    transliteration: `vintuvum nātamum mēlak kaṉalmūla
vanta aṉal mayirk kāltōṟum maṉṉiṭac
cintaṉai māṟac civamaka mākavē
vintuvum māḷummeyk kāyattil vittilē`,
    english: `1963: Union of Bindu and Nada
When Bindu and Nada unite,
And Kundalini Fire each minute hair root permeates,
All thought devoid,
Siva Himself you Become;
And the Bindu then dies in the Primal Bindu
Of the Body Divine.`,
    elaborationEnglish: `With the union of bindu and nada you become Siva Himself,
devoid of all thoughts. The semenal bindu then dies in the
primal bindu of the divine body.`,
    elaborationTamil: `மேற்கூறியவாறு செய்யும் யோகத்தால் மூலாக் கினியால் விந்துவும், நாதமும் கலந்த ஒன்றாதலும், அவ்வக் கினியின் வெம்மை உடம்பின் மயிக்கால்தோறும் பரவி நிற்றலும் நிகழ, அவ் வாற்றால் உள்ளம் உலகை வெறுத்துச் சிவத்தினிடத்தே செல்ல, பின்பு, 'சிவம் நான்' என்பதாகிய சிவோகம் பாவனை உண்டாக, அதனால் விந்து அழியா உடம்பில் அதற்கு வித்தாய், அதனுள்ளே சுவறி நிற்கும்.`,
  },
  {
    id: 1965, tantraId: 7, verseNumber: 1964,
    tamil: `வித்துக்குற் றுண்பான் விளைவுஅறி யாதவன்
வித்துக்குற் றுண்ணாமல் வித்துச் சுட்டு உண்பான்
வித்துகுற் றுண்பானில் வேறலன் ஈற்றவன்
வித்துக்குற் றுண்ணாமல் வித்துவித்தான் அன்றே`,
    transliteration: `vittukkuṟ ṟuṇpāṉ viḷaivuaṟi yātavaṉ
vittukkuṟ ṟuṇṇāmal vittuc cuṭṭu uṇpāṉ
vittukuṟ ṟuṇpāṉil vēṟalaṉ īṟṟavaṉ
vittukkuṟ ṟuṇṇāmal vittuvittāṉ aṉṟē`,
    english: `1964: Yogi Sublimates Bindu
He who pounds seed and consumes it
Knows not good that of harvest comes;
Different is he,
Who fries it (in
Kundalini Fire) and in body absorbs;
The latter, of the seed a meal does not make,
But the Seed of Birth he ends.`,
    elaborationEnglish: `He who pounds and consumes the seed will not get
a good harvest. Different"is he who fries bindu in the
kundalini fire, and end the seed of birth.`,
    elaborationTamil: `விதைக்கு வைத்திருக்கும் நெல்லைக்குற்றி உண வாக்கிக் கொள்பவன் வித்தினால் விளையக் கூடிய பெரும்பயனை இழந்தவனாவன். இனி, விதை நெல்லைக்குற்றி உண்ணாமல், பொரி யாக வறுத்து உண்பவனும் முன் சொல்லப்பட்டவனைவிட அறிவுடை யவன் ஆகமாட்டான். (ஏனெனில், அவனும் விளைவை இழக்கின்றா னன்றோ!) ஆகையால் சிவயோகி விதையைக் குற்றி, அல்லது வறுத்து உண்ணாமலும், பலரும் செய்கிறபடி நிலத்தில் விதைத்தலைச் செய்யா மலும் பொன்னுக்கு விற்பவனைப் போன்றவன் ஆவான்.`,
  },
  {
    id: 1966, tantraId: 7, verseNumber: 1965,
    tamil: `அன்னத்தில் விந்து அடங்கும் படிகண்டு
மன்னப் பிராணனாம் விந்து மறித்திட்டு
மின்னொத்த விந்துநா தாந்தத்து விட்டிட
வன்னத் திருவிந்து மாயும் கா யத்திலே`,
    transliteration: `aṉṉattil vintu aṭaṅkum paṭikaṇṭu
maṉṉap pirāṇaṉām vintu maṟittiṭṭu
miṉṉotta vintunā tāntattu viṭṭiṭa
vaṉṉat tiruvintu māyum kā yattilē`,
    english: `1965: Merging of Bodily Bindu in Cosmic Bindu
Coursing upward, Bindu that is Prana vital
Merging it in Divine Bindu
That the "Swan" in cranium (Sahasrara) is,
There, uniting in Nadanta,
The luminous Bindu is in body absorbed.`,
    elaborationEnglish: `Bindu is the vital prana coursing upward; it merges in the divine bindu. There uniting in Nadanta, the luminous bindu is absorbed into the body.`,
    elaborationTamil: `உணவிலே விந்து காரண ரூபமாய் அடங்கி யிருத்தலை அறிந்து உணவை நன்முறையில் ஒழுங்காக உண்டு வருதலாலும், பின்பு பிராணனின் அவ்வாறுள்ள விந்துவை அந்தப் பிராணனை ஒழுங்கான முறை இயக்குதலால் ஒளிவடிவாக எழச் செய்து ஒலிவடிவாகிய விந்துநாதத் தானங்களில் ஏற்றி அதற்கு மேலும் செலுத்துதலாலும் அக்கர வடிவாய் நின்று அறிவைத் தோற்றுவிக்கின்ற பெரிய சுத்த மாயையும் உடம்பினுள்ளே அடங்கி நேரிதாம்.`,
  },
  {
    id: 1967, tantraId: 7, verseNumber: 1966,
    tamil: `அன்னம் பிராணன்என் றார்க்கும் இருவிந்து
தன்னை அறிந்துண்டு சாதிக்க வல்லார்க்குச்
சொன்ன மாம்உருத் தோன்றும்எண் சித்தியாம்
அன்னவர் எல்லாம் அழிவற நின்றதே`,
    transliteration: `aṉṉam pirāṇaṉeṉ ṟārkkum iruvintu
taṉṉai aṟintuṇṭu cātikka vallārkkuc
coṉṉa māmurut tōṉṟumeṇ cittiyām
aṉṉavar ellām aḻivaṟa niṉṟatē`,
    english: `1966: Absorb Bindu in Body and Become Immortal
The Swan (the macrocosmic), and Prana (the microcosmic)
--Bindu is thus two for all;
Those who realize this
And absorb one in Other
--The Prana (Individual) in the Swan (Cosmic)--
Will eight siddhis attain;
Their body as gold glitters;
They immortal become.`,
    elaborationEnglish: `They who know the truth of the two forms of bindu — the
swan (macrocosmic) and prana (microcosmic) and absorb the
latter in the former will attain the eight siddhis. Immortal
they become, their bodies glittering as gold.`,
    elaborationTamil: `ஆடவர் எல்லோர்க்கும் அன்ன விந்து, பிராண விந்து' என இரு விந்துக்கள் உள்ளன. அந்த உண்மையை உணர்ந்து, அன்னத்தையும், பிராணனையும் நெறிபடுத்தி நிற்க வல்லவர்க்கு மேனி பொன்போல விளங்கும். அட்டமா சித்திகள் கூடும். மேலும் அத்தன்மை யுள்ள யோகிகள் யாவரும் நீண்ட காலம் வாழ்ந்தமை வெளிப்படை.`,
  },
  {
    id: 1968, tantraId: 7, verseNumber: 1967,
    tamil: `நின்ற சிகாரம் நினைக்கும் பிராணனாய்
ஒன்றும் மகாரம் ஒருமூன்றோடு ஒன்றவை
சென்று பராசக்தி விந்து சயந்தன்னை
ஒன்ற உரைக்க உபதேசம் தானே`,
    transliteration: `niṉṟa cikāram niṉaikkum pirāṇaṉāy
oṉṟum makāram orumūṉṟōṭu oṉṟavai
ceṉṟu parācakti vintu cayantaṉṉai
oṉṟa uraikka upatēcam tāṉē`,
    english: `1967: Secret Way of Bindu Conquest
Intone sound "Si" (the first sound of Panchakshara)
In your Prana (life breath)'s silent thought
Merge in "Aum"--the sound cluster of "A, U, M"
Thus ParaSakti reach;
That indeed is the way of Bindu Conquest
--This the Mystic Secret (upadesa)--you hold.`,
    elaborationEnglish: `Intone the sound ‘Si’ (the first sound of panchaksara) in you silent thought and merge prana in ‘Aum.’ Thus reach Parasakti. Indeed, this is the secret method of conquering bindu.`,
    elaborationTamil: `(நீயே விந்து சயத்தைப் பெற்று விடலாம் என்று நினையாமல்) திருவருளும் அம்முயற்சியில் தலைப்பட்டு உடன் நிற்றற்பொருட்டுத் திருவைந்தெழுத்தில் உயிராய் உள்ள சிகாரத்தின் பொருளாகிய சிவனை அகார உகார மகாரங்களோடு உடன் வைத்துத் தியானிக்க விந்து சய மார்க்கத்தைப் பிறருக்கு உபதேசிக்கும் பொழுதும் இவ்வாறே உபதேசிப்பாயாக.`,
  },
  {
    id: 1969, tantraId: 7, verseNumber: 1968,
    tamil: `தானே உபதேசம் தானல்லாது ஒன்றில்லை
வானே உயர்விந்து வந்த பதினான்கு
மானேர் அடங்க அதன்பின்பு புத்தியும்
தானே சிவகதி தன்மையும் ஆமே`,
    transliteration: `tāṉē upatēcam tāṉallātu oṉṟillai
vāṉē uyarvintu vanta patiṉāṉku
māṉēr aṭaṅka ataṉpiṉpu puttiyum
tāṉē civakati taṉmaiyum āmē`,
    english: `1968: Conquer Bindu and Attain Siva State
This the Mystic Secret
There is none'but this
He alone is; nothing else there is;
The Bindu heavenward ascends,
The Organs Fourteen
(Jnanandriyas five,
Karmendriyas five and Antakaranas four)
Their action cease;
Then does Jnana follow;
That verily is Siva
State.`,
    elaborationEnglish: `Conquest over bindu makes it ascend heavenward. The action of the 14 organs (five jnanendriyas, five karmendriyas, and four antahkaranas) ceases. Sublimated bindu (elan vital) becomes an intellectual and spiritual force. Truly then is the Siva state filled with jnana.`,
    elaborationTamil: `முன்மந்திரத்தில், 'அகாரம் முதலிய மூன்றோடு உடன் வைத்துத் தியானிக்க' எனக் கூறிய கூற்றில் சுட்டப்பட்ட சிவத்தை உபதேசிக்கும் உபதேசமே உண்மை உபதேசமாகும். ஏனெனில், சிவம் இன்றி யாதொரு பொருளும் இல்லை. இனி ஆகாயம் போல் எப்பொருட்கும் வியாபகமாய் உள்ள சுத்தமாயை யினின்றும் பிரணவ வடிவாய்த் தோன்றுகின்ற வாக்குக்கள் பதினாறு கலைகளாக வைத்துத் தியானிக்கப்படும்பொழுது ஆதார யோகத்தில் ஏழாம் தானத்துடன் உலகியல் உணர்வோடு நிகழும் முதற் பதினான்கு கலைகள் ஆதார சத்திகளோடு அடங்கிவிடும். உலகியல் நீங்க சிவ உணர்வோடே நிகழும் எஞ்சிய ஏனை இருகலைகள் நிராதார யோகத்தில் நிராதார சத்திகளோடு அடங்கிவிடும். அந்நிலையே சிவத்துவ நிலையாம்.`,
  },
  {
    id: 1970, tantraId: 7, verseNumber: 1969,
    tamil: `விந்துவும் நாதமும் விளைய விளைந்தது
வந்தஇப் பல்லுயிர் மன்னுயி ருக்கெலாம்
அந்தமும் ஆதியும் ஆம்மந் திரங்களும்
விந்து அடங்க விளையும் சிவோகமே`,
    transliteration: `vintuvum nātamum viḷaiya viḷaintatu
vantaip palluyir maṉṉuyi rukkelām
antamum ātiyum āmman tiraṅkaḷum
vintu aṭaṅka viḷaiyum civōkamē`,
    english: `1969: Sivoham when Bindu Subsides
In union of Bindu and Nada
Was born this creation vast;
It is beginning and end of all life,
Of great mantras too,
When Bindu subsides,
Then is Sivoham.`,
    elaborationEnglish: `This vast creation, the beginning and end of all life, and the
great mantras were all bom in the union of bindu and nada.
Sivoham is when bindu subsides.`,
    elaborationTamil: `சுத்த மாயையினின்றும் தூலமாகவும், சூக்கும மாகவும் தோன்றுகின்ற வாக்குக்களால்தான் இங்குக் காணப்படுகின்ற பலவாகிய உயிர்களும் உளவாயின. அதனால், மந்திரங்களின் தோற்ற முடிவுகளே உயிர்களின் தோற்ற முடிவுகளாய் அமைகின்றன. ஆகவே அவ்வாக்குக்கள் பிராசாத யோகத்தால் தம் சத்திகள் அடங்கப் பெறுமாயின், சிவோகம் பாவனை உண்மையாய்ப் பயன் தரும்.`,
  },
  {
    id: 1971, tantraId: 7, verseNumber: 1970,
    tamil: `வறுக்கின்ற வாறும் மனத்துலா வெற்றி
நிறுக்கின்ற வாறும் அந் நீள்வரை ஒட்டிப்
பொறிக்கின்ற வாறும்அப் பொல்லா வினையை
அறுக்கின்ற நாள்வரும் அத்திப் பழமே`,
    transliteration: `vaṟukkiṉṟa vāṟum maṉattulā veṟṟi
niṟukkiṉṟa vāṟum an nīḷvarai oṭṭip
poṟikkiṉṟa vāṟumap pollā viṉaiyai
aṟukkiṉṟa nāḷvarum attip paḻamē`,
    english: `1970: Fry Bindu and End Birth
Fry the Bindu, Mind its balance winning;
Raise it high, to mount of Sushumna;
That way, your interminable Karmas are scorched;
Then the day you pluck away
The Fruit of Fig that holds
The seeds of birth, innumerable.`,
    elaborationEnglish: `Fry bindu and raise it high to the mount of sushumna. Scorch your interminable karmas. There ends the of innumerable births.`,
    elaborationTamil: `விந்துவை வற்றச் செய்யும் முறையும், மனம் எங்கும் உலாவருவதில் அடைகின்ற வெற்றியைத் தடுத்து நிறுத்தும் முறையும், அந்த வெற்றியை எட்டுத் திக்கிலும் உயர்ந்து நிற்கின்ற மலைகளில் எழுதிப் புகழ் பெறுதலும் ஆகிய எல்லாம் உடம்பு வினைத் தொடர்பை அறுத்துக்கொள்கின்ற காலத்திலேதான் ஒருவனுக்குக் கைவரும்.`,
  },
  {
    id: 1972, tantraId: 7, verseNumber: 1971,
    tamil: `விந்துவும் நாதமும் மேவியுடன் கூடிப்
சந்திர னோடே தலைப்படு மாயிடில்
சுந்தர வானத்து அமுதம்வந்து ஊறிடும்
அங்குஉதி மந்திரம் ஆகுதி யாகுமே`,
    transliteration: `vintuvum nātamum mēviyuṭaṉ kūṭip
cantira ṉōṭē talaippaṭu māyiṭil
cuntara vāṉattu amutamvantu ūṟiṭum
aṅkuuti mantiram ākuti yākumē`,
    english: `1971: When Bindu Merges Ambrosia Wells
When Bindu and Nada uniting in one
Enter the Sphere of Moon within,
The heavenly ambrosia wells and flows;
The Mantra (Aum) that arises there
Is the sacrificial offering to Lord Supreme.`,
    elaborationEnglish: `The heavenly ambrosia wells and flows when bindu and nada enter the sphere of the moon in union. The mantra that emerges there is the sacrificial offering to the Lord.`,
    elaborationTamil: `மேல், ''மேலாம் நிலத்தெழும் விந்துவும்'' என்னும் மந்திரத்திலும், ''விந்துவின் வீசத்தை'' என்னும் மந்திரத்திலும் சொல்லப்பட்டபடி விந்துவும், நாதமும் ஒன்றாகிச் சந்திர மண்டலத்தை அடைந்த பொழுது அங்கு நின்றும் அமுதம் ஒழுகும் காலத்தில் அதனுடன் கலக்கத்தக்க அவிசு 'நின்ற சிகாரம்' என்னும் மந்திரத்தில் சொல்லப்பட்ட பிரணவ மந்திரமேயாகும்.`,
  },
  {
    id: 1973, tantraId: 7, verseNumber: 1972,
    tamil: `மனத்தொடு சத்து மனஞ்செவி யென்ன
இனத்தெழு வார்கள் இசைந்தன நாடி
மனத்தில் எழுகின்ற வாக்கு வசனம்
கனத்த இரதம் அக் காமத்தை நாடிலே`,
    transliteration: `maṉattoṭu cattu maṉañcevi yeṉṉa
iṉatteḻu vārkaḷ icaintaṉa nāṭi
maṉattil eḻukiṉṟa vākku vacaṉam
kaṉatta iratam ak kāmattai nāṭilē`,
    english: `1972: Merge Mind in Bindu, Away From Lust
When the Mind in the Bindu merges,
Then the Mind, the ears and all organs besides
Will together rise the Divine Goal to seek;
But when thought and sound and words
That in the Mind arise
Seek lust,
As fluid thick it transformed be.`,
    elaborationEnglish: `With the union of bindu with the mind, all sense organs rise to seek the divine goal. Thought, sound and words arise in the mind; when bindu is not sublimated, the working of the mind leads to lust.`,
  },
  {
    id: 1974, tantraId: 7, verseNumber: 1973,
    tamil: `சத்தமும் சத்த மனமும் மனக்கருத்து
ஒத்துஅறி கின்ற இடமும் அறிகிலர்
மெய்த்து அறிகின்ற இடம்அறி வாளர்க்கு
அத்தன் இருப்பிடம் அவ்விடம் தானே`,
    transliteration: `cattamum catta maṉamum maṉakkaruttu
ottuaṟi kiṉṟa iṭamum aṟikilar
meyttu aṟikiṉṟa iṭamaṟi vāḷarkku
attaṉ iruppiṭam avviṭam tāṉē`,
    english: `1973: Jnanis Know Lord's Seat
Lord's Seat
The Sound (Nada), and the Mind that perceives Sound,
And the place where
Mind undistracted discerns Truth,
--These they know not;
That place the Jnanis truly know
That verily is Lord's
Seat.`,
    elaborationEnglish: `True jnanis know the Lord’s seat, where the sound (nada)
and the mind that perceives the sound, remain in union.`,
    elaborationTamil: `சூக்குமை முதலிய வாக்குக்களும், அவ்வாக்குக் களால் இயக்கப்படுகின்ற மனம் முதலிய அந்தக் கரணங்களும், அந்த அந்தக்கரணங்களால் உண்டாகின்ற உணர்வுகளும் ஆகிய இவை ஒருங்கு தொக்க நிலையாகிய அறிவின் நிலையை உலகர் அறிய மாட்டார். அதனை உள்ளவாறு அறிய வல்லவர் ஆசான்ம மூர்த்தியின் அருள் பெற்றவரே ஆவர். அவர்க்கு அந்த நிலையே சிவனது இருப்பிடமாதல் விளங்கும்.`,
  },
  {
    id: 1975, tantraId: 7, verseNumber: 1974,
    tamil: `உரம்அடி மேதினி உந்தியில் அப்பாம்
விரவிய தன்முலை மேவிய கீழ்அங்கி
கருமலை மீமிசை கைக்கீழிற் காலாம்
விரவிய சுந்தரம் மேல்வெளி யாமே`,
    transliteration: `uramaṭi mētiṉi untiyil appām
viraviya taṉmulai mēviya kīḻaṅki
karumalai mīmicai kaikkīḻiṟ kālām
viraviya cuntaram mēlveḷi yāmē`,
    english: `1974: Regions of Five Elements in the body
Earth is, where the legs are (Muladhara);
In the navel (Svatisthana) is the Region of Water;
Below the breast (Manipura) is the Fire;
Above the breast (Anahatha) and below the shoulder (Visuddhi) is Air;
And around the neck and beyond (Ajna) is the Region of Space.`,
    elaborationEnglish: `The regions of the five elements are within the body. The
region of earth is mladhara. The navel (svadhistana) is the
region of water. Below the breast (manipuraka) is the fire;
above the breast (manipuraka) and below the shoulder
(visuddhi) is air. The region of space is around the neck and
beyond (ajna)

The location and significance of the 6 chakras in. the body
are to be noted. Only 5 elements are involved. The association
of Space (Akasa) with Ajna cakra is particularly significant,
for it is here, in the two-petalled lotus, that duality is supposed
to disappear into non-duality during Kundalini Yoga.

22. APSShlaeo sea_nOs5cr`,
    elaborationTamil: `மனித உடம்பில் எல்லாவற்றையும் தாங்கும் வலிமையுடைய கலில் (இடைக்குக் கீழ் உள்ள பகுதியில்) 'நிலம்' என்னும் பூதமும், அதற்கு மேல் கொப்பூழ்வரை உள்ள பகுதியில் 'நீர்' என்னும் பூதமும், கொப்பூழ் முதல் முலையிருக்கும் பரந்த இடமாகிய மார்பு பகுதியில் 'தீ' என்னும் பூதமும் (இதனுள் முலையும் அடங்குதல் அறிக.) மார்பிற்குமேல் கைகளுக்கு ஆதாரமாய்க் கழுத்து வரையில் உள்ள பகுதியில் 'வளி' என்னும் பூதமும், (இதனுள் கைகளும் அடங்குதல் அறிக.) கழுத்திற்கு மேல் உள்ள பகுதியில் 'வெளி' என்னும் பூதமும் நிற்கும்.`,
  },
  {
    id: 1976, tantraId: 7, verseNumber: 1975,
    tamil: `செஞ்சுட ரோன்முத லாகிய தேவர்கள்
மஞ்சுடை மேரு வலம்வரு காரணம்
எஞ்சுடர் ஈசன் இறைவன் இணையடி
தஞ்சுட ராக வணங்கும் தவமே`,
    transliteration: `ceñcuṭa rōṉmuta lākiya tēvarkaḷ
mañcuṭai mēru valamvaru kāraṇam
eñcuṭar īcaṉ iṟaivaṉ iṇaiyaṭi
tañcuṭa rāka vaṇaṅkum tavamē`,
    english: `1975: Sun and Other Gods Adore Lord to Receive Illumination
The fiery Sun and the Celestials rest
Circumnambulate the snow-clad Mountain Meru;
And adore the luminous Lord's Holy Feet in Tapas,
That they might, themselves illumined be.`,
    elaborationEnglish: `The fiery ‘sun’ and other celestial gods adore the Holy Feet of the Lord in Tapas, so that they may receive illumination.`,
    elaborationTamil: `(சூரியன் முதலாகக் காணப்படுகின்ற அனைத்து ஒளிப் பொருள்களின் ஒளியும் சிவனது ஒளியேயன்றி, அவற்றினுடையன அல்ல. அஃது எங்ஙனம் எனின்,) சூரியன் நாள்தோறும் மகாமேரு மலையை வலம் வருதல் தெளிவு. ஏனைத் தேவர்கள் அவ்வாறு வலம் வருதலைப் பலர் அறியாராயினும் யோகியரும், ஞானியரும் அதனை நன்கறிவர். 'அவர் வலம்வருதல் எதன்பொருட்டு' எனின், எங்கட்கு விள்ககாகி நின்று பயன் தருகின்ற சிவனாகிய கடவுளின் திருவடி ஒளிகள் தங்களிடத்துப் பொருந்தி விளங்குதற் பொருட்டேயாம். வேண்டிய வேண்டியாங்கு எய்துதல் தவத்தால்l ஆகலின் அவர் அதனைச் செய்கின்றனர்.`,
  },
  {
    id: 1977, tantraId: 7, verseNumber: 1976,
    tamil: `பகலவன் மாலவன் பல்லுயிர்க்கு எல்லாம்
புகலவ னாய்நின்ற புண்ணிய நாதன்
இகலற ஏழுல கும்உற வோங்கும்
பகலவன் பல்லுயிர்க்கு ஆதியும் ஆமே`,
    transliteration: `pakalavaṉ mālavaṉ palluyirkku ellām
pukalava ṉāyniṉṟa puṇṇiya nātaṉ
ikalaṟa ēḻula kumuṟa vōṅkum
pakalavaṉ palluyirkku ātiyum āmē`,
    english: `1976: Sun is the Primal Energy
The Sun is Vishnu;
He is Siva Holy too,
Who as refuge of all creation stands;
He brings prosperity to the seven worlds in accord;
He, the Beginning of lives all.`,
    elaborationEnglish: `The ‘sun’ is protective Vishnu and blessed Siva too. He is
the primal energy and refuge of all creation. He brings
prosperity to all the seven worlds.

Sun is the Primal Energy (Sakti), and is Vishnu, but belongs
to Siva too. This .is an important concept.`,
    elaborationTamil: `ஆதித்தனாலே உலகுயிர்கள் இறைவாது வாழ்தலால், அவன் காத்தற் கடவுளாகிய மாயோனாக ''சூரிய நாராயணன்'' என்று சொல்லப்படுகின்றான். அதனால் அவனே எல்லா உயிர்கட்கும் புகலிடமாகின்ற முதற்கடவுளும் ஆகின்றான். இன்னும் உயிர்கள் நால்வகை யோனிகளுள் கருவாகித் தோன்றுதலும் ஆதித்த னாலே யாகலின் அவனே அனைத்துயிர்கட்கும் முதலுமாவான்.`,
  },
  {
    id: 1978, tantraId: 7, verseNumber: 1977,
    tamil: `ஆதித்தன் அன்பினோடு ஆயிர நாமமும்
சோதியின் உள்ளே சுடரொளி யாய்நிற்கும்
வேதியர் வேண்டினும் விண்ணவர் சொல்லினும்
ஆதியில் அன்பு பழுக்கின்ற வாறே`,
    transliteration: `ātittaṉ aṉpiṉōṭu āyira nāmamum
cōtiyiṉ uḷḷē cuṭaroḷi yāyniṟkum
vētiyar vēṇṭiṉum viṇṇavar colliṉum
ātiyil aṉpu paḻukkiṉṟa vāṟē`,
    english: `1977: Worship Sun, Primal Lord Blesses
Chant in love the thousand names of Sun,
He in you as spark divine glows;
The Vedic brahmins pray,
The Celestial immortals his name chant;
It is the Lord Primal verily
Who blesses all.`,
    elaborationEnglish: `Worship the ‘sun.’ Chant his thousand names in love. Worship of the sun grants the blessing of the Primal Lord.`,
    elaborationTamil: `ஆதித்தனை ஆயிர நாமங்கள் விண்ணவர் சொல்லி வேண்டினாலும், வேதியர்சொல்லி வேண்டினாலும் அவையெல்லாம் சிவபிரானிடத்தில் அன்புதோன்றி முதிர்வதற்கு வழியாகவே அமையும். ஏனெனில், ஆதித்த மண்டலத்தின் ஒளிக்குள் ஒளியாய்ச் சிவபிரானே நிற்றலால்.`,
  },
  {
    id: 1979, tantraId: 7, verseNumber: 1978,
    tamil: `தானே உலகுக்குத் தத்துவனாய் நிற்கும்
தானே உலகுக்குத் தையலு மாய்நிற்கும்
தானே உலகுக்குச் சம்புவு மாய்நிற்கும்
தானே உலகுக்குத் தண்சுட ராகுமே`,
    transliteration: `tāṉē ulakukkut tattuvaṉāy niṟkum
tāṉē ulakukkut taiyalu māyniṟkum
tāṉē ulakukkuc campuvu māyniṟkum
tāṉē ulakukkut taṇcuṭa rākumē`,
    english: `1978: Primal Lord is Source of All
He stands as the
Tattvas for the world,
He stands as Sakti for the world,
He alone is the Being
Uncreated (Sambhu),
He for the world is the
Moon too,
Of soft light divine.`,
    elaborationEnglish: `The Primal Lord alone is the Uncreated Being (Svayambhu),
who stands as the:tattvas and sakti for the world. He is also
the moon of soft yellow light.`,
    elaborationTamil: `ஆதித்தனே உலகிற்கு அப்பனாய் இருப்பன்; அம்மையாய் இருப்பன். சுகத்தைத் தருபவனாய் இருப்பன். இனிச் சந்திரனாய்க் குளிர்ந்த ஒளியைத் தருகின்றவனும் இவனே.`,
  },
  {
    id: 1980, tantraId: 7, verseNumber: 1979,
    tamil: `வவையமுக் கோணம் வட்டம் அறுகோணம்
துலையிரு வட்டம் துய்ய விதம்எட்டில்
அலையுற்ற வட்டத்தில் ஈர்எட்டு இதழாம்
மலைவுற்று உதித்தனன் ஆதித்தன் ஆமே`,
    transliteration: `vavaiyamuk kōṇam vaṭṭam aṟukōṇam
tulaiyiru vaṭṭam tuyya vitameṭṭil
alaiyuṟṟa vaṭṭattil īreṭṭu itaḻām
malaivuṟṟu utittaṉaṉ ātittaṉ āmē`,
    english: `1979: Position of Sun in the Body
Above the triangle of Muladhara Center,
Above the hexagonal Center of Svadishtana,
Above the twin-circle of Manipura Center,
In the moving Center of sixteen petalled Visuddhi,
There indeed rises the Sun within.`,
    elaborationEnglish: `The ‘sun’ within the body arises in the moving centre of sixteen-petalled visuddhi — above the triangle of the :muladhara centre, the hexagonal centre of svadhistana, and the twin-circle of the manipuraka centre.`,
    elaborationTamil: `சதுரம், வட்டம், முக்கோணம் அறுகோணம், துலாக் கோல், இருவட்டம் - என இவ்வாறு மூலாதாரம் முதலாக ஆறு ஆதாரங்களில் அமைந்த பீடங்களில் ஒவ்வொன்றின் மேலும் எட்டிதழ்த் தாமரையில் ஆதித்தன் அசையும் வட்டமாய் உள்ள பதினாறிதழ்களையுடைய தாமரை மலர்போல மாறுபாடின்றி விளங்கினான்.`,
  },
  {
    id: 1981, tantraId: 7, verseNumber: 1980,
    tamil: `ஆதித்தன் உள்ளி லானமுக் கோணத்தில்
சோதித்து இலங்கும்நற் சூரியன் நாலாம்
கேத முறுங்கேணி சூரியன் எட்டில்
சோதிதன் நீட்டில் சோடசம் தானே`,
    transliteration: `ātittaṉ uḷḷi lāṉamuk kōṇattil
cōtittu ilaṅkumnaṟ cūriyaṉ nālām
kēta muṟuṅkēṇi cūriyaṉ eṭṭil
cōtitaṉ nīṭṭil cōṭacam tāṉē`,
    english: `1980: The Sun Confers the Kalas in Adharas
The Sun is within;
When his beams beat
On Muladhara triangule
That receives Kalas four;
When on Visuddhi his shafts fall,
That with Kalas sixteen shines.`,
    elaborationEnglish: `The effulgent ‘sun’ alone can confer the four kalas on muladhara, and the sixteen kalas on visuddhi.`,
    elaborationTamil: `ஆதித்தனுக்கு மிகச்சிறந்த இடமாகிய முக்கோண மண்டலத்தில் அவன் மிக்க ஒளியுடையவனாய் விளங்குவான். அவன் மூலாதாரத்தினின்றும் நான்காவதாகிய இருதயத்தை அளாவி ஓங்குவானாயின் முன் மந்திரத்தில் சொல்லப்பட்ட பதினாறு இதழ் வடிவம் அப்பால் விசுத்தியை அடைந்து அங்குள்ள பதினாறு இதழ்களில் ஒன்றி ஒளிர்வான்.`,
  },
  {
    id: 1982, tantraId: 7, verseNumber: 1981,
    tamil: `ஆதித்த னோடே அவனி இருண்டது
பேதித்த நாலும் பிதற்றிக் கழிந்தது
சோதிக்குள் நின்று துடியிடை செய்கின்ற
வேதப் பொருளை விளங்குகி லீரே`,
    transliteration: `ātitta ṉōṭē avaṉi iruṇṭatu
pētitta nālum pitaṟṟik kaḻintatu
cōtikkuḷ niṉṟu tuṭiyiṭai ceykiṉṟa
vētap poruḷai viḷaṅkuki līrē`,
    english: `1981: Experiences in the Sphere of Sun Within
When you reach the Sphere of Sun
Your worldly thoughts fade into darkness;
The cognitive organs four no more contend--
The Sakti in the light within reveals
The truth of Vedas
But alas! You seek not to understand!`,
    elaborationEnglish: `When you reach the sphere of the ‘sun,’ you rise above worldly thoughts, desires, and contending notions. The sakti in the light within reveals the truth of the Vedas.`,
    elaborationTamil: `ஆதித்தன் இருண்ட பொழுது அவனோடு உலகமும் இருண்டுவிட்டது. வேறுபட்ட நான்கு வேதங்களின் மொழிகளும் வெறும் பிதற்றலாய்ப் பயனற்றுப்போயின. அவ் வாறாகவும் 'ஆதித்தனுக்குள்ளே சிவசத்தி நின்றே உலகிற்கு ஒளியைத் தருகின்றாள்' எனக் கூறுகின்ற வேத மொழியின் பொருளை, நீவிர் உணரமாட்டீர்.`,
  },
  {
    id: 1983, tantraId: 7, verseNumber: 1982,
    tamil: `பாருக்குக் கீழே பகலோன் வரும்வழி
யாருக்கும் காணஒண் ணாத அரும்பொருள்
நீருக்கும் தீக்கும் நடுவே உதிப்பவன்
ஆருக்கும் எட்டாத ஆதித்தன் தானே`,
    transliteration: `pārukkuk kīḻē pakalōṉ varumvaḻi
yārukkum kāṇaoṇ ṇāta arumporuḷ
nīrukkum tīkkum naṭuvē utippavaṉ
ārukkum eṭṭāta ātittaṉ tāṉē`,
    english: `1982: Sun's Route Inside
Below the Earth Center that is Muladhara
The Sun its route takes;
Invisible indeed is he,
Between the Fiery Center (Manipura)
And the Watery Center (Svatishtana) within.`,
    elaborationEnglish: `Within the body, the ‘sun’ takes its route below the earth
centre (muladhara). Indeed he is invisible between the fiery
centre (manipuraka) and the watery centre (svadhistana).`,
    elaborationTamil: `ஆதித்தன்மேல் எழுந்துவருகின்ற வழி நிலத்திற்குக் கீழே யாருக்கும் அறிய ஒண்ணாத அரும்பொருளாய் உள்ளது. (ஆதலின் அதனை அறிய முயல வேண்டுவதின்று.) இனிக் கண்ணிற்கு நன்கு புலனாயினும் யாராலும் அணுகிப் பற்ற இயலாத ஆதித்தன் புறப்பட்டுத் தோன்றுதல் நீருக்கும், தீக்கும் நடுவேயாகும்.`,
  },
  {
    id: 1984, tantraId: 7, verseNumber: 1983,
    tamil: `மண்ணை இடந்துஅதின் கீழொடும்
விண்ணை இடந்து வெளிசெய்து நின்றிடும்
கண்ணை இடந்து களிதந்த ஆனந்தம்
எண்ணும் கிழமைக்கு இசைந்து நின்றானே`,
    transliteration: `maṇṇai iṭantuatiṉ kīḻoṭum
viṇṇai iṭantu veḷiceytu niṉṟiṭum
kaṇṇai iṭantu kaḷitanta āṉantam
eṇṇum kiḻamaikku icaintu niṉṟāṉē`,
    english: `1983: Sun's Course in the Higher Adharas
He penetrates beyond into the Adharas that
Are Sky (Visuddhi) and
Space (Ajna) within;
He is the very source of joy that dazzles the eye;
He indeed responds to contemplation sweet.`,
    elaborationEnglish: `The ‘sun’ breaking through the earth (muladhara) penetrates
beyond into the higher adharas — sky (visuddhi) and space
(ajna). He is the source of joy that dazzles the vision and
truly responds to sweet contemplation.`,
    elaborationTamil: `ஆதித்தன் நிலத்தைப் பிளந்து கொண்டு அதன் கீழேயும் ஓடுகின்றான். பின்பு மேலே வந்து ஆகாயத்தைப் பிளந்துகொண்டு எங்கும் ஒளிமயமாகவும் செய்கின்றான். மற்றும் உயிர்களின் கண்களைத் துளைத்து அவற்றுள்ளேயும் புகுந்து இருளை ஓட்டி மகிழ்ச்சியைத் தருகின்றான். அந்த இன்பத்தை நினைத்தல் கடமையாகலின் அக்கடமையில் வழுவாது நின்று அவனைத் தியானித்தற்கும் அவன் உடன்பட்டு நிற்கின்றான்.`,
  },
  {
    id: 1985, tantraId: 7, verseNumber: 1984,
    tamil: `பாரை இடந்து பகலோன் வரும்வழி
யாரும் அறியார் அருங்கடை நூலவர்
தீரன் இருந்த திருமலை சூழ்என்பர்
ஊரை உணர்ந்தார் உணர்ந்திருந் தாரே`,
    transliteration: `pārai iṭantu pakalōṉ varumvaḻi
yārum aṟiyār aruṅkaṭai nūlavar
tīraṉ irunta tirumalai cūḻeṉpar
ūrai uṇarntār uṇarntirun tārē`,
    english: `1984: Sun Circumambulates Sahasrara
The sun that penetrates Earth (Muladhara)
His route none knows,
That are but versed in worldly lore;
He circumambulates Mount of Meru, (Sahasrara)
Of the Lord Unconquerable;
--Thus they say;
Only those who have realized Truth
Know His abode real.`,
    elaborationEnglish: `No one knows this route of the ‘sun.’ Folks believe only the
worldly lore. Only they who have realised know the truth
that the ‘sun’ circumambulates Mount Meru (sahasrara) of
the Invincible Lord.

23. Dear_n8ss5er`,
    elaborationTamil: `ஆதித்தன் நிலத்திற்குக் கீழிருந்து அதனைப் பிளந்து கொண்டு மேலே எழுவது போலத் தோற்றுகின்ற அந்த வழியின் உண்மையை, தாழ்ந்த நிலையில் உள்ளார்க்கு உரிய நூலை மட்டுமே உணர்ந்தவர்களில் ஒருவரும் அறியமாட்டார். (அதனை அவ்வாறே கொள்வர். உண்மையில் அது புறநிலையில் நில உருண்டையின் சுழற்சியும், அகநிலையில் மேற்கூறியவாறு மூலா தாரத்திற்குக் கீழ் நின்றுமேல் எழுதலும் ஆகும்.) இனி அவ்வாதித்தின் விண்ணில் காணப்படும் பொழுது அவன் சிவபிரான் எழுந்தருளி யிருக்கின்ற மகாமேரு மலையை வலம் வருகின்றான் என்றே கொள்வர். (உண்மையில் அதுவும் புற நிலையில் நில உருண்டையின் சுழற்சியும், அகநிலையில் மேற்கூறியவாறு வீணாத் தண்டைச் சூழ்ந்து ஒளிர்வதுமேயாகும்.) கோள்களின் இயக்கம் பற்றியும், பிராணா யாமம் பற்றியும் இனிது விளங்கக் கூறும் நூல்களின் வழி அவற்றை உணர்ந்த ஒரு சிலரே மேற்கூறிய உண்மைகளை உணர்ந்திருந்தனர்.`,
  },
  {
    id: 1986, tantraId: 7, verseNumber: 1985,
    tamil: `நின்றும் இருந்தும் கிடந்தும் நடந்தும்
கன்றாய நந்திக் கருத்துள் இருந்தனன்
கொன்று மலங்கன் குழல்வழி ஓடிட
வென்று விளங்கும் விரிசுடர் காணுமே`,
    transliteration: `niṉṟum iruntum kiṭantum naṭantum
kaṉṟāya nantik karuttuḷ iruntaṉaṉ
koṉṟu malaṅkaṉ kuḻalvaḻi ōṭiṭa
veṉṟu viḷaṅkum viricuṭar kāṇumē`,
    english: `1985: Vision Sun Within Through Spinal Way
Staning, sitting, walking and lying prostrate
Nandi the benevolent in my thoughts incessant stood;
Destroy your Malas (Impurities)
And ascend the Adharas
Through Sushumna Central;
There shall you vision the Sun
That within shines in brightness nonpareil.`,
    elaborationEnglish: `Nandi stood in my thought in all postures. Destroy the malas (impurities), ascend the adharas through the central sushumna. There you will behold the sun blazing bright.`,
    elaborationTamil: `உயிர்கள் உடம்போடு கூடிநிற்றல், இருத்தல், கிடத்தல், நடத்தல் முதலிய எத்தொழிலைச் செய்யினும் அவ் வுயிர்களில் அழுந்தப் பொருந்தியுள்ள சிவன் அவற்றின் உடம்பில் உள்ள ஆதாரங்களில் நீக்கமின்றி நிற்கின்றான். பிராணவாயு இடநாடி வல நாடிகளை ஒழித்து நடுநாடி வழியாக ஓடினால் அஃது ஆதித்தனைப் போல ஒளியுடையதாய்க் காணப்படும். அந்த ஒளியில் சிவன் மும்மலங்களை ஒழித்து, உயிர்களின் தற்போதத்தையும் அடக்கி, அவற்றின் அறிவுக்கறிவாய் விளங்குவான்.`,
  },
  {
    id: 1987, tantraId: 7, verseNumber: 1986,
    tamil: `ஆதித்தன் ஓடி அடங்கும் இடங்கண்டு
சாதிக்க வல்லவர் தம்மை யுணர்ந்தவர்
பேதித்து உலகம் பிதற்றும் பிதற்றெல்லாம்
ஆதித்தனோடே அடங்குகின் றாரே`,
    transliteration: `ātittaṉ ōṭi aṭaṅkum iṭaṅkaṇṭu
cātikka vallavar tammai yuṇarntavar
pētittu ulakam pitaṟṟum pitaṟṟellām
ātittaṉōṭē aṭaṅkukiṉ ṟārē`,
    english: `1986: The Self-Realized Reach Sun
They who by Adhara-ascending
Reach and see where the Sun within reposes
They indeed are the self-realized ones;
They who differ from this
And say aught they like,
Are in darkness enveloped,
As when the Sun here, below horizon dips.`,
    elaborationEnglish: `Verily, they who reach the sun by ascending the adharas
realise their Selves.`,
    elaborationTamil: `'பிண்டாதித்தன்' என மேற்கூறிய பிராணன் ஓடுமளவும் ஓடி ஒடுங்கி நிற்கும் இடத்தை 'இது' என உணர்ந்து அவ்விடத்திலே நின்று பயன்பெற வல்லவரே தம்மை அண்டாதித்தன் இயக்கத்திற்கு வேறாய்ப் பிண்டாதித்தன் இயக்கத்தின் வழிபட்டவராக உணர்ந்து அவ்வியக்கத்தால் நீண்டகாலம் இவ்வுலகில் வாழ்வர். உலகம் இவ்வியல்பின் வேறுபட்டுத் தான் அறிந்ததையே அறிவாக நாட்டித் தான் வல்ல வற்றை ஓயாது கூறும். அக்கூற்றினைத் தெளிந்தோர் எல்லாம் அந்த அண்ட ஆதித்தனது இயக்கத்திற்கு உட்பட்டு விரைவில் மாய்பவரேயாவர்.`,
  },
  {
    id: 1988, tantraId: 7, verseNumber: 1987,
    tamil: `உருவிப் புறப்பட்டு உலகை வலம்வந்து
சொருகிக் கிடக்கும் துறையறி வார்இல்லை
சொருகிக் கிடக்கும் துறையறி வாளர்க்கு
உருகிக் கிடக்கும்என் உள்ளன்பு தானே`,
    transliteration: `uruvip puṟappaṭṭu ulakai valamvantu
corukik kiṭakkum tuṟaiyaṟi vārillai
corukik kiṭakkum tuṟaiyaṟi vāḷarkku
urukik kiṭakkumeṉ uḷḷaṉpu tāṉē`,
    english: `1987: Those Who Know the Sun Within is Worthy of Adoration
They penetrate not the
Adharas,
Search not the world within,
And know not where in its midst Sun is;
Those who know where he furtive lies
To them my heart
In love melts.`,
    elaborationEnglish: `The yogi’s heart melts in love for those who contemplate
the sun within as worthy of .adoration.`,
    elaborationTamil: `[இம் மந்திரம் அண்டாதித்தன், பிண்டாதித்தன் இருவர்க்கும் பொருந்தக் கூறியது.]. அண்டாதித்தன் கீழ் நின்றும் ஊடுருவி மேலே புறப்பட்டு உலகைச் சுற்றிச் சென்று, முடிவில் ஒடுங்கி நிற்பது உலக முதல்வ னாகிய சிவனிடத்திலாகும். அவ்வாறே பிண்டாதித்தனும் மூலா தாரத்திற்குக் கீழ் நின்றும் உருவி மூலாதாரத்திலே வெளிப்பட்டு மேலே ஏனை ஆதாரங்களையும் கடந்து, முடிவில் ஒடுங்கி நிற்பது ஆஞ்ஞை யில் உள்ள சதாசிவ மூர்த்தியினடத்தி லாகும். ஆகவே எவ்வகை யிலும் உயிர்கட்குப் புகலிடமாகின்றவன் சிவனேயாவன். ஆயினும் இவ்வுண்மையை அறிபவர் உலகில் இல்லை. அறிபவர் எவரேனும் இருப்பின், எனது உள்ளத்தில் உள்ள அன்பு அவரிடமே சென்று உருகி நிற்கும்.`,
  },
  {
    id: 1989, tantraId: 7, verseNumber: 1988,
    tamil: `எறிகதிர் ஞாயிறு மின்பனி சோரும்
எறிகதிர் சோமன் எதிர்நின்று எறிப்ப
விரிகதிர் உள்ளே இயங்கும் என் ஆவி
ஒருகதிர் ஆகில் உலாஅது ஆமே`,
    transliteration: `eṟikatir ñāyiṟu miṉpaṉi cōrum
eṟikatir cōmaṉ etirniṉṟu eṟippa
virikatir uḷḷē iyaṅkum eṉ āvi
orukatir ākil ulāatu āmē`,
    english: `1988: Life's Full Moon Within
The luminous Sun dewy cool becomes
When Moon spreads its contending rays;
In the luminosity that commingling emanates,
My yearning Prana as a ray beams,
That verily is my life's Full Moon.`,
    elaborationEnglish: `When the moon spreads its rays, the sun becomes dewy cool. In the soft luminosity that emanates, the yogi’s soul emits a beam. That truly is his life’s full moon.’`,
    elaborationTamil: `பூர்ணிமை நாளில் மிக விளங்குகின்ற சந்திரன், தெறும் இயல்பினையுடைய கதிர்களையுடைய சூரியனுக்கு எதிரே நின்று தன் கதிர்களை வீசும் இயல்பு அமைந்திருக்குமாயின், அந்தச் சூரியனும் குளிர்ந்த கதிர்களை வீசுவோன் ஆகிவிடுவான். (அந்த அமைப்புத்தான் இல்லையே!) பிண்டாதித்தனுக்குள்ளே விளங்கு கின்ற எனது மனம் அவனால் ஓர் ஆதித்தனாயின், அது பின்பு பிண்டத் துள்ளே விளங்கும் சந்திர மண்டல்தினது அமுத தாரையால் பூர்ணிமை நாளில் தோன்றுகின்ற சந்திரனாகிவிடும்.`,
  },
  {
    id: 1990, tantraId: 7, verseNumber: 1989,
    tamil: `சந்திரன் சூரியன் தான்வரின் பூசனை
முந்திய பானுவில் இந்துவந்து ஏய்முறை
அந்த இரண்டும் உபய நிலத்தில்
சிந்தை தெளிந்தார் சிவமாயி னரே`,
    transliteration: `cantiraṉ cūriyaṉ tāṉvariṉ pūcaṉai
muntiya pāṉuvil intuvantu ēymuṟai
anta iraṇṭum upaya nilattil
cintai teḷintār civamāyi ṉarē`,
    english: `1989: To See the Blending of the Rays of Sun and Moon is
Divine
When on Sun, Moon's rays afore fall,
That in order is;
When on Sun, Moon's rays beat,
Divine indeed;
In that mystic land
Where the two shafts mingle
They who the Light see,
Have Siva Himself become.`,
    elaborationEnglish: `To vision the union of the beams of the sun and moon in
the mystic land within is divine. They who have visioned it
have indeed become Siva Himself.`,
    elaborationTamil: `'சந்திர கலை' எனப்படும் இட நாடியில், 'சூரிய கலை' எனப்படும் வல நாடிக் காற்று ஒடுங்கி இட நாடிக் காற்றே இயங்கினும் பின்னர் மாறி இயங்கும் காலமே சிவனைப் பூசித்தற்கு உரிய காலமும். ('ஆகவே, பூசை செய்வோர் அவ்வாறு செய்து கொள்க' என்பதாம்.) இனி அந்த இருவழியிலும் யோகம் ஆதலின், அவ்வாறு யோகம் செய்பவரே அந்தக்கரணம் தூய்மையாகப் பெற்றவர் ஆவர். அவரே பின்பு சிவயோகத்தால் சிவமாகி நிற்பர்.`,
  },
  {
    id: 1991, tantraId: 7, verseNumber: 1990,
    tamil: `ஆகும் கலையோடு அருக்கன் அனல்மதி
ஆகும் கலையிடை நான்குஎன லாம்என்பர்
ஆகும் அருக்கன் அனல்மதி யோடுஒன்ற
ஆகும்அப் பூரணை யாம்என்று அறியுமே`,
    transliteration: `ākum kalaiyōṭu arukkaṉ aṉalmati
ākum kalaiyiṭai nāṉkueṉa lāmeṉpar
ākum arukkaṉ aṉalmati yōṭuoṉṟa
ākumap pūraṇai yāmeṉṟu aṟiyumē`,
    english: `1990: Full Moon Within
With Kalas three of Sun, Moon and Fire
Arises the Kala from intermingling of their rays
Thus are they, Kalas Four;
When Sun, Moon and Fire mingle their rays,
Then is Full Moon within, know this.`,
    elaborationEnglish: `The full moon is within, when the rays of the sun, moon and fire merge.`,
    elaborationTamil: `யோக முறையில், சூரியன், அக்கினி, சந்திரன்' எனச் சொல்லப்படுகின்ற கலைகளோடு, அக்கினி செல்லும் வழியாகிய நடு நாடியும் 'கலை' என்று சொல்லப்படும். ஆகவே, கலைகளாவன நான்காம். அவற்றுள் சூரிய கலை, நடு நாடி வழியாக மேற்செல்கின்ற அக்கினியோடு சேர்ந்து சந்திர மண்டலத்தை அடையின் அந்நிலையே யோகியர்க்கு, மேல், 'உவா' எனக்குறித்த பூரணையாகும் என்று அறிமின்கள்.`,
  },
  {
    id: 1992, tantraId: 7, verseNumber: 1991,
    tamil: `ஈர் அண்டத்து அப்பால் இயங்கிய அவ்வொளி
ஓர் அண்டத் தார்க்கும் உணரா உணர்வது
பேர்அண்டத்து ஊடே பிறங்கொளி யாய்நின்று
ஆர் அண்டத் தக்கார் அறியத்தக் காரே`,
    transliteration: `īr aṇṭattu appāl iyaṅkiya avvoḷi
ōr aṇṭat tārkkum uṇarā uṇarvatu
pēraṇṭattu ūṭē piṟaṅkoḷi yāyniṉṟu
ār aṇṭat takkār aṟiyattak kārē`,
    english: `1991: The Vision of Ethereal Light Within
The Light that shone beyond the orbs two,
Is a Light that none in any realm can perceive;
It is a Light that shone piercing the Cosmic Universe;
Who can near it, who can perceive it!`,
    elaborationEnglish: `The ethereal light that shines beyond the two orbs within is imperceptible. It is the light that pierces the cosmic universe.`,
    elaborationTamil: `கீழ்ஏழ் உலகங்களை உள்ளடக்கியுள்ள அண்டமும், மேல் ஏழ் உலகங்களை உள்ளடக்கியுள்ள அண்டமும் ஆகிய இரண்டு அண்டங்களையும் கடந்து அவற்றிற்கு அப்பால் விளங்குகின்ற ஓர் ஒளி பரமசிவன். அவ்வொளி எந்த உலகத்தார்க்கும் உணர இயலாத உணர் வாய் இருப்பது. எனினும் அஃது எல்லா உலகங்களிலும் விளங்குகின்ற எல்லா வகையான ஒளிகளிலும் உள்ளொளியாய் நிற்றலை அறியத் தக்கவர் யார்? அணுகத்தக்கவர் யார்? ஒருவரும் இலர்.`,
  },
  {
    id: 1993, tantraId: 7, verseNumber: 1992,
    tamil: `ஒன்பதின் மேவி உலகம் வலம்வரும்
ஒன்பதும் ஈசன் இயல்அறி வார்இல்லை
முன்புஅதின் மேவி முதல்வன் அருளிலார்
இன்பம் இலார்இருள் சூழநின் றாரே`,
    transliteration: `oṉpatiṉ mēvi ulakam valamvarum
oṉpatum īcaṉ iyalaṟi vārillai
muṉpuatiṉ mēvi mutalvaṉ aruḷilār
iṉpam ilāriruḷ cūḻaniṉ ṟārē`,
    english: `1992: The Nine Planets Lacking Grace Whirl in Darkness
The nine orbs (planets) go round the earth,
But none of nine, knows Lord;
Well may the nine orbs, Him, propitiate;
Yet His Grace they receive not;
Devoid of bliss, in darkness surrounded they are.`,
    elaborationEnglish: `The nine planets,.though they go round the ‘earth whirl in darkness; for they do not know the Lord. To them are not given His Divine Grace and Bliss.`,
    elaborationTamil: `உலகம் ஒன்பது கோள்களில் உளம்பொருந்தி, அதனால் அமை காணாது அலமருகின்றது. (''வேரண்டத் துள்ளே பிறங்கொளியாய் நின்றது'' என மேற்கூறியபடி) 'ஒன்பது கோள்களின் ஆற்றலும் சிவனது ஆற்றலே' என்னும் உண்மையை உணர்ந்து அவனையடைந்து அமைதிகாண்பவர் ஒருவரும் இல்லை. முதலில் அந்நிலையில் நிற்பினும் பின்பாவது அருளாளரது அருள் மொழிகளைக் கேட்டுச் சிவனது அருளைப் பெறாதவர் ஒரு ஞான்றும் இன்பம் இல்லாதவரேயாய்த் துன்பத்தையே உடையவராய் இருப்பர்.`,
  },
  {
    id: 1994, tantraId: 7, verseNumber: 1993,
    tamil: `விந்து அபரம் பரம்இரண் டாய்விரிந்து
அந்த அபரம் பரநாத மாகியே
வந்தன தம்மில் பரங்கலை யாதிவைத்து
உந்தும் அருணோ தயமென்ன உள்ளத்தே`,
    transliteration: `vintu aparam paramiraṇ ṭāyvirintu
anta aparam paranāta mākiyē
vantaṉa tammil paraṅkalai yātivaittu
untum aruṇō tayameṉṉa uḷḷattē`,
    english: `1993: Sun's Para Kalas evoluted from Bindu Through Para Nada
The Bindu expand into two Apara and Para
The Apara becomes the Para Nada
From Para Nada arises the Para Kalas
With those Kalas the Jnana Sun within dawns.`,
    elaborationEnglish: `The nine planets, though they go round the earth, whirl in darkness; for they do not know the Lord. To them are not given His Divine Grace and Bliss.`,
    elaborationTamil: `சுத்த மாயையின் ஒருகூறு சிவனது சத்தியால் உலகத் தோற்றம் நிகழத்ற்குக் காரணமாகப் பக்குவப்படுத்தப்படும். அங்ஙனம் பக்குவப்படுத்தப்பட்ட பகுதி, 'மேற்பகுதியும் கீழ்ப் பகுதியும்' என இரண்டு பகுதியாய் விரியும். அவை முறையே 'பரவிந்து' என்றும், 'அபரவிந்து' என்றும் பெயர் பெறும். அவற்றினின்றும் முறையே சொல்லுலகத்தின் அதிசூக்கும நிலையாகிய பரநாதமும், சூக்கும நிலையாகிய அபர நாதமும் தோன்றும். (இவையே அதிசூக்குமை வாக்கும், சூக்குமை வாக்கும் ஆகும்.) பின்பு அவற்றினின்றும் வைகரி முதலிய வாக்கு வடிவமான சொல்லுலகத்தையும், 'கலை, தத்துவம், புவனம்' என்னும் அத்துவாக்களையும் சிவன் தோற்றுவித்து, அவை வழியாக ஆன்ம அறிவினிடத்தே அருணோதயம் போன்ற ஒளியை விளங்கச் செய்வான்.`,
  },
  {
    id: 1995, tantraId: 7, verseNumber: 1994,
    tamil: `உள்ள அருணோ தயத்தெழும் ஓசைதான்
தெள்ளும் பரநாதத் தின்செயல் என்பதால்
வள்ளல் பரவிந்து வைகரி யாதிவாக்கு
உள்ளன ஐங்கலைக்கு ஒன்றாம் உதயமே`,
    transliteration: `uḷḷa aruṇō tayatteḻum ōcaitāṉ
teḷḷum paranātat tiṉceyal eṉpatāl
vaḷḷal paravintu vaikari yātivākku
uḷḷaṉa aiṅkalaikku oṉṟām utayamē`,
    english: `1994: In the Five Kalas Arise the Five Sound Forms
The Sound that arises
When Sun within dawns
Is emanation from Para Nada;
The Sounds Five, Vaikhari and rest
That to Para Bindu belong
Arise in Kalas Five, one in each.`,
    elaborationEnglish: `1) For notes on the four sounds (vaks) see Mantra 2007, ibid: The fifth sound is known as panchamai which is located in the muladhara. Its form is pravana.

a) Vaikhari — articulated speech. Its source is below the tongue.

b) Madhyamai — sound as it reaches the throat. Its source is between the heart and throat. Its shape is the letter formed articulately inside.

c) Paysanti — thought form sourfd (no letter form) Its source is the stomach. Its shape is prana.

d) Sukshmai.— unarticulated sound. Its source is the navel. Its shape is intelligence.

e) Panchamai — subtle sound-source. Its source is ultra subtle. shape is Pranava.

2) For notes on the five kalas, where the five sound-forms repose, see Mantra 1926, ante.`,
    elaborationTamil: `ஆன்ம அறிவில் அருணோதயம் போலத் தோன்று வதாக முன் மந்திரத்திற் குறித்த விளக்கத்திற்குக் காரணமான எழுத் தோசை, 'பர நாதத்தின் காரியம்' என ஆகமங்களில் சொல்லப் படுதலால், அந்தப் பரநாதத்திற்குக் காரணமாக மேற்குறிக்கப்பட்ட அந்தப் பரவிந்துவிலிருந்தே வைகரி முதலியவாக்குக்களால் நிவிர்த்தி முதலிய ஐங்கலைகளிலும் அறிவு விளக்கம் சிவனால் உண்டாவதாகும்.`,
  },
  {
    id: 1996, tantraId: 7, verseNumber: 1995,
    tamil: `தேவர் பிரான்திசை பத்துஉத யஞ்செய்யும்
மூவர் பிரான்என முன்னொரு காலத்து
நால்வர் பிரான்நடு வாயுரை யாநிற்கும்
மேவு பிரான்என்பர் விண்ணவர் தாமே`,
    transliteration: `tēvar pirāṉticai pattuuta yañceyyum
mūvar pirāṉeṉa muṉṉoru kālattu
nālvar pirāṉnaṭu vāyurai yāniṟkum
mēvu pirāṉeṉpar viṇṇavar tāmē`,
    english: `1995: Sadasiva is the Finite Source of Formless and Formed
Sounds
He is the Lord of Devas;
He creates the directions ten;
Of yore they hailed Him as Lord of Three;
He is the Lord of the Four too;
In them He stands as Being Central,
Thus verily, the Immortal Celestials say.`,
    elaborationEnglish: `The ‘Sun’ rises in the ten directions. He is the Lord of devas.
He is Siva, the Supreme Lord of the three Gods. He is
Sadasiva, the central Being of the four Gods — thus say
immortal celestials.

1) Brahma, Vishnu, and Rudra

2) Nada; bindu, Siva, Sakti — the formless four.`,
    elaborationTamil: `'தேவர்கள் தம் தம் பதவி விருப்பத்தால் விரும்பு கின்ற முழுமுதற் கடவுளாவான் பத்துத் திசைகளிலும் நின்று காவல் புரிகின்ற நூற்றெட்டு உருத்திரர்கட்கும் தலைவன்' என்றும், 'பொது வாக - மும்மூர்த்திகள் என்று யாவராலும் சொல்லப்படுகின்ற - அயன், அரி, அரன் - என்பவர்கட்குத் தலைவன்' என்றும் தொன்மையாக பலர் சொல்லிவர, 'முதற்கடவுள் அவ்வளவில் நில்லாது மேற்குறித்த மூவர்க்கும் மேலாய் நான்காமவனாய் உள்ள மகேசுரனை உள்ளிட்ட நால்வர்க்கும் தலைவனாவான்' எனச் சமயக் கணக்குக்களைக் கடந்து நிற்கின்ற உண்மை நூல்கள் உண்மையைச் சொல்லா நிற்கும் என உயர்ந்தோர் கூறுவர்.`,
  },
  {
    id: 1997, tantraId: 7, verseNumber: 1996,
    tamil: `பொய்யிலன் மெய்யன் புவனா பதிஎந்தை
மையிருள் நீக்கும் மதிஅங்கி ஞாயிறு
செய்யிருள் நீக்கும் திருவுடை நந்திஎன்
கையிருள் நீங்கக் கலந்தெழுந் தானே`,
    transliteration: `poyyilaṉ meyyaṉ puvaṉā patientai
maiyiruḷ nīkkum matiaṅki ñāyiṟu
ceyyiruḷ nīkkum tiruvuṭai nantieṉ
kaiyiruḷ nīṅkak kalanteḻun tāṉē`,
    english: `1996: Siva Dispels Darkness
He is the Truth,
Unreal He is not;
He is the Lord of the
Universe;
My Father;
He is the Sun, Moon and
Fire that darkness dispel;
He dispels too the darkness of Karma,
He, the Nandi Holy, to me appeared
The darkness of my low desires to dispel.`,
    elaborationEnglish: `The Holy Nandi, the Lord of the universe, dispels the darkness of karma. He is also the sun, moon and fire that drives away the darkness of ignorance; and when He beams with His benevolent shafts of light, then flows the honey of the divine fruit. Then, the Lord of Kailas stood within me as Resplendent Light.`,
    elaborationTamil: `முன்மந்திரத்திற் கூறியவாறு சதாசிவ மூர்த்தியாய் நின்று ஐந்தொழில் நடாத்தும் முதல்வன் அவ்வாறு தொழில்புரிய நிற்பதற்கு முன்பே என்னை இயல்பாகவே பற்றி நிற்கின்ற, வெறுக்கத் தக்க அக இருளை நீக்குதற் பொருட்டு என் உயிருக்கு உயிராய்க் கலந்து நின்று, அதன் பின்பு தொழில் புரிய எழுந்தான்.`,
  },
  {
    id: 1998, tantraId: 7, verseNumber: 1997,
    tamil: `தனிச்சுடர் ஏற்றித் தயங்கிருள் நீங்க
அனித்திடும் மேலை அருங்கனி ஊறல்
கனிச்சுட ராய்நின்ற கயிலையில் ஈசன்
நனிச்சுடர் மேல்கொண்ட வண்ணமும் ஆமே`,
    transliteration: `taṉiccuṭar ēṟṟit tayaṅkiruḷ nīṅka
aṉittiṭum mēlai aruṅkaṉi ūṟal
kaṉiccuṭa rāyniṉṟa kayilaiyil īcaṉ
naṉiccuṭar mēlkoṇṭa vaṇṇamum āmē`,
    english: `1997: Siva is the Light Resplendent
With His peerless rays
He dispelled my darkness;
And the divine fruit's honey within flowed;
Beaming with benevolent rays
As Lord of Kailas, He stood;
Within me too He stood aloft
As Light Resplendent.`,
    elaborationTamil: `முன் மந்திரத்தில் கூறியபடி உயிர்களது இருளை நீக்கவேண்டி அவற்றினுள்ளே உள்ள சிவனது, 'திரு' எனப்பட்ட ஒப்பற்ற ஒளி தாக்கிப் பரவுதலால் அவ்விடத்துள்ள இருளாகிய மலம் நீங்கும். அது நீங்கினால் அந்த ஒளிக்கு மேலே உள்ள சிவமாகிய அரிய கனியின் சாறு அக்கனியினின்று வெளிப்பட்டு ஒழுகி இனிக்கும் அப்பொழுது ஊழிக் காலத்தும் அழியாத ஒளியினதாய் விளங்கும் கயிலாய மலைமேல் சிவன் நண்ணிப் பேரொளியுடன் திருமேனி கொண்டு வீற்றிருக்கும் காரணமும் விளங்கும்.`,
  },
  {
    id: 1999, tantraId: 7, verseNumber: 1998,
    tamil: `நேரறி வாக நிரம்பிய பேரொளி
போரறி யாது புவனங்கள் போய்வரும்
தேரறி யாத திசையொளி யாயிடும்
ஆரறி வாரிது நாயக மாமே`,
    transliteration: `nēraṟi vāka nirampiya pēroḷi
pōraṟi yātu puvaṉaṅkaḷ pōyvarum
tēraṟi yāta ticaiyoḷi yāyiṭum
āraṟi vāritu nāyaka māmē`,
    english: `1998: He is Supreme Light
His dazzling Light as Wisdom True spreads;
Unhindered, it invades worlds all;
It is the light pervasive, none can fathom;
Who does know it as the Light Supreme!`,
    elaborationEnglish: `He is the Supreme Light that diffuses as true wisdom. That light pervades the entire world. None can fathom its spread and depth.`,
    elaborationTamil: `உயிர்களது அறிவினுள்ளே நுண்ணறிவாய் நிறைந்து நிற்கின்ற ஒரு பெரிய ஒளி, தடையின்றி எங்கும் போய் வருகின்ற பகலவனது தேர் செல்லாத இடத்தில் அங்குள்ள இருளை நீக்குகின்ற ஒளியாய் இருக்கும். இம்மறை பொருளை உணரும் அறிவுடையோர் யாவர்? எவரேனும் இருப்பாராயின் அவரது அறிவே தலைமை சான்ற அறிவாகும்.`,
  },
  {
    id: 2000, tantraId: 7, verseNumber: 1999,
    tamil: `மண்டலத் துள்ளே மலர்ந்தெழும் ஆதித்தன்
கண்டிதத் துள்ளே கதிரொளி ஆயிடும்
சென்றிடத்து எட்டுத் திசையெங்கும் போய்வரும்
நின்றிடத் தேநிலை நேரறி வார்க்கே`,
    transliteration: `maṇṭalat tuḷḷē malarnteḻum ātittaṉ
kaṇṭitat tuḷḷē katiroḷi āyiṭum
ceṉṟiṭattu eṭṭut ticaiyeṅkum pōyvarum
niṉṟiṭat tēnilai nēraṟi vārkkē`,
    english: `1999: The Jnana Sun is Within and Without
The Sun that rises in firmament vast
Stands within too shedding rays divine;
In directions eight he traverses constant;
Yet in them that Truth know
He stands for ever fixed within.`,
    elaborationEnglish: `The jnana sun constantly traverses in eight directions. It is within and without.`,
    elaborationTamil: `அண்டத்தில் ஒரு வட்ட வடிவினனாய்க் காணப் படுகின்ற ஆதித்தன் உலகில் எட்டுத் திக்கிலும் சென்று அலமருவார்க்கு அவர் சென்ற இடத்தில் எல்லாம் காணப்பட்டு ஒளியை வழங்குவான். வெளியில் அங்ஙனம் அலமரும் நிலையை விட்டு முன் மந்திரத்தில் கூறிய நுண்ணிறிவை அறிந்து அகத்தே நோக்குபவர்க்கு அவன் உட்பினுள் காண்கின்ற பல இடத்திலும் விளங்கி ஒளிதருகின்றவன் ஆவான்.`,
  },
  {
    id: 2001, tantraId: 7, verseNumber: 2000,
    tamil: `நாபிக்கண் நாசிநயன நடுவினும்
தூபியோடு ஐந்தும் சுடர்விடு சோதியைத்
தேவர்கள் ஈசன் திருமால் பிரமனும்
மூவரு மாக உணர்ந்திருந் தாரே`,
    transliteration: `nāpikkaṇ nācinayaṉa naṭuviṉum
tūpiyōṭu aintum cuṭarviṭu cōtiyait
tēvarkaḷ īcaṉ tirumāl piramaṉum
mūvaru māka uṇarntirun tārē`,
    english: `2000: Five Centers where the Light of Lord is
In the navel, eye and nose tip,
In the center of eyebrows, and within crown of head
In these five places, Lord resides as Light Divine;
He is the One Lord
The Devas saw as Three,
Brahma, Vishnu and Isa.`,
    elaborationEnglish: `Navel, eye, nose tip, centre of eyebrows, and the crown of the head are the five centres where the Divine Lord resides. The devas perceived Him in three forms — Brahma, Vishnu and Isa.`,
    elaborationTamil: `கொப்பூழ், கண், மூக்கு, புருவநடு, தலைக்குப் பன்னிரண்டங்குலத்திற்கு மேல் என்னும் ஐந்திடங்களிலும் தோன்றி ஒளி வீசுகின்ற அந்த ஆதித்தனைத் தேவர்கள், 'உருத்திரன், மால், அயன்' என்னும் மும்மூர்த்திகளாக அறிந்து இன்புற்றிருக்கின்றனர்.`,
  },
  {
    id: 2002, tantraId: 7, verseNumber: 2001,
    tamil: `அன்றிய பாச இருளும்அஞ் ஞானமும்
சென்றிடு ஞானச் சிவப்பர காசத்தால்
ஒன்றும் இருசட ராம்அரு ணோதயம்
துன்றிருள் நீங்குதல் போலத் தொலைந்ததே`,
    transliteration: `aṉṟiya pāca iruḷumañ ñāṉamum
ceṉṟiṭu ñāṉac civappara kācattāl
oṉṟum irucaṭa rāmaru ṇōtayam
tuṉṟiruḷ nīṅkutal pōlat tolaintatē`,
    english: `2001: Siva is Sun of Jnana
The darkness of contending Pasa,
And the Ignorance vast
These flee fast,
Before the Jnana Light of Siva,
Even as when the luminous Sun rises,
The murky darkness, before him, flees.`,
    elaborationEnglish: `Siva is the sun of jnana. When His light of jnana dawns,
the murky darkness of contending pasas and enveloping
ignorance flee.

Chapter 26 - Siva-Sun

This chapter along with the preceding one correlates the energy flow (of the Sun) in the Cosmos and (human body) following yogic and tantric principles.

Chapter 24 (The Mind's Sun), Chapter 25 (Jnana Sun) and Chapter 26 (Siva-Sun) present a consolidated picture of the roles of the Sun, Moon and Fire in Cosmos, and in the human body (microcosmos), in various aspects.`,
    elaborationTamil: `உயிர் அடைந்த ஞான ஒளியினுள்ளே வந்து எழு கின்ற சிவத்தினது ஒளியால் அக ஒளியாகிய அறிவை மறைந் திருந்த அக இருளாகிய ஆணவ மலமும், அதனால் விளைந்த அறியாமையும் இராக்காலத்திலே பொருந்தி எழுகின்ற அருணோதயத்தால் அதற்கு முன் திணிந்திருந்த இருள் நீங்குதல் போல நீங்கியொழியும்.`,
  },
  {
    id: 2003, tantraId: 7, verseNumber: 2002,
    tamil: `கடம் கடம் தோறும் கதிரவன் தோன்றில்
அடங்கிட மூடில் அவற்றில் அடங்கான்
விடங்கொண்ட கண்டனும் மேவிய காயத்து
அடங்கிட நின்றதும் அப்பரி சாமே`,
    transliteration: `kaṭam kaṭam tōṟum katiravaṉ tōṉṟil
aṭaṅkiṭa mūṭil avaṟṟil aṭaṅkāṉ
viṭaṅkoṇṭa kaṇṭaṉum mēviya kāyattu
aṭaṅkiṭa niṉṟatum appari cāmē`,
    english: `2002: Sivaditya is Immanent and Transcendent
In pot to pot the sun appears,
Well may you the pots close,
Yet in them you contain him not;
So, too, when Lord that poison swallowed
This body enters,
There can you contain Him not
He pervades all.`,
    elaborationEnglish: `The sun appears in pot after pot; but you cannot contain Him by closing a pot. Similarly, though the Lord, who has swallowed poison enters this body, you cannot have him there alone. He is immanent and transcendent.`,
    elaborationTamil: `நில உலகின்கண் நீர் நிரம்பிய குடங்களில் ஆதித்தனை நோக்கி வாயைத் திறந்துள்ள குடங்களில் தான் ஆதித்தன் விளங்குவான். அவ்வாறின்றி ஆதித்தனை நோக்காதவாறு மூடி வைக்கப்பட்ட குடங்களில் யாதொன்றன் நீரிலும் ஆதித்தன் விளங் குதல் இல்லை. சிவன் உடல்தோறும் உள்ள உயிர்களில் விளங்குதலும் ஆதித்தன் குடத்து நீரில் விளங்குதல் போல்வதுதான்.`,
  },
  {
    id: 2004, tantraId: 7, verseNumber: 2003,
    tamil: `தானே விரிசுடர் மூன்றும்ஒன்றாய் நிற்கும்
தானே அயன்மால் எனநின்று தாபிக்கும்
தானே உடலுயிர் வேறன்றி நின்றுளன்
தானே வெளியொளி தானிருட் டாமே`,
    transliteration: `tāṉē viricuṭar mūṉṟumoṉṟāy niṟkum
tāṉē ayaṉmāl eṉaniṉṟu tāpikkum
tāṉē uṭaluyir vēṟaṉṟi niṉṟuḷaṉ
tāṉē veḷiyoḷi tāṉiruṭ ṭāmē`,
    english: `2003: Sivaditya is Space, Light and Darkness
Himself as the Three Lights (Sun, Moon and Fire) in one stands;
Himself as Brahma and Vishnu stands established;
Himself as life and body indistinguishably stands
Himself Space, Light, and Darkness too.`,
    elaborationEnglish: `Himself Space, Light, and Darkness too.

Sivaditya stands as the three lights (sun, moon and fire). He
is space, light and darkness. He is Brahma and Vishnu. He
is life and body.`,
    elaborationTamil: `இங்குக் கூறிவரும் சிவாதித்தன் தான் ஒருவனே யாயினும் சுடர்களை எங்கும் வீசுகின்ற ஞாயிறு, திங்கள், தீ என்னும் முச்சுடர்களும் ஒன்று கூடினாற் போன்ற பேரொளியாய் இருப்பான்; தன்னை அழிப்பவனாகப் பலர் கருதினானுலும் அயனாய் நின்று படைப் பவனும், அரியாய் நின்று காப்பவனும் தானேயாகும். மேலும் அவன் உயிர்களில் மட்டுமன்றி, உடல்களிலும் வேற்றுமையின்றிக் கலந்து நிற்கின்றான். இன்னும் தான் ஒருவனே ஆகாயமாயும், அதன் கண் விளங்குகின்ற ஒளிகளாயும் நிற்றலேயன்றி இருளாகவும் ஆகின்றான்.`,
  },
  {
    id: 2005, tantraId: 7, verseNumber: 2004,
    tamil: `தெய்வச் சுடர்அங்கி ஞாயிறும் திங்களும்
வையம் புனல்அனல் மாருதம் வானகம்
சைவப் பெரும்பதி தாங்கிய பல்லுயிர்
ஐவர்க்கு இடம்இடை ஆறங்கம் ஆமே`,
    transliteration: `teyvac cuṭaraṅki ñāyiṟum tiṅkaḷum
vaiyam puṉalaṉal mārutam vāṉakam
caivap perumpati tāṅkiya palluyir
aivarkku iṭamiṭai āṟaṅkam āmē`,
    english: `2004: Nine Abodes of Sivaditya
The divine Fire, Sun and Moon,
The earth, water, fire, wind and space
And the creation countless
These the abodes ancient of Siva are;
The Five Gods, (Brahma, Vishnu, Rudra, Mahesa, Sadasiva)
Are in the Vedas that has Angas six.`,
    elaborationEnglish: `The nine abodes of Sivaditya are the spiritual spheres of fire, sun, moon; the elemental spheres of earth, water, fire, wind and space; and the endless creation. Similarly, the five Gods (Brahma, Vishnu, Rudra, Mahesvara, Sadasiva) and the four Vedas — these nine are also favourite resorts of Sivaditya.`,
    elaborationTamil: `தெய்வச் சுடர் அங்கி, வேள்வித் தீ ஞாயிறுமுதல் வானகம் ஈறாயினவும் ''பல்லுயிர்'' என்றதும் வெளிப்படை. ஐவர், பிரமன் முதல் சதாசிவன் ஈறானவர். அவர்க்கு இடம் ஆவன சுவாதிட்டானம் முதல் ஆஞ்ஞை ஈறாய் உள்ள ஐந்து ஆதாரங்கள். ஆறு அங்கம் ஆஞ்ஞையிலிருந்து கீழ்நோக்கி எண்ண ஆறாவதாகும் மூலாதாரம். சைவப் பெரும்பதி - இவை யாவும் சிவத் தலங்களாகும்.`,
  },
  {
    id: 2006, tantraId: 7, verseNumber: 2005,
    tamil: `உன்னும் அளவில் உணரும் ஒருவனைப்
பன்னு மறைகள் பயிலும் பரமனை
என்னுள் இருக்கும் இளையா விளக்கினை
அன்ன மயமென்று அறிந்துகொண் டேனே`,
    transliteration: `uṉṉum aḷavil uṇarum oruvaṉaip
paṉṉu maṟaikaḷ payilum paramaṉai
eṉṉuḷ irukkum iḷaiyā viḷakkiṉai
aṉṉa mayameṉṟu aṟintukoṇ ṭēṉē`,
    english: `2005: He is Para-Bindu
The One whom I in contemplation realize,
The One Param whom
Vedas praise,
The Undying Light in me shines,
Him I beheld, as Divine
Swan (Para Bindu).`,
    elaborationEnglish: `The yogi realises in contemplation the One whom the Vedas praise as twin, inseparable, ‘swans’ — the cosmic bindu and the microcosmic bindu.`,
    elaborationTamil: `சிவன் தன்னை நினைப்பவரையே தான் நினைப் பான். பல பொருள்களையும் சொல்லுகின்ற வேதங்கள் பிறரைப்போல அல்லது தன்னைப் பலவிடத்தும் பெரும்பான்மை எடுத்துச் சொல்ல நிற்பவன். என் உள்ளே என்றும் ஒளிகுறையாத விளக்காய் உள்ளவன். 'அவன் உயிர்களிடத்து அன்னப் புள்ளாய் இருக்கின்றான்' என்னும் அரிய உண்மையினை நான் திருவருளால் அறியப்பெற்றேன்.`,
  },
  {
    id: 2007, tantraId: 7, verseNumber: 2006,
    tamil: `அன்னம் இரண்டுள ஆற்றம் கரையினில்
துன்னி இரண்டும் துணைப்பிரி யாதுஅன்னம்
தன்னிலை அன்னம் தனியொன்றது என்றக்கால்
பின்ன மடஅன்னம் பேறணு காதே`,
    transliteration: `aṉṉam iraṇṭuḷa āṟṟam karaiyiṉil
tuṉṉi iraṇṭum tuṇaippiri yātuaṉṉam
taṉṉilai aṉṉam taṉiyoṉṟatu eṉṟakkāl
piṉṉa maṭaaṉṉam pēṟaṇu kātē`,
    english: `2006: Cosmic Bindu and Micro-Cosmic Bindu Are Inseparate
Two the swans on the river bank (of life)
The two swans separation know not,
If one Jiva says he is by himself,
Then that foolish swan, Grace receives not.`,
    elaborationEnglish: `This reminds one of Rg Vedic verse I.164. There, two birds are seated on a tree; one (jiva) enjoys the fruits of the three (pippalam) and the other (Siva or Brahman or Supreme Soul) watches, but does not eat.`,
    elaborationTamil: `இங்கு ''ஆறு'' என்றது பிராணன் இயங்கும் வழி யினை. ''அதன் கரையில் உள்ள இரு அன்னங்கள்'' என்றது, அந்தப் பிராணனை ஒட்டி நிற்கின்ற 'சிவன், சீவன்' என்னும் இருவரையும். அவ்வன்னம் இரண்டும் என்றும் இணைந்து நிற்றலி னின்றும் நீங்கித் தனித்தனியே பிரிதல் இல்லை. அவற்றுள் ஒன்று அறிவுமிக்கது. ஆதலின் அது தனியே பிரிந்து நிற்பினும் யாதொன் றினை இழத்தல் இன்றி, இனிது வாழும். மற்றொன்று அறிவு குறைந்தது ஆதலால் அது பிரிந்து தனி நிற்பின் எந்தப் பயனையும் பெறாது துன்பத்தில் ஆழும் என்றது சிவ சீவர்களது இயல்பினை விளக்கியதாம்.`,
  },
  {
    id: 2008, tantraId: 7, verseNumber: 2007,
    tamil: `வைகரி யாதியும் மாயா மலாதியும்
பொய்கரி யான புருடாதி பேதமும்
மெய்கரி ஞானம் கிரியா விசேடத்துச்
செய்கரி ஈசன் அனாதியே செய்ததே`,
    transliteration: `vaikari yātiyum māyā malātiyum
poykari yāṉa puruṭāti pētamum
meykari ñāṉam kiriyā vicēṭattuc
ceykari īcaṉ aṉātiyē ceytatē`,
    english: `2007: Lord Creates Activating Saktis Jnana and Kriya
Vaikhari and rest of Sounds,
Maya and rest of Impurities,
Purusha and rest of Tattvas illusory
--All these,
Acting on Saktis, Jnana and Kriya,
The Lord True from time immemorial made.`,
    elaborationEnglish: `Activating the jnana and kriya saktis, the Lord creates vaikhari
and the rest of sounds, maya and the other impurities, and
purusha along with the other illusory tattvas.

1) The four sounds are: vaikhari, madhyamai, paysanti, and
sukshma.

Vaikari—articulate sound form.

Madhyamai—sound form proceeding from the throat and
indistinctly articulate.
_ Paysanti—sound form proceeding from the lungs struggling
towards vocalisation.

Sukshma—subtle source of speech.
2) This is variously translated as, ‘the experient self,’ the
agent of experience,’ ‘the agent-self’, and as ‘the world-soul’
(in Samkhya philosophy). We prefer the first one in the
context of Saiva Siddhanta.`,
    elaborationTamil: `தோன்றியழிகின்ற வைகரி முதலிய வாக்குக்களாகிய சொல்லுலகங்களையும். மற்றும் பொருளுலகங்களையும், அவைகளைப் பற்றி நின்று 'புருடன், உருத்திரன், சிவன்' என உயிர்கள் அடையும் நிலையற்ற வேறுபாடுகளையும் தனது உண்மைத் துணையாகிய ஞானம், கிரியை என்னும் வேறுபாடுகளையுடைய தனது சத்தியால் செய்கின்ற நிலையான முதல்வன் சிவபெருமானே. இவ்வமைப்பு அனாதியே அமைந்த அமைப்பாகும்.`,
  },
  {
    id: 2009, tantraId: 7, verseNumber: 2008,
    tamil: `அணுவில் அணுவினை ஆதிப் பிரானை
அணுவில் அணுவினை ஆயிரங் கூறிட்டு
அணுவில் அணுவை அணுகவல் லார்கட்கு
அணுவில் அணுவை அணுகலும் ஆமே`,
    transliteration: `aṇuvil aṇuviṉai ātip pirāṉai
aṇuvil aṇuviṉai āyiraṅ kūṟiṭṭu
aṇuvil aṇuvai aṇukaval lārkaṭku
aṇuvil aṇuvai aṇukalum āmē`,
    english: `2008: Lord is Atom-Within-Atom
The Lord is the Beginning of all,
He is the Atom-within-the-atom;
Divide an atom within the atom,
Into parts one thousand,
They who can thus divide
That atom within the atom
May well near the Lord,
He, indeed, is the Atom-within-the-atom.`,
    elaborationEnglish: `The Lord, the Source of all, is the atom within the atom. Only they who are capable of fragmenting an atom can vision this atom within an atom (the Lord).`,
    elaborationTamil: `ஆணவ பந்தத்தால் தனது வியாபக நிலையை இழந்து அணுத்தன்மை எய்த நிற்கின்ற உயிரை அணுவிலும் பல கூற்றில் ஒரு கூற்றளவினதாகப் பாவித்து, 'அணுவுக்கும் அணு' எனப்படுகின்ற நுண்ணியனாகிய சிவனை அணுக வல்லவர்கட்கே அவனை அடைதல் கூடும்.`,
  },
  {
    id: 2010, tantraId: 7, verseNumber: 2009,
    tamil: `படர்கொண்ட ஆலதின் வித்தது போலச்
சுடர்கொண்டு அணுவினைத் தூவழி செய்ய
இடர்கொண்ட பாச இருளற ஒட்டி
நடர்கொண்ட நல்வழி நாடலும் ஆமே`,
    transliteration: `paṭarkoṇṭa ālatiṉ vittatu pōlac
cuṭarkoṇṭu aṇuviṉait tūvaḻi ceyya
iṭarkoṇṭa pāca iruḷaṟa oṭṭi
naṭarkoṇṭa nalvaḻi nāṭalum āmē`,
    english: `2009: Seek the Jnana Way of Lord
Tiny unto the seed,
Of the spreading banyan tree
Is the atom that is
Jiva;
If by fire of Jnana
Your way purifies,
The dark Pasas that malign you
May well driven away be;
Seek the Divine way,
The Dancing Lord shows you.`,
    elaborationEnglish: `Jiva, the atom, is the seed of the spreading banyan tree.`,
    elaborationTamil: `சிவனது திருவருளாகிய ஒளியினை ஆன்மா, பல கிளைகளும் விழுதுகளுமாய் விரிவடையும் ஆற்றலைத் தன்னுள்ளே அடக்கியிருக்கும் ஆலம் விதைபோலத் தன்னுள் அடக்குமாற்றால் தன்னை அச்சிவத்திற்கு ஏற்ற தூய இடமாகச் செய்யுமானால், அந்தத் திருவருள் ஒளி துணையாக, துன்பத்தையே தனது இயல்பாகக் கொண்ட ஆணவமாகிய இருளை ஓட்டி, அம்பலத்தில் ஞான நடனத்தைச் செய்கின்ற அப்பெருமான் தரக் கருதும் நல்வழியைத் தான் உணரும் வாய்ப்பு உண்டாகும்.`,
  },
  {
    id: 2011, tantraId: 7, verseNumber: 2010,
    tamil: `அணுவுள் அவனும் அவனுள் அணுவும்
கணுஅற நின்ற கலப்பது உணரார்
இணையிலி ஈசன் அவன்எங்கும் ஆகித்
தணிவற நின்றான் சராசரம் தானே`,
    transliteration: `aṇuvuḷ avaṉum avaṉuḷ aṇuvum
kaṇuaṟa niṉṟa kalappatu uṇarār
iṇaiyili īcaṉ avaṉeṅkum ākit
taṇivaṟa niṉṟāṉ carācaram tāṉē`,
    english: `2010: Jiva and Siva Commingling Stand
He within the atom (Jiva),
And the atom (Jiva) within Him
Commingling stand,
They know this not;
The peerless Lord pervades all
Unintermittent, in creation entire.`,
    elaborationEnglish: `Jiva is the atom which resides within Siva, the Lord who is all-pervasive and immanent.in the entirety of creation. Seek the Dancing Lord, the divine jnana way.`,
    elaborationTamil: `முன் மந்திரத்தில், 'உயிர் ஆலம் விதைபோலவும், சிவன் அவ்விதையில் அடங்கியுள்ள கிளை முதலியன போலவும் ஆதல் வேண்டும்' என்றது ஒருபுடை உவமையேயன்றி, முற்றுவமை யன்று. மற்று, உண்மை நிலையாது' எனின், 'உயிர் மேல்; சிவன் உள்' என்றாயினும், 'சிவன்மேல்; உயிர் உள்' என்றாயினும் ஒருபடித்தாக வரையறுத்தல் கூடாதபடி, புறவேற்றுமையே யன்றி, அகவேற்றுமை தானும் இன்றி ஒன்றி நிற்கின்ற கலப்பே உண்மை நிலையாகும். இவ்வுண்மையை உணர்வார் ஒருவரும் இல்லை. இனித் தன்னொப் பில்லாத் தனிப்பெரும் பொருளாகிய சிவன் எல்லாப்பொருளிலும் ஒரு படித்தாக நீக்கமின்றி நிறைந்து நிற்கின் இயங்குவனவும், நிற்பனவு மாய்க் காணப்படுகின்ற உயிர்கள் பலவும் அவனிடத்தில் தத்தமக்கு இயலும் முறையில் கலந்து நிற்கின்றன.`,
  },
  {
    id: 2012, tantraId: 7, verseNumber: 2011,
    tamil: `மேவிய சீவன் வடிவது சொல்லிடில்
கோவின் மயிர்ஒன்று நூறுடன் கூறிட்டு
மேவிய கூறது ஆயிரம் ஆயினால்
ஆவியின் கூறுநா றாயிரத்து ஒன்றே`,
    transliteration: `mēviya cīvaṉ vaṭivatu colliṭil
kōviṉ mayiroṉṟu nūṟuṭaṉ kūṟiṭṭu
mēviya kūṟatu āyiram āyiṉāl
āviyiṉ kūṟunā ṟāyirattu oṉṟē`,
    english: `2011: Size of Soul
To speak of the size of Jiva
It is like this:
Split a cow's hair soft
Into a hundred tiny parts;
And each part into a thousand parts divide;
The size of Jiva is that one of part
Of the one hundred thousand.`,
    elaborationEnglish: `Split a cow’s downy hair into one hundred tiny parts and then divide each part into one thousand parts. The size of jiva equals that one part of the one hundred thousand.`,
    elaborationTamil: `உயிர் பருப்பொருளாகக் கருதிக்கொண்டு, 'அதன் அகல, நீர், கன அளவுகள் எத்துணையன' என வினாவுவார்க்கு விடை கூறின், 'பசுவின் மயிர்களில் ஒன்றை எடுத்து அதனைப் பல நூறாயிரங் கூறு செய்தால் அவற்றுள் ஒரு கூற்றின் அகல, நீள, கன அளவுகளே உயிரின் அகல, நீள, கன அளவுகள்' எனக் கூறலாம்.`,
  },
  {
    id: 2013, tantraId: 7, verseNumber: 2012,
    tamil: `ஏனோர் பெருமையின் ஆயினும் எம்மிறை
ஊனே சிறுமையின் உட்கலந்து அங்குளன்
வானோர் அறியும் அளவல்லன் மாதேவன்
தானே அறியும் தவத்தின் அளவே`,
    transliteration: `ēṉōr perumaiyiṉ āyiṉum emmiṟai
ūṉē ciṟumaiyiṉ uṭkalantu aṅkuḷaṉ
vāṉōr aṟiyum aḷavallaṉ mātēvaṉ
tāṉē aṟiyum tavattiṉ aḷavē`,
    english: `2012: Siva's Infinite Size
Infinite great is my Lord,
Yet within the littleness of this body
He dwells permeating;
He is the Lord Supreme
Whom the Celestials cannot know;
As much as your Tapas is
So much also is He known.`,
    elaborationEnglish: `Siva, though of infinite size, in this little body. He is the Supreme Lord whom even celestials cannot know. Only through tapas can He be visioned.`,
    elaborationTamil: `கட்புலனாகாப் பொருள் சிவன் ஒருவனேயாக, பலவாகிய உயிர்களையும் அத்தகைய பொருளாகக் கூறுதல் கூடுமோஎனின், கூடும். ஏனெனில், சிவனது பெருமையை நோக்கு மிடத்து ஏனைத் தேவர் அனைவர் பெருமையினும் பெரிது. ஆயினும் பருப்பொருளாகிய உடம்புகளில் சூக்குமமாய் நிறைந் திருக்கின்ற உயிர்களினுள்ளே அவற்றினும் அதிசூக்குமமாய் அவன் நிறைந் திருக்கின்றான். (எனவே, உயிர் சூக்குமப் பொருளும், சிவன் அதி சூக்குமப் பொருளுமாம் ஆதலின் அதுபற்றி ஐயமில்லை என்றபடி,) சிவன் இத்தகைய அதிசூக்குமப் பொருளாதலின் அவன் தேவர்களா லும் எளிதில் அறியத்தக்கவனல்லன். ஆயினும் அவனே அவரவரது தவத்தின் அளவை யறிந்து அவ்வளவிற்கு ஏற்ப விளங்கி நிற்பன்.`,
  },
  {
    id: 2014, tantraId: 7, verseNumber: 2013,
    tamil: `உண்டு தெளிவன் உரைக்க வியோகமே
கொண்டு பயிலும் குணமில்லை யாயினும்
பண்டு பயிலும் பயில்சீவ னார்பின்னைக்
கண்டு சிவனுருக் கொள்வர் கருத்துளே`,
    transliteration: `uṇṭu teḷivaṉ uraikka viyōkamē
koṇṭu payilum kuṇamillai yāyiṉum
paṇṭu payilum payilcīva ṉārpiṉṉaik
kaṇṭu civaṉuruk koḷvar karuttuḷē`,
    english: `2013: Practise Yoga in Perserverence
You may not for Yoga inclined be,
But if your Guru
Illumined teaches you,
You may yet accomplish it;
And so perservere
In lives several;
And seeing you thus abored,
Sivva's Form will in your thought arise.`,
    elaborationEnglish: `And seeing you thus practise, Siva’s Form will in your thought arise. Yoga practice persevered through several lives makes Siva’s form arise in your thoughts.`,
    elaborationTamil: `உயிர்கட்கு முதற் காலத்திலே, 'சிவனை அறியும் வாயில் உண்டு' எனக் கூறுதற்கு அவனைத் தம்முன்னே கொண்டு யோகம் பயில்கின்ற குணம் இல்லவிட்டாலும் பின்பு அக்குணத்தை அடைந்து தம்முன்னே கொண்டு யோகம் பயிலும். ஆகவே, உயிர்கட்கு என்றாயினும் ஒருநாள் சிவனைத் தெளிவாக உணரும் உணர்வு உண்டாகவே செய்யும்.`,
  },
  {
    id: 2015, tantraId: 7, verseNumber: 2014,
    tamil: `மாயா உபாதி வசத்ததாகும் சேதனத்து
ஆய குருஅரு ளாலே அதில்தூண்ட
ஓயும் உபாதியோடு ஒன்றின் ஒன் றாது உயிர்
ஆய துரியம் புகுந்தறி வாகவே`,
    transliteration: `māyā upāti vacattatākum cētaṉattu
āya kuruaru ḷālē atiltūṇṭa
ōyum upātiyōṭu oṉṟiṉ oṉ ṟātu uyir
āya turiyam pukuntaṟi vākavē`,
    english: `2014: Guru Illumines You
Harassed are you
By Maya's manifestations;
But when the Guru Illumined
By His grace lights you up
Your troubles entire cease;
The Jiva illumined in Jnana
Will Turiya State reach.`,
    elaborationEnglish: `With the help of the Guru’s guidance, liberation is obtained from maya’s manifestations. The Jiva, illumined by jnana, teaches the turiya state.`,
    elaborationTamil: `மாயா காரியமாகிய கருவிக்கூட்டம் சடமாகலின், அது சித்தாகிய உயிருக்குக் கூடாப் பொருளாய்க் குற்றமாகும். ஆயினும் அவ்வுயிரின் உள்ளே என்றும் உள்ள சிவன் அதனது பக்குவம் அறிந்து அருள் காரணமாகக் குருவாகி எதிர் வந்து அதனை அக்குற்றத்தினின்றும் பிரிவிக்க, அஃது அங்ஙனமே பிரிந்து திருவருளில் புகுந்து, அதன் கண் பேருறக்கத்தை எய்தி அமைதியுற் றிருக்கும். அருள் உறக்கம், இருள் உறக்கம் அன்றாகலின் அந் நிலையில் உயிர் அறிவே வடிவாய் விளங்கும்.`,
  },
  {
    id: 2016, tantraId: 7, verseNumber: 2015,
    tamil: `கற்ற பசுக்கள் கதறித் திரியினும்
கொற்ற பசுக்கள் குறிகட்டி மேயினும்
முற்ற பசுக்கள் ஒருகுடம் பால்போலும்
மற்றைப் பசுக்கள் வறள்பசு தானே`,
    transliteration: `kaṟṟa pacukkaḷ kataṟit tiriyiṉum
koṟṟa pacukkaḷ kuṟikaṭṭi mēyiṉum
muṟṟa pacukkaḷ orukuṭam pālpōlum
maṟṟaip pacukkaḷ vaṟaḷpacu tāṉē`,
    english: `2015: Jnani is the Mature Jiva
The learned cows(Jivas) may wander bellowing,
The power-giddy cows may strut about,
Their insignia displaying;
But precious is a pot's milk (Jnana),
The goodly mature cows (Jnani's) yield;
The rest are but barren cows indeed.`,
    elaborationEnglish: `Only mature cows (jnanis) yeild a pot of milk that is precious- The rest are indeed barren and sterile.`,
    elaborationTamil: `கருவுறும் பருவம் வாயாத இளம் பசுக்கள் இனச் சார்பால் கதற மட்டும் தெரிந்து கொண்டு, கன்றை ஈன்ற பசுக்கள் தம் கன்றினை அழைக்கக் கதறுவதுபோலத் தாமும் கதறித் திரியும். கன்றை ஈனாது கருவுற்று மட்டும் உள்ள பசுக்கள் தமக்குரிய புல்லை விடுத்து மனிதர்க்கு உயிர பயிரில் சென்று மேயாதபடி அதன்தலைவன் புல்வெளியில் ஓரிடத்தில் முளையடித்து நீண்ட கயிற்றால் கட்டி வைக்க, அக்கயிற்றின் அளவிற்கு அவை கட்டில்லாதது போலத் தம் விருப்பப்படி சென்று புல்லை மேயும். எனினும் கன்றை ஈன்று தாய்மையை எய்திய பசுக்களே ஒன்று ஒரு குடம்போல நிரம்பப் பால் பொழியும் பசுக்களாகும். அவை தவிர மேற்சொன்ன மற்ற இருவகைப் பசுக்களும் பயன்படாத பசுக்களாகவே இருக்கும்.`,
  },
  {
    id: 2017, tantraId: 7, verseNumber: 2016,
    tamil: `கொல்லையின் மேயும் பசுக்களைச் செய்வதென்
எல்லைக் கடப்பித்து இறைவன் அடிகூட்டி
வல்லசெய்து ஆற்ற மதித்தபின் அல்லது
கொல்லை செய் நெஞ்சம் குறிப்பறி யாதே`,
    transliteration: `kollaiyiṉ mēyum pacukkaḷaic ceyvateṉ
ellaik kaṭappittu iṟaivaṉ aṭikūṭṭi
vallaceytu āṟṟa matittapiṉ allatu
kollai cey neñcam kuṟippaṟi yātē`,
    english: `2016: Jivas Graze in the Backwood of Worldly Pleasures
What to do with those cows
In the backwoods of desires graze?
Take them beyond,
And lead them to Feet of Lord;
Discipline them in ways superior;
Thus manage the herd;
Until then, their thoughts turn not
From the backwoods of worldly pleasures.`,
    elaborationEnglish: `Lead the cows that graze in the backwoods of worldly desires to the Holy Feet of the Lord. Instruct them in supreme: disciplined ways. From then on they will never tum back to their previous state. :`,
    elaborationTamil: `காப்பாருமின்றி, மேய்ப்பாருமின்றி, கறப்பாரு மின்றித் தம் விருப்பம்போல் காட்டில் மேய்ந்து கொண்டிருக்கும் காட்டுப் பசுப்போன்ற மக்களை எப்படித் திருத்த முடியும். (அவர் யாருக்கும் அடங்குபவரல்லர்.) அவர் தாமே தமது இழிநிலையை உணர்ந்து ஆசிரியரை அடைக்கலமாக அடைவாராயின் அவரை ஆசிரியர் கல்லில் நார் உரிப்பதுபோலவும், கல்லைப் பிசைந்து கனியாக்குதல் போலவும்* தமது திருவருள் திறத்தால் அவரது நிலையினின்றும் நீக்கிச் சீர்செய்து, அவர் சீர்ப்பட்டமையை நன்குணர்ந்து சிவமாக்கிய பின்பல்லது அதற்கு முன் காடும், மேடும், கல்லும், முள்ளுமாய்க் கிடக்கின்ற நிலம் போன்றுள்ள அவரது மனம் உணர வேண்டியவற்றை உணராது.`,
  },
  {
    id: 2018, tantraId: 7, verseNumber: 2017,
    tamil: `சீவன் எனச்சிவன் என்னவே றில்லை
சீவ னார்சிவ னாரை அறிகிலர்
சீவ னார்சிவ னாரை அறிந்தபின்
சீவ னார்சிவ னாயிட்டு இருப்பரே`,
    transliteration: `cīvaṉ eṉaccivaṉ eṉṉavē ṟillai
cīva ṉārciva ṉārai aṟikilar
cīva ṉārciva ṉārai aṟintapiṉ
cīva ṉārciva ṉāyiṭṭu irupparē`,
    english: `2017: Jiva and Siva are One
Jiva and Siva
Separate are not;
Jiva knows not Siva;
When Jiva knows Siva;
Jiva becomes Siva.`,
    elaborationEnglish: `Siva and jiva are one and the same. With the knowledge of Siva, jiva becomes Siva.`,
    elaborationTamil: `'சீவன்' எனவும், 'சிவன்' எனவும் வேறு வேறாய்த் தனித்து எக்காலத்தும் இல்லை, உடலும், உயிரும் போல என்றும் ஒன்றியே நிற்கும். அவ்வாறிருந்தும் சீவன் சிவனை அறிந்ததில்லை. ஏன்? பாசங்கள் சீவனது அறிவை மறைத்து நிற்கின்றன. (அம்மறைப்பு நீங்கிச்) சீவன் சிவனை அறியுமாயின் அது சீவனாய் இராது, சிவமாகவே இருக்கும்.`,
  },
  {
    id: 2019, tantraId: 7, verseNumber: 2018,
    tamil: `குணவிளக் காகிய கூத்தப் பிரானும்
மனவிளக் காகிய மன்னுயிர்க் கெல்லாம்
பணவிளக் காகிய பல்தலை நாகம்
கணவிளக் காகிய கண்காணி யாகுமே`,
    transliteration: `kuṇaviḷak kākiya kūttap pirāṉum
maṉaviḷak kākiya maṉṉuyirk kellām
paṇaviḷak kākiya paltalai nākam
kaṇaviḷak kākiya kaṇkāṇi yākumē`,
    english: `2018: Lord is Light
The Dancing Lord is the Light Benevolent,
He is the Joyous Light for Creation all;
He adorns the many hooded serpent with gemlike shining eyes
He is the Cluster of Lights that oversees all.`,
    elaborationEnglish: `The Dancing Siva is the cluster of benevolent lights that oversees all, and the joyous light that vibrates through the entire’ creation.`,
    elaborationTamil: `எண்குணங்களையுடைய கூத்தப்பிரான், மனத்தை விளக்காகக் கொண்டு பொருள்களை அறிந்து வருகின்ற, நிலைபெற்ற உயிர்களுக்கெல்லாம், படந்தோறும் மணியாகிய விளக்கினையுடைய பலதலைப் பாம்புபோலவும், இரவிலும் பல விளக்குக்களை ஏற்றி வைத்துக் கொண்டு பொருள்களைக் காவல் செய்கின்ற கண்காணி போலவும் இருக்கின்றான்.`,
  },
  {
    id: 2020, tantraId: 7, verseNumber: 2019,
    tamil: `அறிவாய் அறியாமை நீங்கி யவனே
பொறிவாய் ஒழிந்தெங்கும் தானான போதன்
அறிவாய் அவற்றினுள் தானாய் அறிவன்
செறிவாகி நின்றஅச் சீவனும் ஆகுமே`,
    transliteration: `aṟivāy aṟiyāmai nīṅki yavaṉē
poṟivāy oḻinteṅkum tāṉāṉa pōtaṉ
aṟivāy avaṟṟiṉuḷ tāṉāy aṟivaṉ
ceṟivāki niṉṟaac cīvaṉum ākumē`,
    english: `2019: Lord is Knowledge and Knower
He is all Knowledge, immune from Ignorance,
Without aid of sensory organs, He is self-Illumined,
Himself as Knowledge and Himself as the Knower too
He is the Jiva as well,
He stands pervasive all.`,
    elaborationEnglish: `God is Self-Illumined, free from ignorance. He is the knowledge and knower also. He is also jiva and is all pervasive.`,
    elaborationTamil: `சிவன் அறியாமையோடு விரவாது அறிவாயே இருப்பவன். அவன் சீவன்களின் அறிவில் பொருந்திச் சீவர்கள் அறிவனவற்றையெல்லாம் தான் உடனாய்நின்று அறிவன். அதனால் அவன் சீவன்களாகியும் இருப்பான். ஆகையால் இந்நிலையை உணர்கின்ற சீவன் தானும் அச்சிவனேயாய் நிற்கும் ஆதலால், அத்தகைய சீவனே யாதும் அறியாத இருள் நிலையும், பொறிகளின் வழிப்பட்டு உலகை ஏகதேசமாய் அறிகின்ற மருள் நிலையும் ஆகிய இவற்றினின்றும் நீங்கிச் சிவனைப் போல எங்கும் வியாபகமாய் நின்று அறியும் நிலையை எய்தி, 'போதன்' எனப்படுவதாகும்.`,
  },
  {
    id: 2021, tantraId: 7, verseNumber: 2020,
    tamil: `ஆறாறின் தன்மை அறியாது இருந்தேனுக்கு
ஆறாறின் தன்மை அறிவித்தான் பேர்நந்தி
ஆறாறின் தன்மை அருளால் அறிந்த பின்
ஆறாறுக்கு அப்புறம் ஆகி நின் றானே`,
    transliteration: `āṟāṟiṉ taṉmai aṟiyātu iruntēṉukku
āṟāṟiṉ taṉmai aṟivittāṉ pērnanti
āṟāṟiṉ taṉmai aruḷāl aṟinta piṉ
āṟāṟukku appuṟam āki niṉ ṟāṉē`,
    english: `2020: He is Beyond Tattvas Thirty-Six
To me that knew not the truth of Tattvas six times six,
He taught the truth of Tattvas six times six
He, Nandi Famed;
And when by His Grace I learned the truth of Tattvas six times six
He stood beyond the Tattvas six times six.`,
    elaborationTamil: `'தத்துவங்கள் சடம்' என்று அறியாமல், அவை களையே யானாக மயங்கிக் கிடந்த எனக்குச் சிவபிரான் தனது அருளைப் பற்றி நின்று அவ்வுண்மையை நான் உணர்ந்தபின் அவ்வாறு உணர்த்திய அவன் தத்துவங்கட்கு அப்பாற்பட்டு நிற்றலையும் உணர்ந்தேன்.`,
  },
  {
    id: 2022, tantraId: 7, verseNumber: 2021,
    tamil: `சிவமா கியஅருள் நின்றுஅறிந்து ஓரார்
அவமாம் மலம்ஐந்தும் ஆவது அறியார்
தவமான செய்து தலைப்பறி கின்றார்
நவமான தத்துவம் நாடாகி லாரே`,
    transliteration: `civamā kiyaaruḷ niṉṟuaṟintu ōrār
avamām malamaintum āvatu aṟiyār
tavamāṉa ceytu talaippaṟi kiṉṟār
navamāṉa tattuvam nāṭāki lārē`,
    english: `2021: Lord is Truth
They know Him not as Grace that is Siva,
They know not the Malas (Impurities) Five to rid of,
They perform penance diverse,
And are in distraction lost,
They seek not the Tattva (Truth),
That is ever New.`,
    elaborationEnglish: `Men do not know that Siva is Grace. He is pure, rid of the
five malas (impurities). Though they perform diverse penances
and atonements, they are lost in distraction. The Lord is the
tattva (Truth) that is ever new.`,
    elaborationTamil: `பிற ஆகமங்களிலன்றிச் சைவாகமங்களில் சொல்லப்படுகின்ற தத்துவங்களின் உயர்வை உணர்ந்து அவற்றைத் தெளியமாட்டாதவர் சிவமுதற் பொருளையும், அதனது ஆற்றலின் சிறப்பையும் உணர்ந்து அதிலே பழகியறியார். அதனால் அவர் உயிர் பஞ்ச மலங்களால் போதம் இழந்து நிற்றலையும் உணர மாட்டார். பிற பிற சமய நூல்களில் எல்லாம் சொல்லப்படுகின்ற தவங்களைச் செய்து, தாம் அடையவேண்டிய பயனை அடையாது இளைக்கின்றவ ராகின்றனர்.`,
  },
  {
    id: 2023, tantraId: 7, verseNumber: 2022,
    tamil: `நாடோ றும் ஈசன் நடத்தும் தொழில்உள்ளார்
நாடோ றும் ஈசன் நயந்தூட்டல் நாடிடார்
நாடோ றும் ஈசன்நல் லோர்க்கருள் நல்கலால்
நாடோ றும் நாடார்கள் நாள்வினை யாளரே`,
    transliteration: `nāṭō ṟum īcaṉ naṭattum toḻiluḷḷār
nāṭō ṟum īcaṉ nayantūṭṭal nāṭiṭār
nāṭō ṟum īcaṉnal lōrkkaruḷ nalkalāl
nāṭō ṟum nāṭārkaḷ nāḷviṉai yāḷarē`,
    english: `2022: Lord Bestows His Grace on the Good
His Grace on the Good
They think not of divine acts, Lord daily performs
They think not of the ministering acts, Lord daily performs;
The Lord daily bestows
His Grace on the good,
They who know this not,
daily seek Him not'
Entangled in their work-a-day Karmas interminable.`,
    elaborationEnglish: `They do not concentrate on holy and divine acts. They do not seek Him either; they are ignorant of the fact that God Tesponds to the love and devotion of the good, and bestows His blessing on them.`,
    elaborationTamil: `நாளும் நாளும் தம்பால் நிகழ்வன யாவும் சிவ பெருமான் நிகழ்த்துவிக்க நிகழ்வனவே யாதலையும் ஊன்றியுணரார்; அங்ஙனம் அவன் நிகழ்த்துவித்தல் தாம் செய்த வினையின் பயன்களைத் தமக்குத் தனது அருள் காரணமாக ஊட்டுவித்தலே யாதலையும் கேட்டல் சிந்தித்தல்களின்வழி எண்ணிப்பாரார். சிவன் தனது அருளைத் தான் நேரே வழங்குதல் மேற்சொல்லிய உண்மைகளை ஆசிரியரது அருளால் கேட்டுச் சிந்தித்துத் தெளிந்தவர் கட்கே என்பதையும் எண்ணமாட்டார். யார் எனில், நாள்தோறும் முன் மந்திரத்தில் கூறிய ஐம்பாசங்களின் வழியே உழைத்து நாட்களைக் கழிக்கின்றவர் என்க.`,
  },
  {
    id: 2024, tantraId: 7, verseNumber: 2023,
    tamil: `ஆக மதத்தன ஐந்து களிறுள
ஆக மதத்தறி யோடுஅணை கின்றில
பாகனும் எய்த்துஅவை தாமும் இளைத்தபின்
யோகு திருந்துதல் ஒன்றிஅறி யோமே`,
    transliteration: `āka matattaṉa aintu kaḷiṟuḷa
āka matattaṟi yōṭuaṇai kiṉṟila
pākaṉum eyttuavai tāmum iḷaittapiṉ
yōku tiruntutal oṉṟiaṟi yōmē`,
    english: `2023: Do Not Delay to Control Senses
Five are the elephants (Senses)
That are in MAST
Their MAST increasing
They do not to the (Divine) Post remain tied;
As the mahout (Jiva) tires,
And the elephants (Senses) too, get their energy exhausted,
Then they turn to Yoga;
Why this way (they delayed) we know not!`,
    elaborationEnglish: `Five elephants (senses) are there in the ‘mast’ (body) and they are not tied to the post (divine). As the mahout (jiva) tries and tries in vain, he becomes exhausted; and then he tums to the yogic way and succeeds. So, do not delay to control your senses.`,
    elaborationTamil: `இம்மந்திரம் ஒட்டணி. ஐந்து களிறுகள். ஐம்புலன் களின் மேல் செல்லும் ஐந்து அவாக்களையுடைய மனம் - மனம் ஒன்றாயினும் அவா வகையால் ஐந்தாயிற்று. ஆக மதத்தமை. மிகவும் மதம் கொண்டமை. அஃதாவது அவா மிக மிகுத்தமை. தறி - திருவருள். பாகன் - உயிர். அவன் எய்த்தமை - அந்த மனத்தை அவாக் கொள்ளாதவாறு தன் முயற்சியாலே தான் அடக்கி அடக்கிப் பார்த்து இயலாது இளைத்தமை. இனிக் களிறுகள் இளைத்தமை - மனம்தான் அவாவிய புலன்களை அடைந்து அடைந்து நிறைவுபெற விரும்பி, நிறைவு கூடாமையால் வெறுப்புற்றமை. இந்நிலையிலே அந்த மனம் திருந்தி நிறைவு பெறுதற்கு வழி சிவயோகத்தைத் தவிர வேறொன்றில்லாமை அறியப்பட்டது.`,
  },
  {
    id: 2025, tantraId: 7, verseNumber: 2024,
    tamil: `கருத்தின்நன் னூல்கற்று கால்கொத்திப் பாகன்
திருத்தலும் பாய்மாத் திகைத்தன்றிப் பாயா
எருத்துற ஏறி இருக்கிலும் ஆங்கே
வருத்தினும் அம்மா வழிநட வாதே`,
    transliteration: `karuttiṉnaṉ ṉūlkaṟṟu kālkottip pākaṉ
tiruttalum pāymāt tikaittaṉṟip pāyā
eruttuṟa ēṟi irukkilum āṅkē
varuttiṉum ammā vaḻinaṭa vātē`,
    english: `2024: Difficulty of Training Senses
Attentively learning holy lore
And coursing breath in Yogic way,
Unless the rider (Jiva) thus trains,
The restless steed (Senses),
Its wayward course it takes;
Firm may the rider on its neck sit
And hard the punishment he administers,
Yet the animal forward moves not.`,
    elaborationEnglish: `Unless the rider (jiva) trains the restless steed (senses) in the yogic way, it goes astray. The animal seldom moves, though the rider sitting on its back goes on making the punishment more and more severe.`,
    elaborationTamil: `இதுவும் ஒட்டணி. அடங்காமையை ஐம்பொறி மேல் வைத்துக் கூறினும் அடங்காது ஓடுவது மனமே. ஓட்டத்தின் விளைவு குறித்து மனம் குதிரையாக உருவகிக்கப்படும். பாய்மா - குதிரை. குதிரையைப் போரின்கண் செயற்படுத்தும் வீரன் அதன் முதுகின் மேல் அமர்ந்துகொண்டு கால்களால் குறிப்புத் தருவான். நல்ல குதிரைகள் அக்குறிப்பின் வழியே பாய்ந்து பாகனுக்கு வெற்றியை உண்டாக்கும். முருட்டுக் குதிரைகள் முரணி வேறுவழியிற் பாய்ந்து பாகனுக்கு வீழ்ச்சியைத்தரும். இங்கு ''பாய் மா'' என்றதை, 'குறிப்பிட்ட ஒரு பாய்மா' எனக் கொள்க. அது மனம். அதனைப் பிராணாயாமத்தால் அடக்குதல் கூடும். ஆகவே ''கால்'' என்றது சிலேடை வகையால் உவமையில் பாகனது கால்களையும், பொருளில் பிராண வாயுவையும் குறித்தது. கொத்துதல் - உட்செலுத்துதல். பாகன், ஆன்மா. அவன் யோகநூலைக் கருத்துடன் கற்று அதன்படி பிராணா யாமம் செய்து தாரணை நிலையில் நின்று அடக்கினாலும் அடங்காது ஓடுவதே மனத்தின் இயல்பு. உவமையில் 'நூல்' குதிரை செலுத்தும் நூல். 'எருத்தம்' என்பது ஈறு குறைந்து, ''எருத்து'' என நின்றது. எருத்தம் - பிடரி; இங்கு அது முதுகைக் குறித்தது. 'முதுகு' என்றது தாரணை நிலையை. திருத்துதல் - பிராணாயாமத்தினாலும், வருத்துதல், அஃதாவது அடக்குதல். தாரணையினாலும் என்றற்கு அவற்றைத் தனித் தனிக் கூறினார். திகைத்தல் - வேறு வழியில் செல்லுதல். வழி, நேர்வழி. அம் மா - மேற் குறிப்பிட்ட அந்தக் குதிரை. ''திகைத்தன்றிப் பாயாது, வழி நடவாது' என்றவை, அடங்குதல் அரிதாதலையே குறித்தது.`,
  },
  {
    id: 2026, tantraId: 7, verseNumber: 2025,
    tamil: `புலம் ஐந்து புள்ஐந்து புள்சென்று மேயும்
நிலம்ஐந்து நீர்ஐந்து நீர்மையும் ஐந்து
குலம் ஒன்று கோல்கொண்டு மேய்ப்பான் ஒருவன்
உலம்வந்து போம்வழி ஒன்பது தானே`,
    transliteration: `pulam aintu puḷaintu puḷceṉṟu mēyum
nilamaintu nīraintu nīrmaiyum aintu
kulam oṉṟu kōlkoṇṭu mēyppāṉ oruvaṉ
ulamvantu pōmvaḻi oṉpatu tāṉē`,
    english: `2025: Harassing Senses Bring Sorrow
Five the Sense Organs,
Five the Sense-birds,
(Jnanendriyas)
Five the Fields
(Tanmatras)
The Sense-birds seek to feed,
Five the waters
(Kanmendriyas),
Five their functions,
Yet are they of one lineage;
And one the hunter
(Jiva)
That herds them together;
Nine the exits of body
Where he in sorrow wanders.`,
    elaborationEnglish: `Five are the sense organs (sensoria) and five the sense-birds (motoria). Five are the sense-fields (potencies) the sense-birds seek to feed upon, five the waters (elements) and five their functions; yet, they are all of one lineage. The lonely hunter (jiva) brings them together, but the harassing senses bring sorrow to him.`,
    elaborationTamil: `மேய்ப்புத் தொழில் செய்து பிழைக்கும் குலங்கள் ஆமேய்க்கும் குலம், எருமை மேய்க்கும் குலம், ஆடு மேய்க்கும் குலம், தாரா, கோழி முதலிய பறவைகள் மேய்க்கும் குலம் எனப் பலவகை உண்டு. அவற்றுள் பறவை மேய்க்கும் குலத்தில் இரங்கத் தக்க ஒரு குலம் உண்டு. அந்தக் குலத்தில் ஒருவனுக்கு ஒரு குடில். அந்தக் குடிலில் ஐந்து கூடுகள். அந்தப் பறவைகள் வெளியே மேயும் இடங்களும் ஐந்து. அந்த இடத்தில் மேய்கின்ற உணவுகளும் வேறு பட்ட ஐந்து. அந்த உணவுகளின் குணங்களும் வேறுபட்ட ஐந்து. இந் நிலையில் அந்த மேய்ப்பான் ஒருவன் அந்தப் பறவைகளை ஒரு வழியிற் செலுத்தி மேய்க்க வேண்டும். இது மாற்ற முடியாத ஓர் அமைப்பு முறை - அதனால் இந்த மேய்ப்புத் தொழிலில் வெற்றி பெற மாட்டாதார் பலர் மேற்குறித்த ஒரு குடிலில் ஒன்பது வாயில்கள் இருப்பதால் அந்த வாயில்களில் எந்த ஒன்றின் வழியாகவாவது யாருக்கும் தெரியாமல் ஓடிவிடுகின்றார்கள்.`,
  },
  {
    id: 2027, tantraId: 7, verseNumber: 2026,
    tamil: `அஞ்சுள சிங்கம் அடவியல் வாழ்வன
அஞ்சும்போய் மேய்ந்துதம் அஞ்சுஅக மேபுகும்
அஞ்சின் உகிரும் எயிரும் அறுத்திட்டால்
எஞ்சாது இறைவனை எய்தலும் ஆமே`,
    transliteration: `añcuḷa ciṅkam aṭaviyal vāḻvaṉa
añcumpōy mēyntutam añcuaka mēpukum
añciṉ ukirum eyirum aṟuttiṭṭāl
eñcātu iṟaivaṉai eytalum āmē`,
    english: `2026: Senses are Like Roaming Lions
Five the lions, that roam the forest
The Five seeking their prey, get filled;
And to their caves the Five return;
If the claws and teeth of the Five you pull,
You shall sure the Lord reach.`,
    elaborationEnglish: `The senses are roaming like lions which feel contented when their stomachs get filled. If their claws and teeth are pulled, they will have no more terrors for you. You will safely reach the Lord.`,
    elaborationTamil: `இம்மந்திரமும் பிசிச் செய்யுளே, முன் மந்திரங்களில் களிறுகளாகவும், குதிரைகளாகவும், பறவைகளாகவும் குறிக்கப்பட்ட புலனடக்கம் இல்லாத மனம் இம்மந்திரத்தில் அதனது அடங் காமையின் மிகுதி இனிது விளங்குமாறு சிங்கமாகக் குறிக்கப்பட்டது. அடவி - வேறுபட்ட பல பெருமரங்கள் செறிந்த காடு. அது 'நல்லன, தீயன' எனப் பெரும்பான்மையாக இருவகைப்பட்டு, அவற்றுள் எண்ணில வாய் விளையும் வினைகளைக் குறித்தது. நல்வினை, பயன்மரம், தீவினை, நச்சுமரம், வாய்ப்பு உள்ள பொழுது சென்று ஐம்புலன்களை நுகர்கின்ற மனம் வாய்ப்பு இல்லாதபொழுதும் அவற்றையே நாடுதல் பற்றி ''அஞ்சு அகமே புகும்'' என்றார். அஞ்சு - பொறிகள். சிங்கங்கட்கு உகிர் (நகம்) உண்டற்குரிய விலங்குகளை இறுகப் பற்றுதற்கும், எயிறு (பல்) அவ்விலங்கின் தசைகளை உண்டு சுவைத்தற்கும் உதவுவன. எனவே, 'அவற்றை அறுத்தல்' என்பது மனத்திற்குப் பொருள்களின் மேல் உளதாய பற்றினையும், அவற்றை நுகர்தற்கண் உளதாய ஈடுபாட்டினையும் நீக்குதலாயிற்று. 'நீக்குதற்குக் கருவி சிவயோக சிவானங்கள் என்பது மேல் பல இடங்களில் கூறப்பட்டது. ''அறுத் திட்டால்'' எனவே, ''அறுத்திடல் மிக அரிது'' என்பது விளங்கிற்று. நகமும், பல்லும் போயபின் காட்டில் வாழும் சிங்கங்கள் அங்குச்சென்றோரை அப்பாற் போகவிடாமல் மறித்துக் கொன்றொழிக்க மாட்டா. அதனால் அவர் அக்காட்டைக் கடந்து இன்புறலாம் என்பது பற்றி, ''அறுத்திட்டால் - எஞ்சாது இறைவனை எய்தலும் ஆகும்'' என்றார்.`,
  },
  {
    id: 2028, tantraId: 7, verseNumber: 2027,
    tamil: `ஐவர் அமைச்சருள் தொண்ணூற்று அறுவர்கள்
ஐவரும் மைந்தரும் ஆளக் கருதுவர்
ஐவரும் ஐந்த சினத்தொட நின்றிடில்
ஐவர்க்கு சிறைஇறுத்து ஆற்றகி லோமே`,
    transliteration: `aivar amaiccaruḷ toṇṇūṟṟu aṟuvarkaḷ
aivarum maintarum āḷak karutuvar
aivarum ainta ciṉattoṭa niṉṟiṭil
aivarkku ciṟaiiṟuttu āṟṟaki lōmē`,
    english: `2027: Senses are Like Ministers that Seek to Usurp the Body-
Kingdom
Five are the ministers,
Ninety six (Tattvas) are within they,
The Five and their brood of sons within
Seek you to rule;
If the Five in their fiery passion stand,
Endless indeed is the tribute
That to the Five we are to pay.`,
    elaborationEnglish: `Five senses and the ninety-six tattvas reign supreme.over you. The senses are like conspiring miristers that everplot to usurp the ‘body-kingdom.`,
    elaborationTamil: `அரசராகிய நம்மில் ஒவ்வொருவருக்கும் ஐவர் அமைச்சர் உள்ளிட்ட தொண்ணூற்றாறு பேர் வல்லுநர் பணியாளராய் உள்ளனர். அவர் நமக்கு அடங்கிப் பணி புரியாமல் ஒவ்வொருவரும் தனித்தனியே நம்மை ஆள விரும்புகின்றனர். எனினும் ஐவர் அமைச்சரே நம்மை ஆள்வதில் வெற்றி காண்கின்றனர். அந்த ஐவருக்குள்ளேயும் ஒற்றுமையில்லை. அதனால் அவரவரும் ஒவ்வொரு நோக்கத்தோடு நம்மை ஆள முயல்கின்றனர். அவர்கட்கு வரிசெலுத்தி நாம் எவ்வாறு நிறைவு செய்ய இயலும்!`,
  },
  {
    id: 2029, tantraId: 7, verseNumber: 2028,
    tamil: `சொல்லகில் லேன்சுடர்ச் சோதியை நாடொறும்
சொல்லகில் லேன்திரு மங்கையும் அங்குள
வெல்லகில் லேன்புலன் ஐந்துடன் தன்னையும்
கொல்லநின் றோடும் குதிரைஒத் தேனே`,
    transliteration: `collakil lēṉcuṭarc cōtiyai nāṭoṟum
collakil lēṉtiru maṅkaiyum aṅkuḷa
vellakil lēṉpulaṉ aintuṭaṉ taṉṉaiyum
kollaniṉ ṟōṭum kutiraiot tēṉē`,
    english: `2028: Without Sense Control Jiva is Like a Murderous Steed
I praise not daily
The Holy Light;
I speak not of Sakti
That is within there;
I conquer not the senses Five;
Unto a murderous steed headlong that races
Verily, am I.`,
    elaborationTamil: `''துஞ்சும் போதும் சுடர்விடும் சோதியாய், (தி.5 ப.93 பா.8) உள்ள இறைவனையும், அவனோடே நீக்கமின்றி யிருக்கின்ற இறைவி யையும் நாள்தோறும் ஒழிவின்றி மந்திரமொழியாலும், தோத்திரப் பாடல்களாலும் சொல்லக் கடவேனாகிய யான் அங்ஙனம் செய்ய மாட்டாதவனாய் நிற்கின்றேன். அதனால் அங்ஙனம் மாட்டா தாரிடத்து வளர்வனவாகிய ஐம்புல ஆசைகளையும், அதனை உடைத்தாகின்ற மனத்தையும் அடக்கும் வலியிலேனாகின்றேன் அதனால், தன்மேல் இருப்பவனைக் குழியில் வீழ்த்திக் கொல்லவே நினைத்து வேகமாகப் பாய்ந்து ஓடுகின்ற குதிரையை அடக்க மாட்டாது விழிப்பவன்போலத் திகைக்கின்றேன்.`,
  },
  {
    id: 2030, tantraId: 7, verseNumber: 2029,
    tamil: `எண்ணிலி இல்லி அடைத்துஅவ் இருட்டறை
எண்ணிலி இல்லியோடு ஏகில் பிழைதரும்
எண்ணிலி இல்லியோடு ஏகாமை காக்குமேல்
எண்ணிலி இல்லதோடு இன்பமது ஆமே`,
    transliteration: `eṇṇili illi aṭaittuav iruṭṭaṟai
eṇṇili illiyōṭu ēkil piḻaitarum
eṇṇili illiyōṭu ēkāmai kākkumēl
eṇṇili illatōṭu iṉpamatu āmē`,
    english: `2029: Control Desires, and Attain Bliss
Countless the holes
In this body's chamber dark;
If with the countless holes (desires) I run,
Faulty will my lot be;
If you run not
With the countless holes of desires,
Countless indeed the bliss you attain.`,
    elaborationEnglish: `Do not run with the numerous holes of desire present in this body. Control will bring countless blessings.`,
    elaborationTamil: `ஒரு தலைவன் எனக்கென ஓர் அறையை ஈந்துள்ளான். (தலைவன் - பிரமன். அறை - உடம்பு) அதில் உள்ள பொத்தல்களோ அளவில்லன. (மயிர்க்கால்கள்) ஆயினும் அந்த அறைக்குள்ளே சிறிதே ஒளிபுகாது இருட்டிக் கிடப்பது வியப்பைத் தருகின்றது. (ஞானம் உடம்பு வழியாக வாராமை தெளிவு,) இந்த இருட்டறையிலேதான் என்னுடைய காலமெல்லாம்போய் ஆக வேண்டும் என்றால், அஃது எத்துணைத் துன்பத்தைத் தரும் என்பது சொல்லவேண்டுவதில்லை. ஆயினும் இறைவன் என்னை அவ்வறை யிற்றானே யிருந்து காலந் தள்ளாமல் காக்கத் திருவுளம் பற்றுவா னாயின், உடனே எனக்கு அளவுட்படாத கலத்தையுடைய ஒரு பெரிய மாளிகையைத்தரின் ஒப்பற்ற பெரியதோர் இன்பம் கிடைத்துவிடும். (அம்மாளிகை வியாபகப் பொருளாகிய திருவருள். இன்பம், சிவானந்தம்.)`,
  },
  {
    id: 2031, tantraId: 7, verseNumber: 2030,
    tamil: `விதியின் பெருவலி வேலைசூழ் வையம்
துதியின் பெருவலி தொல்வான் உலகம்
மதியின் பெருவலி மானுடர் வாழ்க்கை
நிதியின் பெருவலி நீர்வலி தானே`,
    transliteration: `vitiyiṉ peruvali vēlaicūḻ vaiyam
tutiyiṉ peruvali tolvāṉ ulakam
matiyiṉ peruvali māṉuṭar vāḻkkai
nitiyiṉ peruvali nīrvali tāṉē`,
    english: `2030: Strength of Wisdom Leads to Higher Life
Of their Karma's strength is life here below,
Of their prayers' strength is life in heaven above,
Of their wisdom's strength is men's higher life;
Verily, of their strength of Grace
Is their way of life.`,
    elaborationEnglish: `The life here below is of karma’s strength; and the life in heaven above is of prayer’s strength. Strength of wisdom: belongs to man’s higher life.`,
    elaborationTamil: `உலகில் அறத்திற்கும் இன்பத்திற்கும் காரணமாய் உள்ள பொருளின் வலிமைக்குக் காரணம் மழையின் வலிமையே யாகும். அதுபோல, கடல் சூழ்ந்த நிலவுலகில் உள்ள அனைத் துயிர்களின் வாழ்க்கை வலி அயன் விதித்த விதியின் வலிமையும், அவ்வுயிர்களுள் மக்கள் உயிர்களின் வாழ்க்கை வலிமைக்குக் காரணம் அவர்களது ஆறாவது அறிவின் வலிமையும், சுவர்க்க லோகத்தவரது வாழ்க்கையின் வலிமைக்குக் காரணம் அவர்கள் இந்நிலவுலகில் செய்த பல தெய்வ வழிபாடுகளின் வலிமையும், சிவலோகத்தவரது வாழ்க்கையின் வலிமைக்குக் காரணம் அவர்கள் இந்நிலவுலகில் செய்த சிவவழிபாட்டின் வலிமையுமாகும்.`,
  },
  {
    id: 2032, tantraId: 7, verseNumber: 2031,
    tamil: `குட்டம் ஒருமுழம் உள்ளது அரைமுழம்
வட்டம் அமைந்ததோர் வாவியுள் வாழ்வன
பட்டன மீன்பல பரவன் வகைகொணர்ந்து
இட்டனன் யாம்இனி ஏதம்இ லோமே`,
    transliteration: `kuṭṭam orumuḻam uḷḷatu araimuḻam
vaṭṭam amaintatōr vāviyuḷ vāḻvaṉa
paṭṭaṉa mīṉpala paravaṉ vakaikoṇarntu
iṭṭaṉaṉ yāmiṉi ētami lōmē`,
    english: `2031: Lord is a Fisher of Desires
One cubit its depth,
Half cubit its diameter,
Thus shaped round is the body pond;
The Fisherman (Lord) His net spreads;
Many the fish (of desires) He caught;
No more--the troubles I encounter.`,
    elaborationTamil: `ஒவ்வொரு மனித உயிரையும் ஒவ்வொரு நீர்வாழ் உயிராகக் கருதினால் அவ்வுயிர் வாழ்வதற்கு உள்ள குளமும் ஒரு சாண் குறுக்களவுடைய வட்ட வடிவினதாய்த் தோன்றும். எனவே அதன் ஆழமும் ஒரு சாணளவே உள்ளதாக மதிக்கப்படும். ஆயினும் அவ்வாறின்றி ஒரு சாணுக்குமேல் கூடுதலாக ஒரு முழ ஆழம் உள்ளது. (குளம் - முகம். ஆழம் கழுத்திற்குக் கீழ் மூலாதாரம் வரை உள்ள இடம்.) மேற்குறித்த குளத்தில் ஐந்து கொடிய மீன்கள் உள்ளன. (அவை அந்நீர் வாழ் உயிரை அமைதியாக வாழ விடாமல் அலைக்கழிப்பன. மீன்கள், (ஐம்பொறிகள்) இந்த நிலைமை எமக்குந்தான் உள்ளது. இதனை அறிந்த ஓர் வலைஞன் எம்மிடத்தில் இரக்கங்கொண்டு வலையைக் கொணர்ந்து வீசினான். மீன்கள் தப்ப முடியாமல் அவ்வலையில் அகப்பட, வலைஞன் அவைகளைத் தான் எடுத்துக் கொண்டான். (சிவன் கருணை கூர்ந்து தனது சத்தியைச் செலுத்தி எமது ஐம்பொறிகளைத் தன்னையே பற்றியிருக்கச் செய்தான்.) அதனால் யாம் துயர் ஒழிந்தோம்.`,
  },
  {
    id: 2033, tantraId: 7, verseNumber: 2032,
    tamil: `கிடக்கும் உடலின் கிளர்இந் திரியம்
அடக்க லுறும் அவன்தானே அமரன்
விடக்கிண்டு இன்புற மேவுறு சிந்தை
நடக்கின் நடக்கும் நடக்கும் அளவே`,
    transliteration: `kiṭakkum uṭaliṉ kiḷarin tiriyam
aṭakka luṟum avaṉtāṉē amaraṉ
viṭakkiṇṭu iṉpuṟa mēvuṟu cintai
naṭakkiṉ naṭakkum naṭakkum aḷavē`,
    english: `2032: Control Senses and Become Immortal
The stirring Indriyas within the body dwell,
He who controls them is immortal verily;
If your thoughts seek the pleasure twain--
Food and sex,
Only that far will they last,
Until your breath lasts.`,
    elaborationTamil: `நாம் நடத்தினால் நடந்து, கிடத்தினால் கிடப் பதாகிய உடம்பை நம் விருப்பத்தின் படியே நடத்திட ஒட்டாது, அதினின்றும் எழுகின்ற ஐந்து இந்திரியங்களும் கிளர்ச்சி செய் கின்றன. அக்கிளர்ச்சியை அடக்குபவனே மனிதருள் தேவனாவான். அவ்வாறின்றி, அக்கிளர்ச்சியின் வழிப்பட்டு நமது உடம்பாகிய ஒரு மாமிச பிண்டத்துடன் இன்னொரு மாமிச பிண்டத்தை அணைத்து இன்பம் அடைய விரும்புவனவாய் உள்ளன தமது மனங்கள். அந்த மனத்தின் வழியே நாம் நடந்து கொண்டிருந்தால் நமது உடம்புகள் அவற்றிற்கு வரையறுத்த நாள் வரையில் நடந்து பின்பு வீழ்ந்துவிடும்.`,
  },
  {
    id: 2034, tantraId: 7, verseNumber: 2033,
    tamil: `அஞ்சும் அடக்குஅடக்கு என்பர் அறிவிலார்
அஞ்சும் அடக்கும் அமரரும் அங்கிலை
அஞ்சும் அடக்கிய அசேதன மாம்என்றிட்டு
அஞ்சும் அடக்கா அறிவு அறிந்தேனே`,
    transliteration: `añcum aṭakkuaṭakku eṉpar aṟivilār
añcum aṭakkum amararum aṅkilai
añcum aṭakkiya acētaṉa māmeṉṟiṭṭu
añcum aṭakkā aṟivu aṟintēṉē`,
    english: `2033: Not Control But Sublimation of Senses is Wisdom's Way
--Thus say those who know not;
None, not even the
Immortals
The senses Five control;
When you the senses
Five control
Verily are you an inert mass;
(There is a way alternate open)
Sublimate them toward the Lord
That Wisdom's Way, I learned.`,
    elaborationTamil: `’ஐம்பொறிகளையும் அடக்குதல்’ என்பதற்கு, 'அவற்றைக் கெடுத்தல்' எனப்பொருள் செய்து, 'அவற்றை அடக்கு, அடக்கு' என மாணாக்கர்க்கு வலியுறுத்திக் கூறும் ஆசிரியர் உண்மை ஞானாசிரியர் ஆகார். ஏனெனில் அவ்வாறு அடக்கி உயர்நிலை பெற்றவர் வானுலகத்திலும் இல்லை. அதற்குக் காரணம் ஐம் பொறிகளைக் கெடுத்தொழித்தால் அவற்றால் அறிந்துவருகின்ற ஆன்மா அறிவற்ற சடம்போல் ஆகிவிடும். அதனையறிந்து யான் அவற்றைக் கெடுத்திடாது செயற்பட வைத்தே பெறுகின்ற ஞானத்தை அறிந்தேன்.`,
  },
  {
    id: 2035, tantraId: 7, verseNumber: 2034,
    tamil: `முழக்கி எழுவன மும்மத வேழம்
அடக்க அறிவென்றும் கோட்டையை வைத்தேன்
பிழைத்தன ஓடிப் பெருங்கேடு மண்டிக்
கொழுத்தன வேழம் குலைக்கின்ற வாறே`,
    transliteration: `muḻakki eḻuvaṉa mummata vēḻam
aṭakka aṟiveṉṟum kōṭṭaiyai vaittēṉ
piḻaittaṉa ōṭip peruṅkēṭu maṇṭik
koḻuttaṉa vēḻam kulaikkiṉṟa vāṟē`,
    english: `2034 Mere Control Does Not Avail
Loud they roar, the elephants in MAST triple, (Pasas)
I applied the goad of knowledge to them control;
But they romped about and in fury escaped,
They fat became, causing destruction in their train,
And sweet fields of sugarcane (goodly qualities) devastating.`,
    elaborationTamil: `ஐந்திந்திரியங்களாகிய மத யானைகள் தறியில் கட்டுண்ணாது பிளிறிக்கொண்டு தாம் நினைத்தபடி செல்லும் இயல் புடையன. அதையறிந்து நான் அவைகளை அடக்கி நேரிய வழியில் செலுத்துதற் பொருட்டு ஞானமாகிய அங்குசத்தைப் பயன் படுத்தினேன். எனினும் அவைகள் அதையும் மீறித் தம் விருப்பப்படி ஓடித் தமக்கு விருப்பமான உணவை அளவு கடந்து உண்டு, அதனால் மேலும் மதம் மிகுந்து தீய குணத்தை மிக அடைந்து என்னை நிலைகுலையச் செய்யுமாறு பெரிது.`,
  },
  {
    id: 2036, tantraId: 7, verseNumber: 2035,
    tamil: `ஐந்தில் ஒடுங்கில் அகலிடம் ஆவது
ஐந்தில் ஒடுங்கில் அருந்தவம் ஆவது
ஐந்தில் ஒடுங்கில் அரன்பதம் ஆவது
ஐந்தில் ஒடுங்கில் அருளுடை யாரே`,
    transliteration: `aintil oṭuṅkil akaliṭam āvatu
aintil oṭuṅkil aruntavam āvatu
aintil oṭuṅkil araṉpatam āvatu
aintil oṭuṅkil aruḷuṭai yārē`,
    english: `2035: Sublimation is the Way to Grace
If the senses Five you sublimate
Then all worlds are yours;
That is tapas rare;
That is the Lord's Feet too;
That indeed is the way to Grace receive.`,
    elaborationTamil: `இந்திரியங்களாகிய யானைகள் ஐந்தும் மதம் பிடித்துத் திரியாமல் ஆன்ம அறிவாகிய கூடத்திற்குள்ளே அடங்கி யிருக்குமாயின் அதுவே அறம், தவம், இறையுலகப் பேறு, ஞானம் எல்லாமாம்.`,
  },
  {
    id: 2037, tantraId: 7, verseNumber: 2036,
    tamil: `பெருக்கப் பிதற்றிலென் பேய்த்தேர் நினைந்தென்
விரித்த பொருட்கெல்லாம் வித்தாவது உள்ளம்
பெருக்கிற் பெருக்கம் சுருக்கிற் சுருக்கம்
அருத்தமும் அத்தனை ஆராய்ந்துகொள் வார்க்கே`,
    transliteration: `perukkap pitaṟṟileṉ pēyttēr niṉainteṉ
viritta poruṭkellām vittāvatu uḷḷam
perukkiṟ perukkam curukkiṟ curukkam
aruttamum attaṉai ārāyntukoḷ vārkkē`,
    english: `2036: Control of Thought is the Key to Control of Senses
Why drivel at length?
Why the mirage think of?
The thought is the seed
Of things all;
Expand your thought
The things too expand;
Contract your thought;
That is all there is to it,
For those who think about it.`,
    elaborationTamil: `'உலகம் நிலையற்றது' என்பதைக் கூறும் நூல்களைப் பலவாக எடுத்துச் சொல்லி, அவற்றின் பொருளையும் பலவாறாக விளக்கிப் பேசினாலும், 'உலகம் கானல் போல்வது' என்பதைக் கல்வியளவிலும் கேள்வியளவிலும் உணர்ந்தாலும் அவை யெல்லாம் இந்திரிய அடக்கத்திற்கு நேர்க்கருவியாவன அல்ல. ஏனெனில், நிலையாதவற்றின்மேல் அவாக்கொண்டு ஓடி அவற்றுள் முன்னர் ஒன்றைப் பற்றிக் கிடந்து, பின்பு அதனை விட்டு மற் றொன்றின்மேல் தாவி அதனைப் பற்றிக்கிடந்து இவ்வாறு முடிவின்றிச் செல்வது மனமே. அதனால் அஃது அவ்வாறு முடிவின்றி ஓட விட்டால், அது புலனுணர்வை முடிவின்றித் தோற்றுவித்துக் கொண்டேயிருக்கும். மனத்தை ஓடவிடாது நிறுத்திவிட்டால், புலன் உணர்வின் தோற்றமும் இல்லையாய் விடும். ஆகையால் மனத்தை யடக்குதலே இந்திரிய அடக்கத்திற்கு நேர்க்கருவியாகும். 'இந்திரியங்களை அடக்குமாறு எவ்வாறு' என ஆராய்பவர்க்கு அறிய வேண்டிய பொருளாயிருப்பது அவ்வளவே.`,
  },
  {
    id: 2038, tantraId: 7, verseNumber: 2037,
    tamil: `இளைக்கின்ற வாறுஅறிந்து இன்னுயிர் வைத்த
கிளைக்குஒன்றும் ஈசனைக் கேடில் புகழோன்
தளைக்கொன்ற நாகம்அஞ் சாடல் ஒடுக்கத்
துளைக்கொண்டது அவ்வழி தூங்கும் படைத்தே`,
    transliteration: `iḷaikkiṉṟa vāṟuaṟintu iṉṉuyir vaitta
kiḷaikkuoṉṟum īcaṉaik kēṭil pukaḻōṉ
taḷaikkoṉṟa nākamañ cāṭal oṭukkat
tuḷaikkoṇṭatu avvaḻi tūṅkum paṭaittē`,
    english: `2037: Control the Serpentine Thought in the Yoga Way of
Knowing well how spent away you are
The Lord comes to dwell in the body
For the soul to lean on;
And He of blemishless fame
To aubdue the five-headed serpent
That in Pasa coiled lay,
Provides the fluted
Sushumna
That central stands.`,
    elaborationEnglish: `That central stands.

He, the Immaculate Pinnacle, subdues the serpentine thought
that is coiled in pasa, that burrows a way through the
sushumna cavity.`,
    elaborationTamil: `இன்பத்தை நுகர்ந்து இனிதே வாழ்தற்கு உரியன வாகிய உயிர்கள் அவ்வாறின்றித் துன்பத்திற் கிடந்து துயர் உறுதலை அறிந்து அவை அத்துன்பத்தினின்றும் நீங்குதற்குரிய வழியை அமைத்துக் கொடுத்து, அதனாலே உறவாதற்குப் பொருந்தியவன் தானேயாய் நிற்கின்ற இறைவனைப் புகழ்ந்து போற்றி அதனால் தானும் என்றும் அழியாப் புகழைப் பெறுகின்ற அறிவன், ஐம்பொறிக ளாகிய பாம்புகள் ஐந்தும் தாம் படம் எடுத்து ஆடுகின்ற ஆட்டத்தை விடுத்துத் தமது புற்றிலே சென்று அடங்கிக் கிடக்கும்படி அடக்கி விடுவானாயின், அதன்பின், அவனும் துளையை உடைய அந்தப் புற்றுவழியாகவே இன்பம் பெற்று அமைதியை அடைவான்.`,
  },
  {
    id: 2039, tantraId: 7, verseNumber: 2038,
    tamil: `பாய்ந்தன பூதங்கள் ஐந்தும் படரொளி
சார்ந்திடும் ஞானத் தறியினில் பூட்டிட்டு
வாய்ந்துகொள் ஆனந்தம் என்னும் அருள் செய்யில்
வேய்ந்துகொள் மேலை விதியது தானே`,
    transliteration: `pāyntaṉa pūtaṅkaḷ aintum paṭaroḷi
cārntiṭum ñāṉat taṟiyiṉil pūṭṭiṭṭu
vāyntukoḷ āṉantam eṉṉum aruḷ ceyyil
vēyntukoḷ mēlai vitiyatu tāṉē`,
    english: `2038: Control Senses By Jnana Yoga
Tie the prancing senses five
To the post of Jnana that illumines;
Thus you attain Grace that is Bliss;
This the Way of Yore, high and true.`,
    elaborationTamil: `பூத காரியங்களாகிய ஐம்புலப் பொருள்கள்மேல் மதங்கொண்டு செல்கின்ற ஐந்து இந்திரியங்களாகிய யானைகளை அவற்றின் வழியே செல்கின்ற உயிரினது அறிவு, தான் அடையத் தக்க தாகிய திருவடி ஞானமாகிய தறியை அடைந்து அதன்கண் கட்டிவிட, அதனைக் கண்டு, அறிவர் பலரும் அறிந்து அடைகின்ற அருளானந் தத்தை இறைவன் தருவானாயின், அதுவே, யாவரும் மேற்கொள்ளத் தக்க முதல் நூல் விதியின் பயனாகும்.`,
  },
  {
    id: 2040, tantraId: 7, verseNumber: 2039,
    tamil: `நடக்கின்ற நந்தியை நாடோ றும் உன்னில்
படர்க்கின்ற சிந்தையப் பைய ஒடுக்கிக்
குறிக்கொண்ட சிந்தை குறிவழி நோக்கில்
வடக்கொடு தெற்கு மனக்கோயி லாமே`,
    transliteration: `naṭakkiṉṟa nantiyai nāṭō ṟum uṉṉil
paṭarkkiṉṟa cintaiyap paiya oṭukkik
kuṟikkoṇṭa cintai kuṟivaḻi nōkkil
vaṭakkoṭu teṟku maṉakkōyi lāmē`,
    english: `2039: Control Thought and Make it a Temple
Daily think of the Living Nandi
Gently control your thoughts distracting,
Course your thoughts through Muladhara,
Then your thoughts a temple become,
From north to south extending.`,
    elaborationTamil: `உயிர் செய்யும் செயல் யாவற்றிலும் தானும் உடனாய் நின்று செய்யும் சிவனை அறியாது அனைத்துச் செயல் களையும் தானே செய்வதாகக் கருதி மயங்குகின்ற உயிர் அம் மயக்கத்தினின்றும் நீங்கி அவனை இடைவிடாது உணர்ந்து நிற்பின், ஐம்புலன்களை நாடி ஓடுகின்ற மனம் மெல்ல மெல்ல அதனை விடுத்து அவனிடத்தே சென்று ஒடுங்கும். அங்ஙனம் ஒடுங்கிய நிலை ஒருவர்க்கு வாய்க்குமாயின், உலகில் உள்ள அனைத்துக் கோயில் களும் அவரது மனமாகிய அந்தக் கோயிலாகவே அமைந்துவிடும்.`,
  },
  {
    id: 2041, tantraId: 7, verseNumber: 2040,
    tamil: `சென்றன நாழிகை நாள்கள் சிலபல
நின்றது நீள்பொருள் நீர்மேல் எழுத்துஒத்து
வென்று புலன்கள் விரைந்து விடுமின்கள்
குன்று விழவதில் தாங்கலும் ஆமே`,
    transliteration: `ceṉṟaṉa nāḻikai nāḷkaḷ cilapala
niṉṟatu nīḷporuḷ nīrmēl eḻuttuottu
veṉṟu pulaṉkaḷ viraintu viṭumiṉkaḷ
kuṉṟu viḻavatil tāṅkalum āmē`,
    english: `2040: Control Senses and Bear Your Troubles Gently
The hours sped,
The days many passed away;
Unto the writing on the water
Transitory your possessions are;
Conquer the senses,
Quickly give them up;
Then even if as mountain,
Your troubles roll on you
Well may you bear them, gently indeed.`,
    elaborationTamil: `வாழ்நாளில் கழிவன சில நாழிகைகள் போலத் தோன்றுகின்றன. ஆயினும் அவை உண்மையில் சிலவும், பலவுமான நாட்களாய் விடுகின்றன. நெடுங்காலம் நிற்பதுபோலத் தோன்றுகின்ற உடம்பு நீர்மேல் எழுத்துப்போல விரைய மறைவதாகின்றது. இதனை உணர்ந்து, 'அறிவுடையேம்' என உங்களை நீங்களே மதித்துக் கொள் கின்ற உலகீர், இளமையிற்றானே ஐம்புல ஆசையை வென்று, அப்புலன்களுக்குச் சார்பாய் உள்ள பொருள்களைத் துறந்து விடுங்கள். இல்லையேல், அவ்வாசையால் விளையும் வினைகள் மலைபோல வந்துவிழும்; அவைகளைத் தாங்க இயலாது.`,
  },
  {
    id: 2042, tantraId: 7, verseNumber: 2041,
    tamil: `போற்றிசைத் துப்புனி தன்திரு மேனியைப்
போற்றிசெய் மீட்டே புலன்ஐந்தும் புத்தியால்
நாற்றிசைக் கும்பின்னை யாருக்கும் நாதனை
ஊற்றுக உள்ளத்து ஒருங்கலும் ஆமே`,
    transliteration: `pōṟṟicait tuppuṉi taṉtiru mēṉiyaip
pōṟṟicey mīṭṭē pulaṉaintum puttiyāl
nāṟṟicaik kumpiṉṉai yārukkum nātaṉai
ūṟṟuka uḷḷattu oruṅkalum āmē`,
    english: `2041: Redeem the Senses By Intelligence and Prayer
Praise the Holy Form
Of the Pure One;
Praise Him,
The Senses redeeming by intelligence;
In your heart welling up in love,
You shall become one with Him,
--He the Lord of directions four
And of beings, in others all.`,
    elaborationTamil: `சிவனது திருமேனியைத் துதிக்குமாற்றால் பருப் பொருள்களாய் உள்ள அவைகளைச் சார்ந்துள்ள புலன்களை விரும்பிச் செல்கின்ற மனத்தை அச்செலவினின்றும், மீட்டு, மீண்டும் அதனையே துதி. அங்ஙனம் துதித்தால், அப்பெருமானை அவனது ஆனந்தத்தைப் பொழிகின்ற மனத்திலே ஒன்றியிருக்கச் செய்தலும் கூடும்.`,
  },
  {
    id: 2043, tantraId: 7, verseNumber: 2042,
    tamil: `தரிக்கின்ற நெஞ்சம் சகளத்தின் உள்ளே
அரிக்கின்ற ஐவரை யாரும் உணரார்
சிரிக்கின்ற வாறு சிலபல பேசில்
வரிக்கின்ற மைசூழ் வரையது வாமே`,
    transliteration: `tarikkiṉṟa neñcam cakaḷattiṉ uḷḷē
arikkiṉṟa aivarai yārum uṇarār
cirikkiṉṟa vāṟu cilapala pēcil
varikkiṉṟa maicūḻ varaiyatu vāmē`,
    english: `2042: Senses Are Very Powerful
None knows that the senses Five,
Within body thoughts engrossing,
Slowly eat you away;
Do not take them lightly
And talk away;
They are verily unto a mountain range
That are by dark clouds capped.`,
    elaborationTamil: `சிவபெருமானது உருவத் திருமேனியினுள்ளே படிந்து நிற்றற்குரிய மனத்தை அங்ஙனம் நிற்க ஒட்டாமல் நச்சரித்துப் பெயர்க்கின்ற ஐம்புலன்களாகிய குறும்பரது தீச்செயலை உலகவர் யாரும் உணர்வதில்லை. அதனால் அங்ஙனம் உணராத நிலையில் இருந்து கொண்டே கவலையின்றி ஒருவரோடொருவர் நகையாடிச் சிலவும் பலவுமாகிய பேச்சுக்களைப் பேசி அவர் பொழுது போக்குவாரேயானால் அவரது செயல் தனது நிலையான இயற்கைப் பொலிவுடன் விளங்கத் தக்கதாகிய மலையை நிலையாது நீங்கும் அழகையுடைய மேகங்கள் வந்து சூழ்ந்து மறைத்தல் போல்வதாகும்.`,
  },
  {
    id: 2044, tantraId: 7, verseNumber: 2043,
    tamil: `கைவிட லாவது ஒன்று இல்லை கருத்தினுள்
எய்தி அவனை இசையினால் ஏத்துமின்
ஐவருடைய அவாவினில் தோன்றிய
பொய்வ ருடைய புலன்களும் ஐந்தே`,
    transliteration: `kaiviṭa lāvatu oṉṟu illai karuttiṉuḷ
eyti avaṉai icaiyiṉāl ēttumiṉ
aivaruṭaiya avāviṉil tōṉṟiya
poyva ruṭaiya pulaṉkaḷum aintē`,
    english: `2043: Give Up Nothing; But Sublimate Your Thought Towards
God
There is nothing, you need give up;
The Five senses are organs false
That the five cravings to meet arose;
Reach to Him in your thoughts
And praise Him in songs sweet.`,
    elaborationEnglish: `Renounce nothing, But sublimate your thoughts and senses towards God. Praise Him and adore Him in sweet music and ecstatic songs. He will direct you inner being to divine destiny.`,
    elaborationTamil: `'ஐந்திந்திரியங்களை அடக்குதல் நம்மால் ஆகிற காரியம் அன்று' என இளைத்து, அதனைக் கைவிடுதற்குக் காரணம் சிறிதும் இல்லை. ஏனெனில், ஐந்திந்திரியங்களின் அவாவிற்குக் காரணமான நிலையற்ற பொருள்களில் பொருந்தியுள்ள புலன்களும் ஐந்திற்குமேல் இல்லை. அந்த ஐந்தையும் அடக்குதற்குச் செய்யத் தக்க உபாயமும் ஒன்றே ஒன்றுதான். அஃது ஒருபொழுதும் நம்மை விட்டு நீங்கிச் சேய்மையில் இல்லாது, எப்பொழுதும் நம் உள்ளத்திலேயே வீற்றிருக்கின்ற சிவனை நல்ல இசைப் பாடல்களால் துதிப்பதுதான். ஆகவே, அதனைச் செய்து இந்திரியங்களை அடக்கி, இன்பம் எய்துங்கள்.`,
  },
  {
    id: 2045, tantraId: 7, verseNumber: 2044,
    tamil: `உணர்வுஒன்று இலாமூடன் உண்மைஒ ராதோன்
கணுவின்றி வேதா கமநெறி காணான்
பணிஒன்று இலாதோன் பரநிந்தை செய்வோன்
அணுவின் குணத்தோன் அசற்குரு வாமே`,
    transliteration: `uṇarvuoṉṟu ilāmūṭaṉ uṇmaio rātōṉ
kaṇuviṉṟi vētā kamaneṟi kāṇāṉ
paṇioṉṟu ilātōṉ paranintai ceyvōṉ
aṇuviṉ kuṇattōṉ acaṟkuru vāmē`,
    english: `2044: The Unholy Guru Has Virtues None
A fool he is,
Wisdom none he has;
Truth he has realized not;
Versed is he not in the way
Of Vedas and Agamas;
Humility he has none;
Of God he speaks ill;
Worldly life is his sole concern;
He, verily, is the Guru unholy.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 2046, tantraId: 7, verseNumber: 2045,
    tamil: `மந்திர தந்திர மாயோக ஞானமும்
பந்தமும் வீடும் தரிசித்துப் பார்ப்பவர்
சிந்தனை செய்யாத் தெளிவியாது ஊண்பொருட்டு
அந்தகர் ஆவோர் அசற்குரு வாமே`,
    transliteration: `mantira tantira māyōka ñāṉamum
pantamum vīṭum taricittup pārppavar
cintaṉai ceyyāt teḷiviyātu ūṇporuṭṭu
antakar āvōr acaṟkuru vāmē`,
    english: `2045: The Unholy is only in Search of Food
Mantra, Tantra,
Mahayoga and Jnana,
Bondage, and Mukti
--These they seek to know, the holy ones;
The Gurus unholy
Them, they seek not;
Doubts they clear not;
Food are they in search of,
Verily blind are they.`,
    elaborationTamil: `சற்குரவராதற்கு உரியன பலவற்றை உடையோரும் தமது உபதேசத்தை உணரும் தகுதியில்லாதோர்க்கு அவர் வழியாகப் பெறப்படும் சில பயன் கருதி அவரை விலக்கமாட்டாராய் அவர்க்கு உபதேசம் செய்வாராயின், அவரும் அறியற்பாலனவற்றை அறியாத அறிவிலிகளாய், அசற்குரவராய் விடுவர்.`,
  },
  {
    id: 2047, tantraId: 7, verseNumber: 2046,
    tamil: `ஆமாது அறியாதோன் மூடன் அதிமூடன்
காமாதி நீங்காக் கலதி கலதிகட்கு
ஆமாறு அசத்துஅறி விப்போன் அறிவிலோன்
கோமான் அலன்அசத் தாகும் குரவனே`,
    transliteration: `āmātu aṟiyātōṉ mūṭaṉ atimūṭaṉ
kāmāti nīṅkāk kalati kalatikaṭku
āmāṟu acattuaṟi vippōṉ aṟivilōṉ
kōmāṉ alaṉacat tākum kuravaṉē`,
    english: `2046: The Unholy Guru is Bereft of Knowledge
Fool is he,
A big fool is he;
The Way of Becoming he knows not;
A vile fellow that is not of passions rid,
To vile men he teaches things vile;
Bereft of knowledge,
He no teacher exalted is;
--The Guru unholy.`,
    elaborationTamil: `'தக்கது இன்னது; தகாதது இன்னது' என உணரும் உணர்வில்லாதவன் மூடன்' என்பது உலகம் அறிந்தது. ஆயினும், அவ்வாறு அவற்றை அறிந்தும் காமம் முதலிய குற்றங்களின் நீங்கி, நல்லவற்றைப் பற்றியொழுகும் நல்லொழுக்கம் இல்லாதவன் அறிவுடையவன் ஆயினும் அதிமூடன் ஆவான். இனிக்குற்றங்களின் நீங்கி வல்லவற்றையே கடைப்பிடித்தொழுகும் நல்லொழுக்கம் உடையனாயினும் நல்லனவற்றை மதித்து உவந்து ஏற்கும் பண்பின்றி அவற்றை உணர்த்துவோரையும் இகழ்கின்ற கீழ்மக்கட்கு நல்லுபதேசத்தைச் செய்வானாயின் அவனும் அறிவிலியேயாவான். ஆகையால் அத்தகையோனும் சற்குருவாகாது, அசற்குருவாயாவன்.`,
  },
  {
    id: 2048, tantraId: 7, verseNumber: 2047,
    tamil: `கற்பாய கற்பங்கள் நீக்காமற் கற்பித்தால்
தற்பாவங் குன்றும் தனக்கே பகையாகும்
நற்பால் அரசுக்கும் நாட்டுக்கும் கேடென்றே
முற்பால நந்தி மொழிந்துவைத் தானே`,
    transliteration: `kaṟpāya kaṟpaṅkaḷ nīkkāmaṟ kaṟpittāl
taṟpāvaṅ kuṉṟum taṉakkē pakaiyākum
naṟpāl aracukkum nāṭṭukkum kēṭeṉṟē
muṟpāla nanti moḻintuvait tāṉē`,
    english: `2047: The False Guru is an Enemy to Himself and World
If without driving away
The illusory thoughts
That imagination breeds,
A teacher teaches,
He will in divinity lose faith;
Unto his own self an enemy be;
For the king and the kingdom an evil be;
--Thus has Nandi of yore declared.`,
    elaborationTamil: `சற்குருவாவான் தன்னை அடைந்த மாணாக்க னிடத்தில் உள்ள குற்றங்களை முதலில் நல்லனவற்றைக் கூறும் முறையால் நீக்கி அதன் பின்பே ஞானத்தை உணர்த்துதல் வேண்டும். அவ்வாறு செய்யாமலே ஞானத்தை உணர்த்தினால் தனது ஆசிரியத் தன்மையுங் கெட்டுத் தனது செய்கையே தனக்குத் தீங்காய் முடியும். அதனால் நாட்டில் புல்லரே தலையெடுப்பர் ஆதலின் அரசு நல்லரசாய் இருப்பினும் அதற்கும் கேடு விளையும். நாடும் தீய நாடாகி விடும். இதனைப் படைப்புக் காலத்திற்றானே சிவன் தனது ஆகமங்களில் சொல்லி வைத்துள்ளான்.`,
  },
  {
    id: 2049, tantraId: 7, verseNumber: 2048,
    tamil: `குருடர்க்குக் கோல்காட்டிச் செல்லும் குருடர்
முரணும் பழங்குழி வீழ்வர்கள் முன்பின்
குருடனும் வீழ்வர்கள் முன்பின் அறவே
குருடரும் வீழ்வார் குருடரோடு ஆகியே`,
    transliteration: `kuruṭarkkuk kōlkāṭṭic cellum kuruṭar
muraṇum paḻaṅkuḻi vīḻvarkaḷ muṉpiṉ
kuruṭaṉum vīḻvarkaḷ muṉpiṉ aṟavē
kuruṭarum vīḻvār kuruṭarōṭu ākiyē`,
    english: `2048: The Blind Leading the Blind Together Fall
The blind (the unholy Guru), who lead the blind (foolish disciples)
Will into the eternal pit first fall;
Then the foolish disciples too fall;
And in the end in disorder together they fall,
--The blind that lead and the blind that are led--
Indistinguishably, jumbled in one.`,
    elaborationTamil: `குருடர் சிலர், வேறு சில குருடருடனே சேர்ந்து வழிச் செல்வார்களாயின் எல்லோருமாக 'முன், பின்' என்பதின்றி ஒருங்கே குழியில் விழுவதைத் தவிர வேறு என்ன நிகழும்! ஆகையால், சில குருடர்கள் வேறுசில குருடர்களுக்கு 'நாங்கள் உங்கட்கு வழிகாட்டு கின்றோம்' என்றுசொல்லி அவர்கள் கையில் கோலைக் கொடுத்துத் தாங்கள் அக்கோலைப் பற்றிக் கொண்டு முன்னே செல்வாராயின், முதலில் வழிகாட்டும் குருடர் பாழ்ங்குழியில் வீழ்வர். பின்பு அவர்களால் அழைத்துவரப்பட்ட அந்தக் குருடர்களும் அந்தக் குழியிலே வீழ்வார்கள், (அது தான் நிகழும்.)`,
  },
  {
    id: 2050, tantraId: 7, verseNumber: 2049,
    tamil: `தாள்தந்து அளிக்கும் தலைவனே சற்குரு
தாள்தந்து தன்னை அறியத் தரவல்லோன்
தாள்தந்து தத்துவா தீதத்துச் சார்சீவன்
தாள்தந்து பாசம் தணிக்கும் அவன்சத்தே`,
    transliteration: `tāḷtantu aḷikkum talaivaṉē caṟkuru
tāḷtantu taṉṉai aṟiyat taravallōṉ
tāḷtantu tattuvā tītattuc cārcīvaṉ
tāḷtantu pācam taṇikkum avaṉcattē`,
    english: `2049 Holy Guru Leads Disciple to Truth
Placing his feet on my head
The Master blesses me;
He is Guru Holy;
He, my self-realization, works;
He takes the Jiva to the State beyond Tattvas;
He subdues my Pasas,
All these he performs
--He that is Truth itself.`,
    elaborationTamil: `சற்குருவே தன்னையடைந்த மாணாக்கர்க்குத் திரு வருளை வழங்கிக் காக்கும் பதியாவான். அவனையடைந்த மாணவனுக்கு அவன் தனது திருவடியைச் சென்னிமேல் சூட்டித் திருவடி ஞானத்தை அருளுமாற்றால் மாணவன் தனது உண்மை இயல்பை அறியும்படி செய்யவல்லான். அவன் தனது ஒரு வார்த்தை யாலும், திருவடி சூட்டலாலும் தன்னை யடைந்த மாணவனாகிய பசுவை மாயா கருவிகளினின்றும் விடுவித்து, ஆணவக் கட்டினையும் அவிழ்த்துவிடுவான்.`,
  },
  {
    id: 2051, tantraId: 7, verseNumber: 2050,
    tamil: `தவிரவைத் தான்வினை தன்னடி யார்கோள்
தவிரவைத் தான்சிரத் தோடுதன் பாதம்
தவிரவைத் தான்நமன் தூதுவர் கூட்டம்
தவிரவைத் தான் பிற வித்துயர் தானே`,
    transliteration: `taviravait tāṉviṉai taṉṉaṭi yārkōḷ
taviravait tāṉcirat tōṭutaṉ pātam
taviravait tāṉnamaṉ tūtuvar kūṭṭam
taviravait tāṉ piṟa vittuyar tāṉē`,
    english: `2050: What the Holy Guru does for His Disciples
From their Karmas, he extricated his disciples
Blessing them with his feet on their head,
He drove away their evil stars;
The messengers of Death
He kept at bay from them;
The miseries of unending birth
He ended for them.`,
    elaborationTamil: `(சற்குரு) தன் அடியார் வினை நீங்கவும் ஒன்பான் கோள்களின் தீங்கு நீங்கவும் யம தூதரது கூட்டம் விலகி ஓடவும், முடிவாகப் பிறவித் துன்பம் நீங்கவும் தனது திருவடிகளை அவர்தம் தலையோடு பொருந்துமாறு வைத்தருளினான்.`,
  },
  {
    id: 2052, tantraId: 7, verseNumber: 2051,
    tamil: `கறுத்த இரும்பே கனகமது ஆனால்
மறித்துஇரும் பாகா வகையது போலக்
குறித்தஅப் போதே குருவருள் பெற்றான்
மறித்துப் பிறவியல் வந்தணு கானே`,
    transliteration: `kaṟutta irumpē kaṉakamatu āṉāl
maṟittuirum pākā vakaiyatu pōlak
kuṟittaap pōtē kuruvaruḷ peṟṟāṉ
maṟittup piṟaviyal vantaṇu kāṉē`,
    english: `2051: He Takes Them to the Bourne From Which They Return
Not
The black iron, transmuted into gold,
To black iron returns not;
Even unto it,
He who once the Guru's grace received
Does not to birth return.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 2053, tantraId: 7, verseNumber: 2052,
    tamil: `பாசத்தை நீக்கிப் பரனோடு தன்னையும்
நேசத்து நாடி மலமற நீக்குவோர்
ஆசற்ற சற்குரு வாவோர் அறிவற்றுப்
பூசற்கு இரங்குவோர் போதக் குருவன்றே`,
    transliteration: `pācattai nīkkip paraṉōṭu taṉṉaiyum
nēcattu nāṭi malamaṟa nīkkuvōr
ācaṟṟa caṟkuru vāvōr aṟivaṟṟup
pūcaṟku iraṅkuvōr pōtak kuruvaṉṟē`,
    english: `2052: Holy Guru Does not Exult in Vain Contentions
He liberates you from Pasas;
He removes your Malas, entire;
He makes you seek the Lord in love;
--Such are the Gurus Holy, blemishless;
They who in contention exult
Are no Gurus enlightened.`,
    elaborationTamil: `உலகப்பற்றை ஒழித்து வீடுபேற்றில் விருப்பம் கொண்டு தன்னையும், தலைவனாகிய சிவனையும் ஆசிரியர் அருள் மொழியைக் கேட்டுச் சிந்தித்துத் தெளியுமாற்றால் தனது அறி யாமையைப் போக்கித் தன்னை அடைந்தவரது அறியாமையையும் முற்றப்போக்க வல்லவனே குற்றம் அற்ற உண்மை ஞான குரு ஆவான். அவ்வாறன்றி, அனுபவ ஞானம் இன்றி, நூலறிவு மாத்திரையால் செய்யும் ஆரவாரத்தில் மயங்கித் தானும் அதனையே செய்பவன் உண்மை ஞான குரு ஆகான்.`,
  },
  {
    id: 2054, tantraId: 7, verseNumber: 2053,
    tamil: `நேயத்தே நிற்கும் நிமலன் மலமற்ற
நேயத்தை நல்கவல் லோன்நித்தன் சுத்தனே
ஆயத்த வர்தத் துவம் உணர்ந் தாங்குஅற்ற
நேயர்க்கு அளிப்பவன் நீடும் குரவனே`,
    transliteration: `nēyattē niṟkum nimalaṉ malamaṟṟa
nēyattai nalkaval lōṉnittaṉ cuttaṉē
āyatta vartat tuvam uṇarn tāṅkuaṟṟa
nēyarkku aḷippavaṉ nīṭum kuravaṉē`,
    english: `2053: Holy Guru Assesses Worth of His Disciples
He is a pure being
He is so endearing;
He can give you love,
That is from Malas free;
He is immortal,
He is holy;
He assesses the worth of his disciples;
And on those who are impurity rid,
He bestows his grace;
He, the Master High.`,
    elaborationTamil: `நித்தியனாகிய சிவன் நின்மலன் ஆகலின், அவன் மலம் நீங்கித் தன்பால் மெய்யன்பு செலுத்துவோரது அறிவிலே விளங்கி நின்று அம்மெய்யன்பினை மேலும் மேலும் பெருக்க வல்லவ னாவன். ஆகையால், மலம் நீங்கிச் சுத்தான்மாவாய் நிற்கின்றவனே தன்னை அடைந்த மாணவக் கூட்டத்தாரது உண்மை நிலையை உணர்ந்து, அவர்களில் பாசப் பற்று அறும் பக்குவத்தை எய்தி னோர்க்கே ஞானத்தை உணர்த்துவன். ஆதலால் அவனே நிலைபெற்ற சற்குரு ஆவன்.`,
  },
  {
    id: 2055, tantraId: 7, verseNumber: 2054,
    tamil: `பரிசன வேதி பரிசித்தது எல்லாம்
வரிசை தரும்பொன் வகையாகு மாபோல்
குருபரி சித்த குவலயம் எல்லாம்
திரிமலம் தீர்ந்து சிவகதி யாமே`,
    transliteration: `paricaṉa vēti paricittatu ellām
varicai tarumpoṉ vakaiyāku māpōl
kurupari citta kuvalayam ellām
tirimalam tīrntu civakati yāmē`,
    english: `2054: By His Alchemic Touch Jiva Becomes Siva
All that the alchemist touches
Turns into gold;
Even, unto it,
The Jivas blessed by Guru
Siva become,
Freed from Malas Triple.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 2056, tantraId: 7, verseNumber: 2055,
    tamil: `தானே எனநின்ற சற்குரு சந்நிதி
தானே எனநின்ற தன்மை வெளிப்படில்
தானே தனைப்பெற வேண்டும் சதுர்பெற
ஊனே எனநினைந்து ஓர்ந்துகொள் உன்னிலே`,
    transliteration: `tāṉē eṉaniṉṟa caṟkuru canniti
tāṉē eṉaniṉṟa taṉmai veḷippaṭil
tāṉē taṉaippeṟa vēṇṭum caturpeṟa
ūṉē eṉaniṉaintu ōrntukoḷ uṉṉilē`,
    english: `2055: Holy Guru is Siva in Flesh
The Holy Guru
As Siva Himself stands;
In his presence
Jiva, his self-realization attains
If you, your self-realization seek,
Think of him, within,
As Siva in fleshly body.`,
    elaborationTamil: `'யான் சிவனே' என மாணாக்கற்கு அறிவுறுத்து கின்ற அந்தக் குருவின் சந்நிதியில் அவன் சிவனே ஆன தன்மை எவ்வாற்றா லேனும் மாணாக்கனுக்கு இனிது புலப்படுமாயின், அவனது மனித உடம்பைச் சிவனது அருள் திருமேனியாகவே உணர்ந்து, தான் அவனால் சிவமாந் தன்மையைப் பெறல் வேண்டும். (பின்னர் வேறு நினைத்தல் கூடாது.) இதனை உன் உள்ளத்திற்குள்ளே ஆராய்ந்து கொள்க.`,
  },
  {
    id: 2057, tantraId: 7, verseNumber: 2056,
    tamil: `வரும்வழி போம்வழி மாயா வழியைக்
கருவழி கண்டவர் காணா வழியைக்
பெரும்வழி யாநந்தி பேசும் வழியைக்
குருவழியே சென்று கூடலும் ஆமே`,
    transliteration: `varumvaḻi pōmvaḻi māyā vaḻiyaik
karuvaḻi kaṇṭavar kāṇā vaḻiyaik
perumvaḻi yānanti pēcum vaḻiyaik
kuruvaḻiyē ceṉṟu kūṭalum āmē`,
    english: `2056: Follow Holy Guru and Reach the Great Way
The Way of birth,
The Way of death,
The Way of Maya;
The Way they have not seen
Who the birth's Way saw;
The Great Way that Nandi speaks of
That Way you can reach
If your Holy Guru you follow.`,
    elaborationTamil: `பிறப்பும், இறப்பும் ஆகிய மாயையின் வேறு பாடுகளே 'பிறவி நெறி' எனப்படும். அதனையே கண்டு அவ்வழியே உழல்பவர் கண்டறியாத பெருவழியாக எங்கள் நந்தி பெருமான் தம்மை யடைந்தவர்க்குக் காட்டியருள்கின்ற வீட்டு நெறியை அவரைப்போலும் சற்குரு காட்டும் வழியிலே சென்று பிறரும் பெறுதல் கூடும்.`,
  },
  {
    id: 2058, tantraId: 7, verseNumber: 2057,
    tamil: `குருஎன் பவனே வேதாக மங்கூறும்
பரஇன்ப னாகிச் சிவயோகம் பாவித்து
ஒருசிந்தை யின்றி உயிர்பாசம் நீக்கி
வருநல் குரவன்பால் வைக்கலும் ஆமே`,
    transliteration: `kurueṉ pavaṉē vētāka maṅkūṟum
paraiṉpa ṉākic civayōkam pāvittu
orucintai yiṉṟi uyirpācam nīkki
varunal kuravaṉpāl vaikkalum āmē`,
    english: `2057: Holy Guru Leads to Lord
He is Guru Holy,
Who, entranced in bliss
The Vedas and Agamas speaks of,
Enters into Siva Yoga;
And all thoughts stilled,
Removes the bondage of
Pasa
And leads you to Lord.`,
    elaborationTamil: `'குரு' என்று சிறப்பித்துச் சொல்லப்படுபவன் வேதாகமங்களால் சொல்லப்படுகின்ற பேரின்பத்தை நுகர்பவனாய், சிவோகம் பாவனை தவிர வேறு பாவனை எதுவும் இன்றிப் பக்குவம் வாய்ந்த உயிரை மிகவாய் உள்ள பாசங்களினின்றும் நீக்கிச் சிவத்தில் சேர்க்கும் தலைவன் ஆவான்.`,
  },
  {
    id: 2059, tantraId: 7, verseNumber: 2058,
    tamil: `சத்தும் அசத்தும் சதசத்தும் தான்காட்டிச்
சித்தும் அசித்தும் சிவபரத் தேசேர்த்துச்
சுத்தம் அசுத்தம் அறச்சுக மானசொல்
அத்தன் அருட்குரு வாம்அவன் கூறிலே`,
    transliteration: `cattum acattum catacattum tāṉkāṭṭic
cittum acittum civaparat tēcērttuc
cuttam acuttam aṟaccuka māṉacol
attaṉ aruṭkuru vāmavaṉ kūṟilē`,
    english: `2058: Holy Guru Imparts Nature of Truth
He reveals the Real (Sat), the Unreal (Asat) and the Real-Unreal (Sat-Asat);
He takes Chit (Jiva) and Achit (Tattvas) into Siva-Para;
The words the blessed Guru speak
Are blissful,
Beyond Pure (Suddha) and (Asuddha) Impure.`,
    elaborationTamil: `சிவனது அருளே தன் வடிவாய் நிற்கின்ற உண்மைக் குருவாகிய அவன் தன் மாணாக்கர்க்கு ஒரு வார்த்தையைச் சொல்வானாயின் அந்த ஒரு வார்த்தை முப்பொருளின் இயல்பை உள்ளவாறு விளங்கச்செய்து, ஏனை எல்லாப் பொருளும் சிவ வியா பகத்தை விட்டு வேறு நில்லாமையைப் புலப்படுத்தி, சுத்தம், அசுத்தம் என்னும் இருவகைப் போகங்களும் அல்லாத வேறு ஒரு தனிப் போக மாகிய பரபோகத்தை விளைத்து நிற்கும் வார்த்தையாய் இருக்கும்.`,
  },
  {
    id: 2060, tantraId: 7, verseNumber: 2059,
    tamil: `ஊற்றிடும் ஐம்மலம் பாச உணர்வினை
பற்றறு நாதன் அடியில் பணிதலால்
சுற்றிய பேதம் துரியம் மூன் றால்வாட்டித்
தற்பரம் மேவுவோர் சாதகர் ஆமே`,
    transliteration: `ūṟṟiṭum aimmalam pāca uṇarviṉai
paṟṟaṟu nātaṉ aṭiyil paṇitalāl
cuṟṟiya pētam turiyam mūṉ ṟālvāṭṭit
taṟparam mēvuvōr cātakar āmē`,
    english: `2059: True Disciples Adore Holy Guru
By Pasa's sensations, the Five Malas arise;
Adoring feet of Guru in love intense,
Purified in Turiya Awareness Three
They the Supreme State attain;
They alone are Sadhakas true.`,
    elaborationTamil: `பக்குவம் இன்மையால் உயிர் பாச ஞானத்தையே உண்மை ஞானமாகக் கருதி நிற்றலால் அனாதியே அதனைப் பற்றிய ஐம்மலங்களும் அதனை விட்டு நீங்காது அதனைப் பற்றியே நிற்கும். பக்குவம் வந்தபொழுது பாச ஞானத்தை வெறுத்துப் பதியாகிய சிவனை நோக்கி நின்று அவனைப் பல முறையால் வணங்குதலால் முன் கூறிய ஐம்மலங்களும் அற்றொழியும். ஆகவே, தம்மைக் கட்டி யுள்ள பாசக் கூட்டத்தால் தாம் சிவனை விட்டு நீங்கியிருக்கும் நிலையை முத்துரிய நிலைகளால் முறையே போக்கிச் சிவனை அடைய முயல்பவரே சற்குருவின் அருள்வழி நிற்கும் சாதகர் ஆவார்.`,
  },
  {
    id: 2061, tantraId: 7, verseNumber: 2060,
    tamil: `எல்லாம் இறைவன் இறைவி யுடன்இன்பம்
வலலார் புலனும் வருங்கால் உயிர்தோன்றிச்
சொல்லா மலம்ஐந்து அடங்கிட்டு ஓங்கியே
செலலாச் சிவகதி சேர்தல்விளை யாட்டே`,
    transliteration: `ellām iṟaivaṉ iṟaivi yuṭaṉiṉpam
valalār pulaṉum varuṅkāl uyirtōṉṟic
collā malamaintu aṭaṅkiṭṭu ōṅkiyē
celalāc civakati cērtalviḷai yāṭṭē`,
    english: `2060: Jiva Subsiding in Silentness in Self Ascends to Siva-
State
Powerful are the senses,
From them arise pleasure sensations;
If Jiva, in silence, subsides in Self
And ascends high,
It shall reach Siva-State;
All, but play of Siva and Sakti.`,
    elaborationEnglish: `Powerful, indeed, are the senses from which arise pleasure sensations. If jiva subsides in silence in the Self, it conquers the senses and ascends high to reach the Siva state.`,
    elaborationTamil: `ஞானம் வரும்பொழுது ஆன்ம இயல்பு உள்ளவாறு விளங்கப்பெற்று, ஐந்து மலங்களும் சத்தியடங்கி நிற்க அவற்றைக் கடந்து மோனம் உடையராய் நிலைபெயராத வீட்டு நிலையை அடைதல் எளிதாகும். அந்நிலை சிவானந்தமே. ஞானியர் எல்லாரும் அதனைப் பெறவல்லவராவர்.`,
  },
  {
    id: 2062, tantraId: 7, verseNumber: 2061,
    tamil: `ஈனப் பிறவியில் இட்டது மீட்டுட்டித்
தானத்துள் இட்டுத் தனையூட்டித் தாழ்த்தலும்
ஞானத்தின் மீட்டலும் நாட்டலும் வீடுற்று
மோனத்துள் வைத்தலும் முத்தன்தன் செய்கையே`,
    transliteration: `īṉap piṟaviyil iṭṭatu mīṭṭuṭṭit
tāṉattuḷ iṭṭut taṉaiyūṭṭit tāḻttalum
ñāṉattiṉ mīṭṭalum nāṭṭalum vīṭuṟṟu
mōṉattuḷ vaittalum muttaṉtaṉ ceykaiyē`,
    english: `2061: From Jiva's Birth to its Final Emancipation--It is All Lord's
Consigning Jiva to birth's sorrows,
Rescuing it by ministrations gentle,
Assigning it positions appropriate,
Baptising it in Jnana,
Redeeming it,
And in Mukti establishing it,
And in the end,
Placing it in Mystic
Silentness (Mauna)
--All these are but
Lord's work.`,
    elaborationTamil: `இழிவான பிறப்பு நிலையில் அதன் இழிவு தோன் றாதவாறு மறைத்து மீள மீள அதிலே நின்ற கருவிக் கூட்டத்தின் இயல்பை உணர்த்தி, அதனின்றும் பிரித்து உயிர் தனது இயல்பினைத் தான் உணருமாறு செய்து அவ்வுணர்விலே சிறிது காலம் நின்று தாமதிக்கச் செய்தலும், பின்பு இறைவன் இயல்பை உணர்த்தி உயிருணர்வினின்றும் பிரித்து இறை உணர்விலே நிலைத்திருக்கச் செய்தலும், பின் இறையின்பத்திலே தோய்ந்து பேச்சற்றிருக்கச் செய்தலும் ஆய இவையெல்லாம் முத்தான்மாவாய் நின்ற சற்குருவின் செய்கைகளாய் விளங்கும்.`,
  },
  {
    id: 2063, tantraId: 7, verseNumber: 2062,
    tamil: `அத்தன் அருளின் விளையாட் டிடம்சடம்
சித்தொடு அசித்துஅறத் தெளிவித்த சீவனைச்
சுத்தனும் ஆக்கித் துடைத்து மலத்தினைச்
சத்துடன் ஐங்கரு மத்திடும் தன்மையே`,
    transliteration: `attaṉ aruḷiṉ viḷaiyāṭ ṭiṭamcaṭam
cittoṭu acittuaṟat teḷivitta cīvaṉaic
cuttaṉum ākkit tuṭaittu malattiṉaic
cattuṭaṉ aiṅkaru mattiṭum taṉmaiyē`,
    english: `2062: Lord's Play in the Arena of Jiva's Body
The fleshly body is arena of Lord's Play,
He imparts to Jiva,
Knowledge clear of Chit and Achit,
Purifies him,
Wipes off the Malas
And consigns him to the Sat (Real),
Unto Himself the Five Acts to perform;
--These the Play of Lord's Grace.`,
    elaborationTamil: `சிவன் தனது கருணை காரணமாகச் செய்யும் முத் தொழில்களாகிய விளையாட்டு நிகழும் இடம் சடமாய மாயை யினிடத்திலாம். ஆயினும் அவ்விளையாட்டிற்குப் பயன் அறிவுடைப் பொருளாகிய உயிரை, 'சித்து இவை, அசித்து இவை' என்பதை அறியச் செய்து மும்மலங்களைத் துடைத்துத் தூய்மையுறப் பண்ணி வேறு இரு தொழில்களால் மெய்ப்பொருளை அடையச் செய்தலேயாகும்.`,
  },
  {
    id: 2064, tantraId: 7, verseNumber: 2063,
    tamil: `ஈசத்து வங்கடந்து இல்லையென்று அப்புறம்
பாசத்து ளேயென்றும் பாவியும் அண்ணலை
நேசத்து ளேநின்ற நின்மலன் எம்மிறை
தேசத்தை எல்லாம் தெளியவைத் தானே`,
    transliteration: `īcattu vaṅkaṭantu illaiyeṉṟu appuṟam
pācattu ḷēyeṉṟum pāviyum aṇṇalai
nēcattu ḷēniṉṟa niṉmalaṉ emmiṟai
tēcattai ellām teḷiyavait tāṉē`,
    english: `2063: Love for Lord Takes You to Siva State
Beyond the state of Isatva (Siva State)
Nothing there is;
Realizing this,
Continue ever, in love intense, for Lord;
My Lord is the Pure One
Who in love abides;
He it is,
Who illumined directions all.`,
    elaborationTamil: `உலகீர், எங்கள் சிவபெருமான் 'தனக்கு வேறாய் விலகி நிற்கும் பொருள் எதுவும் இல்லை' என்று அறிந்து தன்பால் செலுத் தப்படும் அன்பிலே விளங்கி நிற்பவன். அத்தகைய அன்பர்க்கு அவன் அனைத்துப் பொருளின் உண்மைகளையும் தெளிவாக உணரக் காட்டி னான். ஆதலால் நீங்கள் 'அவனது வியாபகத்தைக் கடந்து அவனின் வேறாக யாதொரு பொருளும் இல்லை' என உணர்ந்து உடம்பில் உள்ள பொழுதும் அவனை எவ்வகையிலேனும் உணர்ந்து போற்றுங்கள்.`,
  },
  {
    id: 2065, tantraId: 7, verseNumber: 2064,
    tamil: `மாணிக்க மாலை மலர்ந்தெழு மண்டலம்
ஆணிப்பொன் நின்றங்கு அமுதம் விளைந்தது
பேணிக்கொண்டு உண்டார் பிறப்பற்று இருந்த
ஊனுக்கு இருந்தார் உணராத மாக்களே`,
    transliteration: `māṇikka mālai malarnteḻu maṇṭalam
āṇippoṉ niṉṟaṅku amutam viḷaintatu
pēṇikkoṇṭu uṇṭār piṟappaṟṟu irunta
ūṉukku iruntār uṇarāta mākkaḷē`,
    english: `2064: Divine State Ends Birth's Cycle
In the sphere (of cranium)
Where the garland of scarlet rubies glows,
He the unalloyed Gold,
There stood;
The divine nectar welled up there;
They who swilled it,
Ended their birth's cycle;
They who did not
Remained but to gormandize.`,
    elaborationTamil: `மாணிக்க மணிகளைக் கோத்த ஒரு வடத்தைத் தூங்கவிட்டது போல உடம்பினுள்ளே ஒன்றின்மேல் ஒன்றாய் அமைந்து ஒளிவிட்டு விளங்கும் ஏழு மண்டலங்கள் உள்ளன, அங் கெல்லாம் அவற்றுக்கு மேல் உள்ள மாற்றுயர்ந்த பொன் போல்வ தொரு நற்பொருளினின்றும் ஓர் அமுதம் ஊற்றெடுத்துப் பாய்கின்றது. அதனையறிந்து போற்றிக்கொண்டு உண்டவர்களே பிறப்பற்றிருக் கின்றார்கள். அதனை அறியாதவரெல்லாம் விலங்கொடொத்து உணவை உண்டு வயிறு வளர்ப்பதற்காகவே வாழ்கின்றனா.`,
  },
  {
    id: 2066, tantraId: 7, verseNumber: 2065,
    tamil: `அசத்தொடு சத்தும் அசத்சத்து நீங்க
இசைத்திடு பாசப்பற்று ஈங்குஅறு மாறே
அசைத்துஇரு மாயை அனுத்தானும் ஆங்கே
இசைத்தானும் ஒன்றறி விப்போன் இறையே`,
    transliteration: `acattoṭu cattum acatcattu nīṅka
icaittiṭu pācappaṟṟu īṅkuaṟu māṟē
acaittuiru māyai aṉuttāṉum āṅkē
icaittāṉum oṉṟaṟi vippōṉ iṟaiyē`,
    english: `2065: Lord Attaches Mayas to Jiva for Attainment of True
The Sat, Asat, and the
Sat-Asat to free,
The Pasa's bonds here to sunder,
He activated Mayas
Two'Suddha and Asuddha'
And to Jiva, He them attached,
And imparted the peerless Light of Knowledge, too,
He, the Lord.`,
    elaborationTamil: `சத்தோடு கூடியவழிச் சத்தாம் தன்மையும், அசத்தோடு கூடியவழி அசத்தாம் தன்மையும் உடைத்தாதல் பற்றி, 'சதசத்து' எனப் பெயர் பெற்ற உயிரை அநாதியில் சத்தோடு சேராது நீங்கச் செய்து, அசத்தோடு சேர்த்த ஆணவ மலத்தொடர்பு இப்பெத்த காலத்தில் அற்றொழிதற் பொருட்டு, 'சுத்த மாயை, அசுத்த மாயை' என்னும் இருமாயைகளைச் செயற்படுத்தி, உயிரையும் அச்செயற் பாட்டிற்கு உள்ளாக்கியவனும், பின் என்றும் திரிபின்றி ஒருபடித்தாய் நிற்பதாகிய உண்மையை உணர்த்தி, அவ்வுயிரை உய்யக் கொள்கின்ற வனும் இறைவனேயன்றிப் பிறர் இல்லை.`,
  },
  {
    id: 2067, tantraId: 7, verseNumber: 2066,
    tamil: `ஏறு நெறியே மலத்தை எரித்தலால்
ஈறில் உரையால் இருளை அறுத்தலான்
மாறில் பசுபாசம் வாட்டலால் வீடுக
கூறு பரனே குருவாம் இயம்பிலே`,
    transliteration: `ēṟu neṟiyē malattai erittalāl
īṟil uraiyāl iruḷai aṟuttalāṉ
māṟil pacupācam vāṭṭalāl vīṭuka
kūṟu paraṉē kuruvām iyampilē`,
    english: `2066: Siva is the Supreme Guru
The way of Adhara ascending scorches Malas,
The endless chanting of His name dispells Darkness (of Ignorance)
Harass the Pasa, Jiva a heir to,
Thus do you liberation seek;
The Lord, forsooth, is the Guru Supreme.`,
    elaborationTamil: `சத்திநிபாதம் படிமுறையால் நாளும் நாளும் மிகுந்து வரும் வகையால் ஆணவத்தைச் சிறிது சிறிதாக முறையே நீக்கி வருதலாலும், முடிவில் என்றும் நீங்காது நிலைத்து நிற்கும் உப தேச மொழியால் அவ்வாணவங் காரணமாக இருந்து வந்த அறியாமையைப் போக்கி அறிவைத் தருதலாலும், பின்னும் பண்டை வாசனையால் பாச உணர்வு தோன்றுமாயின் அதனைத் தோன்றும் பொழுதே பசையின்றி உலர்ந்து கெடும்படி வாட்டி விடுதலாலும், ஆராய்ந்து சொல்லுமிடத்து எல்லா முதன்மையும் உடையவனாக உண்மை நூல்களில் கூறப்படுகின்ற இறைவனே உயிர்கட்கு வீடுபேறு கிடைக்கும்படி குருவாய் வருபவனாவான்.`,
  },
  {
    id: 2068, tantraId: 7, verseNumber: 2067,
    tamil: `கண்காணி இல்லென்று கள்ளம் பலசெய்வார்
கண்காணி இல்லா இடமில்லை காணுங்கால்
கண்காணி யாகக் கலந்தெங்கும் நின்றானைக்
கண்காணி கண்டார் களஒழிந் தாரே`,
    transliteration: `kaṇkāṇi illeṉṟu kaḷḷam palaceyvār
kaṇkāṇi illā iṭamillai kāṇuṅkāl
kaṇkāṇi yākak kalanteṅkum niṉṟāṉaik
kaṇkāṇi kaṇṭār kaḷaoḻin tārē`,
    english: `2067: God is Omniscient
Thinking there is none that oversees
They many evil deeds perform;
None the place, in fact,
Where the over-seer is not;
The Lord pervades all, overseeing all;
They who the Over-seer saw,
Abandoned evil deeds all.`,
    elaborationTamil: `அறிவில்லாதவர் 'தங்களை உடன் இருந்து காவல் புரிபவன் எவனும் இல்லை' என்று தவறாகக் கருதிக் கொண்டு தவறான செயல்கள் பலவற்றைச் செய்கின்றனர். உண்மையை உணர்ந்தால் யாவரையும் உடன் இருந்து காவல் புரிகின்ற ஒருவன் எங்கும் இருக்கின்றான். அவன் இல்லாத இடம் இல்லை. (எனவே தவறு செய்பவர் அவனால் ஒறுக்கப்படுதல் திண்ணம்) எவ்விடத்திலும் நிறைந்து காவல் புரிகின்ற அவனை அங்ஙனம் காவல் புரிபவனாக அறிந்தோர் யாவரும் தவற்றை ஒரு ஞான்றும் செய்யாது ஒழிந்திருக்கின்றனர்.`,
  },
  {
    id: 2069, tantraId: 7, verseNumber: 2068,
    tamil: `செய்தான் அறியும் செழுங்கடல் வட்டத்துப்
பொய்தான் மிகவும் புலம்பும் மனிதர்கள்
மெய்தான் உரைக்கில்விண் ணோர் தொழச் செய்வான்
மைதாழ்ந்து இலங்கும் மிடறுடை யோனே`,
    transliteration: `ceytāṉ aṟiyum ceḻuṅkaṭal vaṭṭattup
poytāṉ mikavum pulampum maṉitarkaḷ
meytāṉ uraikkilviṇ ṇōr toḻac ceyvāṉ
maitāḻntu ilaṅkum miṭaṟuṭai yōṉē`,
    english: `2068: Speak Truth
He who this sea-girt world created
He knows all;
Men falsehoods many utter,
Let them the Truth speak;
He will make Celestials revere them
--He, that is of the lustrous dark throat.`,
    elaborationTamil: `'செழுங்கடல் வட்டத்து நிகழ்வனவற்றை அவற்றைச் செய்தான் அறியும்' எனக் கூட்டுக. ஏனைய வெளிப்படை.`,
  },
  {
    id: 2070, tantraId: 7, verseNumber: 2069,
    tamil: `பத்துவிற் றுண்டு பகலைக் கழிவிடும்
மத்தகர்க்கு அன்றோ மறுபிறப்பு உள்ளது
வித்துக்குற் றுண்டு விளைபுலம் பாழ்செய்யும்
பித்தர்கட்கு என்றும் பிறப்பில்லை தானே`,
    transliteration: `pattuviṟ ṟuṇṭu pakalaik kaḻiviṭum
mattakarkku aṉṟō maṟupiṟappu uḷḷatu
vittukkuṟ ṟuṇṭu viḷaipulam pāḻceyyum
pittarkaṭku eṉṟum piṟappillai tāṉē`,
    english: `2069: Conserve Bindu
They sell the Love of
God,
They make a daily business of it;
Pride-filled are they,
They in birth's whirl will be;
They who pound the Seed
(Bindu) and consume
Lay waste the body-land;
But, verily, for the
God-mad,
Forever no birth will be.`,
    elaborationTamil: `சற்குரு அருளால் ஞானம் பெற்றவர்கட்கும் மறு பிறப்பு உண்டு' எனக் கூறுதல் அதன் பின்பும் பத்திச் செய்கைகளைத் தமக்கு விருப்பமின்றி உலகத்தார் பாராட்டுதற் பொருட்டே செய்து அதனால் புகழும் பொருளும் பெற்றுக் காலத்தைக் கழிக்கின்ற அந்தப் பித்தர்களுக்கேயாம். அவ்வாறின்றிப் புகழ் பொருள் முதலியவற்றுள் ஒன்றையும் விரும்பாது பத்திச் செய்கைகளைத் தமது அன்பானே செய்து ஒழுகுமாற்றால் மறுபிறப்பாகிய பயிருக்கு வித்தாய் அமைகின்ற ஆகாமிய வினையை வித்தைக் குற்றியுண்பார்போல வலுத்து நில்லாதபடி அழித்து, மறுபிறப்பாகிய பயிர் விளைக்கின்ற நெறியைப் பாழாய்க் கிடக்கும்படி செய்கின்ற அந்தப் பித்தர்களுக்கு ஒருஞானறும் மறுபிறப்பு உண்டாதல் இல்லை.`,
  },
  {
    id: 2071, tantraId: 7, verseNumber: 2070,
    tamil: `வடக்கு வடக்கென்பர் வைத்ததுஒன்று இல்லை
நடக்க உறுவரே ஞானமி ல்லாதார்
வடக்கில் அடங்கிய வையகம் எல்லாம்
அகத்தில் அடங்கும் அறிவுடை யோர்க்கே`,
    transliteration: `vaṭakku vaṭakkeṉpar vaittatuoṉṟu illai
naṭakka uṟuvarē ñāṉami llātār
vaṭakkil aṭaṅkiya vaiyakam ellām
akattil aṭaṅkum aṟivuṭai yōrkkē`,
    english: `2070: Acquire True Jnana
"North, North" they say;
Nothing there in the north is;
Northward they walk,
Of Jnana bereft;
All the world in the north,
Is in their heart contained,
For those that knowledge truly possess.`,
    elaborationTamil: `குருவருளைப் பெற்றபின்னும் இறைவனை எவ்விடத்தும் ஒருபெற்றியாகவே உணர்ந்து அவனது திருவருளில் மூழ்கி நிற்றலாகிய ஞானத்தில் ஞானமாம் அசைவிலா நிட்டை நிலையை எய்த மாட்டாதவரே அவனைக் காலம், இடம் முதலிய, சிறப்புக்கள் காரணமாக ஏகதேசமாக உணர்ந்து அவ்வாற்றான் வழிபடும் வழிபாடுகளை நிறைவேற்ற முயல்வர். மேற்கூறிய அந்த நிட்டை நிலையை எய்தினார்க்கு எவ்விடத்தும், எக்காலத்தும் இறை யருட் சிறப்பு அவரது ஞானத்தினுள்ளே இனிது விளங்கியே நிற்கும்.`,
  },
  {
    id: 2072, tantraId: 7, verseNumber: 2071,
    tamil: `காயக் குழப்பனைக் காயநன் னாடனைக்
காயத்தி னுள்ளே கமழ்கின்ற நந்தியைத்
தேயத்து ளேஎங்கும் தேடித் திரிவர்கள்
காயத்துள் நின்ற கருத்தறி யாரே`,
    transliteration: `kāyak kuḻappaṉaik kāyanaṉ ṉāṭaṉaik
kāyatti ṉuḷḷē kamaḻkiṉṟa nantiyait
tēyattu ḷēeṅkum tēṭit tirivarkaḷ
kāyattuḷ niṉṟa karuttaṟi yārē`,
    english: `2071: Look Inward
He who made this body-mix,
He who this body land holds,
He who within this body shines,
He is Nandi;
Him they seek and search in lands all;
They know not
He within the body stands.`,
    elaborationTamil: `காயக் குழப்பன் - உயிர்களின் உடம்புகளை அவற்றின் வினைக்கேற்ப உழல் விப்பவன். காயநன்னாடன் - உயிர்க்கு உயிராய் நிற்றலால் உயிர்களின் உடம்புகளைத் தனது இடமாக உடையவன். காயத்தினுள்ளே கமழ்தல் - ''உற்ற ஆக்கையின் உறுபொருளாய் நறுமலர் எழுதரு நாற்றம்போல்'' (தி.8 அதிசயப்பத்து, 9) உள்நோக்கி உணர்வார்க்கு நுண்ணிய இனிய பொருளாய் வெளிப்படுபவன். ஏனைய வெளிப்படை.`,
  },
  {
    id: 2073, tantraId: 7, verseNumber: 2072,
    tamil: `கண்காணி யாகவே கையகத் தேயெழும்
கண்காணி யாகக் கருத்துள் இருந்திடும்
கண்காணி யாகக் கலந்து வழிசெய்யும்
கண்காணி யாகிய காதலன் தானே`,
    transliteration: `kaṇkāṇi yākavē kaiyakat tēyeḻum
kaṇkāṇi yākak karuttuḷ iruntiṭum
kaṇkāṇi yākak kalantu vaḻiceyyum
kaṇkāṇi yākiya kātalaṉ tāṉē`,
    english: `2072: Lord Oversees From Within You
Visible to your eyes,
He rises in your very palm;
Over-seeing All,
He in your thoughts stands;
As light within the eyes,
He guides your way;
He is Love Embodied,
That Oversees you ever.`,
    elaborationTamil: `உயிர்களின் கண்ணைத் தன் இடமாகக் கொண்டு அவற்றிற்கு அக்கண்போலச் சிறந்து நிற்கின்ற இறைவன் ஞானிகட்கு அவர்தம் புறக் கண்ணிற்குப் புலனாகின்றவனாகியும் இனிது விளங்கு வான்.அகக்கண்ணிற்குப் புலனாகின்றவனாகியும் இனிது விளங்கு வான். ஆகையால் அவர்களது செயல்திறங்களை இடைவிடாது நோக்கி அவற்றிற்கு ஏற்ற பயனை அருளுதல் அவனுக்கு இயல்பாகும்.`,
  },
  {
    id: 2074, tantraId: 7, verseNumber: 2073,
    tamil: `கன்னி ஒருசிறை கற்றோர் ஒருசிறை
மன்னிய மாதவம் செய்வோர் ஒருசிறை
தன்னியல்பு உன்னி உணர்ந்தோர் ஒருசிறை
என்னிது ஈசன் இயல்புஅறி யாரே`,
    transliteration: `kaṉṉi oruciṟai kaṟṟōr oruciṟai
maṉṉiya mātavam ceyvōr oruciṟai
taṉṉiyalpu uṉṉi uṇarntōr oruciṟai
eṉṉitu īcaṉ iyalpuaṟi yārē`,
    english: `2073: How the Lord is Seated
The Virgin Sakti on one side
The learned ones on one side,
The Tapasvins steadfast on one side,
The Self-Realized beings on one side,
Thus is the Lord seated;
How is it they know not
His nature true!`,
    elaborationTamil: `திருவருட்சத்தி பதிவு எல்லோர்க்குமன்றி ஒரு சிலர்க்கே உண்டாவதால் உண்மை நூல்களை ஓதுதலை சிலர் செய்தும், மற்றும் சிலர் சிவனைக் கிரியா முறையில் வழிபடுதலைச் செய்தும், மற்றும் சிலர் யோகம் புரிதலைச் செய்தும் மற்றும் சிலர் சிவனது உண்மை நிலையைக் கேட்டல் சிந்தித்தல் தெளிதல்களால் உணர் தலைச் செய்தும் நிற்கின்றனர். ஆகவே, மிகப்பலர் இவற்றுள் ஒன்ற னையும் செய்யாது சிவவேடத்தை மட்டும் புனைந்து கொண்டு திரி கின்றனர். இஃது என்ன முறைமை!`,
  },
  {
    id: 2075, tantraId: 7, verseNumber: 2074,
    tamil: `காணாத கண்ணில் படலமே கண்ணொளி
காணாத வர்கட்கும் காணாதது அவ்வொளி
காணாத வர்கட்கும் கண்ணாம் பெருங்கண்ணைக்
காணாது கண்டார் களவொழிந் தாரே`,
    transliteration: `kāṇāta kaṇṇil paṭalamē kaṇṇoḷi
kāṇāta varkaṭkum kāṇātatu avvoḷi
kāṇāta varkaṭkum kaṇṇām peruṅkaṇṇaik
kāṇātu kaṇṭār kaḷavoḻin tārē`,
    english: `2074: Lord is the Light of Our Eyes
The eye that sees not
Is by cataract (ignorance) covered;
The Lord is the Light Unseen,
Even for those
Whose eye no sight has;
He is the Eye Divine,
Even for those
Who have seen Him not;
They who have seen Him
In the inward eye
Have verily the Truth seen
All illusion rid.`,
    elaborationTamil: `முகக்கண்கள் புறப்பொருளைக் காணுதல் இயல் பாயினும் சில கண்கள் அப்பொருள்களைக் காணமாட்டாதன ஆதற்குக் காரணம் அக்கண்ணில் ஒளிக்கு மாறாகப் படலம் இருப்பதே யாகும். இனி முகக்கண் உடையார்க்கே யன்றி அக்கண் இல்லா தவர்க்கும் அகக்கண்ணாகிய அறிவுக்கு அறிவாய் உள்ள பேரறிவாம் சிவ ஒளியைத் தற்போத வழியாற் காணாது அருள் வழியாகக் கண்டவரே கள்ளத்தனமாகச் செய்யும் செயல்களைச் செய்யாது ஒழிவர். அந்தச் சிவ ஒளி அகக்கண்ணாகிய ஞானக் கண் இல்லா தவர்க்குக் காணப்படாத ஒன்றேயாய் இருக்கும்.`,
  },
  {
    id: 2076, tantraId: 7, verseNumber: 2075,
    tamil: `பித்தன் மருந்தால் தெளிந்து பிரகிருதி
உய்த்தொன்று மாபோல் விழியும் தன் கண்ணொளி
அத்தன்மை யாதல்போல் நந்தி அருள்தரச்
சித்தம் தெளிந்தோன் செயல் ஒழிந்தேனே`,
    transliteration: `pittaṉ maruntāl teḷintu pirakiruti
uyttoṉṟu māpōl viḻiyum taṉ kaṇṇoḷi
attaṉmai yātalpōl nanti aruḷtarac
cittam teḷintōṉ ceyal oḻintēṉē`,
    english: `2075: By His Grace Our Thoughts Become Serene
Even as
The lunatic by medicine administered
Lucid becomes,
And his true self realizes;
Even as,
The eye its sight regains,
So, too,
Nandi bestowing His Grace on me
Serene my thoughts became,
To actionless state heightened.`,
    elaborationTamil: `பித்துக் கொண்டவன் அதற்காக மருத்துவன் தரும் மருந்தால் பித்து நீங்கித் தெளிவுற்று உடம்பை முன்போலத் தறிகெட்ட நிலையில் செலுத்திக் கெடுக்காமல் இயற்கை நிலையில் செலுத்தி ஏனையோர் குழாத்தில் தானும் ஒருவனாய் ஒன்றுபடுதலைப் போலவும், படலத்தால் மறைக்கப்பட்ட கண்ணும் அவ்வாறே மருத்துவன் செய்யும் சிகிச்சையால் படலம் நீங்கித் தனது ஒளி கிடைக்கப் பெறும் அத்தன்மையைப் போலவும் அஞ்ஞானத்தால் அறிவு மயங்கி, 'யான், எனது' எனச் செருக்கித் திரிந்த யான் எம் ஆசிரியாராகிய நந்திபெருமான் ஞானத்தை அருளியதனால் அறிவு தெளிந்து செருக்கொழிந்து அருள் வழியில் ஒழுகி ஏனைய அருளாளரது குழாத்தில் சேர்ந்து அவர்களில் ஒருவன் ஆயினேன்.`,
  },
  {
    id: 2077, tantraId: 7, verseNumber: 2076,
    tamil: `பிரான்பல மாகப் பெயர்ந்தன எட்டும்
பராமயம் என்றெண்ணிப் பள்ளி யுணரார்
சுராமயம் முன்னிய சூழ்வினை யாளர்
நிராமய மாக நினைப் பொழிந் தாரே`,
    transliteration: `pirāṉpala mākap peyarntaṉa eṭṭum
parāmayam eṉṟeṇṇip paḷḷi yuṇarār
curāmayam muṉṉiya cūḻviṉai yāḷar
nirāmaya māka niṉaip poḻin tārē`,
    english: `2076: Unholy Men Do Not Think of Attaining Divinity
The directions eight moved,
The Lord pervading them all;
Of this, His
Omnipresence, they think not;
From their stupor they wake not;
Drunk are they in their
Karmas inebriate;
Lo! All thoughts of
Divinity-Becoming
They, forever,
abandoned.`,
    elaborationTamil: `கள்ளை மிக உண்டலால் உடல் அக்கள்மயமே யாய் இருத்தலை விரும்பும் வஞ்சமனத்தவர் ஞானிகட்குச் சிவமயமாகத் திகழ்கின்ற உலகப் பகுதி எட்டினையும் அருள்மயமாக எண்ணி அடங்குதலாகிய ஞானவிழிப்பைக் கொள்ளாது அஞ் ஞானத்தில் உறங்குவோராய்த் தாம் குற்றம் சிறிதும் இல்லாத தூயராய் இருத்தல் வேண்டும் என்பதைச் சிறிதும் நினையாதே கெடுகின்றனர்.`,
  },
  {
    id: 2078, tantraId: 7, verseNumber: 2077,
    tamil: `ஒன்றுஇரண் டாகிநின்று ஒன்றிஒன் றாயினோர்க்கு
ஒன்றும் இரண்டும் ஒருகாலும் கூடிடா
ஒன்றுஇரண்டு என்றே உரைதரு வோர்க்கெலாம்
ஒன்றுஇரண் டாய் நிற்கும் ஒன்றோடுஒன் றானதே`,
    transliteration: `oṉṟuiraṇ ṭākiniṉṟu oṉṟioṉ ṟāyiṉōrkku
oṉṟum iraṇṭum orukālum kūṭiṭā
oṉṟuiraṇṭu eṉṟē uraitaru vōrkkelām
oṉṟuiraṇ ṭāy niṟkum oṉṟōṭuoṉ ṟāṉatē`,
    english: `2077: They Think of I and You as Two
The two, I and You, in union one stood,
Undifferentiated as One Becoming;
For them is there no more Two, I and You;
They who speak of I and You as two
To them He is I and You, forever two;
He, the Being, One and One above.`,
    elaborationTamil: `'பலவாய் உள்ள உயிர் ஒன்றாய் உள்ள சிவத்தோடு இரண்டறக் கலத்தலே முடிநிலைப் பயன்' என்பது எல்லோர்க்கும் உடன்பாடு. ஆயினும், ஒரு பொருளாய் உள்ள பிரமமே அவிச்சை யால் பலவாய் உள்ள உயிர்களாக மயங்கி அறியப்பட்டு, அவிச்சை நீங்கியவுடன் உயிர் முன்போல ஒரு பொருளாகிய பிரமத்தோடு ஒன்றாய்விடும் எனக் கூறுகின்றவர்கள் அவிச்சைக்குக் காரணம் கூறாமையால் உயிர் பிரமமேயான நிலைநிலைத்தல் இன்றிப் பிரமமும் உயிரும் வேறு வேறாய் நிற்கும் அவிச்சை நிலையே நிலைபெறுவ தாகும். ஆகவே அவர்கட்கு இரண்டும் ஒன்றாகும் நிலை என்றும் கிட்டுவதின்றாம் இனி 'ஒன்றாகிய பரமனும், பலவாகிய உயிர்களும் என்றும் வேறு வேறாக இருத்தல் அன்றி, ஒன்றாதல் இல்லை' எனக் கூறுவார்க்கு அவ்வாறு நிற்றலே பயனாவதன்றி, முதற்கண் கூறிய முடிநிலைப் பயன்கிட்டாதாம்.`,
  },
  {
    id: 2079, tantraId: 7, verseNumber: 2078,
    tamil: `உயிரது நின்றால் உணர்வுஎங்கு நிற்கும்
அயர்அறி வில்லையால் ஆருடல் வீழும்
உயிரும் உணலும் ஒருங்கிக் கிடக்கும்
பயிரும் கிடந்துள்ளப் பாங்கு அறி யாரே`,
    transliteration: `uyiratu niṉṟāl uṇarvueṅku niṟkum
ayaraṟi villaiyāl āruṭal vīḻum
uyirum uṇalum oruṅkik kiṭakkum
payirum kiṭantuḷḷap pāṅku aṟi yārē`,
    english: `2078: They Do Not Know the Inter-Relation of Body and Life
When life ebbs away,
Where the sensations are?
Sentience lost,
The body drops;
Life and body as one flourish
That state, they know not.`,
    elaborationTamil: `உயிர் உடம்பில் இருப்பதனால்தான் அந்த உடம்பு முழுதிலும் அறியுந்தன்மை காணப்படுகின்றது. (அத் தன்மையால் உடல் வீழ்ந்தொழியாது வாழ்ந்து செயற்படுகின்றது) உயிர் உடலை விட்டு நீங்கினால் உடலைச் செயற்படுத்துகின்ற அந்த அறிவு இல்லையாய்விடும். அறிவு இல்லையானால், வேறு எல்லா அமைப்புக்களும் நிறைந்துள்ள உடம்பு அவ்வமைப்பால் பயனின்றி வீழ்ந்து அழியும். ஆகவே 'உயிர்' எனப்படுவது உடம்பிற்கு வேறாதல் தெளிவாகலின் அத்தகைய உயிரும் உடம்பும் ஒன்றி நிற்கும் பயப்பாடு வெள்ளிடை மலைபோல் விளங்கிக் கிடக்கவும் சிலர் உடம்பையே தாமாக மயங்கிக் கூடா ஒழுக்கத்தினை மேற்கொள்கின்றனர்.`,
  },
  {
    id: 2080, tantraId: 7, verseNumber: 2079,
    tamil: `உயிரது வேறாய் உணர்வுஎங்கும் ஆகும்
உயிரை அறியில் உணர்வுஅறி வாகும்
உயிர்அன்று உடலை விழுங்கும் உணர்வை
அயரும் பெரும்பொருள் ஆங்கறி யாரே`,
    transliteration: `uyiratu vēṟāy uṇarvueṅkum ākum
uyirai aṟiyil uṇarvuaṟi vākum
uyiraṉṟu uṭalai viḻuṅkum uṇarvai
ayarum perumporuḷ āṅkaṟi yārē`,
    english: `2079: Lord is in Awareness, not in Prana
Prana is from pervasive Awareness apart;
When you know what Prana is,
You shall know what Awareness is,
Awareness is Knowledge, (not Prana),
That pervades the body;
He within that Awareness
Is the Lord Great;
That they know not.`,
    elaborationTamil: `உயிர் உடம்பு போல அன்றி அதனின் வேறாய் இருத்தலால்தான் அந்த உடம்பு முழுதும் அறிவுத் தன்மை காணப் படுகின்றது. இதனை ஆய்ந்தறியும் அறிவே மெய்யறிவாகும். உயிர் தான் உடம்போடு சேர்ந்த அன்று முதலாக உடம்பு முழுவதையும் தனது அறிவால் அகப்படுத்தி ஆண்டு வருகின்ற அந்தச் செயலை அவ் வுயிர்க்கு உயிராய் நின்று செய்து வருகின்ற ஒரு பெரும் பொருளை அறிபவர் உலகத்தில் ஒரு சிலரே.`,
  },
  {
    id: 2081, tantraId: 7, verseNumber: 2080,
    tamil: `உலகாணி ஒண்சுடர் உத்தம சித்தன்
நிலவாணி ஐந்தினுள் தேருற நிற்கும்
சிலவாணி யாகிய தேவர் பிரானைத்
தலைவாணி செய்வது தன்னை அறிவதே`,
    transliteration: `ulakāṇi oṇcuṭar uttama cittaṉ
nilavāṇi aintiṉuḷ tēruṟa niṟkum
cilavāṇi yākiya tēvar pirāṉait
talaivāṇi ceyvatu taṉṉai aṟivatē`,
    english: `2080: Realize the Self
He is the world's axle-pin;
The Light Resplendent;
The Siddha True;
He pervades the elements five,
The earth, sky and the rest;
He is the Lord of Devas
He with Sakti stands;
To praise Him in Words high
Is your Self to realize.`,
    elaborationTamil: `அனைத்துலகங்களின் தொகுதியாகிய தேரினை நிலைபெறச் செய்கின்ற அச்சாணியாய் உள்ளவன் ஒளியாய் உள்ள அனாதி முத்தனாகிய சிவனே. அவன் நிவிர்த்தி முதலிய ஆதார கலைகள் ஐந்திலும் நுண்ணியனாய் நிறைந்து நிற்கின்றான். அவ் வைந்து கலைகளுக்கு உட்பட்டுள்ள இடங்களில் சிற்சிலவற்றிற்குத் தலைவராய், 'தேவர்' எனப்பெயர் பெற்று விளங்கும் அனைவர்க்கும் தலைவனாய் உள்ள அந்தப் பெருமானையே ஒருவன் தன் தலைமேல் வைத்து ஒழுகுவானாயின், அவன் அவ்வாறு ஒழுகுதலே தனது இயல்பை உள்ளவாறு அறிந்துஒழுகும் ஒழுக்கமாகும்.`,
  },
  {
    id: 2082, tantraId: 7, verseNumber: 2081,
    tamil: `தான்அந்த மாம்என நின்ற தனிச்சுடர்
ஊன்அந்த மாய்உல காய்நின்ற ஒண்சுடர்
தேன்அந்த மாய்நின்று சிற்றின்பம் நீஒழி
கோன்அந்தம் இல்லாக் குணத்தரு ளாமே`,
    transliteration: `tāṉanta māmeṉa niṉṟa taṉiccuṭar
ūṉanta māyula kāyniṉṟa oṇcuṭar
tēṉanta māyniṉṟu ciṟṟiṉpam nīoḻi
kōṉantam illāk kuṇattaru ḷāmē`,
    english: `2081: Give Up Worldly Pleasures
He is the peerless Light
He is the end of all;
He is the resplendent Light;
He is the goal of fleshly body
And worlds all,
And the worldly pleasures
To you honey-sweet;
Give them up;
The Lord of limitless goodness
On you His Grace bestows.`,
    elaborationTamil: `மாணவகனே, நீ 'எல்லாவற்றையுங் கடந்துவிட்ட எனக்கு இனி அறம் பாவங்கள் எங்குள' எனச் செருக்கி, தேன் துளியால் வரும் இன்பம்போல மிகச்சிறியனவாய்ப் பெறப்படுகின்ற சிற்றின்பத்தைப் பெறும் செயலை அறவே ஒழி. அவ்வாறு ஒழித்தால்தான் சிவனது அளவில்லாத இன்பத்திற்கு ஏதுவாகிய அவனது அருள் முற்றக் கிடைக்கும்.`,
  },
  {
    id: 2083, tantraId: 7, verseNumber: 2082,
    tamil: `உன்முத லாகிய ஊன்உயிர் உண்டெனும்
கல்முதல் ஈசன் கருத்தறி வார்இல்லை
நல்முதல் ஏறிய நாமம் அறநின்றால்
தன்முதல் ஆகிய தத்துவம் ஆமே`,
    transliteration: `uṉmuta lākiya ūṉuyir uṇṭeṉum
kalmutal īcaṉ karuttaṟi vārillai
nalmutal ēṟiya nāmam aṟaniṉṟāl
taṉmutal ākiya tattuvam āmē`,
    english: `2082: Efface the Ego
He is your Beginning;
He is the life in your fleshly body;
He is the God in Mountain Kailas
None knows His design;
When the Primal One sways you,
And your ego entire effaced,
Then shall you reach the Lord,
Above Tattvas all.`,
    elaborationTamil: `''காட்சியால்'' உணரப்படும் உடம்பேயன்றிக் கருதலால் உணரப்படும் உயிரும் உடம்பினுள்ளே உண்டு என்னும் உண்மையையும், 'அவ்வுயிருக்குத் தலைவராகச் சொல்லப் படுவோர் பலருள்ளும் கயிலைக் கடவுளாகிய சிவனே முழுமுதல் தலைவன்' என்னும் உண்மையையும் அறிகின்றவர் உலகத்து அரியர். இனி அவ் வுண்மையை உணர்ந்தவர்களும் அவற்றை உணர்வதற்குமுன் கொண்டிருந்த ஆசை வழிப்பட்ட செயல்களை முற்றவிடுத்தால்தான், ஓர் உயிரும் எஞ்சாதபடி ஒவ்வொன்றிற்கும் முதலாய் உள்ள மெய்ப் பொருளின் விளக்கம் நிரம்ப உண்டாகும்.`,
  },
  {
    id: 2084, tantraId: 7, verseNumber: 2083,
    tamil: `இந்தியம் அந்தக் கரணம் இவைஉயிர்
வந்தன சூக்க உடலன்று மானது
தந்திடும் ஐவிதத் தால்தற் புருடனும்
முந்துளம் மன்னும் ஆறாறு முடிவிலே`,
    transliteration: `intiyam antak karaṇam ivaiuyir
vantaṉa cūkka uṭalaṉṟu māṉatu
tantiṭum aivitat tāltaṟ puruṭaṉum
muntuḷam maṉṉum āṟāṟu muṭivilē`,
    english: `2083: Unborn Being Above Tattvas
He is not Indriyas (external sense organs);
Nor the Antakaranas (internal sense organs);
Nor the the Subtle body that life carries;
Out of the mighty Maan
Arose the Maya Inscrutable,
And the Tattvas thirty and six;
Above them all, high at the apex stands
The Being uncreated, the Eternal and the Everlasting.`,
  },
  {
    id: 2085, tantraId: 7, verseNumber: 2084,
    tamil: `வித்துப் பொதிவார் விரைவிட்டு நாற்றுவார்
அற்றதம் வாணாள் அறிகிலாப் பாவிகள்
உற்ற வினைத்துயர் ஒன்றும் அறிகிலார்
முற்றொளி தீயின் முனிகின்ற வாறே`,
    transliteration: `vittup potivār viraiviṭṭu nāṟṟuvār
aṟṟatam vāṇāḷ aṟikilāp pāvikaḷ
uṟṟa viṉaittuyar oṉṟum aṟikilār
muṟṟoḷi tīyiṉ muṉikiṉṟa vāṟē`,
    english: `2084: Ungodly Ones do not Think of Soul's Liberation
They germinate the seed;
They plant the seedlings;
They think not of their own fleeting life;
Poor are they in spirit;
They know nothing of Karmaic sorrows;
They perish in the blazing fire,
Verily are they such.`,
    elaborationTamil: `மக்கள் தமக்கு வரையறுக்கப்பட்டு அமைந்த வாழ் நாள் இத்துணையது என்று அறியமாட்டாதவராய் அன்றாடம் உண்டு வாழ்வதேயன்றி, அடுத்துவரும் ஆண்டிற்கும் உணவின் பொருட்டான முயற்சிகளை ஓயாமற் செய்வதிலேயே மனம் அமைதியுற்று விடுகின்றனர். இஃது அவர் பிரார்த்த வினைவிளைவாகிய துன்ப நிலையே என்பதையும் அவர் சிறிதும் அறிவதில்லை. இந்தப் பொய்யான இன்பத்திலே அவர் வீழ்ந்து கெடுதல் ஓங்கி எரியும் விளக்கை இனிய உணவென்று கருதிச்சென்று அதில் வீழ்ந்து மடிகின்ற விட்டிற் பூச்சியின் செயலோடு ஒப்பதாகும். அந்தோ? இஃது அவர் ஓர் அறியாமை இருந்தவாறு!.`,
  },
  {
    id: 2086, tantraId: 7, verseNumber: 2085,
    tamil: `போது சடக்கெனப் போகின் றதுகண்டும்
வாதுசெய் தென்னோ மனிதர் பெறுவது
நீதியு ளேநின்று நின்மலன் தாள்பணிந்து
ஆதியை அன்பில் அறியகில் லார்களே`,
    transliteration: `pōtu caṭakkeṉap pōkiṉ ṟatukaṇṭum
vātucey teṉṉō maṉitar peṟuvatu
nītiyu ḷēniṉṟu niṉmalaṉ tāḷpaṇintu
ātiyai aṉpil aṟiyakil lārkaḷē`,
    english: `2085: What do they get, Who do not Adore Lord
Well do they see
Life in a trice fleets away;
Yet do they in contention stand;
What though these men get?
They stand not in ways righteous,
They adore not His Holy Feet
They know not the Primal One
In love endearing.`,
    elaborationTamil: `நாள்கள் மிக விரைவாக வந்து வந்து போவதை அறிந்திருந்தும் பலர் அந்நாள்களை வாது செய்வதிலே கழித்து விடு கின்றனர். ஒழுக்கத்தில் நில்லாமல் வாதுசெய்வதனால் அவர் என்ன பயனை அடையப் போகின்றனர்! ஒரு பயனும் இல்லை. ஒழுக்கத்தில் நின்றும், இறைவன் திருவடியை வணங்கியும் வருவராயின் நாளடைவில் இறையன்பு தோன்றி வளர அவனை அவர்நேரே அறிந்து இன்புறுவர். அதனை அவர் அறிகின்றாரில்லையே!`,
  },
  {
    id: 2087, tantraId: 7, verseNumber: 2086,
    tamil: `கடன்கொண்டு நெற்குத்துக் கையரை
உடம்பினை ஓம்பி உயிராத் திரிவார்
தடங்கொண்ட சாரல் தழல்முரு டேறி
இடங்கொண்டு உடலார் கிடக்கின்ற வாறே`,
    transliteration: `kaṭaṉkoṇṭu neṟkuttuk kaiyarai
uṭampiṉai ōmpi uyirāt tirivār
taṭaṅkoṇṭa cāral taḻalmuru ṭēṟi
iṭaṅkoṇṭu uṭalār kiṭakkiṉṟa vāṟē`,
    english: `2086: They Care Not for Soul's Well-Being
They borrow grain;
They pound it hard,
Feed the base (senses),
And nourish the body;
Thus they wander
Their lives to live;
But in the valley broad
A prey to raging flames
The body finally lies;
This they realize not.`,
    elaborationTamil: `நெல்லைக் கடனாகவேனும் வாங்கிக் குற்றி, குற்றிய அரிசியைக் கொண்டு ஒரு சாண் வயிற்றினுள் இருக்கும் சிறு கருவி களின் வேகத்தைத் தணிக்கும் முகத்தால் உடம்பைப் பாது காக்கின்றவர்களும் தங்களை 'உயிர்' என்று சொல்லிக்கொண்டு திரி கின்றார்கள். அவ்வாறு திரிகின்றவர் தம்மைப்போன்றோர் பலரது உடம்புகளும் முடிவில், மலைச்சாரலில் பற்றி எரிகின்ற தீப்போன்ற பெரிய தீயை உடைய முருட்டணையில் ஏறிப் பின் அதினின்றும் இறங் காமல் அதனையே இடமாகக்கொண்டு கிடந்து ஒழிந்துபோதலைப் பல முறை கண்டிருந்தும் அதனைச் சிறிதும் பொருட்படுத்துதல் இல்லை.`,
  },
  {
    id: 2088, tantraId: 7, verseNumber: 2087,
    tamil: `விரைந்தன்று நால்வர்க்கு மெய்ப்பதி சூழ்ந்து
புரந்தகல் லால்நிழல் புண்ணியன் சொன்ன
பரந்தன்னை ஓராப் பழிமொழி யாளர்
உரந்தன்மை யாக ஒருங்கிநின் றார்களே`,
    transliteration: `viraintaṉṟu nālvarkku meyppati cūḻntu
purantakal lālniḻal puṇṇiyaṉ coṉṉa
parantaṉṉai ōrāp paḻimoḻi yāḷar
urantaṉmai yāka oruṅkiniṉ ṟārkaḷē`,
    english: `2087: They Stand in Wait for the Burial Heap
In days of yore, the
Sages Four
Sought the Holy One in
Kailas;
There, under the wild banyan tree
The Supreme One His teachings imparted;
They are of evil speech
Who think not of Him;
Ready to march to the burial heap
They stand in wait.`,
    elaborationTamil: `தனக்கு உண்மையிடமாகிய திருக்கயிலையின் பாங்கர் நிலவுலகத்து மக்கள் பொருட்டாகத்தான் நிலைநிறுத்திய கல்லால மர நிழலின்கண் இருந்து சிவன் படைப்புக் காலத்திலே முனிவர் நால்வர்க்கு அவர் விரும்பிய உடனே அருளிச் செய்த முதல் மொழிகள் அம்முனிவரிடமிருந்து நல்லோரால் வழிவழியாகப் பெறப் பட்டு உலகில் வழங்கா நிற்கவும் அவற்றைக் கேளாது பழித்து ஒதுக்கத் தக்கனவாகச் சிற்றறிவுடையரால் சொல்லப்பட்டு வழங்கும் மொழிகளைக் கேட்டு நிற்போர் அக்கேள்வியின் பயனாகத் தமது வன்மையையே மெய்ம்மையாகத் துணிந்து இடர்ப்படுகின்றார்களே!. இஃதென்ன அறியாமை!.`,
  },
  {
    id: 2089, tantraId: 7, verseNumber: 2088,
    tamil: `நின்ற புகழும் நிறைதவத்து உண்மையும்
என்றுஎம் ஈசன் அடியவர்க் கேநல்கும்
அன்றி உலகம் அதுஇது தேவுஎன்று
குன்றுகை யாலே குறைப்பட்ட வாறே`,
    transliteration: `niṉṟa pukaḻum niṟaitavattu uṇmaiyum
eṉṟuem īcaṉ aṭiyavark kēnalkum
aṉṟi ulakam atuitu tēvueṉṟu
kuṉṟukai yālē kuṟaippaṭṭa vāṟē`,
    english: `2088: They Are Distracted by Doubts
Imperishable fame,
And truthful fruit of Tapas full,
The Lord ever bestows
Only on those who endear Him;
Yet the world think
"This the God, That the God;"
Thus distracted
Bruised they fall, hands hitting on rocks.`,
    elaborationTamil: `அனைத்திற்கும் முதல்வனாகிய எங்கள் சிவ பெருமான் உலகியலில் நிலைத்த புகழையும், நிரம்பிய மேலான தவத்தையும், அதன் பயனாகிய உண்மை ஞானத்தையும் தன்னை யடைந்த அடியார்களுக்கே அளித்தருள்வான் ஆகையால், உலகர் அவற்றை இழத்தற்குக் காரணம் அவ்வடியவரோடு மாறுபட்டு, 'அது கடவுள், இது கடவுள்' எனத் தத்தமக்கு எட்டிய பொருள்களைத் தனித்தனி கூறித் தம்முள் கலாய்த்துக்கொண்டு, ஞானம் குறை கையாலேயாம். இஃது இரங்கத்தக்கது.`,
  },
  {
    id: 2090, tantraId: 7, verseNumber: 2089,
    tamil: `இன்பத்து ளேபிறந்து இன்பத்து ளேவளர்ந்து
இன்பத்து ளேநினைக் கின்றது இதுமறந்து
துன்பத்து ளேசிலர் சோறொடு கூறையென்று
துன்பத்து ளேநின்று தூங்குகின் றார்களே`,
    transliteration: `iṉpattu ḷēpiṟantu iṉpattu ḷēvaḷarntu
iṉpattu ḷēniṉaik kiṉṟatu itumaṟantu
tuṉpattu ḷēcilar cōṟoṭu kūṟaiyeṉṟu
tuṉpattu ḷēniṉṟu tūṅkukiṉ ṟārkaḷē`,
    english: `2089: They Pursue not the Way of Bliss
Born in bliss, grown in bliss
Steeped in thoughts of bliss
This way, they forget;
Instead,
Hankering after food and raiment
In sorrow steeped they are;
And in sorrow steeped, they insensible slumber.`,
    elaborationTamil: `மக்கள் யாவரும் பிறக்கும்பொழுதே இன்பத்தில் பிறந்து, வளரும் பொழுதும் இன்பத்திலே வளர்ந்து இன்பத்திலே திளைக்கின்றவர்களே யாயினும் சிலர் இதனையறியாது தாங்கள் துன்பத்திலே மூழ்கியிருப்பதாகக் கருதிக்கொண்டு அத்துன்பத்தைப் போக்கிக் கொள்ளும் வழியாக, 'உணவு' என்றும், 'உடை' என்றும் அவாவி, அவற்றைப் பெறவேண்டி அல்லற்பட்டு, அவ்வல்லலை விட்டு நீங்க நினையாமல் அதிலேயே செயலற்றிருக்கின்றார்கள்; இஃது இரங்கத் தக்கது.`,
  },
  {
    id: 2091, tantraId: 7, verseNumber: 2090,
    tamil: `பெறுதற்கு அரிய பிறவியைப் பெற்றும்
பெறுதற்கு அரிய பிரானடி பேணார்
பெறுதற்கு அரிய பிராணிகள் எல்லாம்
பெறுதற்கு அரியதோர் பேறுஇழந் தாரே`,
    transliteration: `peṟutaṟku ariya piṟaviyaip peṟṟum
peṟutaṟku ariya pirāṉaṭi pēṇār
peṟutaṟku ariya pirāṇikaḷ ellām
peṟutaṟku ariyatōr pēṟuiḻan tārē`,
    english: `2090: Human Birth is Rare; Yet They Seek Not Lord's Feet
Rare is human birth,
Yet they seek not Lord's Feet,
So rare to reach;
They attained the rare human birth,
Yet missed this Treasure Rare,
They are but crawling creatures, indeed.`,
    elaborationTamil: `பெறுதற்கரிய பிராணிகள் ஞானத்தையும், அது வழியாக வீட்டையும் பெற இயலாத பிராணிகள். அவை மக்களை யொழித்து ஏனைய உயிர்கள். அவைகளால் பெறுதற்கரிய பேறு இறைவன் திருவடி. ''பெறார் பேறிழந்தார்'' என்க, ஏனைய வெளிப்படை.`,
  },
  {
    id: 2092, tantraId: 7, verseNumber: 2091,
    tamil: `ஆர்வ மனமும் அளவில் இளமையும்
ஈரமும் நல்லஎன்று இன்புறு காலத்துத்
தீர வருவதோர் காமத் தொழில்நின்று
மாதவன் இன்பம் மறந்தொழிந் தார்களே`,
    transliteration: `ārva maṉamum aḷavil iḷamaiyum
īramum nallaeṉṟu iṉpuṟu kālattut
tīra varuvatōr kāmat toḻilniṉṟu
mātavaṉ iṉpam maṟantoḻin tārkaḷē`,
    english: `2091: They Think Not of Heavenly Pleasures
These considering good,
They in pleasure indulged,
And in acts of love diverse sported;
Lo! They forgot the heavenly bliss
The Lord bestows
And for ever, for ever missed it.`,
    elaborationTamil: `யாவரிடத்தும் நட்பையே பாராட்டும் மனமும், எச் செயலிலும் சோர்வடையாத ஊக்கமும், கிளைஞர் எல்லோரிடத்திலும் செல்லுகின்ற ஈரமும் குறைவின்றியிருத்தலால் தாமும், பிறரும் 'இது மிக நல்லதாகிய பருவம்' என மகிழ்ச்சியுறுவதாகிய இளமைப் பருவத்திலே அந்நல்லவற்றை யெல்லாம் உமையொருபாகனுக்குப் பணி செய்வதில் பயன்படுத்தாது, அவனது இன்பத்தைப் பெறாமல் மறந்து, அந்நல்லனவெல்லாம் விரையக் கெடுதற்கு ஏதுவாகிய சிற்றின்பச் செயலிலே சிலர் ஈடுபட்டு ஒழிகின்றார்களே; ஈதென்ன அறியாமை!`,
  },
  {
    id: 2093, tantraId: 7, verseNumber: 2092,
    tamil: `இப்பரி சேஇள ஞாயிறு போலுரு
அப்பரிசு அங்கியின் உள்ளுறை அம்மானை
இப்பரி சேகம லத்துறை ஈசனை
மெய்ப்பரி சேவினை வாதுஇருந் தோமே`,
    transliteration: `ippari cēiḷa ñāyiṟu pōluru
apparicu aṅkiyiṉ uḷḷuṟai ammāṉai
ippari cēkama lattuṟai īcaṉai
meyppari cēviṉai vātuirun tōmē`,
    english: `2092: They Sought Not Lord
Thus He is,
Unto the rising sun, His Form;
That He is,
Within the Fire Kundalini resides;
There He is,
In the Lotus of Heart seated;
The True He is,
The Lord, we sought not.`,
    elaborationTamil: `முன் மந்திரத்தில் கூறிய உமாதவனாகிய சிவன் தன் அடியவர் முன் புறத்தே தோன்றிக் காட்சி வழங்குமிடத்துக் காலையில் தோன்றுகின்ற இளஞாயிற்றைப் போலும் உருவுடையனாய் விளங்குவான். [அது ''காலையே போன்றிலங்கும் மேனி'' (தி.11) என்பது முதலிய திருமொழிகளான் உணரப்படும்] இனி அவர்க்கு இவ்வாறு புறத்துத் தோன்றுதல் போலவே அகத்துத் தோன்றுங்கால் உள்ளக் கமலத்தை இடமாகக்கொண்டு என்றும் இருப்பவனாய் விளங்குவான். இவ்விரண்டும் இன்றிக் கரந்து நின்று அருள்புரியுமிடத்துச் சிறிதும், பெரிதுமாய தீப்பிழம்புகளின் உள்ளிருந்து அருள்புரிவான். [இவ் வுண்மைகள் எல்லாம் அவனை அறிந்து இன்புறும் பெரியோரை அடுத்துக் கேட்பின் விளங்கும்]. அவ்வாறு கேட்டுணராது நாளை வீணாகக் கழிக்கின்றோமே; இஃது அறியாமையன்றோ!`,
  },
  {
    id: 2094, tantraId: 7, verseNumber: 2093,
    tamil: `கூடகில் லார்குரு வைத்த குறிகண்டு
நாடகில் லார்நயம் பேசித் திரிவர்கள்
பாடகில் லார்அவன் செய்த பரிசறிந்து
ஆடவல் லார்அவர் பேறெது வாமே`,
    transliteration: `kūṭakil lārkuru vaitta kuṟikaṇṭu
nāṭakil lārnayam pēcit tirivarkaḷ
pāṭakil lāravaṉ ceyta paricaṟintu
āṭaval lāravar pēṟetu vāmē`,
    english: `2093: They Dance and Waste Away Their Lives
They unite in Him not,
The Way Guru showed;
They seek Him not,
In aimless talk indulging;
They sing Him not,
His benevolent deeds realizing;
What will they get,
They who dance and wastes away?`,
    elaborationEnglish: `The unholy ones dance about and waste away their lives. They do not seek the Lord the way the holy Guru has shown. The benevolent bliss of Siva is not for them.`,
    elaborationTamil: `சிலர் பெரியோரைக் குரவராக அடுத்து உண்மையைக் கேட்டுணர்ந்தாராயினும் அவர் தங்கட்கு ஒருதலைப் பட உணர்த்திய குறிக்கோளை அங்ஙனமே உணர்ந்து அடைய மாட்டார். 'அடைய வேண்டும்' என நினைக்கவும் மாட்டார். குரவர் தம்மை மலம் கழுவித் தூயராகச் செய்த செயலின் அருமையை அறிந்து, அவரைப் புகழ்ந்து பாடவும் மாட்டார். ஆயினும் பிறர் தம்மை மதிக்கும்வண்ணம் இனிமை உண்டாகப் பேசுவர். அப்பேச்சுக்கு ஏற்றவாறு நடிக்கவும் வல்லவராவர். அவர் அடையும் பயன்தான் எதுவோ!`,
  },
  {
    id: 2095, tantraId: 7, verseNumber: 2094,
    tamil: `நெஞ்சு நிறைந்தங்கு இருந்த நெடுஞ்சுடர்
நம்செம் பிரான்என்று நாதனை நாடொறும்
துஞ்சும் அளவும் தொழுமின் தொழாவிடில்
அஞ்சுஅற்று விட்டதோர் ஆனையும் ஆமே`,
    transliteration: `neñcu niṟaintaṅku irunta neṭuñcuṭar
namcem pirāṉeṉṟu nātaṉai nāṭoṟum
tuñcum aḷavum toḻumiṉ toḻāviṭil
añcuaṟṟu viṭṭatōr āṉaiyum āmē`,
    english: `2094: They Fall a Prey to Senses
He is the Great Light
That fills my heart;
Melting in love
Daily adore Him,
Unto the end of your days;
If you adore not,
The Five senses havoc cause
Unto the elephants that roam loose.`,
    elaborationTamil: `சிவபெருமானை, 'ஒவ்வொருவர் உள்ளத்திலும் நிறைந்து அங்கு ஒளிவிட்டும் விளங்குகின்ற அணையா விளக்கு' என்றும், 'உயிர்கட்கெல்லாம் உண்மையான முதற் கடவுள்' என்றும் உணர்ந்து நாள்தோறும் வழிபடுங்கள். இறக்குமளவும் வழிபடுங்கள். அவனை அவ்வாறு வழிபடாது புறக்கணித் திருப்பின் உங்களுடைய ஐம்பொறிகளும் கட்டிய சங்கிலி அறுபட்டொழிந்த அத்தன்மையை உடைய யானைகளாய் விடும்.`,
  },
  {
    id: 2096, tantraId: 7, verseNumber: 2095,
    tamil: `மிருக மனிதர் மிக்கோர் பறவை
ஒருவர்செய்து அன்புவைத்து உன்னாதது இல்லை
பருகுவர் ஓடுவர் பார்ப்பயன் கொள்வர்
திருமருவு மாதவம் சேர்ந்துஉணர்ந் தோரே`,
    transliteration: `miruka maṉitar mikkōr paṟavai
oruvarceytu aṉpuvaittu uṉṉātatu illai
parukuvar ōṭuvar pārppayaṉ koḷvar
tirumaruvu mātavam cērntuuṇarn tōrē`,
    english: `2095: They Care Not for the Fruit of This Birth
The birds, beasts, and the humans several,
They all, all, in endearment seek Him not;
They who in Tapas intense realized Him
Drink and run in rapture surpassing;
They indeed are the beings
Who have reaped the fruit of their birth here below.`,
    elaborationTamil: `விலங்குகள், மக்கள், தேவர்கள், பறவைகள், மற்றும் இவர்கள்போல் உள்ள இனத்தவர் ஆகியோரில் ஓரினத்தவரும் சிவபிரானிடத்தில் அன்பு வைத்து, அதனை மேலும் மேலும் பெருக்கி வழிபடாமையில்லை. அதனை அறிந்தவர்கள் அப்பெருமானது திரு வருளைப் பெறுதற்குரிய பெரிய தவத்தைச் செய்து, அதன் பயனாக விளைந்த அன்பினால் சிவபெருமானைக் கண்டால் இனிய பாலைப் போலப் பருகிவிடுவார் போல்வார்; 'அவன் வெளிப்படும் இடம் எது' என்று தேடிப்பல திசைகளிலும் ஓடுவர். அதனால், தாம் மண்ணில் மக்களாய்ப் பிறந்த பயனை எய்துவர்.`,
  },
  {
    id: 2097, tantraId: 7, verseNumber: 2096,
    tamil: `நீதியி லோர்பெற்ற பொன்போல் இறைவனைச்
சோதியி லாரும் தொடர்ந்துஅறி வாரில்லை
ஆதி பயனென்று அமரர் பிரான்என்ற
நாதியே வைத்தது நாடுகின் றேனே`,
    transliteration: `nītiyi lōrpeṟṟa poṉpōl iṟaivaṉaic
cōtiyi lārum toṭarntuaṟi vārillai
āti payaṉeṉṟu amarar pirāṉeṉṟa
nātiyē vaittatu nāṭukiṉ ṟēṉē`,
    english: `2096: They Seek Not Light
They seek not His Light
In unbroken continuity;
They are unto those
Who cherish not Him that is gold,
The Unrighteous they are;
"O! Lord, the Primal One!
You the Fruit of Wisdom!
The Lord of Celestial Beings!
My Sole Refuge!"
Thus I seek Him, ever and ever.`,
    elaborationTamil: `அற உணர்வு இல்லாதார் பொன்னைப் பெற்றால் அதனது பயனை யறிந்து அப்பயனை எய்தாது பொன்னை வாளா வைத்திருந்தே இறந்தது போலச் சிலர் சிவனை அறிந்தும் அவனால் அடையத் தக்க பயனை அறிந்து அம்முறையில் அவனை வழிபட்டு அப்பயனைப் பெறுகின்றவர் யாரும் இல்லை. ஆயினும் யான் உலகத்தைச் செயற்படுத்துதற்கு, 'படைப்புக் கடவுளாகிய பிரமன்' என்றும், மற்றும் 'தேவேந்திரன்' என்றும் இப்படிப் பல தேவரைத் தக்க வாறு சிவன் நியமித்திருக்கின்ற பெருஞ்செயலை நினைந்து அவனால் அடையத்தக்க பயனை அடைகின்றேன்.`,
  },
  {
    id: 2098, tantraId: 7, verseNumber: 2097,
    tamil: `இருந்தேன் மலர்அளைந்து இன்புற வண்டு
பெருந்தேன் இழைக்கின்ற பெற்றிமை ஓரார்
வருந்தேன் நுகராது வாய்புகு தேனை
அருந்தேனை யாரும் அறியகி லாரே`,
    transliteration: `iruntēṉ malaraḷaintu iṉpuṟa vaṇṭu
peruntēṉ iḻaikkiṉṟa peṟṟimai ōrār
varuntēṉ nukarātu vāypuku tēṉai
aruntēṉai yārum aṟiyaki lārē`,
    english: `2097: They Seek Not the Divine Honey
The bees flit from flower to flower
And in rapture incessant gather
The honey sweet;
Of this they think not;
There is a Honey Pure sweeter far
That in their mouth wells up (in Yoga)
None knows that Honey Rare.`,
    elaborationTamil: `வண்டுகள்தாம் இன்புற வேண்டும் என்றுதான் மிகுந்த தேன் உள்ள மலர்களை அறிந்து அவற்றினுட்புகுந்து கிண்டிச் சிறிது சிறிதாகக் கொணர்ந்து மிகுந்த தேனைச் சேர்க்கின்றன. ஆயினும் அத்தேனில் ஒருசிறிதையும் அவை பருகுவதில்லை. அதனை எண்ணிப் பாராதவர்களாய், அவற்றினும் கீழ்மையராக, தானாகவே வாயில் ஒழுகுவதும், எவ்வுலகத்திலும் கிடைத்தற்கரியதும் ஆகிய தேனை மக்களில் ஒருவரும் அறிந்து பருகுகின்றார்களில்லை. ஆயினும் யான் அவர்களைப்போல அத்தேனை நுகராமல் விட்டு வருந்தமாட்டேன்.`,
  },
  {
    id: 2099, tantraId: 7, verseNumber: 2098,
    tamil: `கருத்தறி யாது கழிந்தன காலம்
அருத்தியுள் ளான்அம ராபதி நாதன்
ஒருத்தன்உள் ளான் உல கத்துயிர்க்கு எல்லாம்
வருத்திநில் லாது வழுக்கின் றாரே`,
    transliteration: `karuttaṟi yātu kaḻintaṉa kālam
aruttiyuḷ ḷāṉama rāpati nātaṉ
oruttaṉuḷ ḷāṉ ula kattuyirkku ellām
varuttinil lātu vaḻukkiṉ ṟārē`,
    english: `2098: They Slip Low Down
Seeking Him not,
I wasted my life away;
In my love
Is the Lord of
Celestial Beings;
He is the One Being,
For the worlds all;
Yet in their thoughts
They praise Him not,
Low down they slip.`,
    elaborationTamil: `தன்னிடத்துச் செலுத்துகின்ற அன்பு உடையாரது அன்பிலே விளங்கி நிற்பவனும், தேவர்கட்கும் தேவனுமாய் உள்ள ஒருவனே அனைத்துயிர்கட்கும் ஒப்பற்ற தலைவன். அடங்காது ஓடுகின்ற மனத்தை வருத்தியாயினும் அடக்கி அவனை நினைந்து நில்லாமையால் பலர் அவனைப் பெறத் தவறுகின்றார்கள். அதனால் அவர்களது காலங்கள் உண்மையை உணராமலே கழிந்தொழியும்.`,
  },
  {
    id: 2100, tantraId: 7, verseNumber: 2099,
    tamil: `குதித்தோடிப் போகின்ற கூற்றமும் சார்வாய்
விதித்தென நாள்களும் வீழ்ந்து கழிந்த
விதிர்திருந்து என்செய்தீர் ஆறுதிர் ஆகில்
கொதிக்கின்ற கூழில் துடுப்பிட லாமே`,
    transliteration: `kutittōṭip pōkiṉṟa kūṟṟamum cārvāy
vititteṉa nāḷkaḷum vīḻntu kaḻinta
vitirtiruntu eṉceytīr āṟutir ākil
kotikkiṉṟa kūḻil tuṭuppiṭa lāmē`,
    english: `2099: Death Nears; Yet They Seek Not Peace
The God of Death leaps forward,
Agreeable to him
The fated days too roll away;
You tremble and shake,
What, though, that comes of it?
If Peace you seek,
Dip the ladle of your heart
In the boiling broth of love.`,
    elaborationTamil: `உலகீர், உங்களுக்கு இவ்வுடம்போடு கூடி வாழ்தற்கு வரையறுத்த நாள்கள் யாவும் தவம் செய்யாமையால் அவமே கழிந்தொழிந்தன. ஆகவே, உங்களை இவ்வுடம்பினின்றும் பிரித்தெடுத்துக் கொண்டு துள்ளி ஓடுபவனாகிய கூற்றுவனும் வந்துவிட்டான். இப்போது நடுங்கி என்ன செய்யப்போகின்றீர்கள்? நீங்கள் அமைதியுற வேண்டின் கொதிக்கின்ற கூழில் கையை யிடாமல் அகப்பையை இட்டு அள்ளி ஆற்றி உண்பதுபோலும் செயலைச் செய்தலே தக்கது.`,
  },
  {
    id: 2101, tantraId: 7, verseNumber: 2100,
    tamil: `கரைஅருகு ஆறாக் கழனி வளைந்த
திரைஅரு காமுன்னம் சேர்ந்தின்பம் எய்தும்
வரைஅருகு ஊறிய மாதவ நோக்கின்
நரைஉரு வாச்செல்லும் நாள்கில வாமே`,
    transliteration: `karaiaruku āṟāk kaḻaṉi vaḷainta
tiraiaru kāmuṉṉam cērntiṉpam eytum
varaiaruku ūṟiya mātava nōkkiṉ
naraiuru vāccellum nāḷkila vāmē`,
    english: `2100: Seek Lord Before Floods of Age Swell
Along the banks of the river (of Life)
The field ripened;
Before the floods (of age) swell,
Seek the Bliss Divine;
Practise Yoga
That takes you to the Mountain top
Where the ambrosial waters flow;
Then no more does greying age seize you.`,
    elaborationTamil: `ஆற்றங் கரையை அடுத்து ஒரு கழனி உண்டு. அதில் உண்டாகின்ற விளைவை உடையவன் பெறுதல் அரிது ஏனெனில், ஆற்றில் எப்பொழுது வேண்டுமானாலும் வெள்ளம் பெருகி வந்து விளைவை அழித்துவிடும். அதனை உணர்ந்து நீவிர் விழிப்பாய் இருந்து வெள்ளம் பெருகி வருவதற்கு முன்னே விளைவிற்குப் பாதுகாப்புச் செய்து விளைவின் பயனை எய்துங்கள். [இஃது ஒட்டணி. ஆறு - வினைவிளைவின் தொடர்ச்சி. ஆற்றங்கரை - அத்தொடர்ச்சியைச் சார்ந்திருக்கின்ற உடம்பு. கழனி - உடம்பில் உள்ள உயிர்; என்றது அதன் உணர்வை, அதில் விளைவது சிவபுண்ணியத்தின் பயனாக விளங்கிய சிவஞானம், அதனை எப்பொழுதும் வந்து அழிக்க இருப்பது உயிருணர்வை வேறுபடுத்தும் வினைவிளைவு. அருகாமுன்னம் - நெருங்குதற்குமுன்னே, இவற்றை இங்ஙனம் அணிவகையால் உணர்த்திய பின்பு அப்பயனைப் பெறுமாற்றைப் பின்னிரண்டடிகளால் நேராகவே உணர்த்தினார். அஃதாவது] மலைமுழை முதலிய தனியிடங்களில் இருந்து செய்வதனால் வளர்ந்து முதிர்கின்ற தவத்தில் உணர்வு செல்லுமாயின் நரை, திரை, மூப்பு இவற்றோடுகூடி வருகின்ற நாட்கள் உங்கட்கு இல்லையாகும்.`,
  },
  {
    id: 2102, tantraId: 7, verseNumber: 2101,
    tamil: `வரவுஅறி வானை மயங்கிருள் ஞாலத்து
இரவுஅறி வானை எழுஞ்சுடர்ச் சோதியை
அரவுஅறி வார்முன் ஒருதெய்வம் என்று
விரவுஅறி யாமலே மேல்வைத்த வாறே`,
    transliteration: `varavuaṟi vāṉai mayaṅkiruḷ ñālattu
iravuaṟi vāṉai eḻuñcuṭarc cōtiyai
aravuaṟi vārmuṉ oruteyvam eṉṟu
viravuaṟi yāmalē mēlvaitta vāṟē`,
    english: `2101: Their Thoughts Do Not Reach to the Lord
He who knows the Origin of all,
He who knows the Night (end)
That envelops worlds all,
The Luminous Light that self-rises,
He whom the Enlightened held aloft
As the One God Supreme,
Him they know not;
And thus on this world their thoughts still stand.`,
    elaborationTamil: `பகலும், இரவும்கலந்து நிற்கின்ற உலகத்தில் உயிர்கள் தோன்றுதல், மறைதல் ஆகியவற்றின் வழிமுறைகள் முழுவதையும் நன்குணர்ந்து அவைகளை ஏற்றபெற்றியால் செய்விக் கின்றவனும், முடிவில் அவ்வுயிர்கள் இராப்பகல் அற்ற இடத்தில் இருக்கும்படி வைத்து அவைகட்கு என்றும் விளக்கத்தைத் தந்தும் விளங்கியும் நிற்கின்ற, சுடர்விடுகின்ற பெருவிளக்காய் உள்ளவனும் ஆகிய சிவபெருமானை, 'நுண்ணறிவாளர் திரிபின்றி உணர்கின்ற ஒப்பற்ற முழுமுதற் கடவுள்' என்று உணர்ந்து அவனை அடைந்து உய்ய அறியாமையால் பலர்வேறு வேறு தெய்வங்களை முதற் கடவுளாகக் கருதி இடருள் அழுந்துதல் இரங்கத்தக்கது.`,
  },
  {
    id: 2103, tantraId: 7, verseNumber: 2102,
    tamil: `மறந்தொழி மண்மிசை மன்னாப் பிறவி
இறந்தொழி காலத்தும் ஈசனை உள்கும்
பறந்துஅல மந்து படுதுயர் தீர்ப்பான்
சிறந்த சிவநெறி சிந்தைசெய் யீரே`,
    transliteration: `maṟantoḻi maṇmicai maṉṉāp piṟavi
iṟantoḻi kālattum īcaṉai uḷkum
paṟantuala mantu paṭutuyar tīrppāṉ
ciṟanta civaneṟi cintaicey yīrē`,
    english: `2102: Think of Siva's Holy Way
Away forget,
This transient life here below;
Even unto the day your life passes away
Think of Lord;
Flying He comes to you,
And your distracting sorrows end;
Do, therefore, think
Of Siva's Holy Way.`,
    elaborationTamil: `மண்மேல் உள்ள பிறவிகள் நிலையின்றிச் சின்னாளில் அழிந்தொழிவனவேயாம். ஆதலின் அவற்றுள் சில பிறவிகளை உயர்ந்தனவாகக் கருதி அப்பிறவியில் பிறக்க வேண்டும் என விரும்புதலை விட்டுவிடுங்கள். அங்ஙனம் விட்டு வீடுபெற விரும்பும் பொழுது அதன் பொருட்டுப் பிற நெறிகளை நாடாது, நெறிகள் அனைத்திலும் மிக மேலானதாகிய சிவ நெறியை நாடுங்கள். நாடி அதனை அடைந்து இறக்குங் காலம் உட்பட எக்காலத்தும் சிவனை இடைவிடாது நினையுங்கள். அவ்வாறு நினைந்தால் அவன் நலனடைதற் பொருட்டு அதற்கான வழிகளைத் தேடி எவ்விடத்தும் விரைந்து ஓடி அலையும் நம் அலைவை நீக்கியருளுவான்.`,
  },
  {
    id: 2104, tantraId: 7, verseNumber: 2103,
    tamil: `செல்லும் அளவு செலுத்துமின் சிந்தையை
வல்ல பரிசால் உரைமின்கள் வாய்மையை
இல்லை யெனினும் பெரிதுளன் எம்மிறை
நல்ல அரநெறி நாடுமின் நீரே`,
    transliteration: `cellum aḷavu celuttumiṉ cintaiyai
valla paricāl uraimiṉkaḷ vāymaiyai
illai yeṉiṉum perituḷaṉ emmiṟai
nalla araneṟi nāṭumiṉ nīrē`,
    english: `2103: Seek the Holy Path of Hara
Think of Him
As far as your thoughts go;
Speak His truth
As far as you can;
"Lord," they may say, "He is not."
Very much He is, everywhere;
Seek the Holy Path
Of Hara that is good ever.`,
    elaborationTamil: `நாங்கள், 'ஒருகாலத்திலும் பிறத்தலும், இறத்தலும் இல்லாதவன், எல்லாவற்றையும் அறிந்தவன், எல்லா உயிர்களிடத்தும் காரணம் இல்லாமலே இரங்குகின்ற பேரிரக்கம் உடையவன்' என்பன போலச் சொல்கின்ற அப்படிப் பட்ட முதல்வன் ஒருவன் இல்லை; இருக்க இயலாது' என்று சிலர் முரணிக் கூறுவராயினும் அப்படிப்பட்ட பேரதிசயமான தன்மைகளையுடைய சிவ முதல்வன் இருக்கவே செய்கின்றான். அதனை நம்பி அவனது நல்ல நெறியை நீங்கள்நாடி அடையுங்கள். அடைந்து எந்த அளவு உங்கள் மனம் சோர்வடையாது நினைக்க வல்லதாகின்றதோ அந்த அளவு அவனை நினையுங்கள். எந்த அளவு அவன் பொருள் சேர்ந்த புகழை உணர்ந்து உரைக்க இயலுமோ; அந்த அளவு உரையுங்கள்; பயனுண்டு.`,
  },
  {
    id: 2105, tantraId: 7, verseNumber: 2104,
    tamil: `ஒன்றே குலமும் ஒருவனே தேவனும்
நன்றே நினைமின் நமனில்லை நாணாமே
சென்றே புகுங்கதி இல்லைநும் சித்தத்து
நின்றே நிலைபெற நீர்நினைந்துய் மினே.`,
    transliteration: `oṉṟē kulamum oruvaṉē tēvaṉum
naṉṟē niṉaimiṉ namaṉillai nāṇāmē
ceṉṟē pukuṅkati illainum cittattu
niṉṟē nilaipaṟa nīrniṉaintuy miṉē`,
    english: `2104 One the Family, One the God
One the family,
One the God;
Thus intense hold,
No more will death be;
None Other is Refuge,
With confidence you can seek;
Think of Him and be redeemed,
In your thoughts, holding Him steadfast.`,
    elaborationEnglish: `This. is extra-ordinarily modem in tone. Tirumular rises here to the highest in grandeur of thought.`,
    elaborationTamil: `உலகத்தார் பல சாதிகளைக் கூறுவராயினும் உண்மையில் உள்ளது ஒரு சாதியே. அது சிவ சாதி. உலகத்தார் பல கடவுளர்களைக் கூறிக் கொண்டாடுவராயினும் உண்மையில் உள்ள கடவுள் ஒருவனே. அவன் சிவன். இவற்றை நீவிர் முதலில் நன்றாக உணருங்கள். உணர்ந்தால், நமனும் உங்களை அணுகான்; வெட்கமின்றி முன்முன் பிறந்து இறந்த பிறப்புகளிலே மீண்டும் மீண்டும் பிறக்கும் நிலையும் உங்களுக்கு இல்லையாகும். அப்பால் மேற்கூறிய உண்மைகள் உங்கள் உள்ளத்தில் அசையாது நிலைபெற, அதன்வழிப் பின்னர்ச் சிவனை இடையறாது நினைந்து உய்தி பெறுங்கள்.`,
  },
  {
    id: 2106, tantraId: 7, verseNumber: 2105,
    tamil: `போற்றிசெய் அந்தண் கயிலைப் பொருப்பனை
நாற்றிசைக் கும்நடு வாய்கின்ற நம்பனைக்
காற்றிசைக் கும் கமழ்ஆக்கையைக் கைக்கொண்டு
கூற்றுதைத் தான்தன்மைக் கூறிநின்று உய்ம்மினே`,
    transliteration: `pōṟṟicey antaṇ kayilaip poruppaṉai
nāṟṟicaik kumnaṭu vāykiṉṟa nampaṉaik
kāṟṟicaik kum kamaḻākkaiyaik kaikkoṇṭu
kūṟṟutait tāṉtaṉmaik kūṟiniṉṟu uymmiṉē`,
    english: `2105: Praise Lord and Spurn Death
Praise the benevolent Lord,
He of Mount Kailas;
He as central stood,
In cardinal directions four, our Lord;
With the precious body
That Prana's vital breath holds
Praise the Lord and be redeemed,
The Lord,
Who with His Feet the
God of Death spurned.`,
    elaborationTamil: `இனி இங்கு நின்றும் இவ்வதிகாரத்தில் மேல் '' ஒருவனே தேவனும்' என ஒருதலைப் பட வலியுறுத்தி உணர்த்தி யருளிய, 'சிவபிரானுக்கு ஆட்செய்வதையே நும் கடமையாகக் கொண்டு ஒழுகிப் பயன் பெறுங்கள்' என்பதையே பல்லாற்றானும் பன்னிப் பன்னி அறிவுறுத்துகின்றார். இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 2107, tantraId: 7, verseNumber: 2106,
    tamil: `இக்காயம் நீக்கி இனியொரு காயத்தில்
புக்கும் பிறவாமல் போய்வழி நாடுமின்
எக்காலத்து இவ்வுடல் வந்துஎமக்கு ஆனதென்று
அக்காலம் உன்ன அருள்பெற லாமே`,
    transliteration: `ikkāyam nīkki iṉiyoru kāyattil
pukkum piṟavāmal pōyvaḻi nāṭumiṉ
ekkālattu ivvuṭal vantuemakku āṉateṉṟu
akkālam uṉṉa aruḷpeṟa lāmē`,
    english: `2106: Seek Lord; No More Births Will Be
Seek the Way
That when this body leaves,
Another body, you enter not;
"When did this human body come to me?"
Of that time you think of;
Verily will you His Grace receive.`,
    elaborationTamil: `'உயிராகிய நமக்கு உடல் எக்காலத்தில் வந்து பொருந்திற்று' என்று அக்காலத்தை ஆராய்ந்து உணரின், 'அதனை நமக்குப் படைத்துக் கொடுத்ததலைவன் இவன்' என்பது புலனாகும். அது புலனாகவே, அவன் மீது அன்பு செல்ல அவனது அருளைப் பெறுதல் உண்டாகும். அவ்வாற்றால் இவ்வுடம்பைக் கழித்துவிட்டு, இனி மற்றோர் உடம்பில் புகுந்து பிறத்தல் இன்றி உய்ந்துபோம் வழியை நாடுங்கள்.`,
  },
  {
    id: 2108, tantraId: 7, verseNumber: 2107,
    tamil: `போகின்ற வாறே புகுகின்ற அப்பொருள்
ஆகின்ற போதும் அரன்அறிவான்உளன்
சாகின்ற போதும் தலைவனை நாடுமின்
ஆகின்ற அப்பொருள் அக்கரை ஆகுமே`,
    transliteration: `pōkiṉṟa vāṟē pukukiṉṟa apporuḷ
ākiṉṟa pōtum araṉaṟivāṉuḷaṉ
cākiṉṟa pōtum talaivaṉai nāṭumiṉ
ākiṉṟa apporuḷ akkarai ākumē`,
    english: `2107: Lord is Your Redemption
The Lord who enters into you
And walks with you in the life
Knows sure when you in holiness ripen;
Seek the Lord
Even on the eve of your death;
He will your Redemption be
For the life to be.`,
    elaborationTamil: `நீவிர் போகின்ற போக்கிலே உங்களைப் போக விட்டுத் தானும், அப்போக்கிற்குத் துணையாய் உடன் வருகின்ற முதற்பொருள் சிவனே. அவன் அவ்வாறு விடுதலும், உடன் புகுதலும் நீவிர் உண்மையை உணர்தற்கு உரிய காலம் வருவதை அறிதற்காகவே யாம். ஆகையால், வாழ்கின்ற பொழுது மட்டுமின்றிச் சாகின்ற பொழுதும் அவனை நினையுங்கள். ஏனெனில், அவனே பிறவியாகிய கடலுக்கு அப்பால் உள்ள கரையாவான்.`,
  },
  {
    id: 2109, tantraId: 7, verseNumber: 2108,
    tamil: `பறக்கின்ற ஒன்று பயனுற வேண்டின்
இறக்கின்ற காலத்தும் ஈசனை உள்கும்
சிறப்பொடு சேரும் சிவகதி பின்னைப்
பிறப்பொன்றும் இலாமையும் பேருல காமே`,
    transliteration: `paṟakkiṉṟa oṉṟu payaṉuṟa vēṇṭiṉ
iṟakkiṉṟa kālattum īcaṉai uḷkum
ciṟappoṭu cērum civakati piṉṉaip
piṟappoṉṟum ilāmaiyum pērula kāmē`,
    english: `2108: Think of Lord unto Your Last Days
If your fleeting life
Is its goodly goal to attain,
Even on death-bed
Think of Lord;
Then will follow Siva's grace,
No more birth will be;
The heavenly world will yours be.`,
    elaborationTamil: `கூட்டில் சிறிது போது தங்கியிருந்து பின்பு இரையை நாடி அக்கூட்டைவிட்டுப் பறந்து போகின்ற பறவையைப் போல உடம்பில் சிறிது காலம் வாழ்ந்து பின்பு அவ்வாழ்வினும் வேறான பயனை நாடி அவ்வுடம்பை விட்டு ஓடுகின்ற உயிர், உண்மையாகவே தான் அடையத்தக்க பயனை அடைய வேண்டின் உடம்பை விட்டுப் பிரிகின்ற காலத்திலும் சிவனை மறவாமல் நினைக்கும். அவ்வாறு நினைத்தால் எல்லாச் சிறப்பினும் மேம்பட்ட சிறப்பாகிய, சிவ ஞானத்தின்வழி சிவகதியைச் சேரும் இனி அச்சிவகதிதான், ஏனையுலகங்கள் எல்லாவற்றையும் விடப் பெரியதாகிய உலகமும், அதனையும் கடந்த நிலைமையும் ஆகும்.`,
  },
  {
    id: 2110, tantraId: 7, verseNumber: 2109,
    tamil: `கூடியும் நின்றும் தொழுதுஎம் இறைவனைப்
பாடியுளே நின்று பாதம் பணிமின்கள்
ஆடியு ளேநின்று அறிவுசெய் வார்கட்கு
நீடிய ஈற்றுப் பசுவது ஆமே`,
    transliteration: `kūṭiyum niṉṟum toḻutuem iṟaivaṉaip
pāṭiyuḷē niṉṟu pātam paṇimiṉkaḷ
āṭiyu ḷēniṉṟu aṟivucey vārkaṭku
nīṭiya īṟṟup pacuvatu āmē`,
    english: `2109: Lord Yearns After Devotees
Praise Our Lord
In devotion congregational;
Sing His praise within,
And at His Feet adore;
Dance within and know Him;
Then He yearns after you,
Like the cow after its calf.`,
    elaborationTamil: `எங்கள் சிவபெருமானை அவன் அடியவரோடு கூடியும், தனித்தும், பாடியும், ஆடியும் வணங்குவதுடன் உள்ளத்திலே யும் அவனது திருவடிகளை நினைந்து அடிபணியுங்கள். ஏனெனில், உள்ளத்திலே நினைந்து பணிபவர்கட்குக் கன்றையீன்ற பசு அக் கன்றைவிட்டுப் பிரியாதது போலக் கரவாது விளங்கி அருள் செய்வான்.`,
  },
  {
    id: 2111, tantraId: 7, verseNumber: 2110,
    tamil: `விடுகின்ற சிவனார் மேல்எழும் போது
நடுநின்று நாடுமின் நாதன்தன் பாதம்
கெடுகின்ற வல்வினை கேடில் புகழோன்
இடுகின்றான் உம்மை இமையவ ரோடே`,
    transliteration: `viṭukiṉṟa civaṉār mēleḻum pōtu
naṭuniṉṟu nāṭumiṉ nātaṉtaṉ pātam
keṭukiṉṟa valviṉai kēṭil pukaḻōṉ
iṭukiṉṟāṉ ummai imaiyava rōṭē`,
    english: `2110: Attaining Celestial Status
When in death
Your life breath upward ascends
Course it through central Sushumna
And seek the Feet of Lord;
Your evil Karmas dire perish;
He of the blemishless fame
Seats you among Beings Immortal.`,
    elaborationTamil: `எப்பொழுதாயினும் உடம்பை விட்டு நீங்குவதே யன்றி அதில் நிலைத்திராததாகிய உயிர் அவ்வாறு எப்பொழுதாயினும் உடம்பைக் கீழே வீழ்த்தி விட்டுத் தான்மேலே செல்கின்ற பொழுது வாழ்விற்கும், சாவிற்கும் இடைப்பட்ட நேரத்தில் சிவனது திருவடிகளை நினையுங்கள். நினைந்தால் உங்கள் வினைகள் கெட்டொழிவன. தான் மறைந்திருப்பினும் தனது செயல் எஞ்ஞான்றும் நிகழ்வதால் அதுபற்றி முடிவின்றி வருகின்ற புகழை உடையவனாகிய சிவன் உங்களைத் தேவர்களோடு தேவர்களாய்ச் சேர்ப்பான்.`,
  },
  {
    id: 2112, tantraId: 7, verseNumber: 2111,
    tamil: `ஏறுடை யாய்இறை வாஎம்பி ரான்என்று
நீறிடு வார்அடி யார்நிகழ் தேவர்கள்
ஆறணி செஞ்சுடை அண்ணல் திருவடி
வேறுஅணி வார்க்கு வினையில்லை தானே`,
    transliteration: `ēṟuṭai yāyiṟai vāempi rāṉeṉṟu
nīṟiṭu vāraṭi yārnikaḻ tēvarkaḷ
āṟaṇi ceñcuṭai aṇṇal tiruvaṭi
vēṟuaṇi vārkku viṉaiyillai tāṉē`,
    english: `2111: Devotees Become Celestials
"O! Lord on the bull mounted,
O! God, My Lord--"
The devotees who thus praising
His holy ashes wear,
Celestial Beings, indeed, become;
For them who adore the Feet of Lord,
Who the Ganga on His matted lock wears,
No more Karma further is.`,
  },
  {
    id: 2113, tantraId: 7, verseNumber: 2112,
    tamil: `இன்புறு வீர்அறிந் தேஎம் இறைவனை
அன்புறு வீர்தவம் செய்யும்மெய்ஞ் ஞானத்து
பண்புறு வீர்பிற வித்தொழி லேநின்று
துன்புறு பாசத்து உழைத்துஒழிந் தீரே`,
    transliteration: `iṉpuṟu vīraṟin tēem iṟaivaṉai
aṉpuṟu vīrtavam ceyyummeyñ ñāṉattu
paṇpuṟu vīrpiṟa vittoḻi lēniṉṟu
tuṉpuṟu pācattu uḻaittuoḻin tīrē`,
    english: `2112: Know Lord and Be in Bliss
Know Our Lord,
And in bliss be;
Be filled with love;
Perform Tapas;
Perfect Jnana True;
You, who has laboured hard,
In worldly pursuits,
Of miserable Pasa entangled.`,
    elaborationTamil: `மீண்டும் மீண்டும் பிறந்து பிறந்து உழல்வதாகிய அந்தத் தொழிலிற்றானே நின்று, அத்துன்பத்தை அடைதற்கு ஏதுவான வினைகளில் கிடந்து உழைத்துக் கெட்டவர்களே, கேளுங்கள். எம் இறைவனாகிய சிவன் எல்லா உயிர்கட்கும் என்றும் உறுதுணையாய் இருந்து உதவி வருதலை உணர்ந்து அவனிடத்திலே அன்பு செய்யுங்கள்; அதன் மேலும் தவத்தைச் செய்யுங்கள்; அப்பொழுது உண்மை ஞானத்தைப் பெற்ற சிறப்பை உடையவராவீர்கள். அச்சிறப்பால் நிலையான இன்பத்தை எய்துவீர்கள்.`,
  },
  {
    id: 2114, tantraId: 7, verseNumber: 2113,
    tamil: `மேற்கொள்ள லாவதோர் மெய்த்தவம் ஒன்றுண்டு
மேற்கொள்ள லாவதோர் மெய்த்தாளும் ஒன்றுண்டு
மேற்கொள்ள லாவதோர் மெய்ந்நெறி ஒன்றுண்டு
மேற்கொள்ள லாம்வண்ணம் வேண்டிநின்றோர்க்கே`,
    transliteration: `mēṟkoḷḷa lāvatōr meyttavam oṉṟuṇṭu
mēṟkoḷḷa lāvatōr meyttāḷum oṉṟuṇṭu
mēṟkoḷḷa lāvatōr meynneṟi oṉṟuṇṭu
mēṟkoḷḷa lāmvaṇṇam vēṇṭiniṉṟōrkkē`,
    english: `2113 Ways to Seek the Higher Goal
There is a Tapas High
That you should seek;
There are Feet True
That you should adore;
There is a Way True
That you should adopt;
For all those
That the Higher Goal in earnest seek.`,
    elaborationTamil: `'யாவரும் மேற்கொள்ளத்தக்க நல்ல முறை எது' என்று அறிந்து அதனை மேற்கொள்ள விரும்புபவர்க்கு அம்முறை குறிப்பிடுகின்ற ஒப்பற்ற உண்மையான தவமும், ஒப்பற்ற அரு ளாற்றாலும், ஒப்பற்ற வீட்டு நெறியும் உள்ளன.`,
  },
  {
    id: 2115, tantraId: 7, verseNumber: 2114,
    tamil: `சார்ந்தவர்க்கு இன்பம் கொடுக்கும் தழல்வண்ணன்
பேர்ந்தவர்க்கு இன்னாப் பிறவி கொடுத்திடும்
கூர்ந்தவர்க்கு அங்கே குரைகழல்காட்டிடும்
சேர்ந்தவர் தேவரைச் சென்றுணர் வாரே`,
    transliteration: `cārntavarkku iṉpam koṭukkum taḻalvaṇṇaṉ
pērntavarkku iṉṉāp piṟavi koṭuttiṭum
kūrntavarkku aṅkē kuraikaḻalkāṭṭiṭum
cērntavar tēvaraic ceṉṟuṇar vārē`,
    english: `2114: Seek Lord and Be Blessed
On them who seek Him
He, His blessings bestows;
To them, who do not
He sorrows of birth gives;
To those who intense adore Him,
He reveals the Grace of His Holy Feet;
Joining the horde of Devas
They seek and realize Him,
Him, the Fire-hued Lord.`,
    elaborationTamil: `பொதுவாக, 'தேவரைச் சேர்தல்' என்பது தேவரை அவரை உணரும் நெறியிற் சென்று உணர்தலே யாகும். அம்முறையில் சிவபெருமான் தன்னைச் சார்ந்தவர்கட்கு இன்ப நிலையாகிய வீட்டையும், சாராது நீங்கினவர்கட்குத் துன்ப நிலையாகிய பிறப்பையும் கொடுப்பான். இதனை உணர்ந்து அவனிடத்தில் அன்பு மிகப் பெற்றவர்கட்கே அவன் தனது திருவடி நிழலைத் தருவான்.`,
  },
  {
    id: 2116, tantraId: 7, verseNumber: 2115,
    tamil: `முத்தியை ஞானத்தை முத்தமிழ் ஓசையை
எத்தனை காலமும் ஏத்துவர் ஈசனை
நெய்த்தலைப் பால்போல் நிமலனும் அங்குளன்
அத்தகு சோதி அதுவிரும் பாரே`,
    transliteration: `muttiyai ñāṉattai muttamiḻ ōcaiyai
ettaṉai kālamum ēttuvar īcaṉai
neyttalaip pālpōl nimalaṉum aṅkuḷaṉ
attaku cōti atuvirum pārē`,
    english: `2115: Lord Stands as Ghee in Milk
He is Mukti, Jnana and Nada
That in the three branches of Tamil resound,
Thus they praise Lord
Through time unending;
As the ghee within milk
The Pure One within them stands;
That Light they seek not, and love not.`,
    elaborationEnglish: `Three branches of knowledge: Poetry, music and drama. Here, the references is to nada of all the three — A, U, M (Aum)`,
    elaborationTamil: `வீடாகிய முடிநிலைப் பயனாயும், அப்பயனுக்கு நேர்வாயிலாகிய ஞானமாயும், அந்த ஞானத்தை முதற்கண் கேள்வி யால் உணர்த்தும் முத்தமிழின் ஒலியாயும் உள்ள சிவபெருமானையே அறிஞர் எத்துணைக் காலமாயினும் ஒழியாது துதித்து நிற்பர். அங்ஙனம் துதிக்கின்ற துதியில் அவன் தன்னுள்ளே நெய்யைக் கொண்டிருத்தலால் தன்னைப் பருகுகின்றவர்கட்கு இனிக்கின்ற பால்போல அவன் இனிப்பான். ஆகவே அறிவில் இனிக்கின்ற அறிவாயுள்ள அவனை அறிவுடையோர் விரும்பாமல் இருப்பரோ?`,
  },
  {
    id: 2117, tantraId: 7, verseNumber: 2116,
    tamil: `நியமத்த னாகிய நின்மலன் வைத்த
உகம்எத் தனையென்று ஒருவரும் தேறார்
பவமத்தி லேவந்து பாய்கின்றது அல்லால்
சிவமத்தை ஒன்றும் தெளியகில் லாரே`,
    transliteration: `niyamatta ṉākiya niṉmalaṉ vaitta
ukamet taṉaiyeṉṟu oruvarum tēṟār
pavamatti lēvantu pāykiṉṟatu allāl
civamattai oṉṟum teḷiyakil lārē`,
    english: `2116: Cascade of Births
The Pure One, as Creator of all
Many aeons, allotted;
How many they are,
None knows;
Into the cascade of births they leap;
Beyond that,
Of Siva they nothing clear know.`,
    elaborationTamil: `'ஒவ்வொரு பொருளையும் அதனதன் தன்மையில் நிற்குமாறு நிறுத்தி நடத்துபவனாகிய சிவபெருமான் அனைத்து உயிர்களையும் வீடு பெறுவிக்க எத்தனை யுகங்களை வரையறுத் திருக்கின்றான்' என்பதை அறிய வல்லவர் ஒருவரும் இல்லை, இந்நிலையில் அவரவரும் அச்சிவபரம் பொருளை உள்ளவாறு உணரும் நெறியால் உணர்ந்து பிறவியினின்றும் நீங்குதலையே ஒவ்வொருவரும் செய்தலே தக்கதாய் இருக்க, ஒருவரும் அதனைச் சிறிதும் செய்யாது, பிறவிக் கடலிலே குதித்து அதன் கரையைக் காணாது அமிழ்கின்றனர்.`,
  },
  {
    id: 2118, tantraId: 7, verseNumber: 2117,
    tamil: `இங்கித்தை வாழ்வும் எனைத்தோர் அகிதமும்
துஞ்சொத்த காலத்துத் தூய்மணி வண்ணனை
விஞ்சத்து உறையும் விகிர்தா எனநின்னை
நஞ்சுஅற் றவர்க்குஅன்றி நாடஒண் ணாதே`,
    transliteration: `iṅkittai vāḻvum eṉaittōr akitamum
tuñcotta kālattut tūymaṇi vaṇṇaṉai
viñcattu uṟaiyum vikirtā eṉaniṉṉai
nañcuaṟ ṟavarkkuaṉṟi nāṭaoṇ ṇātē`,
    english: `2117: Pray in Pure Heart
Heart
Filled with misery
Is life here below;
When to sleep in death
You near,
Praise the Pure One,
Of gem-hued Form;
Unless you in melting heart hail Him
As 'Oh, Lord, who in
Light Divine abides'
You realize Him not.`,
    elaborationTamil: `இவ்வுலகில் தமக்கு வருகின்ற நன்மை, தீமை இரண்டினையும் அவை ஒரு நிகரனவாக நிற்க வைக்கும் காலத்தில் மாணிக்க வண்ணனாகிய சிவபெருமானை, அவனது ஞானத்திலே விளங்கும் தனியொரு பொருளாக உணர்ந்து அவ்வாறான அவனது பெருமையைச் சொல்லி நினைக்கின்ற தூய மனம் உடையவர்க்கன்றி, அவனை உணர இயலாது.`,
  },
  {
    id: 2119, tantraId: 7, verseNumber: 2118,
    tamil: `பஞ்சமும் ஆம்புவி சற்குறுபால்முன்னி
வஞ்சகர் ஆனவர் வைகில் அவர்தம்மை
அஞ்சுவன் நாதன் அருநர கத்துஇடும்
செஞ்சநிற் போரைத் தெரிசிக்கச் சித்தியே`,
    transliteration: `pañcamum āmpuvi caṟkuṟupālmuṉṉi
vañcakar āṉavar vaikil avartammai
añcuvaṉ nātaṉ arunara kattuiṭum
ceñcaniṟ pōrait tericikkac cittiyē`,
    english: `2118: Fate of Knaves who Seek the Holy Guru
Some, who, knaves in real are,
Seek the Holy Guru;
If such be there,
Famine strikes the land;
At them even the Lord is appalled;
And to bottomless hell He consigns them;
To meet them
Who the righteous path tread,
That is Siddhi, verily.`,
    elaborationTamil: `தமக்கு ஞானத்தை அளித்த நல்லருள் ஆசிரியரிடத்து அவரையும் ஏனைப் பலரொடு ஒப்ப நினைக்கும் நேர்மையில்லாத மனத்தையுடைய மாணாக்கர் நன்மாணாக்கருள் தாமும் ஒருவராய் இருந்து அவர்கள் போல ஒழுகிவருவாராயின் அவரது கரவொழுக்கத்தால் நாடு பஞ்சத்தை எய்தும். அவரை அணுகச் சிவனும் அஞ்சுவான். அதனால் அவரைப் பின்பு அவன் மீளுதற்கரிய நரகத்தில் இடுவான். நேர்மையான மாணாக்கரைக் கண்ணால் கண்டவர்கட்கும் நற்பேறு உண்டாம்.`,
  },
  {
    id: 2120, tantraId: 7, verseNumber: 2119,
    tamil: `சிவனை வழிபட்டார் எண்ணிலாத் தேவர்
அவனை வழிபட்டங்கு ஆமாறுஒன் றில்லை
அவனை வழிபட்டங்கு ஆமாறு காட்டும்
குருவை வழிபடின் கூடலும் ஆமே`,
    transliteration: `civaṉai vaḻipaṭṭār eṇṇilāt tēvar
avaṉai vaḻipaṭṭaṅku āmāṟuoṉ ṟillai
avaṉai vaḻipaṭṭaṅku āmāṟu kāṭṭum
kuruvai vaḻipaṭiṉ kūṭalum āmē`,
    english: `2119: Holy Guru Shows the Way
The countless Devas worshipped Siva;
What becomes them
By worshipping Him?
Far better it be,
That you worship the Holy Guru
--Who, having himself worshipped Lord
Shows the Way of Becoming, too;
Sure, indeed, is your Mukti finite.`,
    elaborationTamil: `அளவற்ற தேவர்கள் சிவனையை நேராகச் சென்று கண்டு வழிபட்டனர். ஆயினும் அவர்கள் பின்பு துன்பம் இன்றி வாழ்ந்ததாக வரலாறில்லை. பின்பும் துன்பம் எய்தியதாகவே வரலாறுகள் உள்ளன. ஆகையால், என்றும் துன்பமில்லா வாழ்வைப் பெறும் வகையில் சிவனை வழிபடும் முறையைத் தெரிவிக்கின்ற குருவை வழிபட்டால், அவரது அருளால் அவ்வழிபாட்டில் நின்று துன்பம் இல்லாத நிலையை அடைதல் கூடும்.`,
  },
  {
    id: 2121, tantraId: 7, verseNumber: 2120,
    tamil: `நரரும் சுரரும் பசுபாசம்நண்ணிக்
கருமங்க ளாலே கழிதலில் கண்டு
குருஎன் பவன்ஞானி கோதிலன் ஆனால்
பரம்என்றல் அன்றிப் பகர்ஒன்றும் இன்றே`,
    transliteration: `nararum curarum pacupācamnaṇṇik
karumaṅka ḷālē kaḻitalil kaṇṭu
kurueṉ pavaṉñāṉi kōtilaṉ āṉāl
parameṉṟal aṉṟip pakaroṉṟum iṉṟē`,
    english: `2120: Hold on to Guru
The humans and
Celestials
Inveighed by Pasas
In Karma perish;
Seeing this,
Why not hold to Guru
That is Jnani,
And blemishless Pure
As Param Supreme itself
No more then to speak of.`,
    elaborationTamil: `மக்களே யாகுக; அவரினும் மேற்பட்ட தேவரே யாகுக; எல்லோரும் பாசத்துட்பட்ட பசுக்களேயாய் வினைவழிவந்து நீங்கிப் போதலின், 'குரு' எனப்படுபவன் அந்நிலையை உணர்ந்து பாசத்தின் நீங்கி நிற்றலால், 'ஞானி' என வேறுவைத்து எண்ணப் படுதலால், அவனை, 'பதி' எனவே கூறுதல் வேண்டுமன்றி, வேறு சொல்லுதற்கில்லை.`,
  },
  {
    id: 2122, tantraId: 7, verseNumber: 2121,
    tamil: `ஆட்கொண் டவர்தனி நாயகன் அன்புற
மேற்கொண்டவர்வினை போயற நாடொறும்
நீர்க்கின்ற செஞ்சுடை நீளன் உருவத்தின்
மேற்கொண்ட வாறுஅல்லை வீவித்து ளானே`,
    transliteration: `āṭkoṇ ṭavartaṉi nāyakaṉ aṉpuṟa
mēṟkoṇṭavarviṉai pōyaṟa nāṭoṟum
nīrkkiṉṟa ceñcuṭai nīḷaṉ uruvattiṉ
mēṟkoṇṭa vāṟuallai vīvittu ḷāṉē`,
    english: `2121: Guru is Lord Siva Himself
The Guru who admitted him into his loving Grace,
Is Lord Himself;
He works day by day
For the disciple's Karma to perish;
In the form of Lord
Of flowing russet locks
That wears the dripping Ganga
The Guru appears
And our sorrows ends.`,
    elaborationTamil: `ஒப்பற்ற தலைவனாகிய சிவன் தான் குருவாகி வந்து ஆட்கொள்ளப் பெற்றவர்களுள் பின்னும் நாள்தோறும் அக்குரு வடிவின்கண் அன்பு மேலும், மேலும் மிகச் செய்கின்றவரது வினைகள் சேய்மைக்கண் விலகிக் கெடும்படி, தனது இயற்கை உருவத்தில் நீண்டசடையினிடத்தே கங்கையை அடக்கி வைத்திருப்பது போல் அவற்றின் ஆற்றலை அடக்கி அவரிடத்தே விட்டு நீங்காதிருப்பான்.`,
  },
];
